#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/ioctl.h>
#include <linux/i2c.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spi.h>
#include <linux/spi/spi-bcm2835.h>
#include <gpiod.h>

#define SPI0 "/dev/spi0.0"
#define MCP3008_ADDR 0x68
#define CE0 8
#define D0 4
#define A0 0

int flame_sensor_fd;
int spi_fd;
int i2c_fd;
gpiod_device_t *gpio_device;
gpiod_line_mixin_t *gpio_line_mixin;
gpiod_line_t *gpio_line;
gpiod_edge_handler_t *gpio_edge_handler;
int flame_detected = 0;
int temperature = 0;
char timestamp[256];
char filename[] = "flame_data.csv";

void spi_open() {
    if ((spi_fd = open(SPI0, O_RDWR)) < 0) {
        perror("Failed to open SPI device");
        return;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, 0) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MOSI, 1) < 0) {
        perror("Failed to set SPI MOSI");
        close(spi_fd);
        return;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MISO, 0) < 0) {
        perror("Failed to set SPI MISO");
        close(spi_fd);
        return;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_SCLK, 1) < 0) {
        perror("Failed to set SPI SCLK");
        close(spi_fd);
        return;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_LSB_FIRST, 1) < 0) {
        perror("Failed to set SPI LSB_FIRST");
        close(spi_fd);
        return;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_SPICLK, 1) < 0) {
        perror("Failed to set SPI SPICLK");
        close(spi_fd);
        return;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, 1000000) < 0) {
        perror("Failed to set SPI speed to 1MHz");
        close(spi_fd);
        return;
    }
}

void spi_read() {
    uint8_t buffer[1];
    if (ioctl(spi_fd, SPI_IOC_RD_DATA0, buffer) < 0) {
        perror("Failed to read SPI data");
        return;
    }
    temperature = (buffer[0] * 3.3) / 255;
}

void gpio_open() {
    if ((gpio_fd = gpiod_open("/dev/gpiod")) < 0) {
        perror("Failed to open GPIO device");
        return;
    }
    gpio_device = gpiod_get_device(gpio_fd);
    if (gpio_device == NULL) {
        perror("Failed to get GPIO device");
        return;
    }
    gpio_line_mixin = gpiod_get_line_mixin(gpio_device);
    if (gpio_line_mixin == NULL) {
        perror("Failed to get GPIO line mixin");
        return;
    }
    gpio_line = gpiod_get_line(gpio_line_mixin, D0);
    if (gpio_line == NULL) {
        perror("Failed to get GPIO line");
        return;
    }
    gpio_edge_handler = gpiod_create_edge_handler(gpio_line, GPIOD_EDGE_BOTH, NULL);
    if (gpio_edge_handler == NULL) {
        perror("Failed to create GPIO edge handler");
        return;
    }
    gpiod_add_edge_handler(gpio_line_mixin, gpio_edge_handler);
    gpiod_enable(gpio_line_mixin);
}

void i2c_open() {
    if ((i2c_fd = open("/dev/i2c-ad0", O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, MCP3008_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return;
    }
}

void i2c_read() {
    uint8_t buffer[1];
    int result = ioctl(i2c_fd, I2C_SMBUS_READ, (unsigned long)&buffer, 1, 0);
    if (result < 0) {
        perror("Failed to read I2C data");
        return;
    }
    flame_detected = (buffer[0] & 0x01) ? 1 : 0;
}

void gpio_read() {
    int value = 0;
    if (gpiod_get_value(gpio_line) == 1) {
        flame_detected = 1;
    } else {
        flame_detected = 0;
    }
}

void log_data() {
    struct tm *timeinfo;
    time_t rawtime;
    rawtime = time(NULL);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    if (fopen(filename, "a") == NULL) {
        perror("Failed to open file for appending");
        return;
    }
    fprintf(f, "%s,%d,%d\n", timestamp, flame_detected, temperature);
    fclose(f);
}

void cleanup() {
    if (spi_fd > 0) {
        close(spi_fd);
    }
    if (i2c_fd > 0) {
        close(i2c_fd);
    }
    if (gpio_fd > 0) {
        gpiod_close(gpio_fd);
    }
    if (gpio_line_mixin) {
        gpiod_line_mixin_free(gpio_line_mixin);
    }
    if (gpio_line) {
        gpiod_line_free(gpio_line);
    }
    if (gpio_edge_handler) {
        gpiod_edge_handler_free(gpio_edge_handler);
    }
    if (f) {
        fclose(f);
    }
}

int main() {
    f = fopen(filename, "w");
    if (f == NULL) {
        perror("Failed to open file for writing");
        return 1;
    }
    if ((spi_fd = open(SPI0, O_RDWR)) < 0) {
        perror("Failed to open SPI device");
        cleanup();
        return 1;
    }
    spi_open();
    if ((i2c_fd = open("/dev/i2c-ad0", O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        cleanup();
        return 1;
    }
    i2c_open();
    if ((gpio_fd = gpiod_open("/dev/gpiod")) < 0) {
        perror("Failed to open GPIO device");
        cleanup();
        return 1;
    }
    gpio_open();
    while (1) {
        if (gpiod_get_value(gpio_line) == 1) {
            flame_detected = 1;
        } else {
            flame_detected = 0;
        }
        i2c_read();
        spi_read();
        log_data();
        usleep(1000000);
    }
    cleanup();
    return 0;
}

