#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>

#define I2C_ADDR 0x38
#define I2C_BUS 1
#define GPIO2 2
#define GPIO3 3
#define SAMPLE_RATE 100000
#define BUFFER_SIZE 1024

int i2c_fd;
wiringPiI2C_t *i2c;

void handle_signal(int signum) {
    if (i2c_fd > 0) {
        close(i2c_fd);
    }
    if (i2c) {
        wiringPiI2CClose(i2c);
    }
    printf("Exiting...\n");
    exit(0);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    wiringPiSetupGpio();
    i2c = wiringPiI2COpen(I2C_ADDR, I2C_BUS);

    if (i2c_fd < 0) {
        printf("Error opening I2C device\n");
        return 1;
    }

    FILE *log_file = fopen("audio_log.txt", "a");
    if (!log_file) {
        printf("Error opening log file\n");
        return 1;
    }

    double samples[2];
    double avg;
    char timestamp[128];

    for (int i = 0; i < 10; i++) {
        for (int j = 0; j < 2; j++) {
            if (wiringPiI2CReadReg16(i2c, 0x00) < 0) {
                samples[j] = -999.0;
            } else {
                samples[j] = (double) (wiringPiI2CReadReg16(i2c, 0x00) & 0xFF) * 256 +
                            (double) (wiringPiI2CReadReg16(i2c, 0x01) & 0xFF);
                samples[j] = 1000.0 - samples[j];
            }
        }

        avg = (samples[0] + samples[1]) / 2.0;

        sprintf(timestamp, "%d.%03d", i, (int) (1000.0 * (i * 100 + j) / SAMPLE_RATE));
        fprintf(log_file, "%s %f\n", timestamp, avg);

        delay(100);
    }

    fclose(log_file);
    wiringPiI2CClose(i2c);
    close(i2c_fd);
    printf("Program exited successfully\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/ioctl.h>
#include <linux/i2c.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spi.h>
#include <linux/spi/spi-bcm2835.h>
#include <signal.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>

#define SPI_CHANNEL 0
#define SPI_CS0 8
#define SPI_CS1 9
#define SPI_MISO 9
#define SPI_MOSI 10
#define SPI_SCLK 11
#define LED 27

#define ADC_CHANNELS 2
#define ADC_SAMPLE_RATE 100
#define HIGH_LEVEL_THRESHOLD 0.5

#define SPI_MODE 0
#define SPI_SPEED 1000000

#define SPI_DEV "/dev/spi0.0"

#define LOG_FILE "audio_events.csv"

volatile sig_atomic_t running = 1;

void handle_sigint(int signum) {
    printf("SIGINT received, exiting...\n");
    wiringPiLEDWrite(1); // Turn off LED
    running = 0;
    // Release all resources
    // SPI
    wiringPiSPIClose(SPI_CHANNEL);
    // GPIO
    wiringPiClose();
}

int spi_init() {
    int fd;
    if ((fd = open(SPI_DEV, O_RDWR)) < 0) {
        perror("Failed to open SPI device");
        return -1;
    }
    if (ioctl(fd, SPI_SET_MODE, SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(fd);
        return -1;
    }
    if (ioctl(fd, SPI_SET_SPEED, SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(fd);
        return -1;
    }
    return fd;
}

int spi_deinit(int fd) {
    close(fd);
    return 0;
}

int spi_write_cs(int fd, int cs) {
    if (ioctl(fd, SPI_CS, cs) < 0) {
        perror("Failed to write CS");
        return -1;
    }
    return 0;
}

int spi_read(int fd, int cs, int num_bytes) {
    uint8_t buffer[num_bytes];
    if (ioctl(fd, SPI_READ, cs, buffer, num_bytes) < 0) {
        perror("Failed to read from SPI");
        return -1;
    }
    return 0;
}

int spi_deinit_spi(int fd) {
    close(fd);
    return 0;
}

int adc_read(int fd, int cs, int channel) {
    uint8_t buffer[3];
    int result = spi_write_cs(fd, cs);
    if (result < 0) return -1;
    result = spi_read(fd, cs, 3);
    if (result < 0) return -1;
    buffer[0] = buffer[1] = buffer[2] = 0;
    buffer[0] = buffer[1] = buffer[2] = 0;
    buffer[0] = (buffer[0] << 2) | (buffer[1] >> 6);
    buffer[1] = (buffer[1] << 6) | (buffer[2] >> 10);
    return buffer[0] * 256 + buffer[1];
}

double adc_rms(int samples[], int count) {
    double sum = 0;
    for (int i = 0; i < count; i++) {
        sum += (samples[i] / 32768.0) * 2.8284271247461903; // sqrt(2)
    }
    return sqrt(sum / count);
}

void log_audio_events(double rms1, double rms2, long timestamp) {
    char buffer[256];
    sprintf(buffer, "%ld,%f,%f\n", timestamp, rms1, rms2);
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        return;
    }
    fprintf(fp, "%s", buffer);
    fclose(fp);
}

void handle_spi_error(int fd) {
    printf("SPI initialization failed\n");
    exit(EXIT_FAILURE);
}

void handle_file_error(FILE *fp) {
    if (fp == NULL) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
}

int main() {
    wiringPiSetupGpio();
    wiringPiSetup();
    wiringPiSPISetBitOrder(SPI_CHANNEL, SPI_ORDER_MSB);
    wiringPiSPISetDataMode(SPI_CHANNEL, SPI_MODE);
    wiringPiSPISetClockSpeed(SPI_CHANNEL, SPI_SPEED);

    int spi_fd = spi_init();
    if (spi_fd < 0) {
        handle_spi_error(spi_fd);
    }

    FILE *fp = fopen(LOG_FILE, "w");
    if (fp == NULL) {
        handle_file_error(fp);
    }

    int samples[ADC_CHANNELS][ADC_SAMPLE_RATE];
    int sample_index = 0;

    signal(SIGINT, handle_sigint);

    long timestamp = 0;
    while (running) {
        for (int channel = 0; channel < ADC_CHANNELS; channel++) {
            int cs = channel == 0 ? SPI_CS0 : SPI_CS1;
            for (int i = 0; i < ADC_SAMPLE_RATE; i++) {
                int sample = adc_read(spi_fd, cs, channel);
                samples[channel][sample_index++] = sample;
            }
            double rms = adc_rms(samples[channel], ADC_SAMPLE_RATE);
            log_audio_events(rms, channel == 0 ? rms1 : rms2, timestamp);
            timestamp += 1000 / ADC_SAMPLE_RATE;
        }
        if (channel == 0) {
            if (rms1 > HIGH_LEVEL_THRESHOLD) {
                wiringPiLEDWrite(1); // Turn on LED
            } else {
                wiringPiLEDWrite(0); // Turn off LED
            }
        } else {
            if (rms2 > HIGH_LEVEL_THRESHOLD) {
                wiringPiLEDWrite(1); // Turn on LED
            } else {
                wiringPiLEDWrite(0); // Turn off LED
            }
        }
        delay(1000 / ADC_SAMPLE_RATE);
    }

    spi_deinit_spi(spi_fd);
    fclose(fp);
    wiringPiSPIClose(SPI_CHANNEL);
    wiringPiClose();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c.h>
#include <linux/i2c-dev.h>
#include <linux/sensors.h>
#include <linux/sensors_gpio.h>
#include <linux/sensors_gpio.h>
#include <linux/delay.h>
#include <math.h>

#define I2C_BUS 1
#define I2C_ADDR 0x68
#define ADC_CHANNEL 0
#define BUFFER_SIZE 100
#define CURRENT_THRESHOLD 50.0
#define LED_PIN 17

typedef struct {
    float buffer[BUFFER_SIZE];
    int head, tail, count;
} CircularBuffer;

void init_buffer(CircularBuffer *buffer) {
    buffer->head = 0;
    buffer->tail = 0;
    buffer->count = 0;
}

void add_to_buffer(CircularBuffer *buffer, float value) {
    if (buffer->count < BUFFER_SIZE) {
        buffer->buffer[buffer->head] = value;
        buffer->head = (buffer->head + 1) % BUFFER_SIZE;
        buffer->count++;
    } else {
        printf("Buffer full, cannot add value\n");
    }
}

float get_average(CircularBuffer *buffer) {
    if (buffer->count == 0) {
        return 0.0;
    }
    return (float)buffer->count / (float)BUFFER_SIZE * (float)sum(buffer);
}

float sum(float *array, int size) {
    float sum = 0.0;
    for (int i = 0; i < size; i++) {
        sum += array[i];
    }
    return sum;
}

void handle_sigint(int sig) {
    printf("SIGINT received, shutting down...\n");
    // Turn off LED
    digitalWrite(LED_PIN, 0);
    // Release resources
    // ...
    exit(0);
}

int main() {
    // Initialize signal handler for SIGINT
    signal(SIGINT, handle_sigint);

    // Initialize I2C device
    int i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        return 1;
    }

    // Initialize ADS1115 ADC
    struct ads1115_config config;
    config.channel = ADC_CHANNEL;
    config.resolution = 0x3; // 16-bit resolution
    config.mode = ADS1115_MODE_SINGLE_END;
    config.data_rate = 0x0A; // 10 Hz
    ioctl(i2c_fd, ADS1115_CONFIG, &config);

    // Initialize LED GPIO
    int led_fd = open("/dev/gpiod", O_RDWR);
    if (led_fd < 0) {
        perror("Failed to open LED GPIO");
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open(led_fd);
    if (!chip) {
        perror("Failed to open LED GPIO chip");
        return 1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, LED_PIN);
    if (!line) {
        perror("Failed to get LED GPIO line");
        return 1;
    }

    gpiod_line_set_direction(line, GPIOD_LINE_DIR_OUT);
    gpiod_line_set_value(line, 0);

    // Initialize sensor GPIO
    struct sensors_gpio *gpio = sensors_gpio_open();
    if (!gpio) {
        perror("Failed to open sensor GPIO");
        return 1;
    }

    struct sensors_gpio_device *sensor = sensors_gpio_get_device(gpio, "ads1115");
    if (!sensor) {
        perror("Failed to get sensor GPIO device");
        return 1;
    }

    // Initialize circular buffer
    CircularBuffer buffer;
    init_buffer(&buffer);

    while (1) {
        // Read ADC value
        struct ads1115_data data;
        if (ioctl(i2c_fd, ADS1115_READ, &data) < 0) {
            perror("Failed to read ADC value");
            continue;
        }

        // Convert ADC value to current
        float current = (float)data.value * 6.144 / 32768.0;

        // Add to buffer
        add_to_buffer(&buffer, current);

        // Check average current
        float average = get_average(&buffer);
        if (average > CURRENT_THRESHOLD) {
            // Trigger warning LED
            gpiod_line_set_value(line, 1);
        }

        // Clear buffer
        init_buffer(&buffer);

        // Sleep for 100 ms
        usleep(100000);
    }

    // Graceful shutdown
    gpiod_chip_close(chip);
    gpiod_line_close(line);
    sensors_gpio_close(gpio);
    close(i2c_fd);
    close(led_fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
