#include <string.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <syslog.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define TCS34725_ID 0x00
#define TCS34725_CLEAR 0x01
#define TCS34725_RED 0x02
#define TCS34725_GREEN 0x03
#define TCS34725_BLUE 0x04

#define COLOR_LOG_FILE "color_log.csv"
#define COLOR_LOG_HEADER "YYYY-MM-DD HH:MM:SS,clear,red,green,blue"

#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100

typedef struct {
    int i2c_fd;
    int clear;
    int red;
    int green;
    int blue;
} ColorSensor;

static void sigint_handler(int signum) {
    if (ColorSensor::instance->i2c_fd > 0) {
        close(ColorSensor::instance->i2c_fd);
    }
    ColorSensor::instance->cleanup();
    exit(EXIT_FAILURE);
}

static void cleanup() {
    if (ColorSensor::instance->i2c_fd > 0) {
        close(ColorSensor::instance->i2c_fd);
    }
}

static ColorSensor* instance = NULL;

static void init_sensor() {
    if (instance == NULL) {
        instance = calloc(1, sizeof(ColorSensor));
        if (instance == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
    }
    instance->i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (instance->i2c_fd < 0) {
        perror("Failed to open I2C bus");
        cleanup();
        exit(EXIT_FAILURE);
    }
    if (ioctl(instance->i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        cleanup();
        exit(EXIT_FAILURE);
    }
    if (read_i2c_register(instance->i2c_fd, TCS34725_ID) != TCS34725_ID) {
        fprintf(stderr, "Sensor ID mismatch\n");
        cleanup();
        exit(EXIT_FAILURE);
    }
    instance->clear = read_i2c_register(instance->i2c_fd, TCS34725_CLEAR);
    instance->red = read_i2c_register(instance->i2c_fd, TCS34725_RED);
    instance->green = read_i2c_register(instance->i2c_fd, TCS34725_GREEN);
    instance->blue = read_i2c_register(instance->i2c_fd, TCS34725_BLUE);
}

static int read_i2c_register(int fd, int reg) {
    char buf[2];
    ssize_t bytes_read;
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Failed to write to I2C register\n");
        return -1;
    }
    if ((bytes_read = read(fd, buf, 1)) != 1) {
        fprintf(stderr, "Failed to read from I2C register\n");
        return -1;
    }
    return buf[0];
}

static void read_color_values() {
    if (instance->clear == 0 || instance->red == 0 || instance->green == 0 || instance->blue == 0) {
        fprintf(stderr, "Invalid sensor configuration\n");
        return;
    }
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    char timestamp[20];
    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", &ts);
    char line[100];
    snprintf(line, sizeof(line), "%s,%d,%d,%d,%d", timestamp, instance->clear, instance->red, instance->green, instance->blue);
    FILE* file = fopen(COLOR_LOG_FILE, "a");
    if (file == NULL) {
        perror("Failed to open color log file");
        return;
    }
    if (fputs(line, file) == EOF) {
        perror("Failed to write to color log file");
        fclose(file);
        return;
    }
    fclose(file);
}

static void cleanup() {
    if (instance->i2c_fd > 0) {
        close(instance->i2c_fd);
    }
    free(instance);
}

static void handle_i2c_error(int fd, int reg, int expected) {
    if (reg == expected) {
        return;
    }
    fprintf(stderr, "I2C error: expected %d, got %d\n", expected, reg);
    if (errno == EIO) {
        fprintf(stderr, "Transient I2C error\n");
    } else {
        fprintf(stderr, "Fatal I2C error\n");
    }
    if (instance->i2c_fd > 0) {
        close(instance->i2c_fd);
    }
    cleanup();
    exit(EXIT_FAILURE);
}

static void handle_sensor_error() {
    if (instance->clear == 0 || instance->red == 0 || instance->green == 0 || instance->blue == 0) {
        fprintf(stderr, "Sensor error: invalid configuration\n");
    } else {
        fprintf(stderr, "Sensor error: invalid configuration\n");
    }
    if (instance->i2c_fd > 0) {
        close(instance->i2c_fd);
    }
    cleanup();
    exit(EXIT_FAILURE);
}

static void run() {
    init_sensor();
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);
    while (1) {
        if (instance->clear == 0 || instance->red == 0 || instance->green == 0 || instance->blue == 0) {
            handle_sensor_error();
        }
        read_color_values();
        usleep(1000000); // 1 second
    }
}

int main() {
    run();
    return 0;
}

