void spi_init(int fd, struct spi_ioc_transfer *transfer) {
    transfer->cs = SPI0_CE0;
    transfer->d ApostropheCS = 0;
    transfer->delay_usec = 0;
    transfer->speed_hz = 1000000;
    transfer->bits_per_line = 8;
    transfer->nr_of_frames = 1;
    transfer->first_frame = 0;
    transfer->cmd = SPI_CMD0;
    transfer->nax_prf = 1;
    transfer->nax_len = 1;
    transfer->nax_buf = 0;
    transfer->tx_buf = 0;
    transfer->rx_buf = 0;
}

void spi_read(int fd, struct spi_ioc_transfer *transfer, void *buf) {
    int ret;
    ret = ioctl(fd, SPI_IOC_RDWR, transfer);
    if (ret < 0) {
        perror("SPI ioctl failed");
        exit(EXIT_FAILURE);
    }
    ret = read(fd, buf, 1);
    if (ret < 0) {
        perror("read failed");
        exit(EXIT_FAILURE);
    }
}

void spi_write(int fd, struct spi_ioc_transfer *transfer, void *buf) {
    int ret;
    ret = ioctl(fd, SPI_IOC_RDWR, transfer);
    if (ret < 0) {
        perror("SPI ioctl failed");
        exit(EXIT_FAILURE);
    }
    ret = write(fd, buf, 1);
    if (ret < 0) {
        perror("write failed");
        exit(EXIT_FAILURE);
    }
}

