#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/time.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <stdint.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS 1
#define I2C_ADDR 0x55

#define PRESSURE_REG 0x00
#define PRESSURE_LSB 0x01
#define PRESSURE_MSB 0x02
#define PRESSURE_XOR 0x03
#define PRESSURE_CX 0x04
#define PRESSURE_CX_LSB 0x05
#define PRESSURE_CX_MSB 0x06
#define PRESSURE_CX_XOR 0x07
#define PRESSURE_CX_CX 0x08
#define PRESSURE_CX_CX_LSB 0x09
#define PRESSURE_CX_CX_MSB 0x0A
#define PRESSURE_CX_CX_XOR 0x0B
#define PRESSURE_CX_CX_CX 0x0C
#define PRESSURE_CX_CX_CX_LSB 0x0D
#define PRESSURE_CX_CX_CX_MSB 0x0E
#define PRESSURE_CX_CX_CX_XOR 0x0F

#define I2C_DEVICE "/dev/i2c-" I2C_BUS

#define LOG_FILE "pressure_log.csv"

#define TIMESTAMP_FORMAT "%Y-%m-%d %H:%M:%S.%06dZ"

void i2c_read_error(int fd, int reg, int error_code) {
    fprintf(stderr, "I2C read error: Register 0x%02x, error code %d\n", reg, error_code);
}

void handle_sensor_absent(int fd) {
    fprintf(stderr, "Sensor not found or I2C open failed\n");
    close(fd);
}

void handle_sigint_or_term(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        if (i2c_fd != -1) {
            close(i2c_fd);
        }
        if (log_fd != -1) {
            close(log_fd);
        }
        cleanup();
        exit(EXIT_SUCCESS);
    }
}

void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_fd != -1) {
        close(log_fd);
    }
}

int main() {
    struct i2c_msg msg[1];
    struct i2c_rdwr_ioctl_data data;
    int i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd == -1) {
        handle_sensor_absent(i2c_fd);
        return EXIT_FAILURE;
    }

    data.msgs = msg;
    data.nmsgs = 1;
    data.flags = I2C_RDWR;

    if (ioctl(i2c_fd, I2C_RDWR, &data) == -1) {
        handle_sensor_absent(i2c_fd);
        return EXIT_FAILURE;
    }

    if (i2c_fd != -1) {
        msg[0].addr = I2C_ADDR;
        msg[0].flags = I2C_M_RD;
        msg[0].len = 1;
        msg[0].buf[0] = PRESSURE_REG;

        while (1) {
            if (ioctl(i2c_fd, I2C_SMBUS_READ, &msg[0]) == -1) {
                i2c_read_error(i2c_fd, PRESSURE_REG, errno);
                continue;
            }

            uint16_t pressure = (msg[0].buf[0] << 8) | msg[0].buf[1];
            pressure = pressure >> 1; // Remove the XOR bit

            time_t rawtime;
            struct tm * timeinfo;
            char buffer[128];

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(buffer, sizeof(buffer), TIMESTAMP_FORMAT, timeinfo);

            FILE *log_file = fopen(LOG_FILE, "a");
            if (log_file == NULL) {
                fprintf(stderr, "Error opening log file\n");
                continue;
            }

            fprintf(log_file, "%s,%d\n", buffer, pressure / 1000.0);
            fflush(log_file);
            fclose(log_file);

            signal(SIGINT, handle_sigint_or_term);
            signal(SIGTERM, handle_sigint_or_term);
        }
    }

    return EXIT_SUCCESS;
}

