#include <wiringPi.h>
#include <wiringPiI2C.h>

#define I2C_ADDR 0x68
#define ADC0 0x00
#define ADC1 0x01
#define ADC2 0x02
#define ADC3 0x03
#define ADC4 0x04
#define ADC5 0x05
#define ADC6 0x06
#define ADC7 0x07
#define ADC8 0x08
#define ADC9 0x09
#define ADC10 0x0A
#define ADC11 0x0B
#define ADC12 0x0C
#define ADC13 0x0D
#define ADC14 0x0E
#define ADC15 0x0F

#define PRESSURE_CHANNEL 0
#define NTC_CHANNEL 1
#define PRESSURE_OFFSET 0
#define NTC_OFFSET 0
#define PRESSURE_GAIN 1
#define NTC_GAIN 1

#define PRESSURE_THRESHOLD 105.0
#define PRESSURE_UNIT "kPa"
#define TEMPERATURE_UNIT "°C"

#define I2C_TIMEOUT 100
#define I2C_RETRIES 3

#define GPIO17 17

volatile int running = 1;
volatile int sensor_present = 0;
volatile int adc_present = 0;

void handle_sensor_absent(int sig) {
    printf("Sensor not present. Exiting...\n");
    running = 0;
    wiringPiI2Cclose(sensor);
    wiringPiI2Cclose(adc);
    exit(0);
}

void handle_bus_error(int sig) {
    printf("Bus error. Exiting...\n");
    running = 0;
    wiringPiI2Cclose(sensor);
    wiringPiI2Cclose(adc);
    exit(0);
}

void handle_sigint(int sig) {
    printf("SIGINT received. Exiting...\n");
    running = 0;
    wiringPiI2Cclose(sensor);
    wiringPiI2Cclose(adc);
    exit(0);
}

int i2c_read_byte(wiringPiI2C_t *adc, uint8_t addr, uint8_t reg, uint8_t *value) {
    int retries = 0;
    while (retries < I2C_RETRIES) {
        if (retries > 0) {
            printf("I2C read retry %d...\n", retries);
        }
        if (wiringPiI2CWriteI2C(adc, addr, reg) < 0) {
            handle_bus_error(0);
        }
        if (wiringPiI2CReadI2C(adc, addr, reg, value) < 0) {
            handle_bus_error(0);
        }
        if (*value == 0) {
            retries++;
        } else {
            return *value;
        }
    }
    handle_sensor_absent(0);
    return 0;
}

int i2c_read_word(wiringPiI2C_t *adc, uint8_t addr, uint8_t reg, uint16_t *value) {
    int retries = 0;
    while (retries < I2C_RETRIES) {
        if (retries > 0) {
            printf("I2C read retry %d...\n", retries);
        }
        if (wiringPiI2CWriteI2C(adc, addr, reg) < 0) {
            handle_bus_error(0);
        }
        if (wiringPiI2CReadI2C(adc, addr, reg, value) < 0) {
            handle_bus_error(0);
        }
        if (*value == 0) {
            retries++;
        } else {
            return *value;
        }
    }
    handle_sensor_absent(0);
    return 0;
}

int main() {
    wiringPiSetupGpio();
    wiringPiPinMode(GPIO17, PI_OUTPUT);
    wiringPiPinDirection(GPIO17, PI_HIGH);

    wiringPiI2C_t *sensor = wiringPiI2COpen(-1, I2C_SLAVE);
    if (sensor == NULL) {
        printf("Failed to open I2C device. Exiting...\n");
        return 1;
    }
    sensor_present = 1;

    wiringPiI2CSetSlaveAddress(sensor, I2C_ADDR);
    if (wiringPiI2CWriteI2C(sensor, I2C_ADDR, 0x00) < 0) {
        printf("Failed to write to I2C device. Exiting...\n");
        handle_sensor_absent(0);
    }
    adc_present = 1;

    int adc_fd = open("/dev/i2c-1", O_RDWR);
    if (adc_fd < 0) {
        printf("Failed to open I2C device. Exiting...\n");
        handle_sensor_absent(0);
    }

    struct iocb iocb;
    iocb.request_size = 2;
    iocb.data = (char *)malloc(iocb.request_size * sizeof(char));
    iocb.flags = I2C_M_RD;
    iocb.slave_addr = I2C_ADDR;

    if (ioctl(adc_fd, I2C_SET_I2CMB, &iocb) < 0) {
        printf("Failed to set I2C mode. Exiting...\n");
        handle_sensor_absent(0);
    }

    int adc = wiringPiI2COpen(adc_fd, I2C_SLAVE);
    if (adc == NULL) {
        printf("Failed to open I2C device. Exiting...\n");
        handle_sensor_absent(0);
    }

    while (running) {
        uint8_t data[2];
        uint16_t pressure;
        uint16_t temperature;

        if (i2c_read_byte(adc, I2C_ADDR, ADC0 + PRESSURE_CHANNEL + PRESSURE_OFFSET, &data[0]) == 0) {
            if (i2c_read_byte(adc, I2C_ADDR, ADC0 + PRESSURE_CHANNEL + PRESSURE_OFFSET + 1, &data[1]) == 0) {
                pressure = (uint16_t)(data[0] << 8 | data[1]);
                pressure = (pressure * PRESSURE_GAIN) + PRESSURE_OFFSET;
                printf("Pressure: %.2f %s\n", pressure / 1000.0, PRESSURE_UNIT);
            }
        }

        if (i2c_read_byte(adc, I2C_ADDR, ADC1 + NTC_CHANNEL + NTC_OFFSET, &data[0]) == 0) {
            if (i2c_read_byte(adc, I2C_ADDR, ADC1 + NTC_CHANNEL + NTC_OFFSET + 1, &data[1]) == 0) {
                temperature = (uint16_t)(data[0] << 8 | data[1]);
                temperature = (temperature * NTC_GAIN) + NTC_OFFSET;
                printf("Temperature: %.2f %s\n", temperature / 100.0, TEMPERATURE_UNIT);
            }
        }

        if (pressure > PRESSURE_THRESHOLD) {
            wiringPiPinDirection(GPIO17, PI_HIGH);
        } else {
            wiringPiPinDirection(GPIO17, PI_LOW);
        }

        usleep(1000000);
    }

    free(iocb.data);
    wiringPiI2Cclose(adc);
    wiringPiI2Cclose(sensor);
    return 0;
}

