#include <time.h>

#define SPI0_CE0 0
#define SPI0 0
#define MCP3008_ADDR 0x68
#define MCP3008_CHANNEL 0
#define MAX_ADC_VALUE 1023
#define CURRENT_LIMIT 10
#define CURRENT_THRESHOLD 10
#define LOG_FILE "current_log.txt"
#define LOG_FILE_MODE (O_APPEND | O_CREAT | O_WRONLY)
#define LOG_FILE_PERMISSIONS (S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH)

typedef struct {
    int fd;
    struct spi_ioc_transfer spi;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int current;
    int overcurrent;
} MotorControl;

MotorControl motor;

void spi_open() {
    motor.fd = open("/dev/spi0.0", O_RDWR);
    if (motor.fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }
}

void spi_close() {
    close(motor.fd);
}

void spi_init() {
    motor.fd = open("/dev/spi0.0", O_RDWR);
    if (motor.fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    motor.chip = gpiod_chip_open("/dev/gpiod");
    if (!motor.chip) {
        perror("Failed to open gpiod chip");
        exit(EXIT_FAILURE);
    }

    motor.line = gpiod_chip_request_line(motor.chip, GPIO8, GPIOF_DIR_OUT);
    if (!motor.line) {
        perror("Failed to request GPIO8 line");
        exit(EXIT_FAILURE);
    }

    motor.line->direction = GPIOF_DIR_OUT;
    motor.line->value = 1;
    if (gpiod_chip_request_value(motor.chip, motor.line, 0) < 0) {
        perror("Failed to request GPIO8 value");
        exit(EXIT_FAILURE);
    }

    spi_open();
}

void spi_transfer() {
    motor.spi.transfer_size = 1;
    motor.spi.transfer_buf = (unsigned char *) &motor.current;
    motor.spi.transfer_buf2 = (unsigned char *) 0;
    motor.spi.delay_usec = 0;
    motor.spi.delay_mode = SPI_DELAY_MODE_0;
    motor.spi.speed = SPI_SPEED_1MHZ;
    motor.spi.mode = SPI_MODE_0;

    if (ioctl(motor.fd, SPI_IOC_RDWR, &motor.spi) < 0) {
        perror("SPI ioctl failed");
        exit(EXIT_FAILURE);
    }

    motor.current = motor.spi.transfer_buf[0];
}

void spi_read_adc() {
    spi_transfer();
    if (motor.current > MAX_ADC_VALUE) {
        motor.overcurrent = 1;
    } else {
        motor.overcurrent = 0;
    }
}

void spi_write_gpio() {
    if (gpiod_chip_request_value(motor.chip, motor.line, 0) < 0) {
        perror("Failed to request GPIO8 value");
        exit(EXIT_FAILURE);
    }
    if (gpiod_chip_write_value(motor.chip, motor.line, 0) < 0) {
        perror("Failed to write GPIO8 value");
        exit(EXIT_FAILURE);
    }
}

void log_current() {
    char buffer[256];
    time_t rawtime;
    struct tm *timeinfo;
    FILE *log_file = fopen(LOG_FILE, LOG_FILE_MODE);
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    rawtime = time(NULL);
    timeinfo = localtime(&rawtime);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S ", timeinfo);
    fprintf(log_file, "%s%d\n", buffer, motor.current);
    fflush(log_file);
    fclose(log_file);
}

void handle_sigint() {
    log_current();
    spi_close();
    gpiod_chip_release(motor.chip);
    gpiod_line_free(motor.line);
    gpiod_chip_free(motor.chip);
    exit(EXIT_SUCCESS);
}

void handle_sigterm() {
    log_current();
    spi_close();
    gpiod_chip_release(motor.chip);
    gpiod_line_free(motor.line);
    gpiod_chip_free(motor.chip);
    exit(EXIT_SUCCESS);
}

void handle_error() {
    if (motor.overcurrent) {
        log_current();
        printf("OVERCURRENT EVENT\n");
        exit(EXIT_FAILURE);
    }
}

int main() {
    motor.overcurrent = 0;
    motor.current = 0;

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    spi_init();

    while (1) {
        spi_read_adc();
        if (motor.overcurrent) {
            handle_error();
        } else {
            log_current();
        }
        usleep(100000);
    }

    return 0;
}

