#include <syslog.h>
#include <sys/ioctl.h>
#include <linux/spi/spi.h>
#include <linux/i2c.h>
#include <linux/i2c-dev.h>
#include <linux/gpio.h>
#include <stdint.h>

#define SPI0_CE0 8
#define SPI0_SCLK 11
#define SPI0_MOSI 10
#define SPI0_MISO 9
#define SPI0_CS 0
#define SPI0_MODE 0
#define SPI0_SPEED 1000000

#define CO_LOG_FILE "co_log.txt"
#define CO_ALARM_PIN 4

#define CO_ALARM_ON 1
#define CO_ALARM_OFF 0

#define MAX_READS 10

typedef struct {
    int fd;
    struct spi_ioc_transfer spi;
    struct i2c_msg i2c_msg[2];
    struct i2c_rdwr_ioctl_data i2c_rdwr;
} spi_handle;

void spi_init(spi_handle *handle) {
    handle->fd = open("/dev/spi0.0", O_RDWR);
    if (handle->fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    handle->spi.transfer_len = 2;
    handle->spi.command = SPI_IOC_TRANSFER;
    handle->spi.delay_usecs = 0;
    handle->spi.speed_hz = SPI0_SPEED;
    handle->spi.use_spi_polarity = 0;
    handle->spi.use_spi_cs = 1;
    handle->spi.cs_select_bit = SPI0_CS;
    handle->spi.d Apostrophe = 0;

    handle->i2c_msg[0].addr = 0x48;
    handle->i2c_msg[0].flags = I2C_M_RD;
    handle->i2c_msg[0].buf = (uint8_t *)0x00;
    handle->i2c_msg[0].len = 1;

    handle->i2c_rdwr.msgs_num = 1;
    handle->i2c_rdwr.msgs = handle->i2c_msg;
}

void spi_read(spi_handle *handle, uint8_t *buf) {
    int ret = ioctl(handle->fd, I2C_RDWR, &handle->i2c_rdwr);
    if (ret < 0) {
        perror("Failed to read from SPI device");
        exit(EXIT_FAILURE);
    }

    ret = read(handle->fd, buf, 1);
    if (ret < 0) {
        perror("Failed to read from SPI device");
        exit(EXIT_FAILURE);
    }
}

void spi_close(spi_handle *handle) {
    close(handle->fd);
}

void alarm_on(int pin) {
    gpio_set_value(pin, CO_ALARM_ON);
}

void alarm_off(int pin) {
    gpio_set_value(pin, CO_ALARM_OFF);
}

void log_data(const char *filename, const char *format, ...) {
    struct timeval tv;
    struct tm *tm;
    char buffer[128];

    gettimeofday(&tv, NULL);
    tm = localtime(&tv.tv_sec);

    sprintf(buffer, format, tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,
            tm->tm_hour, tm->tm_min, tm->tm_sec);
    strcat(buffer, ",Voltage: ");
    sprintf(buffer + strlen(buffer), "%.2f V", *(float *)buf);

    FILE *file = fopen(filename, "a");
    if (file == NULL) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    fprintf(file, "%s\n", buffer);
    fclose(file);
}

void handle_spi_transfer_error(spi_handle *handle) {
    syslog(LOG_ERR, "SPI transfer error");
    alarm_off(CO_ALARM_PIN);
    usleep(1000000);
    alarm_on(CO_ALARM_PIN);
}

void handle_alarm(int sig) {
    alarm_off(CO_ALARM_PIN);
    spi_close(&handle);
    fclose(log_file);
    exit(EXIT_SUCCESS);
}

int main() {
    spi_handle handle;
    uint8_t buf[1];
    int ret;

    signal(SIGINT, handle_alarm);
    signal(SIGTERM, handle_alarm);

    spi_init(&handle);

    log_file = fopen(CO_LOG_FILE, "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    while (1) {
        ret = spi_read(&handle, buf);
        if (ret < 0) {
            handle_spi_transfer_error(&handle);
            continue;
        }

        float voltage = *(float *)buf;
        if (voltage > 2.5) {
            alarm_on(CO_ALARM_PIN);
        } else {
            alarm_off(CO_ALARM_PIN);
        }

        log_data(CO_LOG_FILE, "%s", "%s");
    }

    return 0;
}

