#include <signal.h>
#include <stdint.h>
#include <math.h>

#include <gpiod.h>

#define I2C_BUS 1
#define SDA_PIN 2
#define SCL_PIN 3
#define ADC_CHANNEL 0
#define ADC_GAIN 2
#define ADC_RESOLUTION 16
#define ADC_SAMPLE_RATE 1
#define PRESSURE_RANGE 100000
#define PRESSURE_MIN 0
#define PRESSURE_MAX 100000

#define LOG_FILE "pressure_log.txt"

typedef struct {
    int fd;
    int channel;
    int gain;
    int resolution;
    int sample_rate;
    int pressure_min;
    int pressure_max;
} ADS1115;

typedef struct {
    int fd;
    int timestamp_fd;
    int pressure_fd;
} Logger;

void sigint_handler(int signum) {
    if (logger.fd > 0) {
        close(logger.fd);
    }
    if (logger.timestamp_fd > 0) {
        close(logger.timestamp_fd);
    }
    if (logger.pressure_fd > 0) {
        close(logger.pressure_fd);
    }
    exit(EXIT_SUCCESS);
}

int init_gpio(int pin) {
    int fd = gpiod_open(NULL);
    if (fd < 0) {
        perror("gpiod_open");
        return -1;
    }

    int line_fd = gpiod_get_line(fd, pin);
    if (line_fd < 0) {
        perror("gpiod_get_line");
        gpiod_close(fd);
        return -1;
    }

    int direction_fd = gpiod_get_direction(line_fd, GPIODIRECTION_IN);
    if (direction_fd < 0) {
        perror("gpiod_get_direction");
        gpiod_close(fd);
        gpiod_close(line_fd);
        return -1;
    }

    int pullup_fd = gpiod_get_pullup(line_fd, GPIOPULLUP_ON);
    if (pullup_fd < 0) {
        perror("gpiod_get_pullup");
        gpiod_close(fd);
        gpiod_close(line_fd);
        gpiod_close(direction_fd);
        return -1;
    }

    gpiod_direction_set(line_fd, GPIODIRECTION_IN);
    gpiod_pullup_set(line_fd, GPIOPULLUP_OFF);
    gpiod_direction_set(line_fd, GPIODIRECTION_IN);

    gpiod_close(fd);
    gpiod_close(line_fd);
    gpiod_close(direction_fd);
    gpiod_close(pullup_fd);

    return 0;
}

int init_adc(ADS1115 *adc) {
    adc->fd = open("/dev/i2c-adc", O_RDWR);
    if (adc->fd < 0) {
        perror("open");
        return -1;
    }

    int addr = 0x68;
    if (ioctl(adc->fd, I2C_SLAVE, addr) < 0) {
        perror("ioctl");
        close(adc->fd);
        return -1;
    }

    adc->channel = ADC_CHANNEL;
    adc->gain = ADC_GAIN;
    adc->resolution = ADC_RESOLUTION;
    adc->sample_rate = ADC_SAMPLE_RATE;
    adc->pressure_min = PRESSURE_MIN;
    adc->pressure_max = PRESSURE_MAX;

