#define SPI_DEV "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_SPEED 1000000
#define SPI_BITS 8
#define SPI_CH 0
#define TMP36_PIN 1
#define MCP3208_VDD 3.3
#define MCP3208_VREF 3.3

typedef struct {
    int fd;
    struct spi_ioc_transfer spi;
    struct i2c_msg i2c_msg;
    struct i2c_rdwr_query i2c_rdwr;
    struct spi_ioc_transfer spi2;
    struct i2c_rdwr_query i2c_rdwr2;
} SpiDevice;

SpiDevice spi_device;

void spi_open() {
    spi_device.fd = open(SPI_DEV, O_RDWR);
    if (spi_device.fd < 0) {
        perror("open SPI device failed");
        exit(EXIT_FAILURE);
    }
}

void spi_close() {
    close(spi_device.fd);
}

void spi_transfer() {
    spi_device.spi.tx_buf = &spi_device.i2c_msg.buffer;
    spi_device.spi.rx_buf = &spi_device.i2c_msg.buffer;
    spi_device.spi.len = 2 * SPI_BITS;
    spi_device.spi.delay_usec = 0;
    spi_device.spi.flags = SPI_IOC_MODE | SPI_IOC_SPEED_hz | SPI_IOC@SuppressWarnings("unsupported")_BITS_PER_WORD;
    spi_device.spi.flags |= SPI_IOC@SuppressWarnings("unsupported")_NOSTANDARD@SuppressWarnings("unsupported")_MODE;
    spi_device.spi.flags |= SPI_IOC@SuppressWarnings("unsupported")_CAPTURE_MODE;

    spi_device.i2c_msg.tx_buf = &spi_device.i2c_msg.buffer;
    spi_device.i2c_msg.rx_buf = &spi_device.i2c_msg.buffer;
    spi_device.i2c_msg.len = 2 * SPI_BITS;
    spi_device.i2c_msg.tx_buf = &spi_device.i2c_msg.buffer;
    spi_device.i2c_msg.rx_buf = &spi_device.i2c_msg.buffer;
    spi_device.i2c_msg.tx_buf[0] = SPI_CH;
    spi_device.i2c_msg.tx_buf[1] = TMP36_PIN;
    spi_device.i2c_msg.flags = I2C_M_RD;

    spi_device.i2c_rdwr.tx_buf = &spi_device.i2c_msg.buffer;
    spi_device.i2c_rdwr.rx_buf = &spi_device.i2c_msg.buffer;
    spi_device.i2c_rdwr.len = 2 * SPI_BITS;
    spi_device.i2c_rdwr.flags = I2C_RDRW;

    if (ioctl(spi_device.fd, SPI_IOC_MESSAGE1, &spi_device.i2c_msg) < 0) {
        perror("SPI transfer failed");
        exit(EXIT_FAILURE);
    }

    spi_device.spi2.tx_buf = &spi_device.i2c_rdwr2.buffer;
    spi_device.spi2.rx_buf = &spi_device.i2c_rdwr2.buffer;
    spi_device.spi2.len = 2 * SPI_BITS;
    spi_device.spi2.delay_usec = 0;
    spi_device.spi2.flags = SPI_IOC_MODE | SPI_IOC_SPEED_hz | SPI_IOC@SuppressWarnings("unsupported")_BITS_PER_WORD;
    spi_device.spi2.flags |= SPI_IOC@SuppressWarnings("unsupported")_NOSTANDARD@SuppressWarnings("unsupported")_MODE;
    spi_device.spi2.flags |= SPI_IOC@SuppressWarnings("unsupported")_CAPTURE_MODE;

    spi_device.i2c_rdwr2.tx_buf = &spi_device.i2c_rdwr2.buffer;
    spi_device.i2c_rdwr2.rx_buf = &spi_device.i2c_rdwr2.buffer;
    spi_device.i2c_rdwr2.len = 2 * SPI_BITS;
    spi_device.i2c_rdwr2.flags = I2C_RDRW;

    if (ioctl(spi_device.fd, SPI_IOC_MESSAGE1, &spi_device.i2c_rdwr2) < 0) {
        perror("SPI transfer failed");
        exit(EXIT_FAILURE);
    }

    spi_device.spi2.tx_buf = &spi_device.i2c_rdwr2.buffer;
    spi_device.spi2.rx_buf = &spi_device.i2c_rdwr2.buffer;
    spi_device.spi2.len = 2 * SPI_BITS;
    spi_device.spi2.delay_usec = 0;
    spi_device.spi2.flags = SPI_IOC_MODE | SPI_IOC_SPEED_hz | SPI_IOC@SuppressWarnings("unsupported")_BITS_PER_WORD;
    spi_device.spi2.flags |= SPI_IOC@SuppressWarnings("unsupported")_NOSTANDARD@SuppressWarnings("unsupported")_MODE;
    spi_device.spi2.flags |= SPI_IOC@SuppressWarnings("unsupported")_CAPTURE_MODE;

    if (ioctl(spi_device.fd, SPI_IOC_MESSAGE1, &spi_device.i2c_rdwr2) < 0) {
        perror("SPI transfer failed");
        exit(EXIT_FAILURE);
    }

    uint16_t adc_value = spi_device.i2c_rdwr2.rx_buf[0];
    float temperature = (adc_value * MCP3208_VREF / 1024) - 0.5 * MCP3208_VREF;
    temperature /= MCP3208_VREF;
    temperature = temperature * 100;
    printf("%.2f\n", temperature);
}

void handle_sigint() {
    spi_close();
    exit(EXIT_SUCCESS);
}

void handle_sigterm() {
    spi_close();
    exit(EXIT_SUCCESS);
}

int main() {
    struct stat st;
    if (stat("/dev/spidev0.0", &st) < 0) {
        perror("stat failed");
        exit(EXIT_FAILURE);
    }

    spi_open();

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    FILE *fp = fopen("temperature_log.csv", "a");
    if (fp == NULL) {
        perror("fopen failed");
        exit(EXIT_FAILURE);
    }

    if (fstat(fileno(fp), &st) < 0) {
        perror("fstat failed");
        exit(EXIT_FAILURE);
    }

    if (st.st_size == 0) {
        fprintf(fp, "timestamp,temperature_celsius\n");
    }

    while (1) {
        spi_transfer();
        char timestamp[100];
        time_t t = time(NULL);
        strftime(timestamp, 100, "%Y-%m-%d %H:%M:%S", localtime(&t));
        fprintf(fp, "%s,%.2f\n", timestamp, temperature);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <sys/time.h>
#include <signal.h>
#include <math.h>

#define SPI0_CE0 8
#define SPI0_CH0 0
#define SPI0_CH1 1
#define SPI0_CH2 2
#define ADC_MAX 1024
#define IMPACT_THRESHOLD 500

typedef struct {
    int fd_spi;
    int fd_log;
    int fd_impact;
    int impact_detected;
} Config;

void sigint_handler(int signum) {
    if (Config.fd_spi != -1) {
        close(Config.fd_spi);
    }
    if (Config.fd_log != -1) {
        close(Config.fd_log);
    }
    if (Config.fd_impact != -1) {
        close(Config.fd_impact);
    }
    exit(EXIT_SUCCESS);
}

int init_spi(int channel, int speed, int mode) {
    int fd = open("/dev/spi0.0", O_RDWR);
    if (fd == -1) {
        perror("Failed to open SPI device");
        return -1;
    }
    if (ioctl(fd, SPI_IOC_MODE, mode) == -1) {
        perror("Failed to set SPI mode");
        close(fd);
        return -1;
    }
    if (ioctl(fd, SPI_IOC_SCLK, SPI0_CE0) == -1) {
        perror("Failed to set SPI clock line");
        close(fd);
        return -1;
    }
    if (ioctl(fd, SPI_IOC_DIO, SPI0_CE0) == -1) {
        perror("Failed to set SPI data line");
        close(fd);
        return -1;
    }
    if (ioctl(fd, SPI_IOC_SPEED_hz, speed) == -1) {
        perror("Failed to set SPI speed");
        close(fd);
        return -1;
    }
    Config.fd_spi = fd;
    return 0;
}

int init_log(const char *filename) {
    Config.fd_log = open(filename, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (Config.fd_log == -1) {
        perror("Failed to open log file");
        return -1;
    }
    return 0;
}

int init_impact(const char *filename) {
    Config.fd_impact = open(filename, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (Config.fd_impact == -1) {
        perror("Failed to open impact file");
        return -1;
    }
    return 0;
}

int read_adc(int fd, int channel) {
    int buffer[3];
    int n = 3;
    if (ioctl(fd, SPI_IOC_RD_DATA_LEN, &n) == -1) {
        perror("Failed to read SPI data length");
        return -1;
    }
    if (read(fd, buffer, n * 2) == -1) {
        perror("Failed to read SPI data");
        return -1;
    }
    int adc_value = (buffer[0] << 8) | buffer[1];
    if (adc_value < 0 || adc_value > ADC_MAX) {
        fprintf(stderr, "ADC value out of range: %d\n", adc_value);
        return -1;
    }
    return adc_value;
}

void log_impact() {
    if (Config.impact_detected) {
        fprintf(Config.fd_log, "%s,IMPACT DETECTED\n", get_time_string());
    }
}

void cleanup() {
    if (Config.fd_spi != -1) {
        close(Config.fd_spi);
    }
    if (Config.fd_log != -1) {
        close(Config.fd_log);
    }
    if (Config.fd_impact != -1) {
        close(Config.fd_impact);
    }
}

int get_time_string() {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    char buffer[20];
    sprintf(buffer, "%ld.%06ld", tv.tv_sec, tv.tv_usec);
    return buffer;
}

int main() {
    Config config;
    config.impact_detected = 0;

    signal(SIGINT, sigint_handler);

    if (init_spi(0, 1000000, 0) == -1) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_log("impact_log.txt") == -1) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_impact("impact_log.txt") == -1) {
        cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        int x = read_adc(Config.fd_spi, SPI0_CH0);
        int y = read_adc(Config.fd_spi, SPI0_CH1);
        int z = read_adc(Config.fd_spi, SPI0_CH2);

        if (isnan(x) || isnan(y) || isnan(z)) {
            fprintf(stderr, "ADC read failed\n");
            continue;
        }

        if (x > ADC_MAX || y > ADC_MAX || z > ADC_MAX) {
            fprintf(stderr, "ADC value out of range\n");
            continue;
        }

        if (x > IMPACT_THRESHOLD || y > IMPACT_THRESHOLD || z > IMPACT_THRESHOLD) {
            config.impact_detected = 1;
        }

        log_impact();

        fprintf(Config.fd_log, "%s,%d,%d,%d\n", get_time_string(), x, y, z);
    }

    cleanup();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <sys/time.h>
#include <signal.h>
#include <syslog.h>
#include <gpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x1A
#define I2C_DEV_NAME "/dev/i2c-" I2C_BUS

#define LOG_FILE "biometric_log.csv"
#define LOG_HEADER "timestamp,hrraw,spowraw,error\n"

#define MAX_SAMPLES 1000

typedef struct {
    int fd;
    struct gpiod_handle *handle;
    struct gpiod_line *line;
    struct gpiod_event *event;
    int error;
} Si1172;

Si1172 si1172;

void handle_sigint(int sig) {
    if (si1172.fd > 0) {
        close(si1172.fd);
    }
    gpiod_close(si1172.handle);
    exit(EXIT_SUCCESS);
}

int i2c_read(uint8_t *buf, int len) {
    int fd = open(I2C_DEV_NAME, O_RDWR);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C device: %s\n", strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    if (read(fd, buf, len) < 0) {
        syslog(LOG_ERR, "Failed to read I2C data: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

int i2c_read_16(uint8_t *buf, uint16_t *val) {
    if (i2c_read(buf, 2) < 0) {
        return 1;
    }
    *val = (buf[0] << 8) | buf[1];
    return 0;
}

int i2c_read_24(uint8_t *buf, uint32_t *val) {
    if (i2c_read(buf, 3) < 0) {
        return 1;
    }
    *val = (buf[0] << 16) | (buf[1] << 8) | buf[2];
    return 0;
}

int i2c_read_32(uint8_t *buf, uint32_t *val) {
    if (i2c_read(buf, 4) < 0) {
        return 1;
    }
    *val = (buf[0] << 24) | (buf[1] << 16) | (buf[2] << 8) | buf[3];
    return 0;
}

int i2c_read_8(uint8_t *buf, uint8_t *val) {
    if (i2c_read(buf, 1) < 0) {
        return 1;
    }
    *val = buf[0];
    return 0;
}

void log_data(uint32_t timestamp, uint16_t hrraw, uint16_t spowraw, int error) {
    char line[128];
    snprintf(line, sizeof(line), "%lu,%u,%u,%d\n", timestamp, hrraw, spowraw, error);
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        syslog(LOG_ERR, "Failed to open log file: %s\n", strerror(errno));
        return;
    }
    fputs(line, fp);
    fflush(fp);
    fclose(fp);
}

void si1172_init() {
    si1172.fd = -1;
    si1172.handle = NULL;
    si1172.line = NULL;
    si1172.event = NULL;
    si1172.error = 0;
}

void si1172_open() {
    if (si1172.fd != -1) {
        return;
    }
    si1172.fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (si1172.fd < 0) {
        si1172.error = 1;
        return;
    }
    if (ioctl(si1172.fd, I2C_SLAVE, I2C_ADDR) < 0) {
        si1172.error = 2;
        close(si1172.fd);
        return;
    }
    si1172.handle = gpiod_open("/dev/i2c-" I2C_BUS);
    if (si1172.handle == NULL) {
        si1172.error = 2;
        close(si1172.fd);
        return;
    }
    si1172.line = gpiod_get_line(si1172.handle, I2C_ADDR, 0);
    if (si1172.line == NULL) {
        si1172.error = 2;
        gpiod_close(si1172.handle);
        close(si1172.fd);
        return;
    }
    si1172.event = gpiod_get_event(si1172.line, 0);
    if (si1172.event == NULL) {
        si1172.error = 2;
        gpiod_close(si1172.handle);
        close(si1172.fd);
        return;
    }
    si1172.error = 0;
}

void si1172_close() {
    if (si1172.fd != -1) {
        close(si1172.fd);
    }
    if (si1172.handle != NULL) {
        gpiod_close(si1172.handle);
    }
    if (si1172.line != NULL) {
        gpiod_free_line(si1172.line);
    }
    if (si1172.event != NULL) {
        gpiod_free_event(si1172.event);
    }
}

int main() {
    si1172_init();
    signal(SIGINT, handle_sigint);
    si1172_open();
    FILE *fp = fopen(LOG_FILE, "w");
    if (fp == NULL) {
        syslog(LOG_ERR, "Failed to open log file: %s\n", strerror(errno));
        si1172_close();
        return EXIT_FAILURE;
    }
    fprintf(fp, "%s", LOG_HEADER);
    fflush(fp);
    uint32_t timestamp;
    uint16_t hrraw, spowraw;
    int error = 0;
    while (1) {
        timestamp = time(NULL);
        if (si1172.error == 0) {
            uint8_t buf[4];
            if (i2c_read_24(buf, &timestamp)) {
                error = 1;
            } else {
                if (i2c_read_16(buf, &hrraw)) {
                    error = 1;
                } else {
                    if (i2c_read_16(buf + 2, &spowraw)) {
                        error = 1;
                    } else {
                        error = 0;
                    }
                }
            }
        }
        log_data(timestamp, hrraw, spowraw, error);
        usleep(1000000); // 1 second delay
    }
    si1172_close();
    fclose(fp);
    return EXIT_SUCCESS;
}

