#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <sys/sigaction.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <string.h>
#include <math.h>

#define SPI_DEV "/dev/spidev0.0"
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_BITS 8
#define SPI_MODE 0
#define SPI_TRANSFER_SIZE 3

#define SPI_READ 1
#define SPI_WRITE 0

#define SPI_CS_GPIO 8
#define SPI_MOSI_GPIO 10
#define SPI_MISO_GPIO 9
#define SPI_SCLK_GPIO 11

#define SPI_CS_PIN 1 << SPI_CS_GPIO
#define SPI_MOSI_PIN 1 << SPI_MOSI_GPIO
#define SPI_MISO_PIN 1 << SPI_MISO_GPIO
#define SPI_SCLK_PIN 1 << SPI_SCLK_GPIO

#define SPI_CS_RELEASE 0
#define SPI_MOSI_RELEASE 0
#define SPI_MISO_RELEASE 0
#define SPI_SCLK_RELEASE 0

typedef struct {
    int fd;
    int cs_gpio;
    int mosi_gpio;
    int miso_gpio;
    int sclk_gpio;
} SpiDevConfig;

void spi_init(SpiDevConfig *config) {
    config->fd = open(SPI_DEV, O_RDWR);
    if (config->fd < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    config->cs_gpio = SPI_CS_GPIO;
    config->mosi_gpio = SPI_MOSI_GPIO;
    config->miso_gpio = SPI_MISO_GPIO;
    config->sclk_gpio = SPI_SCLK_GPIO;

    if (config->cs_gpio < 0 || config->mosi_gpio < 0 || config->miso_gpio < 0 || config->sclk_gpio < 0) {
        perror("GPIO pin error");
        exit(EXIT_FAILURE);
    }

    if (ioctl(config->fd, SPI_IOC_WR_MOSI, SPI_CS_PIN) < 0) {
        perror("SPI MOSI write");
        exit(EXIT_FAILURE);
    }
    if (ioctl(config->fd, SPI_IOC_WR_MISO, SPI_CS_PIN) < 0) {
        perror("SPI MISO write");
        exit(EXIT_FAILURE);
    }
    if (ioctl(config->fd, SPI_IOC_WR_SCLK, SPI_CS_PIN) < 0) {
        perror("SPI SCLK write");
        exit(EXIT_FAILURE);
    }
    if (ioctl(config->fd, SPI_IOC_WR_CS, SPI_CS_RELEASE) < 0) {
        perror("SPI CS write");
        exit(EXIT_FAILURE);
    }

    if (ioctl(config->fd, SPI_IOC_RD_MOSI, SPI_CS_RELEASE) < 0) {
        perror("SPI MOSI read");
        exit(EXIT_FAILURE);
    }
    if (ioctl(config->fd, SPI_IOC_RD_MISO, SPI_CS_RELEASE) < 0) {
        perror("SPI MISO read");
        exit(EXIT_FAILURE);
    }
    if (ioctl(config->fd, SPI_IOC_RD_SCLK, SPI_CS_RELEASE) < 0) {
        perror("SPI SCLK read");
        exit(EXIT_FAILURE);
    }
    if (ioctl(config->fd, SPI_IOC_RD_CS, SPI_CS_RELEASE) < 0) {
        perror("SPI CS read");
        exit(EXIT_FAILURE);
    }

    if (ioctl(config->fd, SPI_IOC_WR_MODE, SPI_MODE) < 0) {
        perror("SPI mode write");
        exit(EXIT_FAILURE);
    }
    if (ioctl(config->fd, SPI_IOC_WR_BIT, SPI_BITS) < 0) {
        perror("SPI bit width write");
        exit(EXIT_FAILURE);
    }
    if (ioctl(config->fd, SPI_IOC_WR_SPD, SPI_SPEED) < 0) {
        perror("SPI speed write");
        exit(EXIT_FAILURE);
    }
}

void spi_read(SpiDevConfig *config, int *raw_data) {
    int buffer[SPI_TRANSFER_SIZE];
    int result;

    config->cs_gpio = SPI_CS_RELEASE;
    if (ioctl(config->fd, SPI_IOC_CS, SPI_CS_RELEASE) < 0) {
        perror("SPI CS release");
        exit(EXIT_FAILURE);
    }

    result = ioctl(config->fd, SPI_IOC_RD_DATA, buffer);
    if (result < 0) {
        perror("SPI read");
        exit(EXIT_FAILURE);
    }

    *raw_data = buffer[0] << 8 | buffer[1] | (buffer[2] & 0x07);
}

void spi_write(SpiDevConfig *config, int value) {
    int buffer[SPI_TRANSFER_SIZE];
    int result;

    config->cs_gpio = SPI_CS_RELEASE;
    if (ioctl(config->fd, SPI_IOC_CS, SPI_CS_RELEASE) < 0) {
        perror("SPI CS release");
        exit(EXIT_FAILURE);
    }

    buffer[0] = value >> 8;
    buffer[1] = value >> 0;
    buffer[2] = 0;

    result = ioctl(config->fd, SPI_IOC_WR_DATA, buffer);
    if (result < 0) {
        perror("SPI write");
        exit(EXIT_FAILURE);
    }
}

void spi_release(SpiDevConfig *config) {
    config->cs_gpio = SPI_CS_RELEASE;
    if (ioctl(config->fd, SPI_IOC_CS, SPI_CS_RELEASE) < 0) {
        perror("SPI CS release");
        exit(EXIT_FAILURE);
    }
    config->mosi_gpio = SPI_MOSI_RELEASE;
    if (ioctl(config->fd, SPI_IOC_RD_MOSI, SPI_MOSI_RELEASE) < 0) {
        perror("SPI MOSI release");
        exit(EXIT_FAILURE);
    }
    config->miso_gpio = SPI_MISO_RELEASE;
    if (ioctl(config->fd, SPI_IOC_RD_MISO, SPI_MISO_RELEASE) < 0) {
        perror("SPI MISO release");
        exit(EXIT_FAILURE);
    }
    config->sclk_gpio = SPI_SCLK_RELEASE;
    if (ioctl(config->fd, SPI_IOC_RD_SCLK, SPI_SCLK_RELEASE) < 0) {
        perror("SPI SCLK release");
        exit(EXIT_FAILURE);
    }
}

void sig_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        SpiDevConfig config;
        config.fd = 0;
        config.cs_gpio = 0;
        config.mosi_gpio = 0;
        config.miso_gpio = 0;
        config.sclk_gpio = 0;

        spi_release(&config);
        close(config.fd);
        exit(EXIT_SUCCESS);
    }
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);

    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    SpiDevConfig config;
    config.fd = 0;
    config.cs_gpio = 0;
    config.mosi_gpio = 0;
    config.miso_gpio = 0;
    config.sclk_gpio = 0;

    spi_init(&config);

    while (1) {
        int raw_data;
        spi_read(&config, &raw_data);

        double moisture = (raw_data * 100.0) / 1023.0;
        printf("Raw ADC: %d, Moisture: %.2f%%\n", raw_data, moisture);

        sleep(5);
    }

    return 0;
}

