#include <stdint.h>

#define SPI0_CE0 8
#define SPI0_MISO 9
#define SPI0_MOSI 10
#define SPI0_SCLK 11
#define ADC_ADDR 0x68

#define SPI_MODE 0
#define SPI_SPEED 1000000

#define LOG_FILE "pressure.log"

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, exiting...\n", signum);
        exit(EXIT_SUCCESS);
    }
}

int spi_init() {
    int fd;
    struct spi_ioc_transfer transfer;
    struct spi_device *dev;

    fd = open("/dev/spi0.0", O_RDWR);
