#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/ioctl.h>
#include <string.h>
#include <signal.h>

#define SPI_DEV "/dev/spidev0.0"
#define SPI_CHANNEL 0
#define SPI_MODE 0
#define SPI_SPEED 1e6
#define SPI_BITS 8
#define SPI_NBYTES 3

#define SPI_CMD_START 0x00
#define SPI_CMD_CONFIG 0x01
#define SPI_CMD_DONT_CARE 0x00

#define SPI_BUFFER_SIZE 1024

void handle_error(const char *msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        if (spidev_fd != -1) {
            close(spidev_fd);
        }
        exit(EXIT_SUCCESS);
    }
}

int main() {
    struct spi_ioc_transfer spi_transfer;
    int spidev_fd = -1;

    // Set up signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open SPI device
    if ((spidev_fd = open(SPI_DEV, O_RDWR)) == -1) {
        handle_error("Failed to open SPI device");
    }

    // Initialize SPI transfer structure
    spi_transfer.msb = SPI_CMD_START;
    spi_transfer.msbs = SPI_CMD_CONFIG;
    spi_transfer.msbbs = SPI_CMD_DONT_CARE;
    spi_transfer.delay_usec = 0;
    spi_transfer.speed_hz = SPI_SPEED;
    spi_transfer.bits_per_word = SPI_BITS;
    spi_transfer.lsb_mode = SPI_LSB_FIRST;
    spi_transfer.cs_change = 0;
    spi_transfer.cs_pol = SPI_CS_HIGH;
    spi_transfer.cs_active_low = 1;
    spi_transfer.tx_buf = NULL;
    spi_transfer.rx_buf = NULL;
    spi_transfer.len = SPI_NBYTES;

    // Configure SPI device
    if (ioctl(spidev_fd, SPI_IOC_WR_MODE, SPI_MODE) == -1) {
        handle_error("Failed to configure SPI mode");
    }
    if (ioctl(spidev_fd, SPI_IOC_WR_BITS_PER_WORD, SPI_BITS) == -1) {
        handle_error("Failed to configure SPI bits per word");
    }
    if (ioctl(spidev_fd, SPI_IOC_WR_SPEED_HZ, SPI_SPEED) == -1) {
        handle_error("Failed to configure SPI speed");
    }

    // Read SPI data
    ssize_t bytes_read = 0;
    while (1) {
        if (ioctl(spidev_fd, SPI_IOC_RD_DATA, &spi_transfer) == -1) {
            handle_error("Failed to read SPI data");
        }
        bytes_read = read(spidev_fd, spi_transfer.buffer, SPI_NBYTES);
        if (bytes_read != SPI_NBYTES) {
            handle_error("Failed to read SPI data");
        }

        // Compute moisture percentage
        int adc_value = (spi_transfer.buffer[0] << 8) | (spi_transfer.buffer[1] << 0);
        int moisture = (adc_value * 100) / 1023;

        // Clamp moisture to 0-100%
        if (moisture < 0) {
            moisture = 0;
        } else if (moisture > 100) {
            moisture = 100;
        }

        printf("Moisture: %d%%\n", moisture);

        // Sleep for 5 seconds
        sleep(5);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <string.h>
#include <signal.h>
#include <sys/sigaction.h>
#include <sys/ioctl.h>
#include <linux/spi/spi.h>
#include <linux/i2c.h>
#include <linux/i2c-dev.h>
#include <linux/mcp3008.h>

#define SPI0_CE0 8
#define SPI0_SPEED 1000000
#define SPI0_MODE 0
#define MCP3008_ADDR 0x68
#define MCP3008_CHANNELS 4

#define SPI_DEVICE "/dev/spi0.0"
#define I2C_DEVICE "/dev/i2c-0"

#define LOG_FILE "environmental_data.csv"

volatile sig_atomic_t exit_flag = 0;

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        exit_flag = 1;
    }
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    struct spi_ioc_transfer spi_transfer;
    spi_transfer.msb = 1;
    spi_transfer.msbs = 1;
    spi_transfer.len = 1;
    spi_transfer.delay_us = 0;
    spi_transfer.speed_hz = SPI0_SPEED;
    spi_transfer.use_last = 0;
    spi_transfer.transfer_mode = SPI_MODE_0;

    struct i2c_msg i2c_msg[2];
    struct i2c_rdwr_ioctl_data i2c_data;

    i2c_msg[0].addr = MCP3008_ADDR;
    i2c_msg[0].flags = I2C_M_RD;
    i2c_msg[0].buf = (unsigned char *)&spi_transfer;
    i2c_msg[0].len = sizeof(spi_transfer);

    i2c_msg[1].addr = MCP3008_ADDR;
    i2c_msg[1].flags = I2C_M_RD;
    i2c_msg[1].buf = NULL;
    i2c_msg[1].len = 0;

    i2c_data.msgs = i2c_msg;
    i2c_data.nummsgs = 2;

    if (ioctl(spi_fd, I2C_RDWR, &i2c_data) < 0) {
        perror("Failed to send I2C message");
        return 1;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return 1;
    }

    while (!exit_flag) {
        if (ioctl(spi_fd, SPI_IOC_RD_SINGLE, &spi_transfer) < 0) {
            perror("Failed to read SPI data");
            return 1;
        }

        int channel_values[MCP3008_CHANNELS];
        for (int i = 0; i < MCP3008_CHANNELS; i++) {
            channel_values[i] = spi_transfer.value;
        }

        for (int i = 0; i < MCP3008_CHANNELS; i++) {
            fprintf(log_file, "%f,%.2f\n", (double)time(NULL), (double)channel_values[i] / 1024.0);
        }

        fflush(log_file);
    }

    fclose(log_file);
    close(spi_fd);

    return 0;
}

