#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <wiringPi.h>
#include <wiringPiGpio.h>

#define I2C_BUS "/dev/i2c‑1"
#define I2C_ADDR 0x3D
#define IR_SENSOR_ADDR 0x38
#define ADC_CHANNEL 0x00
#define CALIBRATION_SAMPLES 10
#define CALIBRATION_SAMPLE_INTERVAL 50
#define SAMPLE_INTERVAL 200
#define RELAY_PIN 17
#define REED_PIN 27
#define RELAY_ON_TIME 3000
#define LOG_FILE "/var/log/door_events.log"

void calibrate_ads1115() {
    int fd = open("/dev/i2c‑1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        exit(1);
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        exit(1);
    }

    int samples[CALIBRATION_SAMPLES];
    for (int i = 0; i < CALIBRATION_SAMPLES; i++) {
        if (ioctl(fd, I2C_RDWR, (unsigned long)&samples[i], 1) < 0) {
            perror("Failed to read I2C data");
            close(fd);
            exit(1);
        }
    }

    double calibration_threshold = 0;
    for (int i = 0; i < CALIBRATION_SAMPLES; i++) {
        calibration_threshold += samples[i];
    }
    calibration_threshold /= CALIBRATION_SAMPLES;

    printf("Calibration threshold: %f\n", calibration_threshold);

    close(fd);
}

void read_ads1115(int fd, double *threshold, double *current) {
    if (ioctl(fd, I2C_RDWR, (unsigned long)&samples[0], 1) < 0) {
        perror("Failed to read I2C data");
        return;
    }

    *current = samples[0] * 0.004096; // ADC conversion factor
    if (*current < *threshold) {
        printf("Door opened\n");
        digitalWrite(REED_PIN, LOW);
        delay(RELAY_ON_TIME);
        digitalWrite(REED_PIN, HIGH);
    } else {
        printf("Door not opened\n");
    }
}

int main() {
    wiringPiSetupGpio();
    pinMode(RELAY_PIN, OUTPUT);
    pinMode(REED_PIN, INPUT);
    pullUpDnControl(REED_PIN, PUD_UP);

    int fd = open("/dev/i2c‑1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        exit(1);
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        exit(1);
    }

    calibrate_ads1115();

    double threshold;
    double current;
    double calibration_threshold = 0;
    calibrate_ads1115();

    while (1) {
        if (ioctl(fd, I2C_RDWR, (unsigned long)&samples[0], 1) < 0) {
            perror("Failed to read I2C data");
            continue;
        }

        calibration_threshold = 0;
        for (int i = 0; i < CALIBRATION_SAMPLES; i++) {
            calibration_threshold += samples[i];
        }
        calibration_threshold /= CALIBRATION_SAMPLES;

        double current = samples[0] * 0.004096;

        if (current < calibration_threshold) {
            printf("Door opened\n");
            digitalWrite(REED_PIN, LOW);
            delay(RELAY_ON_TIME);
            digitalWrite(REED_PIN, HIGH);
        } else {
            printf("Door not opened\n");
        }

        write(fd, (unsigned char *)&samples[0], 1);
        delay(SAMPLE_INTERVAL);
    }

    close(fd);
    return 0;
}

