#include <signal.h>
#include <syslog.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <linux/sensors.h>
#include <linux/delay.h>
#include <wiringPi.h>
#include <wiringPiGpio.h>

#define SS49E_ADDR 0x49E
#define ADC_CHANNEL 0
#define ADC_SAMPLE_RATE 1
#define THRESHOLD 500
#define BUFFER_SIZE 10
#define LOG_FILE "/var/log/pi_honeywell.log"

#define I2C_DEVICE "/dev/i2c-1"

#define GPIO27 27

typedef struct {
    int16_t value;
    int16_t buffer[BUFFER_SIZE];
    int16_t sum;
    int16_t count;
} SensorData;

static SensorData sensor_data;

static int i2c_fd;
static int adc_fd;
static int gpio_fd;

static void handle_i2c_error(int err) {
    if (err < 0) {
        syslog(LOG_ERR, "I2C error: %d", err);
        exit(EXIT_FAILURE);
    }
}

static void handle_adc_error(int err) {
    if (err < 0) {
        syslog(LOG_ERR, "ADC error: %d", err);
        exit(EXIT_FAILURE);
    }
}

static void handle_gpio_error(int err) {
    if (err < 0) {
        syslog(LOG_ERR, "GPIO error: %d", err);
        exit(EXIT_FAILURE);
    }
}

static void init_i2c() {
    if ((i2c_fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        handle_i2c_error(errno);
    }
    if (ioctl(i2c_fd, I2C_SLAVE, SS49E_ADDR) < 0) {
        handle_i2c_error(errno);
    }
}

static void init_adc() {
    if ((adc_fd = open("/dev/adc1", O_RDWR)) < 0) {
        handle_adc_error(errno);
    }
    if (ioctl(adc_fd, I2C_GET_ID, 0) < 0) {
        handle_adc_error(errno);
    }
    if (ioctl(adc_fd, I2C_SET_CONFIG, 0) < 0) {
        handle_adc_error(errno);
    }
    if (ioctl(adc_fd, I2C_SET_CONFIG, ADC_CONFIG_SINGLE) < 0) {
        handle_adc_error(errno);
    }
    if (ioctl(adc_fd, I2C_SET_CONFIG, ADC_CONFIG_GAIN_2) < 0) {
        handle_adc_error(errno);
    }
    if (ioctl(adc_fd, I2C_SET_CONFIG, ADC_CONFIG_RESOLUTION_12BIT) < 0) {
        handle_adc_error(errno);
    }
    if (ioctl(adc_fd, I2C_SET_CONFIG, ADC_CONFIG_SAMPLE_RATE_1) < 0) {
        handle_adc_error(errno);
    }
}

static void init_gpio() {
    if ((gpio_fd = wiringPiGpioInit()) < 0) {
        handle_gpio_error(errno);
    }
    if (wiringPiGpioSetMode(gpio_fd, INPUT_OUTPUT, GPIO27) < 0) {
        handle_gpio_error(errno);
    }
    if (wiringPiGpioSetPullUpDnControl(gpio_fd, GPIO27, 0) < 0) {
        handle_gpio_error(errno);
    }
}

static void shutdown_gpio() {
    if (wiringPiGpioSetMode(gpio_fd, INPUT, GPIO27) < 0) {
        handle_gpio_error(errno);
    }
    if (wiringPiGpioUnexport(gpio_fd) < 0) {
        handle_gpio_error(errno);
    }
}

static void log_data(int value) {
    char log_msg[256];
    snprintf(log_msg, sizeof(log_msg), "ADC value: %d V, Gauss: %d, Timestamp: %s", value, sensor_data.value, ctime());
    syslog(LOG_INFO, log_msg);
}

static void log_threshold(int value) {
    char log_msg[256];
    snprintf(log_msg, sizeof(log_msg), "Threshold crossed: %d Gauss, Timestamp: %s", value, ctime());
    syslog(LOG_INFO, log_msg);
}

static void log_error(int err) {
    char log_msg[256];
    snprintf(log_msg, sizeof(log_msg), "Error: %d, Timestamp: %s", err, ctime());
    syslog(LOG_ERR, log_msg);
}

static void shutdown_gpio_on_threshold() {
    if (wiringPiGpioWrite(gpio_fd, GPIO27, 1) < 0) {
        handle_gpio_error(errno);
    }
}

static void shutdown_gpio_on_signal(int signum) {
    shutdown_gpio();
    exit(EXIT_SUCCESS);
}

static void shutdown_gpio_on_exit(int signum) {
    shutdown_gpio();
    exit(EXIT_SUCCESS);
}

static void shutdown_gpio_on_signal_handler(int signum) {
    shutdown_gpio_on_signal(signum);
}

static void shutdown_gpio_on_exit_handler(int signum) {
    shutdown_gpio_on_exit(signum);
