} SensorHandler;

void spi_init(SensorHandler *handler) {
    handler->fd = open("/dev/spi0.0", O_RDWR);
    if (handler->fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    handler->spi_params.msb_first = 0;
    handler->spi_params.mode = SPI_MODE0;
    handler->spi_params.bits_per_line = 8;
    handler->spi_params.line_order = SPI_LINE_ORDER_MSBFIRST;
    handler->spi_params.delay_useconds = 0;

    if (ioctl(handler->fd, SPI_IOC_WR_MODE, &handler->spi_params.mode) < 0) {
        perror("Failed to set SPI mode");
        close(handler->fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(handler->fd, SPI_IOC_WR_BITS_PER_LINE, &handler->spi_params.bits_per_line) < 0) {
        perror("Failed to set bits per line");
        close(handler->fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(handler->fd, SPI_IOC_WR_LINE_ORDER, &handler->spi_params.line_order) < 0) {
        perror("Failed to set line order");
        close(handler->fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(handler->fd, SPI_IOC_WR_SPEED_hz, &handler->spi_params.speed_hz) < 0) {
        perror("Failed to set SPI speed");
        close(handler->fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(handler->fd, SPI_IOC_RD_SPEED_hz, &handler->spi_params.speed_hz) < 0) {
        perror("Failed to read SPI speed");
        close(handler->fd);
        exit(EXIT_FAILURE);
    }

