#define SPI0_CE0 8
#define SPI0_CS 10
#define SPI0_MOSI 11
#define SPI0_MISO 12
#define SPI0_SCLK 13
#define SPI0_MISO 12
#define SPI0_MOSI 11
#define SPI0_SCLK 13
#define SPI0_CE 8
#define SPI0_D0 9
#define SPI0_D1 7
#define SPI0_D2 6
#define SPI0_D3 5
#define SPI0_D4 4
#define SPI0_D5 3
#define SPI0_D6 2
#define SPI0_D7 1
#define SPI0_D8 0
#define SPI_MODE 0
#define SPI_FREQ 1000000
#define SPI_WORD 8
#define SPI_CHANNEL 0
#define SPI_READ 1
#define SPI_MAX_RETRIES 3
#define SPI_RETRY_DELAY 100000

#define LOG_FILE "alcohol_log.txt"
#define LOG_FORMAT "%Y-%m-%dT%H:%M:%S.%03dZ"

int spi_fd;
int spi_adc;
int gpio_fd;
struct gpiod_handle handle;
struct gpiod_line *gpio_line;
struct spi_ioc_transfer spi_transfer;
struct i2c_msg i2c_msg[2];
char log_buffer[256];
char log_buffer_time[256];
char log_buffer_data[256];
char log_buffer_error[256];

void handle_error(int error_code, const char *message) {
    fprintf(stderr, "Error: %s (%d)\n", message, error_code);
    exit(EXIT_FAILURE);
}

void handle_sigint(int signum) {
    handle_error(signum, "SIGINT received, shutting down gracefully");
    gpiod_close(&handle);
    close(spi_fd);
    close(gpio_fd);
    exit(EXIT_SUCCESS);
}

void handle_sigterm(int signum) {
    handle_error(signum, "SIGTERM received, shutting down gracefully");
    gpiod_close(&handle);
    close(spi_fd);
    close(gpio_fd);
    exit(EXIT_SUCCESS);
}

int spi_read_adc() {
    int retries = 0;
    int adc_value = 0;
    while (retries < SPI_MAX_RETRIES) {
        memset(i2c_msg, 0, sizeof(i2c_msg));
        i2c_msg[0].addr = 0x48; // MCP3008 I2C address
        i2c_msg[0].flags = I2C_M_RD;
        i2c_msg[0].len = 1;
        i2c_msg[0].buf = &adc_value;
        i2c_msg[1].addr = 0x48;
        i2c_msg[1].flags = I2C_M_RD;
        i2c_msg[1].len = 1;
        i2c_msg[1].buf = &adc_value;

        if (ioctl(spi_fd, I2C_RDWR, i2c_msg) < 0) {
            handle_error(errno, "SPI read failed");
        }

        if (adc_value < 0 || adc_value > 1023) {
            handle_error(errno, "ADC read error");
        }

        if (adc_value == 0 || adc_value == 1023) {
            handle_error(errno, "Sensor absent");
        }

        return adc_value;
    }

    handle_error(errno, "Failed to read ADC after %d retries", retries);
    return 0;
}

void log_measurement(int adc_value) {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    snprintf(log_buffer_time, sizeof(log_buffer_time), LOG_FORMAT, timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_mday, timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec);

    snprintf(log_buffer_data, sizeof(log_buffer_data), "%s, %d", log_buffer_time, adc_value);

    if (adc_value < 20) {
        snprintf(log_buffer_error, sizeof(log_buffer_error), "Sobriety confirmed.");
    } else if (adc_value > 50) {
        snprintf(log_buffer_error, sizeof(log_buffer_error), "Alcohol detected! Limit exceeded.");
    } else {
        snprintf(log_buffer_error, sizeof(log_buffer_error), "Alcohol level within acceptable range.");
    }

    snprintf(log_buffer, sizeof(log_buffer), "%s, %s\n", log_buffer_data, log_buffer_error);

    if (write(STDERR_FILENO, log_buffer, strlen(log_buffer)) < 0) {
        handle_error(errno, "Failed to write to log file");
    }

    if (write(STDOUT_FILENO, log_buffer, strlen(log_buffer)) < 0) {
        handle_error(errno, "Failed to write to log file");
    }

    if (fopen(LOG_FILE, "a") == NULL) {
        handle_error(errno, "Failed to open log file");
    }

    if (fprintf(fopen(LOG_FILE, "a"), log_buffer) < 0) {
        handle_error(errno, "Failed to write to log file");
    }

    if (fclose(fopen(LOG_FILE, "a")) < 0) {
        handle_error(errno, "Failed to close log file");
    }
}

int main() {
    struct gpiod_line *gpio_line;
    struct gpiod_chip *gpio_chip;
    struct gpiod_edge *gpio_edge;
    int gpio_value;

    gpiod_init(&handle);
    gpio_chip = gpiod_chip_open(&handle, "gpio");
    gpio_line = gpiod_chip_get_line(gpio_chip, SPI0_CE0);
    gpio_edge = gpiod_chip_get_line(gpio_chip, SPI0_D0);

    if (gpio_line == NULL || gpio_edge == NULL) {
        handle_error(errno, "Failed to get GPIO line");
    }

    if (gpiod_line_request_edge(gpio_line, GPIOD_EDGE_BOTH, &gpio_edge) < 0) {
        handle_error(errno, "Failed to request edge");
    }

    if (gpiod_chip_request_fd(gpio_chip, SPI0_CE0, &spi_fd) < 0) {
        handle_error(errno, "Failed to request SPI device");
    }

    if (gpiod_chip_request_fd(gpio_chip, SPI0_D0, &spi_fd) < 0) {
        handle_error(errno, "Failed to request SPI device");
    }

    if (gpiod_chip_request_fd(gpio_chip, SPI0_CS, &spi_fd) < 0) {
        handle_error(errno, "Failed to request SPI device");
    }

    if (gpiod_chip_request_fd(gpio_chip, SPI0_MOSI, &spi_fd) < 0) {
        handle_error(errno, "Failed to request SPI device");
    }

    if (gpiod_chip_request_fd(gpio_chip, SPI0_MISO, &spi_fd) < 0) {
        handle_error(errno, "Failed to request SPI device");
    }

    if (gpiod_chip_request_fd(gpio_chip, SPI0_SCLK, &spi_fd) < 0) {
        handle_error(errno, "Failed to request SPI device");
    }

    if (gpiod_chip_request_fd(gpio_chip, SPI0_CE, &spi_fd) < 0) {
        handle_error(errno, "Failed to request SPI device");
    }

    if (gpiod_chip_request_fd(gpio_chip, SPI0_D1, &spi_fd) < 0) {
        handle_error(errno, "Failed to request SPI device");
    }

    if (gpiod_chip_request_fd(gpio_chip, SPI0_D2, &spi_fd) < 0) {
        handle_error(errno, "Failed to request SPI device");
    }

    if (gpiod_chip_request_fd(gpio_chip, SPI0_D3, &spi_fd) < 0) {
        handle_error(errno, "Failed to request SPI device");
    }

    if (gpiod_chip_request_fd(gpio_chip, SPI0_D4, &spi_fd) < 0) {
        handle_error(errno, "Failed to request SPI device");
    }

    if (gpiod_chip_request_fd(gpio_chip, SPI0_D5, &spi_fd) < 0) {
        handle_error(errno, "Failed to request SPI device");
    }

    if (gpiod_chip_request_fd(gpio_chip, SPI0_D6, &spi_fd) < 0) {
        handle_error(errno, "Failed to request SPI device");
    }

    if (gpiod_chip_request_fd(gpio_chip, SPI0_D7, &spi_fd) < 0) {
        handle_error(errno, "Failed to request SPI device");
    }

    if (gpiod_chip_request_fd(gpio_chip, SPI0_D8, &spi_fd) < 0) {
        handle_error(errno, "Failed to request SPI device");
    }

    spi_transfer.multiple = 0;
    spi_transfer.speed = SPI_FREQ;
    spi_transfer.delay_usec = 0;
    spi_transfer.flags = SPI_MODE;
    spi_transfer.len = SPI_WORD;
    spi_transfer.buf = &spi_transfer.buf;

    spi_adc = spi_open(gpio_chip, SPI0_CE0, SPI_MODE, SPI_FREQ, SPI_WORD, SPI_READ);

    if (spi_adc < 0) {
        handle_error(errno, "Failed to open SPI device");
    }

    while (1) {
        int adc_value = spi_read_adc();
        log_measurement(adc_value);

        if (gpio_edge->edge == GPIOD_EDGE_RISING) {
            gpio_value = gpio_get_value(gpio_edge);
            if (gpio_value == 1) {
                gpiod_line_request_edge(gpio_line, GPIOD_EDGE_FALLING, &gpio_edge);
            } else {
                gpiod_line_request_edge(gpio_line, GPIOD_EDGE_RISING, &gpio_edge);
            }
        } else if (gpio_edge->edge == GPIOD_EDGE_FALLING) {
            gpio_value = gpio_get_value(gpio_edge);
            if (gpio_value == 1) {
                gpiod_line_request_edge(gpio_line, GPIOD_EDGE_RISING, &gpio_edge);
            } else {
                gpiod_line_request_edge(gpio_line, GPIOD_EDGE_FALLING, &gpio_edge);
            }
        }

        sleep(1);
    }

    gpiod_close(&handle);
    return 0;
}

