    transfer.ioctl = SPI_IOC_WR_MODE8;
    transfer.multiple = 0;
    transfer.delay_usec = 0;
    transfer.speed_hz = SPI0_SPEED;
    ret = ioctl(state.spi_fd, SPI_IOC_RDWR, &transfer);
    if (ret < 0) {
        fprintf(stderr, "Failed to set SPI mode\n");
        exit(EXIT_FAILURE);
    }
    transfer.ioctl = SPI_IOC_RD_MODE8;
    ret = ioctl(state.spi_fd, SPI_IOC_RD_MODE8, &transfer);
    if (ret < 0) {
        fprintf(stderr, "Failed to read SPI mode\n");
        exit(EXIT_FAILURE);
    }
}

void init_mcp3008() {
    int ret;
    struct i2c_msg msg;
    struct i2c_rdwr_ioctl_data data;
    data.msgs = &msg;
    data.len = 1;
    msg.addr = MCP3008_ADDR;
    msg.flags = I2C_MSG_READ;
    msg.buf = (unsigned char *)&state.mcp3008_value;
    ret = ioctl(state.spi_fd, I2C_RDWR, &data);
    if (ret < 0) {
        fprintf(stderr, "Failed to read MCP3008\n");
        exit(EXIT_FAILURE);
    }
}

void init_log() {
    int ret;
    state.log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (state.log_fd < 0) {
        fprintf(stderr, "Failed to open log file\n");
        exit(EXIT_FAILURE);
    }
}

void init_pump() {
    int ret;
    state.pump_fd = open("/dev/spi0.0", O_WRONLY);
    if (state.pump_fd < 0) {
        fprintf(stderr, "Failed to open pump GPIO\n");
        exit(EXIT_FAILURE);
    }
    ret = ioctl(state.pump_fd, SPI_IOC_WR_MODE8, SPI0_MODE);
    if (ret < 0) {
        fprintf(stderr, "Failed to set pump GPIO mode\n");
        exit(EXIT_FAILURE);
    }
    ret = ioctl(state.pump_fd, SPI_IOC_WR_OLAT, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to set pump GPIO output\n");
        exit(EXIT_FAILURE);
    }
}

void handle_sigint(int signum) {
    if (state.running) {
        close(state.pump_fd);
        close(state.spi_fd);
        close(state.log_fd);
        exit(EXIT_SUCCESS);
    }
}

void handle_sigterm(int signum) {
    if (state.running) {
        close(state.pump_fd);
        close(state.spi_fd);
        close(state.log_fd);
        exit(EXIT_SUCCESS);
    }
}

void start_irrigation() {
    state.running = 1;
    init_spi();
    init_mcp3008();
    init_log();
    init_pump();
    while (state.running) {
        int ret;
        unsigned char buffer[3];
        unsigned int moisture;
        struct timespec ts;
        ret = ioctl(state.spi_fd, SPI_IOC_RD_DATA0, buffer);
        if (ret < 0) {
            fprintf(stderr, "Failed to read SPI data\n");
            continue;
        }
        moisture = (buffer[0] << 8) | buffer[1];
        if (moisture < THRESHOLD) {
            ret = ioctl(state.pump_fd, SPI_IOC_WR_OLAT, 1);
            if (ret < 0) {
                fprintf(stderr, "Failed to activate pump\n");
            } else {
                fprintf(stderr, "Pump activated\n");
            }
        } else {
            ret = ioctl(state.pump_fd, SPI_IOC_WR_OLAT, 0);
            if (ret < 0) {
                fprintf(stderr, "Failed to deactivate pump\n");
            } else {
                fprintf(stderr, "Pump deactivated\n");
            }
        }
        ret = ioctl(state.spi_fd, SPI_IOC_RD_DATA0, buffer);
        if (ret < 0) {
            fprintf(stderr, "Failed to read SPI data\n");
            continue;
        }
        moisture = (buffer[0] << 8) | buffer[1];
        if (moisture < THRESHOLD) {
            fprintf(stderr, "Moisture reading: %d\n", moisture);
        } else {
            fprintf(stderr, "Moisture reading: %d\n", moisture);
        }
        ret = write(state.log_fd, &moisture, sizeof(moisture));
        if (ret < 0) {
            fprintf(stderr, "Failed to write to log file\n");
        } else {
            fprintf(stderr, "Moisture reading written to log file\n");
        }
        nanosleep(&ts, &ts);
    }
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sa.sa_flags = SA_RESTART;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    state.initialized = 0;
    state.running = 0;
    state.pump_fd = -1;
    state.spi_fd = -1;
    state.log_fd = -1;
    if (fcntl(state.pump_fd, F_SETFL, O_NONBLOCK) < 0) {
        fprintf(stderr, "Failed to set pump GPIO non-blocking\n");
        exit(EXIT_FAILURE);
    }
    if (fcntl(state.spi_fd, F_SETFL, O_NONBLOCK) < 0) {
        fprintf(stderr, "Failed to set SPI interface non-blocking\n");
        exit(EXIT_FAILURE);
    }
    if (fcntl(state.log_fd, F_SETFL, O_NONBLOCK) < 0) {
        fprintf(stderr, "Failed to set log file non-blocking\n");
        exit(EXIT_FAILURE);
    }
    if (fcntl(state.pump_fd, F_SETOWN, getpid()) < 0) {
        fprintf(stderr, "Failed to set pump GPIO owner\n");
        exit(EXIT_FAILURE);
    }
    if (fcntl(state.spi_fd, F_SETOWN, getpid()) < 0) {
        fprintf(stderr, "Failed to set SPI interface owner\n");
        exit(EXIT_FAILURE);
    }
    if (fcntl(state.log_fd, F_SETOWN, getpid()) < 0) {
        fprintf(stderr, "Failed to set log file owner\n");
        exit(EXIT_FAILURE);
    }
    state.initialized = 1;
    state.running = 1;
    start_irrigation();
    return 0;
