void init_spi(void) {
    struct spi_ioc_transfer spi_transfer;
    int spi_fd;

    spi_fd = open(SPI_DEV, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    spi_transfer.msb = SPI_CHANNEL;
    spi_transfer.msbs = 1;
    spi_transfer.size = 1;
    spi_transfer.delay_usec = SPI_TIMEOUT;
    spi_transfer.delay = 0;
    spi_transfer.speed = SPI_SPEED;
    spi_transfer.transfer_mode = SPI_MODE;
    spi_transfer.use_last = 1;

    ioctl(spi_fd, SPI_IOC_WR_MODE, &spi_transfer);
    ioctl(spi_fd, SPI_IOC_RD_MODE, &spi_transfer);
    ioctl(spi_fd, SPI_IOC_WR_BITS_PER_LINE, 8);
    ioctl(spi_fd, SPI_IOC_RD_BITS_PER_LINE, &spi_transfer);
    ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, SPI_SPEED);
    ioctl(spi_fd, SPI_IOC_RD_MAX_SPEED_HZ, &spi_transfer);

    close(spi_fd);
}

