#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/signal.h>
#include <sys/ioctl.h>
#include <linux/i2c.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spi.h>
#include <linux/spi/spi-bcm2835.h>
#include <linux/gpio.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>

#define MCP3008_ADDR 0x48
#define MIC_CHANNEL 0
#define LED_PIN 17
#define DEBOUNCE_TIME 10

int spi_fd;
int spi_handle;
int i2c_fd;
int i2c_handle;
int gpio17;
int calibrated_baseline;
int threshold;
int last_state = 0;

void cleanup() {
    if (spi_fd > 0) {
        close(spi_fd);
    }
    if (spi_handle > 0) {
        wiringPiSPISetDataMode(spi_handle, SPI_MODE0);
        wiringPiSPISetClockDivider(spi_handle, SPI_CLOCK_DIV2);
        wiringPiSPIClose(spi_handle);
    }
    if (i2c_fd > 0) {
        close(i2c_fd);
    }
    if (i2c_handle > 0) {
        wiringPiI2CClose(i2c_handle);
    }
    if (gpio17 > 0) {
        gpioTerminate(gpio17);
    }
    printf("Cleanup complete.\n");
}

void handle_sigint(int signum) {
    cleanup();
    printf("SIGINT received. Exiting.\n");
    exit(0);
}

int init_spi() {
    int ret;
    ret = wiringPiSPISetupDataMode(0, SPI_MODE0);
    if (ret < 0) {
        printf("Error initializing SPI data mode.\n");
        return -1;
    }
    ret = wiringPiSPISetClockDivider(0, SPI_CLOCK_DIV2);
    if (ret < 0) {
        printf("Error initializing SPI clock divider.\n");
        return -1;
    }
    ret = wiringPiSPISetBitOrder(0, SPI_BITORDER_MSBFIRST);
    if (ret < 0) {
        printf("Error initializing SPI bit order.\n");
        return -1;
    }
    ret = wiringPiSPISetHalfDuplex(0, 1);
    if (ret < 0) {
        printf("Error initializing SPI half duplex mode.\n");
        return -1;
    }
    ret = wiringPiSPISetSlaveSelectPolarity(0, 1);
    if (ret < 0) {
        printf("Error initializing SPI slave select polarity.\n");
        return -1;
    }
    ret = wiringPiSPISetSlaveSelectDelay(0, 0);
    if (ret < 0) {
        printf("Error initializing SPI slave select delay.\n");
        return -1;
    }
    ret = wiringPiSPISetUp(0, 5000000, 8);
    if (ret < 0) {
        printf("Error initializing SPI setup.\n");
        return -1;
    }
    spi_fd = wiringPiSPISpiOpen(0, 0, 0);
    if (spi_fd < 0) {
        printf("Error opening SPI device.\n");
        return -1;
    }
    spi_handle = wiringPiSPISpiOpenHandle(spi_fd, 0);
    if (spi_handle < 0) {
        printf("Error creating SPI handle.\n");
        return -1;
    }
    return 0;
}

int init_i2c() {
    int ret;
    ret = wiringPiI2CSetup(i2c_handle, MCP3008_ADDR);
    if (ret < 0) {
        printf("Error initializing I2C device.\n");
        return -1;
    }
    return 0;
}

int init_gpio() {
    int ret;
    ret = wiringPiSetupGpio();
    if (ret < 0) {
        printf("Error initializing GPIO.\n");
        return -1;
    }
    ret = wiringPiPinMode(LED_PIN, PI_OUTPUT);
    if (ret < 0) {
        printf("Error setting GPIO17 to output.\n");
        return -1;
    }
    ret = wiringPiPinMode(LED_PIN, PI_ALT0);
    if (ret < 0) {
        printf("Error setting GPIO17 to SPI0_CS.\n");
        return -1;
    }
    ret = wiringPiPinMode(MIC_CHANNEL, PI_INPUT);
    if (ret < 0) {
        printf("Error setting GPIO8 to input.\n");
        return -1;
    }
    gpio17 = wiringPiPinNumber(LED_PIN);
    if (gpio17 < 0) {
        printf("Error getting GPIO17 number.\n");
        return -1;
    }
    return 0;
}

int calibrate() {
    int samples[5];
    int sum = 0;
    int i;
    for (i = 0; i < 5; i++) {
        sum += wiringPiI2CRead8(i2c_handle);
    }
    calibrated_baseline = sum / 5;
    threshold = calibrated_baseline * 0.5;
    return 0;
}

int main() {
    signal(SIGINT, handle_sigint);
    if (init_spi() < 0) {
        printf("SPI initialization failed.\n");
        return 1;
    }
    if (init_i2c() < 0) {
        printf("I2C initialization failed.\n");
        return 1;
    }
    if (init_gpio() < 0) {
        printf("GPIO initialization failed.\n");
        return 1;
    }
    calibrated_baseline = 0;
    threshold = 0;
    calibrate();
    printf("Calibrated baseline: %d\n", calibrated_baseline);
    printf("Threshold: %d\n", threshold);
    while (1) {
        int sample = wiringPiI2CRead8(i2c_handle);
        if (sample > threshold) {
            if (sample != last_state) {
                last_state = sample;
                if (sample > threshold) {
                    gpioWrite(gpio17, 1);
                } else {
                    gpioWrite(gpio17, 0);
                }
            }
        } else {
            if (last_state == 1) {
                last_state = 0;
                gpioWrite(gpio17, 0);
            }
        }
        delay(DEBOUNCE_TIME);
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/ioctl.h>
#include <linux/spi/spi.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_CHANNEL 0
#define SPI_CS 0
#define SPI_SPEED 1000000
#define SPI_BITS 8
#define SPI_MODE 0
#define SPI_TIMEOUT 1000

#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE "airflow_log.txt"

typedef struct {
    int fd;
    struct spi_ioc_transfer spi;
    struct gpiod_handle handle;
    struct gpiod_line *line;
    struct gpiod_edge *edge;
} spi_config;

static spi_config config;

static int spi_open() {
    int ret;
    config.fd = open("/dev/spi0.0", O_RDWR);
    if (config.fd < 0) {
        perror("open");
        return -1;
    }

    ret = ioctl(config.fd, SPI_IOC_WR_MODE, SPI_MODE);
    if (ret < 0) {
        perror("ioctl");
        return -1;
    }

    ret = ioctl(config.fd, SPI_IOC_WR_BITS_PER_LINE, SPI_BITS);
    if (ret < 0) {
        perror("ioctl");
        return -1;
    }

    ret = ioctl(config.fd, SPI_IOC_WR_SPEED_hz, SPI_SPEED);
    if (ret < 0) {
        perror("ioctl");
        return -1;
    }

    return 0;
}

static int spi_close() {
    if (config.fd > 0) {
        close(config.fd);
    }
    return 0;
}

static int spi_init() {
    int ret;

    ret = spi_open();
    if (ret < 0) {
        return -1;
    }

    config.line = gpiod_new_line(gpiod_new_line_request());
    if (config.line == NULL) {
        perror("gpiod_new_line");
        return -1;
    }

    ret = gpiod_request_edge(config.line, GPIOD_EDGE_BOTH, GPIOD_EDGE_TRIGGER_RISING);
    if (ret < 0) {
        perror("gpiod_request_edge");
        return -1;
    }

    ret = gpiod_request_line(config.line, config.fd);
    if (ret < 0) {
        perror("gpiod_request_line");
        return -1;
    }

    config.handle = gpiod_open(config.line);
    if (config.handle < 0) {
        perror("gpiod_open");
        return -1;
    }

    return 0;
}

static void spi_cleanup() {
    if (config.handle > 0) {
        gpiod_close(config.handle);
    }

    if (config.line) {
        gpiod_free_line(config.line);
    }

    if (config.fd > 0) {
        spi_close();
    }
}

static int calibrate() {
    FILE *fp;
    char line[256];
    int calib[2];

    fp = fopen(CALIBRATION_FILE, "r");
    if (fp == NULL) {
        perror("fopen");
        return -1;
    }

    while (fgets(line, sizeof(line), fp)) {
        if (sscanf(line, "%d %d", &calib[0], &calib[1]) == 2) {
            break;
        }
    }

    fclose(fp);

    if (calib[0] < 0 || calib[1] < 0) {
        return -1;
    }

    return 0;
}

static int read_adc() {
    int ret;
    unsigned char buffer[3];
    struct spi_ioc_transfer transfer;

    memset(&transfer, 0, sizeof(transfer));
    transfer.tx_buf = (unsigned long)&buffer;
    transfer.rx_buf = (unsigned long)&buffer;
    transfer.cs = SPI_CS;
    transfer.len = 3;
    transfer.speed_hz = SPI_SPEED;
    transfer.delay_us = SPI_TIMEOUT;
    transfer.use_spi_buf = 0;

    ret = ioctl(config.fd, SPI_IOC_RDWR, &transfer);
    if (ret < 0) {
        perror("ioctl");
        return -1;
    }

    if (buffer[0] & 0x80) {
        return -1;
    }

    return (buffer[0] << 8) | buffer[1];
}

static double convert_to_airflow(int adc_value) {
    double airflow;
    FILE *fp;
    char line[256];
    int calib[2];

    fp = fopen(CALIBRATION_FILE, "r");
    if (fp == NULL) {
        perror("fopen");
        return -1;
    }

    while (fgets(line, sizeof(line), fp)) {
        if (sscanf(line, "%d %d", &calib[0], &calib[1]) == 2) {
            break;
        }
    }

    fclose(fp);

    if (calib[0] < 0 || calib[1] < 0) {
        return -1;
    }

    airflow = (double)adc_value * (calib[1] - calib[0]) / 1024.0 + calib[0];
    return airflow;
}

static void log_reading(double airflow) {
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[128];

    rawtime = time(NULL);
    timeinfo = localtime(&rawtime);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(stderr, "%s, %f\n", buffer, airflow);
    fprintf(stdout, "%s, %f\n", buffer, airflow);

    if (fopen(LOG_FILE, "a") == NULL) {
        perror("fopen");
        return;
    }

    fprintf(stdout, "%s\n", buffer);
    fprintf(stdout, "%f\n", airflow);
    fprintf(stdout, "\n");

    if (fputs(buffer, fopen(LOG_FILE, "a")) < 0) {
        perror("fputs");
        return;
    }

    if (fputs("%f\n", fopen(LOG_FILE, "a")) < 0) {
        perror("fputs");
        return;
    }

    fclose(fopen(LOG_FILE, "a"));
}

static void handle_sigint(int signum) {
    if (config.handle > 0) {
        gpiod_close(config.handle);
    }

    if (config.line) {
        gpiod_free_line(config.line);
    }

    if (config.fd > 0) {
        spi_close();
    }

    exit(EXIT_SUCCESS);
}

static void main_loop() {
    double airflow;
    int adc_value;

    while (1) {
        adc_value = read_adc();
        if (adc_value < 0) {
            fprintf(stderr, "ERROR: ADC read failed\n");
            log_reading(-1.0);
            continue;
        }

        airflow = convert_to_airflow(adc_value);
        if (airflow < 0) {
            fprintf(stderr, "ERROR: Calibration file not found\n");
            log_reading(-1.0);
            continue;
        }

        log_reading(airflow);

        sleep(100);
    }
}

int main() {
    signal(SIGINT, handle_sigint);

    if (calibrate() < 0) {
        fprintf(stderr, "ERROR: Calibration file not found\n");
        return EXIT_FAILURE;
    }

    if (spi_init() < 0) {
        fprintf(stderr, "ERROR: SPI initialization failed\n");
        return EXIT_FAILURE;
    }

    main_loop();

    return EXIT_SUCCESS;
}

