volatile sig_atomic_t sigint_received = 0;

void sigint_handler(int signum) {
    sigint_received = 1;
}

int spi_init() {
    int fd;
    if ((fd = open(SPI_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, 0) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

int spi_read_adc(int fd) {
    mcp3008_data_t data;
    if (ioctl(fd, I2C_SMBUS_READ, MCP3008_REG_DOUT, &data) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    return data.value;
}

void log_data(const char *filename, double voltage, int ppm) {
    FILE *file = fopen(filename, "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }

    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(file, "%s %f %d\n", buffer, voltage, ppm);
    fclose(file);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to set SIGINT handler");
        return 1;
    }

    int spi_fd = spi_init();
    if (spi_fd < 0) {
        return 1;
    }

    double voltage;
    int ppm;
    char buffer[256];

    while (!sigint_received) {
        voltage = spi_read_adc(spi_fd);
        if (voltage < 0) {
            usleep(100000);
            continue;
        }

        voltage = (voltage / 1024.0) * 3.3;
        ppm = (voltage * 1000000) / 0.0095; // 0.0095 is the sensitivity of the sensor

        snprintf(buffer, sizeof(buffer), "Voltage: %.2f V, PPM: %d\n", voltage, ppm);
        printf("%s\n", buffer);

        log_data("gas_log.txt", voltage, ppm);

        usleep(1000000); // 1 second delay
    }

    close(spi_fd);
    return 0;
}

