#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <string.h>
#include <signal.h>
#include <math.h>

#define SPI_DEV "/dev/spidev0.0"
#define SPI_CHANNEL 0
#define SPI_SPEED 1e6
#define SPI_BITS 8
#define SPI_MODE 0
#define SPI_CS 0

#define MAX_LINE_LENGTH 256

int spi_fd;
char spi_buf[256];
char csv_filename[] = "sensor_data.csv";

void handle_sigint(int signum) {
    if (close(spi_fd) < 0) {
        perror("Error closing SPI device");
        exit(EXIT_FAILURE);
    }
    if (remove(csv_filename) < 0) {
        perror("Error removing CSV file");
        exit(EXIT_FAILURE);
    }
    exit(EXIT_SUCCESS);
}

int main() {
    struct spi_ioc_transfer spi_transfer;
    struct spi_ioc_transfer spi_transfer2;

    // Open SPI device
    if ((spi_fd = open(SPI_DEV, O_RDWR)) < 0) {
        perror("Error opening SPI device");
        exit(EXIT_FAILURE);
    }

    // Initialize SPI transfer structure
    spi_transfer.ioctl = SPI_IOC_WR_MODE;
    spi_transfer.mode = SPI_MODE_0;
    spi_transfer.bits_per_word = SPI_BITS;
    spi_transfer.multiple = 0;
    spi_transfer.speed_hz = SPI_SPEED;
    spi_transfer.delay_us = 0;
    spi_transfer.use_spi_buf = 0;

    spi_transfer2.ioctl = SPI_IOC_RD_MODE;
    spi_transfer2.mode = SPI_MODE_0;
    spi_transfer2.bits_per_word = SPI_BITS;
    spi_transfer2.multiple = 0;
    spi_transfer2.speed_hz = SPI_SPEED;
    spi_transfer2.delay_us = 0;
    spi_transfer2.use_spi_buf = 0;

    // Set SPI device options
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, SPI_MODE_0) < 0) {
        perror("Error setting SPI mode");
        exit(EXIT_FAILURE);
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITMODE, SPI_BITS) < 0) {
        perror("Error setting SPI bit mode");
        exit(EXIT_FAILURE);
    }
    if (ioctl(spi_fd, SPI_IOC_WR_SPEED_HZ, SPI_SPEED) < 0) {
        perror("Error setting SPI speed");
        exit(EXIT_FAILURE);
    }
    if (ioctl(spi_fd, SPI_IOC_WR_CS, SPI_CS) < 0) {
        perror("Error setting SPI CS");
        exit(EXIT_FAILURE);
    }

    // Set SPI transfer structure for reading
    spi_transfer.buffer = spi_buf;
    spi_transfer.len = 3 * SPI_BITS;
    spi_transfer.delay_usec = 0;

    // Set SPI transfer structure for reading
    spi_transfer2.buffer = spi_buf;
    spi_transfer2.len = 3 * SPI_BITS;
    spi_transfer2.delay_usec = 0;

    // Create CSV file
    if (access(csv_filename, F_OK) == -1) {
        if (creat(csv_filename, 0644) < 0) {
            perror("Error creating CSV file");
            exit(EXIT_FAILURE);
        }
    }

    // Install SIGINT handler
    signal(SIGINT, handle_sigint);

    // Main loop
    while (1) {
        // Read from SPI channels
        if (ioctl(spi_fd, SPI_IOC_RD_DATA, &spi_transfer) < 0) {
            perror("Error reading SPI data");
            exit(EXIT_FAILURE);
        }
        if (ioctl(spi_fd, SPI_IOC_RD_DATA, &spi_transfer2) < 0) {
            perror("Error reading SPI data");
            exit(EXIT_FAILURE);
        }

        // Log readings to CSV file
        char line[MAX_LINE_LENGTH];
        snprintf(line, MAX_LINE_LENGTH, "%f,%f,%f\n", spi_buf[0], spi_buf[1], spi_buf[2]);
        if (write(spi_fd, line, strlen(line)) < 0) {
            perror("Error writing to CSV file");
            exit(EXIT_FAILURE);
        }

        // Sleep for 1 second
        usleep(1000000);
    }

    return 0;
}

