#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/time.h>
#include <signal.h>
#include <errno.h>
#include <syslog.h>
#include <sys/ioctl.h>
#include <gpiod.h>

#define GPIO_LINE "vibration-monitor"
#define GPIO_CHIP "/dev/gpiochip0"
#define EVENT_LINE "event"
#define EVENT_LINE_SIZE 16
#define LOG_FILE "/var/log/vibration_shutdown.log"
#define LOG_FILE_MODE (O_WRONLY | O_CREAT | O_APPEND)

volatile sig_atomic_t shutdown_flag = 0;

void handle_signal(int sig) {
    shutdown_flag = 1;
    syslog(LOG_INFO, "Received signal %d, shutting down.", sig);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_event *event;
    struct gpiod_line_info info;
    struct gpiod_event_request req;
    struct timespec ts;
    char buffer[EVENT_LINE_SIZE + 1];
    int fd, line_fd, event_fd, ret;

    // Set up signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open the GPIO chip
    if ((fd = open(GPIO_CHIP, O_RDONLY)) < 0) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    // Get the GPIO chip info
    if (ioctl(fd, GIOCGLINEINFO, &info) < 0) {
        perror("Failed to get GPIO chip info");
        close(fd);
        return 1;
    }

    // Open the desired GPIO line
    if ((line_fd = gpiod_open_chip(fd, info.line)) < 0) {
        perror("Failed to open GPIO line");
        close(fd);
        return 1;
    }

    // Get the line info
    if (gpiod_get_line_info(line_fd, &info) < 0) {
        perror("Failed to get GPIO line info");
        gpiod_close_chip(line_fd);
        close(fd);
        return 1;
    }

    // Set the line to the desired mode
    if (gpiod_set_line_mode(line_fd, info.line, GPIOD_MODE_EDGE_FALLING) < 0) {
        perror("Failed to set GPIO line mode");
        gpiod_close_chip(line_fd);
        gpiod_close_fd(fd);
        close(fd);
        return 1;
    }

    // Request the event line
    if (gpiod_request_event(line_fd, info.line, EVENT_LINE, &req) < 0) {
        perror("Failed to request event line");
        gpiod_close_chip(line_fd);
        gpiod_close_fd(fd);
        close(fd);
        return 1;
    }

    // Open the log file
    if ((ret = open(LOG_FILE, LOG_FILE_MODE)) < 0) {
        perror("Failed to open log file");
        gpiod_close_chip(line_fd);
        gpiod_close_fd(fd);
        close(fd);
        return 1;
    }

    while (!shutdown_flag) {
        // Wait for an event
        if (gpiod_wait_event(line_fd, &event) < 0) {
            perror("Failed to wait for event");
            gpiod_close_chip(line_fd);
            gpiod_close_fd(fd);
            close(fd);
            return 1;
        }

        // Read the event
        if (gpiod_get_event(event, &req) < 0) {
            perror("Failed to read event");
            gpiod_close_chip(line_fd);
            gpiod_close_fd(fd);
            close(fd);
            return 1;
        }

        // Read the event value
        if (gpiod_get_value(event, &info.value) < 0) {
            perror("Failed to read event value");
            gpiod_close_chip(line_fd);
            gpiod_close_fd(fd);
            close(fd);
            return 1;
        }

        // Check if the event is a falling edge
        if (info.value == 0) {
            // Get the current time
            clock_gettime(CLOCK_MONOTONIC, &ts);

            // Format the timestamp
            char timestamp[20];
            snprintf(timestamp, sizeof(timestamp), "%ld.%09ld", ts.tv_sec, ts.tv_nsec / 1000000.0);

            // Append the timestamped message to the log file
            if (write(ret, timestamp, strlen(timestamp)) < 0) {
                perror("Failed to write to log file");
                close(ret);
                gpiod_close_chip(line_fd);
                gpiod_close_fd(fd);
                close(fd);
                return 1;
            }

            // Append the event message to the log file
            if (write(ret, "Falling edge detected\n", 18) < 0) {
                perror("Failed to write to log file");
                close(ret);
                gpiod_close_chip(line_fd);
                gpiod_close_fd(fd);
                close(fd);
                return 1;
            }

            // Print the event message to stdout
            printf("Falling edge detected\n");

            // Shutdown the system
            system("sudo shutdown -h now");

            // Clear the event
            if (gpiod_clear_event(event) < 0) {
                perror("Failed to clear event");
                gpiod_close_chip(line_fd);
                gpiod_close_fd(fd);
                close(fd);
                return 1;
            }
        }

        // Free the event
        gpiod_free_event(event);
    }

    // Close the GPIO line
    if (gpiod_close_line(line_fd, info.line) < 0) {
        perror("Failed to close GPIO line");
        gpiod_close_chip(line_fd);
        gpiod_close_fd(fd);
        close(fd);
        return 1;
    }

    // Close the GPIO chip
    if (gpiod_close_chip(line_fd) < 0) {
        perror("Failed to close GPIO chip");
        gpiod_close_fd(fd);
        close(fd);
        return 1;
    }

    // Close the GPIO file descriptor
    if (close(fd) < 0) {
        perror("Failed to close GPIO file descriptor");
        return 1;
    }

    return 0;
}

