#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/sigaction.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spi.h>
#include <linux/sigaction.h>
#include <linux/sched.h>

#define BH1750_ADDR 0x23
#define MAX4466_ADDR 0x60
#define MCP3008_CS 0
#define MCP3008_SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_BITS 8
#define SPI_MODE 0

#define LIGHT_FILE "/home/pi/environmental_log.txt"

typedef struct {
    int i2c_fd;
    int spi_fd;
} SensorHandle;

void i2c_init(SensorHandle *handle) {
    char i2c_path[100];
    snprintf(i2c_path, sizeof(i2c_path), "/dev/i2c-%d", 1);
    handle->i2c_fd = open(i2c_path, O_RDWR);
    if (handle->i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }
    ioctl(handle->i2c_fd, I2C_SLAVE, BH1750_ADDR);
}

void spi_init(SensorHandle *handle) {
    handle->spi_fd = open("/dev/spi/spi0.0", O_RDWR);
    if (handle->spi_fd < 0) {
        perror("Failed to open SPI bus");
        exit(EXIT_FAILURE);
    }
    ioctl(handle->spi_fd, SPI_SET_SPEED, SPI_SPEED);
    ioctl(handle->spi_fd, SPI_SET_MODE, SPI_MODE);
    ioctl(handle->spi_fd, SPI_SET@SuppressWarnings("unused")BITS, SPI_BITS);
}

void i2c_read_light(SensorHandle *handle, float *lux) {
    struct i2c_msg msg[1];
    struct i2c_rdwr_ioctl_msg rdwr_msg;
    msg[0].addr = BH1750_ADDR;
    msg[0].flags = I2C_MSG_READ;
    msg[0].data[0] = 0x00;
    rdwr_msg.msgs = msg;
    rdwr_msg.nummsgs = 1;
    rdwr_msg.control = I2C_RWRANDWR | I2C_RDSMB;
    ioctl(handle->i2c_fd, I2C_RDWR, &rdwr_msg);
    *lux = *((float *)&msg[0].data[0]);
}

void spi_read_sound(SensorHandle *handle, int *raw_value) {
    struct spi_ioc_transfer transfer;
    transfer.ioctl = SPI_IOC_RDWR;
    transfer.multiple = 0;
    transfer.delay_usec = 0;
    transfer.speed_hz = SPI_SPEED;
    transfer.bits_per_line = SPI_BITS;
    transfer.mode = SPI_MODE_0;
    transfer.len = 1;
    transfer.buf = (unsigned char *)raw_value;
    ioctl(handle->spi_fd, SPI_IOC_RDWR, &transfer);
}

void log_data(float light, int sound) {
    static char timestamp[20];
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    snprintf(timestamp, sizeof(timestamp), "%04d-%02d-%02d %02d:%02d:%02d",
             tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday, tm->tm_hour,
             tm->tm_min, tm->tm_sec);
    printf("Light: %f, Sound: %d\n", light, sound);
    FILE *file = fopen(LIGHT_FILE, "a");
    if (file) {
        fprintf(file, "%s, Light: %f, Sound: %d\n", timestamp, light, sound);
        fclose(file);
    }
}

void handle_sigint(int signum) {
    log_data(0, 0);
    close(handle->i2c_fd);
    close(handle->spi_fd);
    exit(EXIT_SUCCESS);
}

int main() {
    SensorHandle handle;
    float light;
    int sound;
    struct sigaction sa;

    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_init(&handle);
    spi_init(&handle);

    while (1) {
        i2c_read_light(&handle, &light);
        spi_read_sound(&handle, &sound);
        log_data(light, sound);
        sleep(1);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <signal.h>
#include <poll.h>
#include <gpiod.h>

#define GPIO_PIN 17
#define CSV_FILE "flame_events.log"
#define LOG_FORMAT "%s,%d,%d"

int main() {
    int fd, err;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_edge *edge;
    struct gpiod_event *event;
    struct pollfd pollfd;
    char timestamp[128];
    char buffer[1024];
    FILE *fp;

    // Initialize GPIO
    fd = open("/dev/gpiod", O_RDONLY);
    if (fd < 0) {
        perror("open /dev/gpiod");
        exit(EXIT_FAILURE);
    }

    chip = gpiod_chip_open(fd);
    if (!chip) {
        perror("gpiod_chip_open");
        close(fd);
        exit(EXIT_FAILURE);
    }

    // Find the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        close(fd);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Set the line to input mode with pull-down resistor
    if (gpiod_line_set_mode(line, GPIOD_MODE_INPUT) < 0) {
        perror("gpiod_line_set_mode");
        close(fd);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Set the line to pull-down
    if (gpiod_line_set_pull(line, GPIOD_PULL_DOWN) < 0) {
        perror("gpiod_line_set_pull");
        close(fd);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Create an edge for the line
    edge = gpiod_line_create_edge(line, GPIOD_EDGE_BOTH);
    if (!edge) {
        perror("gpiod_line_create_edge");
        close(fd);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Create an event for the edge
    event = gpiod_edge_create_event(edge, 0);
    if (!event) {
        perror("gpiod_edge_create_event");
        close(fd);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Set the event to trigger on the line's state change
    if (gpiod_event_set(line, event, GPIOD_EVENT_EDGE_CHANGE) < 0) {
        perror("gpiod_event_set");
        close(fd);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Open the CSV file for writing
    fp = fopen(CSV_FILE, "w");
    if (!fp) {
        perror("fopen");
        close(fd);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Initialize the pollfd structure
    pollfd.fd = fileno(fd);
    pollfd.events = POLLIN;
    pollfd.revents = 0;

    // Main loop
    while (1) {
        // Poll the GPIO line
        if (poll(&pollfd, 1, -1) < 0) {
            perror("poll");
            close(fd);
            gpiod_chip_close(chip);
            fclose(fp);
            exit(EXIT_FAILURE);
        }

        // Check if the line has changed
        if (gpiod_line_get_value(line) == 1) {
            // Record the timestamp
            struct timeval tv;
            gettimeofday(&tv, NULL);
            sprintf(timestamp, "%ld.%06ld", tv.tv_sec, tv.tv_usec);
            fprintf(fp, LOG_FORMAT, tv.tv_sec, GPIO_PIN, 1);
            printf("Flame detected at %s\n", timestamp);
        } else {
            fprintf(fp, LOG_FORMAT, tv.tv_sec, GPIO_PIN, 0);
        }

        // Sleep for 1 second
        if (sleep(1) < 0) {
            perror("sleep");
            close(fd);
            gpiod_chip_close(chip);
            fclose(fp);
            exit(EXIT_FAILURE);
        }
    }

    // Cleanup GPIO resources
    gpiod_chip_close(chip);
    close(fd);
    fclose(fp);

    return 0;
}

