#define SPI_SPEED 500000000
#define SPI_MODE 0

#define SPI_DEV "/dev/spi0.0"
#define I2C_DEV "/dev/i2c-1"

#define LOG_FILE "temperature_log.txt"

typedef struct {
    int spi_fd;
    int i2c_fd;
    int adc_fd;
    int dac_fd;
    int log_fd;
    char log_buffer[256];
    time_t log_time;
} Config;

void spi_init(Config *config) {
    config->spi_fd = open(SPI_DEV, O_RDWR);
    if (config->spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }
    ioctl(config->spi_fd, SPI_SET_SPEED, &SPI_SPEED);
    ioctl(config->spi_fd, SPI_SET_MODE, &SPI_MODE);
}

void i2c_init(Config *config) {
    config->i2c_fd = open(I2C_DEV, O_RDWR);
    if (config->i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }
    ioctl(config->i2c_fd, I2C_SLAVE, MCP4725_ADDR);
}

void adc_init(Config *config) {
    config->adc_fd = open("/dev/spi0.0", O_RDWR);
    if (config->adc_fd < 0) {
        perror("Failed to open ADC device");
        exit(EXIT_FAILURE);
    }
    ioctl(config->adc_fd, SPI_SET_SPEED, &SPI_SPEED);
    ioctl(config->adc_fd, SPI_SET_MODE, &SPI_MODE);
    ioctl(config->adc_fd, SPI_SET@SuppressWarnings("unused") SPI_CS, MCP3008_CS);
    ioctl(config->adc_fd, SPI_SET@SuppressWarnings("unused") SPI_CH, MCP3008_CH);
}

void dac_init(Config *config) {
    config->dac_fd = open("/dev/i2c-1", O_RDWR);
    if (config->dac_fd < 0) {
        perror("Failed to open DAC device");
        exit(EXIT_FAILURE);
    }
    ioctl(config->dac_fd, I2C_SLAVE, MCP4725_ADDR);
}

void log_data(Config *config, double temp, double voltage) {
    char log_line[256];
    struct tm *log_time = localtime(&config->log_time);
    strftime(log_line, sizeof(log_line), "%Y-%m-%d %H:%M:%S", log_time);
    snprintf(config->log_buffer, sizeof(config->log_buffer), "%s %d %f %f\n", log_line, (int)config->adc_value, temp, voltage);
    write(config->log_fd, config->log_buffer, strlen(config->log_buffer));
    fflush(config->log_fd);
}

void spi_transfer(Config *config, uint8_t *buf, uint8_t *buf2, uint8_t *buf3, uint8_t *buf4, uint8_t *buf5, uint8_t *buf6, uint8_t *buf7, uint8_t *buf8) {
    int res = ioctl(config->spi_fd, SPI_IOC_TRANSFER, buf);
    if (res < 0) {
        perror("SPI transfer failed");
        exit(EXIT_FAILURE);
    }
    res = ioctl(config->spi_fd, SPI_IOC_WAIT, buf2);
    if (res < 0) {
        perror("SPI wait failed");
        exit(EXIT_FAILURE);
    }
    res = ioctl(config->spi_fd, SPI_IOC_TRANSFER, buf3);
    if (res < 0) {
        perror("SPI transfer failed");
        exit(EXIT_FAILURE);
    }
    res = ioctl(config->spi_fd, SPI_IOC_WAIT, buf4);
    if (res < 0) {
        perror("SPI wait failed");
        exit(EXIT_FAILURE);
    }
    res = ioctl(config->spi_fd, SPI_IOC_TRANSFER, buf5);
    if (res < 0) {
        perror("SPI transfer failed");
        exit(EXIT_FAILURE);
    }
    res = ioctl(config->spi_fd, SPI_IOC_WAIT, buf6);
    if (res < 0) {
        perror("SPI wait failed");
        exit(EXIT_FAILURE);
    }
    res = ioctl(config->spi_fd, SPI_IOC_TRANSFER, buf7);
    if (res < 0) {
        perror("SPI transfer failed");
        exit(EXIT_FAILURE);
    }
    res = ioctl(config->spi_fd, SPI_IOC_WAIT, buf8);
    if (res < 0) {
        perror("SPI wait failed");
        exit(EXIT_FAILURE);
    }
}

void i2c_write(Config *config, uint8_t *buf, uint8_t len) {
    int res = write(config->i2c_fd, buf, len);
    if (res < 0) {
        perror("I2C write failed");
        exit(EXIT_FAILURE);
    }
}

void adc_read(Config *config, uint8_t *buf) {
    int res = ioctl(config->adc_fd, SPI_IOC_RD_DATA0, buf);
    if (res < 0) {
        perror("ADC read failed");
        exit(EXIT_FAILURE);
    }
}

void dac_write(Config *config, uint8_t *buf) {
    int res = write(config->dac_fd, buf, 2);
    if (res < 0) {
        perror("DAC write failed");
        exit(EXIT_FAILURE);
    }
}

void cleanup(Config *config) {
    if (config->spi_fd > 0) {
        close(config->spi_fd);
    }
    if (config->i2c_fd > 0) {
        close(config->i2c_fd);
    }
    if (config->adc_fd > 0) {
        close(config->adc_fd);
    }
    if (config->dac_fd > 0) {
        close(config->dac_fd);
    }
    if (config->log_fd > 0) {
        close(config->log_fd);
    }
