    config.log_time = 0;

    if (access(LOG_FILE, F_OK) == -1) {
        if (mkdir("/tmp/temperature_log", 0777) < 0) {
            perror("Failed to create log directory");
            exit(EXIT_FAILURE);
        }
        config.log_fd = open(LOG_FILE, O_CREAT | O_WRONLY | O_APPEND, 0777);
    } else {
        config.log_fd = open(LOG_FILE, O_WRONLY | O_APPEND, 0777);
    }

    if (config.log_fd < 0) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

