        dac_value[0] = (uint8_t)(voltage * 256.0);
        dac_value[1] = (uint8_t)(voltage * 256.0 >> 8);

        i2c_write(&config, dac_value, 2);

        printf("%.2f %d %.2f\n", temp, adc_value[0], voltage);
    }

    cleanup(&config);

    return 0;
}

