#define GPIO_BASE 0x3F800000
#define GPIO_MAJOR 0x14
#define GPIO_MINOR 0x0

#define RELAY_1 17
#define RELAY_2 22
#define RELAY_3 23
#define RELAY_4 24

#define RELAY_COUNT 4

int gpiod_fd;
gpiod_device_t *dev;
gpiod_line_mfd_t *line;
gpiod_line_t *line_ptr;
gpiod_line_state_t state;
gpiod_line_request_t request;

void handle_sigint(int signum) {
    for (int i = 0; i < RELAY_COUNT; i++) {
        line_ptr = line[i];
        if (line_ptr) {
            gpiod_line_request_set(line_ptr, GPIOD_LINE_STATE, &state);
            gpiod_line_request_submit(line_ptr, request);
        }
    }
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    gpiod_fd = open("/dev/gpiod", O_RDONLY | O_NONBLOCK);
    if (gpiod_fd < 0) {
        perror("Failed to open gpiod");
        return 1;
    }

    if (ioctl(gpiod_fd, GIOCGMAYOR, &GPIO_MAJOR) < 0) {
        perror("Failed to get GPIO major");
        return 1;
    }

    if (ioctl(gpiod_fd, GIOCGMINOR, &GPIO_MINOR) < 0) {
        perror("Failed to get GPIO minor");
        return 1;
    }

    dev = gpiod_open(gpiod_fd, GPIO_MAJOR, GPIO_MINOR);
    if (dev == NULL) {
        perror("Failed to open device");
        return 1;
    }

    for (int i = 0; i < RELAY_COUNT; i++) {
        line = gpiod_get_line(dev, RELAY_1 + i);
        if (line == NULL) {
            perror("Failed to get line");
            return 1;
