#define GP2Y0A21YK0F_PIN 17
#define GP2Y0A21YK0F_LOG_FILE "distance_log.txt"

void handle_error(int fd, const char *msg) {
    if (fd < 0) {
        perror(msg);
        return;
    }
    if (close(fd) < 0) {
        perror(msg);
        return;
    }
}

void log_distance(int distance) {
    char buffer[128];
    struct tm *timeinfo;
    time_t rawtime;
    FILE *log_file;

    rawtime = time(NULL);
    timeinfo = localtime(&rawtime);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);

    log_file = fopen(GP2Y0A21YK0F_LOG_FILE, "a");
    if (log_file == NULL) {
        handle_error(-1, "opening log file");
        return;
    }

    fprintf(log_file, "%s %d\n", buffer, distance);
    fclose(log_file);
}

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        if (gpio_unexport(GP2Y0A21YK0F_PIN) < 0) {
            perror("unexporting GPIO");
            return;
        }
        printf("Feeder stopped\n");
        exit(0);
    }
}

