#include <sys/types.h>
#include <syslog.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spi.h>
#include <linux/spi/spi-bcm2835.h>
#include <linux/gpiod.h>

#define SPI_DEV "/dev/spi0.0"
#define SPI_CS0 "/sys/class/i2c-dev/i2c-0"
#define SPI_CS0_ADDR 0x74
#define ADC_CHANNEL 0
#define PUMP_RELAY 17
#define PUMP_ON 1
#define PUMP_OFF 0
#define LOG_FILE "soil_moisture.log"
#define LOG_FORMAT "%Y-%m-%d %H:%M:%S,%d,%d"

typedef struct {
    int fd;
    int spi_fd;
    int adc_fd;
    int log_fd;
    int pump_fd;
    int pump_state;
    int initialized;
    int adc_initialized;
    int log_initialized;
    int pump_initialized;
} Config;

void init_spi(Config *config) {
    config->spi_fd = open(SPI_DEV, O_RDWR);
    if (config->spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        exit(EXIT_FAILURE);
    }
    config->initialized = 1;
    config->adc_initialized = 0;
    config->log_initialized = 0;
    config->pump_initialized = 0;
}

void init_adc(Config *config) {
    if (!config->initialized) {
        return;
    }
    config->adc_fd = ioctl(config->spi_fd, SPI_IOC_WR_MODE, 0);
    if (config->adc_fd < 0) {
        fprintf(stderr, "Failed to configure SPI mode\n");
        exit(EXIT_FAILURE);
    }
    config->adc_fd = ioctl(config->spi_fd, SPI_IOC_RD_MODE, 0);
    if (config->adc_fd < 0) {
        fprintf(stderr, "Failed to read SPI mode\n");
        exit(EXIT_FAILURE);
    }
    config->adc_fd = ioctl(config->spi_fd, SPI_IOC_WR_BIT, 0);
    if (config->adc_fd < 0) {
        fprintf(stderr, "Failed to configure SPI bit order\n");
        exit(EXIT_FAILURE);
    }
    config->adc_fd = ioctl(config->spi_fd, SPI_IOC_WR_SCLK, 1);
    if (config->adc_fd < 0) {
        fprintf(stderr, "Failed to configure SPI SCLK\n");
        exit(EXIT_FAILURE);
    }
    config->adc_fd = ioctl(config->spi_fd, SPI_IOC_WR_MOSI, 1);
    if (config->adc_fd < 0) {
        fprintf(stderr, "Failed to configure SPI MOSI\n");
        exit(EXIT_FAILURE);
    }
    config->adc_fd = ioctl(config->spi_fd, SPI_IOC_WR_MISO, 1);
    if (config->adc_fd < 0) {
        fprintf(stderr, "Failed to configure SPI MISO\n");
        exit(EXIT_FAILURE);
    }
    config->adc_fd = ioctl(config->spi_fd, SPI_IOC_WR_SPEED, 1000000);
    if (config->adc_fd < 0) {
        fprintf(stderr, "Failed to configure SPI speed\n");
        exit(EXIT_FAILURE);
    }
    config->adc_initialized = 1;
}

void init_log(Config *config) {
    config->log_fd = open(LOG_FILE, O_CREAT | O_WRONLY | O_APPEND, 0644);
    if (config->log_fd < 0) {
        fprintf(stderr, "Failed to open log file\n");
        exit(EXIT_FAILURE);
    }
    config->log_initialized = 1;
}

void init_pump(Config *config) {
    config->pump_fd = open("/dev/spi-bcm2835-0", O_RDWR);
    if (config->pump_fd < 0) {
        fprintf(stderr, "Failed to open pump SPI device\n");
        exit(EXIT_FAILURE);
    }
    config->pump_initialized = 1;
}

void pump_on(Config *config) {
    if (!config->pump_initialized) {
        return;
    }
    config->pump_state = PUMP_ON;
    ioctl(config->pump_fd, SPI_IOC_WR_MOSI, config->pump_state);
}

void pump_off(Config *config) {
    if (!config->pump_initialized) {
        return;
    }
    config->pump_state = PUMP_OFF;
    ioctl(config->pump_fd, SPI_IOC_WR_MOSI, config->pump_state);
}

void log_sample(Config *config, int moisture) {
    if (!config->log_initialized) {
        return;
    }
    char buffer[256];
    struct tm *timeinfo;
    time_t rawtime;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(buffer, sizeof(buffer), LOG_FORMAT, timeinfo);
    if (config->pump_state == PUMP_ON) {
        strcat(buffer, ",ON");
    } else {
        strcat(buffer, ",OFF");
    }
    write(config->log_fd, buffer, strlen(buffer));
    write(config->log_fd, "\n", 1);
}

void handle_error(Config *config, int error_code) {
    if (error_code) {
        fprintf(stderr, "Error: %d\n", error_code);
    }
    if (config->initialized) {
        close(config->spi_fd);
    }
    if (config->adc_initialized) {
        close(config->adc_fd);
    }
    if (config->log_initialized) {
        close(config->log_fd);
    }
    if (config->pump_initialized) {
        close(config->pump_fd);
    }
    exit(EXIT_FAILURE);
}

void handle_sigint(Config *config) {
    pump_off(config);
    close(config->log_fd);
    close(config->adc_fd);
    close(config->spi_fd);
    close(config->pump_fd);
    exit(EXIT_SUCCESS);
}

int main() {
    Config config;
    config.initialized = 0;
    config.adc_initialized = 0;
    config.log_initialized = 0;
    config.pump_initialized = 0;
    config.pump_state = PUMP_OFF;

    signal(SIGINT, handle_sigint);

    init_spi(&config);
    if (!config.initialized) {
        handle_error(&config, -1);
    }

    init_adc(&config);
    if (!config.adc_initialized) {
        handle_error(&config, -1);
    }

    init_log(&config);
    if (!config.log_initialized) {
        handle_error(&config, -1);
    }

    init_pump(&config);
    if (!config.pump_initialized) {
        handle_error(&config, -1);
    }

    pump_off(&config);

    while (1) {
        int moisture = 0;
        int adc_result = 0;
        int adc_error = 0;

        adc_result = ioctl(config.spi_fd, SPI_IOC_RD_ADC0, &adc_result);
        if (adc_result < 0) {
            adc_error = -1;
        } else {
            adc_error = 0;
        }

        if (adc_error) {
            fprintf(stderr, "ADC read error\n");
            handle_error(&config, adc_error);
        }

        moisture = (adc_result * 100) / 1024;
        log_sample(&config, moisture);

        if (moisture < 20) {
            pump_on(&config);
        } else {
            pump_off(&config);
        }

        usleep(60000000); // 60 seconds
    }

    return 0;
}

