#define SPI_DEV "/dev/spi0.0"
#define SPI_CHANNEL 0
#define SPI_MCP3008_MODE 0
#define SPI_MCP3008_SPEED 1000000
#define SPI_MCP3008_CHIP_ENABLE 0
#define SPI_MCP3008_ADC_CHANNEL 0

#define MOISTURE_LOG_FILE "moisture_log.txt"

#define MAX_LOG_ENTRIES 1000

typedef struct {
    int fd;
    int *buffer;
    int buffer_size;
    int buffer_index;
    int last_error;
} MoistureLog;

MoistureLog moisture_log;

void handle_sigint(int signum) {
    if (moisture_log.fd > 0) {
        close(moisture_log.fd);
    }
    munmap(moisture_log.buffer, moisture_log.buffer_size);
    free(moisture_log.buffer);
    exit(0);
}

int init_spi() {
    int fd = open(SPI_DEV, O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    struct spi_ioc_transfer transfer = {
        .cs = SPI_MCP3008_CHIP_ENABLE,
        .delay_usec = 0,
        .speed_hz = SPI_MCP3008_SPEED,
        .bits_per_line = 8,
        .nr_of_transfers = 1,
        .buffer_size = 0,
        .ctrl = {
            .cmd = SPI_MCP3008_MODE,
            .delay_usec = 0,
            .bits_per_line = 8,
            .nbits = 8,
            .delay_usec = 0,
            .ctrl = SPI_MCP3008_CHIP_ENABLE,
            .delay_usec = 0,
            .bits_per_line = 8,
            .nbits = 8,
            .delay_usec = 0,
        },
        .buffer = NULL,
        .ctrl2 = {
            .cmd = SPI_MCP3008_ADC_CHANNEL,
            .delay_usec = 0,
            .bits_per_line = 8,
            .nbits = 8,
            .delay_usec = 0,
            .ctrl = SPI_MCP3008_CHIP_ENABLE,
            .delay_usec = 0,
            .bits_per_line = 8,
            .nbits = 8,
            .delay_usec = 0,
        },
        .buffer = NULL,
    };

    if (ioctl(fd, SPI_IOC_WR_I2C_MODE, &transfer) < 0) {
        perror("Failed to set SPI mode");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_RD_I2C_MODE, &transfer) < 0) {
        perror("Failed to read SPI mode");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_I2C_SPEED, &transfer) < 0) {
        perror("Failed to set SPI speed");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_RD_I2C_SPEED, &transfer) < 0) {
        perror("Failed to read SPI speed");
        close(fd);
        return -1;
    }

    moisture_log.fd = fd;
    moisture_log.buffer = mmap(0, 2, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (moisture_log.buffer == MAP_FAILED) {
        perror("Failed to mmap SPI buffer");
        close(fd);
        return -1;
    }
    moisture_log.buffer_size = 2;
    moisture_log.buffer_index = 0;
    moisture_log.last_error = 0;
    return 0;
}

int read_moisture() {
    struct spi_ioc_transfer transfer = {
        .cs = SPI_MCP3008_CHIP_ENABLE,
        .delay_usec = 0,
        .speed_hz = SPI_MCP3008_SPEED,
        .bits_per_line = 8,
        .nr_of_transfers = 1,
        .buffer_size = 0,
        .ctrl = {
            .cmd = SPI_MCP3008_ADC_CHANNEL,
            .delay_usec = 0,
            .bits_per_line = 8,
            .nbits = 8,
            .delay_usec = 0,
            .ctrl = SPI_MCP3008_CHIP_ENABLE,
            .delay_usec = 0,
            .bits_per_line = 8,
            .nbits = 8,
            .delay_usec = 0,
        },
        .buffer = NULL,
        .ctrl2 = {
            .cmd = SPI_MCP3008_CHIP_ENABLE,
            .delay_usec = 0,
            .bits_per_line = 8,
            .nbits = 8,
            .delay_usec = 0,
        },
        .buffer = NULL,
    };

    if (ioctl(moisture_log.fd, SPI_IOC_RD_I2C_DATA, &transfer) < 0) {
        moisture_log.last_error = -1;
        return -1;
    }

    int raw_value = *((int *) moisture_log.buffer);
    return raw_value;
}

void append_to_log(int raw_value) {
    char timestamp[26];
    struct tm *now = localtime(&time(NULL));
    strftime(timestamp, 26, "%Y-%m-%d %H:%M:%S", now);
    char log_entry[100];
    snprintf(log_entry, 100, "%s %d", timestamp, raw_value);

    if (write(moisture_log.fd, log_entry, strlen(log_entry)) < 0) {
        perror("Failed to write to log file");
        close(moisture_log.fd);
        munmap(moisture_log.buffer, moisture_log.buffer_size);
        free(moisture_log.buffer);
        exit(1);
    }
}

int main() {
    signal(SIGINT, handle_sigint);

    if (init_spi() < 0) {
        return 1;
    }

    while (1) {
        int raw_value = read_moisture();
        if (raw_value == -1) {
            append_to_log(-1);
        } else {
            append_to_log(raw_value);
        }

        if (moisture_log.buffer_index >= MAX_LOG_ENTRIES) {
            close(moisture_log.fd);
            munmap(moisture_log.buffer, moisture_log.buffer_size);
            free(moisture_log.buffer);
            exit(0);
        }

        usleep(60000000); // 60 seconds
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
