#include <linux/spi/spi.h>
#include <linux/sigaction.h>
#include <linux/gpiod.h>

#define SPI_DEV "/dev/spidev0.0"
#define SPI_CS 0
#define SPI_SPEED 1000000
#define SPI_BITS 8
#define SPI_MODE 0

#define GPIO17 17

#define LOG_FILE "current_log.txt"

#define MAX_LINE_LENGTH 256

typedef struct {
    int fd;
    struct spi_ioc_transfer spi;
    struct gpiod_handle handle;
    struct gpiod_line line;
    struct gpiod_event event;
} spi_gpio_handle;

void spi_init(spi_gpio_handle *handle) {
    handle->fd = open(SPI_DEV, O_RDWR);
    if (handle->fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    handle->spi.transfer.ioctl = SPI_IOC_WR_MODE;
    handle->spi.transfer.ioctl = SPI_IOC_WR_BITS_PER_LINE;
    handle->spi.transfer.ioctl = SPI_IOC_WR_SPEED_hz;
    handle->spi.transfer.ioctl = SPI_IOC_WR_MOSI;
    handle->spi.transfer.ioctl = SPI_IOC_WR_MISO;
    handle->spi.transfer.ioctl = SPI_IOC_WR_CS;
    handle->spi.transfer.ioctl = SPI_IOC_WR_LSB_FIRST;
    handle->spi.transfer.size = 1;
    handle->spi.transfer.delay_usec = 0;
    handle->spi.transfer.tx_buf = (unsigned long)&handle->spi;
    handle->spi.transfer.rx_buf = (unsigned long)&handle->spi;

    if (ioctl(handle->fd, SPI_IOC_WR_MODE, SPI_MODE) < 0) {
        perror("Failed to configure SPI mode");
        close(handle->fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(handle->fd, SPI_IOC_WR_BITS_PER_LINE, SPI_BITS) < 0) {
        perror("Failed to configure SPI bits per line");
        close(handle->fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(handle->fd, SPI_IOC_WR_SPEED_hz, SPI_SPEED) < 0) {
        perror("Failed to configure SPI speed");
        close(handle->fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(handle->fd, SPI_IOC_WR_CS, SPI_CS) < 0) {
        perror("Failed to configure SPI CS");
        close(handle->fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(handle->fd, SPI_IOC_WR_MOSI, 1) < 0) {
        perror("Failed to configure SPI MOSI");
        close(handle->fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(handle->fd, SPI_IOC_WR_MISO, 0) < 0) {
        perror("Failed to configure SPI MISO");
        close(handle->fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(handle->fd, SPI_IOC_WR_LSB_FIRST, 1) < 0) {
        perror("Failed to configure SPI LSB first");
        close(handle->fd);
        exit(EXIT_FAILURE);
    }

    handle->line.fd = open("/dev/gpiod", O_RDONLY);
    if (handle->line.fd < 0) {
        perror("Failed to open gpiod");
        close(handle->fd);
        exit(EXIT_FAILURE);
    }

    if (gpiod_get_line(&handle->line, GPIO17) < 0) {
        perror("Failed to get GPIO line");
        close(handle->fd);
        close(handle->line.fd);
        exit(EXIT_FAILURE);
    }

    if (gpiod_request_event(&handle->line, &handle->event, GPIOD_EVENT_EDGE_ANY) < 0) {
        perror("Failed to request event");
        close(handle->fd);
        close(handle->line.fd);
        exit(EXIT_FAILURE);
    }

    if (gpiod_request_handler(&handle->line, &handle->handle, GPIOD_HANDLER_EDGE_ANY, GPIOD_HANDLER_TYPE_EDGE_ANY) < 0) {
        perror("Failed to request handler");
        close(handle->fd);
        close(handle->line.fd);
        exit(EXIT_FAILURE);
    }

    if (gpiod_enable(&handle->line, &handle->handle) < 0) {
        perror("Failed to enable handler");
        close(handle->fd);
        close(handle->line.fd);
        exit(EXIT_FAILURE);
    }
}

void spi_read(spi_gpio_handle *handle, int *adc_value) {
    handle->spi.tx_buf = (unsigned long)&handle->spi;
    handle->spi.rx_buf = (unsigned long)&handle->spi;
    handle->spi.delay_usec = 0;
    handle->spi.size = 1;
    handle->spi.bits = SPI_BITS;
    handle->spi.mode = SPI_MODE;

    if (ioctl(handle->fd, SPI_IOC_RD_DATAOUT, handle->spi) < 0) {
        perror("Failed to read SPI data");
        close(handle->fd);
        close(handle->line.fd);
        gpiod_disable(&handle->line, &handle->handle);
        exit(EXIT_FAILURE);
    }

    *adc_value = handle->spi.data[0];
}

void gpio_release(spi_gpio_handle *handle) {
    gpiod_disable(&handle->line, &handle->handle);
    close(handle->line.fd);
    close(handle->fd);
}

void sig_handler(int signum) {
    gpio_release(&handle);
    close(handle->fd);
    close(handle->line.fd);
    exit(EXIT_SUCCESS);
}

int main() {
    spi_gpio_handle handle;
    int adc_value;
    char timestamp[MAX_LINE_LENGTH];
    char line[MAX_LINE_LENGTH];

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to install SIGINT handler");
        exit(EXIT_FAILURE);
    }

    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to install SIGTERM handler");
        exit(EXIT_FAILURE);
    }

    spi_init(&handle);

    while (1) {
        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);
        snprintf(timestamp, sizeof(timestamp), "%ld.%09ld", ts.tv_sec, ts.tv_nsec / 1000000);

        spi_read(&handle, &adc_value);

        double voltage = (adc_value * 5.0) / 1024.0;
        double current = voltage / 0.1;

        snprintf(line, sizeof(line), "%s,%f\n", timestamp, current);

        FILE *fp = fopen(LOG_FILE, "a");
        if (fp == NULL) {
            perror("Failed to open log file");
            close(handle->fd);
            close(handle->line.fd);
            gpiod_disable(&handle->line, &handle->handle);
            exit(EXIT_FAILURE);
        }

        fputs(line, fp);
        fclose(fp);

        usleep(1000000);
    }

    return 0;
}

