#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <sys/select.h>
#include <errno.h>
#include <signal.h>

#define OV5647_BASE 0x40000000
#define OV5647_WIDTH 640
#define OV5647_HEIGHT 480
#define OV5647_FORMAT_GRAYSCALE 0x00000000
#define OV5647_MMAP_SIZE 1024 * 1024

typedef struct {
    int fd;
    void *buf;
    int buf_size;
    int frame_count;
} CameraStream;

CameraStream camera;

void camera_stream_init(const char *device) {
    camera.fd = open(device, O_RDWR | O_NONBLOCK);
    if (camera.fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    struct ioctl_arg {
        unsigned int width;
        unsigned int height;
        unsigned int format;
        unsigned int mmap_size;
    } arg;

    arg.width = OV5647_WIDTH;
    arg.height = OV5647_HEIGHT;
    arg.format = OV5647_FORMAT_GRAYSCALE;
    arg.mmap_size = OV5647_MMAP_SIZE;

    if (ioctl(camera.fd, 0x2A, &arg) == -1) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }

    camera.buf = mmap(0, arg.mmap_size, PROT_READ | PROT_WRITE, MAP_SHARED, camera.fd, 0);
    if (camera.buf == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }

    camera.buf_size = arg.mmap_size;
    camera.frame_count = 0;
}

void camera_stream_dequeue(CameraStream *stream) {
    fd_set readfds;
    struct timeval tv;

    FD_ZERO(&readfds);
    FD_SET(stream->fd, &readfds);

    tv.tv_sec = 2;
    tv.tv_usec = 0;

    if (select(stream->fd + 1, &readfds, NULL, NULL, &tv) == 0) {
        return;
    }

    if (!FD_ISSET(stream->fd, &readfds)) {
        return;
    }

    if (read(stream->fd, stream->buf, stream->buf_size) == -1) {
        perror("read");
        exit(EXIT_FAILURE);
    }

    camera.frame_count++;
    printf("Frame %d captured\n", camera.frame_count);
}

void camera_stream_save_frame(CameraStream *stream) {
    char filename[256];
    snprintf(filename, sizeof(filename), "image_%d.pgm", camera.frame_count);

    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    fprintf(fp, "P2\n");
    fprintf(fp, "%d %d\n", OV5647_WIDTH, OV5647_HEIGHT);
    fprintf(fp, "1\n");

    fwrite(stream->buf, stream->buf_size, 1, fp);
    fclose(fp);
}

void camera_stream_stop(CameraStream *stream) {
    if (munmap(stream->buf, stream->buf_size) == -1) {
        perror("munmap");
        exit(EXIT_FAILURE);
    }

    close(stream->fd);
}

void signal_handler(int sig) {
    camera_stream_stop(&camera);
    exit(EXIT_SUCCESS);
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s /dev/video0\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    camera_stream_init(argv[1]);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        camera_stream_dequeue(&camera);
        camera_stream_save_frame(&camera);
    }

    return 0;
}

