    FILE *log_file;
} Camera;

void camera_init(Camera *cam) {
    cam->fd = open("/dev/video0", O_RDWR);
    if (cam->fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    struct v4l2_capability cap;
    if (ioctl(cam->fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("VIDIOC_QUERYCAP");
        exit(EXIT_FAILURE);
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device is not a video capture device\n");
        exit(EXIT_FAILURE);
    }

    struct v4l2_fmtdesc fmtdesc;
    fmtdesc.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(cam->fd, VIDIOC_S_FMT, &fmtdesc) < 0) {
        perror("VIDIOC_S_FMT");
        exit(EXIT_FAILURE);
    }

    cam->device.width = fmtdesc.fmt.pix.width;
    cam->device.height = fmtdesc.fmt.pix.height;
    cam->device.fps = fmtdesc.fmt.pix.framerate;
    cam->device.frame_size = cam->device.width * cam->device.height * 3 / 2;

    struct v4l2_requestbuffers req;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.count = 1;
    req.memory = V4L2_MEMORY_CIRCULAR;
    req.size = cam->device.frame_size;

    if (ioctl(cam->fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("VIDIOC_REQBUFS");
        exit(EXIT_FAILURE);
    }

    struct v4l2_buffer buf;
    if (ioctl(cam->fd, VIDIOC_QBUF, &buf) < 0) {
        perror("VIDIOC_QBUF");
        exit(EXIT_FAILURE);
    }

    if (ioctl(cam->fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("VIDIOC_DQBUF");
        exit(EXIT_FAILURE);
    }

    cam->buffer = mmap(NULL, buf.maj.minor, PROT_READ | PROT_WRITE, MAP_SHARED, cam->fd, buf.maj.minor);
    if (cam->buffer == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }

    gettimeofday(&cam->last_frame_time, NULL);

    cam->log_file = fopen("frame_log.txt", "w");
    if (cam->log_file == NULL) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, [](int) {
        if (cam->fd != -1) {
            close(cam->fd);
            cam->fd = -1;
        }
        if (cam->buffer != MAP_FAILED) {
            munmap(cam->buffer, buf.maj.minor);
            cam->buffer = MAP_FAILED;
        }
        if (cam->log_file != NULL) {
            fclose(cam->log_file);
            cam->log_file = NULL;
        }
        exit(EXIT_SUCCESS);
    });
}

void camera_capture(Camera *cam) {
    struct v4l2_buffer buf;
    gettimeofday(&cam->last_frame_time, NULL);

    if (ioctl(cam->fd, VIDIOC_QBUF, &buf) < 0) {
        perror("VIDIOC_QBUF");
        return;
    }

    if (ioctl(cam->fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("VIDIOC_DQBUF");
        return;
    }

    if (buf.maj.minor == -1) {
        fprintf(stderr, "Error reading frame\n");
        return;
    }

    cam->buffer = mmap(NULL, buf.maj.minor, PROT_READ | PROT_WRITE, MAP_SHARED, cam->fd, buf.maj.minor);
    if (cam->buffer == MAP_FAILED) {
        perror("mmap");
        return;
    }

    unsigned char *frame = (unsigned char *)cam->buffer;
    for (int i = 0; i < cam->device.frame_size; i += 3) {
        fprintf(cam->log_file, "%ld.%06ld\n", cam->last_frame_time.tv_sec, cam->last_frame_time.tv_usec);
        fflush(cam->log_file);
    }

    munmap(cam->buffer, buf.maj.minor);
    cam->buffer = MAP_FAILED;
}

int main() {
    Camera cam;
    camera_init(&cam);

    fd_set readfds;
    FD_ZERO(&readfds);
    FD_SET(cam->fd, &readfds);

    struct timeval tv;
    tv.tv_sec = 0;
    tv.tv_usec = 0;

    while (1) {
        int ret = select(cam->fd + 1, &readfds, NULL, NULL, &tv);
        if (ret == -1) {
            perror("select");
            break;
        }

        if (ret > 0) {
            camera_capture(&cam);
        }
    }

    return 0;
}

