#define YUYV_TO_RGB24_BUF_SIZE  (1024 * 1024) // 1MB buffer for YUYV to RGB24 conversion

typedef struct {
    int fd;
    int width;
    int height;
    int stride;
    int buffer_size;
    unsigned char *yuyv_buffer;
    unsigned char *rgb24_buffer;
    int rgb24_buffer_size;
} CameraStream;

void camera_stream_init(CameraStream *stream) {
    if ((stream->fd = open("/dev/video0", O_RDWR | O_NONBLOCK)) < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    ioctl(stream->fd, VIDIOC_GCAP, &stream->cap);
    stream->width = stream->cap.pix.width;
    stream->height = stream->cap.pix.height;
    stream->stride = stream->cap.pix.width * 2;

    stream->buffer_size = YUYV_TO_RGB24_BUF_SIZE;
    stream->rgb24_buffer_size = stream->width * stream->height * 3;

    if ((stream->yuyv_buffer = malloc(stream->buffer_size)) == NULL) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    if ((stream->rgb24_buffer = malloc(stream->rgb24_buffer_size)) == NULL) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
}

void camera_stream_deinit(CameraStream *stream) {
    if (stream->rgb24_buffer) {
        free(stream->rgb24_buffer);
    }
    if (stream->yuyv_buffer) {
        free(stream->yuyv_buffer);
    }
    close(stream->fd);
}

void camera_stream_start(CameraStream *stream) {
    if (ioctl(stream->fd, VIDIOC_S(Locale) | VIDIOC_S(format), &stream->cap) < 0) {
        perror("ioctl");
        exit(EXIT_FAILURE);
