    if (ioctl(stream->fd, VIDIOC_S(Locale) | VIDIOC_S(buffer, 0), &stream->cap) < 0) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }
    if (ioctl(stream->fd, VIDIOC_S(Locale) | VIDIOC_S(buffer, 1), &stream->cap) < 0) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }
    if (ioctl(stream->fd, VIDIOC_S(Locale) | VIDIOC_S(format, 0), &stream->cap) < 0) {
