#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <sys/ioctl.h>
#include <errno.h>
#include <signal.h>

#define CAPTURE_TIMEOUT 2
#define WIDTH 200
#define HEIGHT 150
#define FRAMESIZE (WIDTH * HEIGHT * 2)

int main() {
    int fd, ret;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_buffer buf;
    void *buf_ptr;
    FILE *fp;
    int status;

    // Open the camera
    fd = open("/dev/video0", O_RDWR);
    if (fd < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    // Get camera capabilities
    ret = ioctl(fd, VIDIOC_QUERYCAP, &cap);
    if (ret < 0) {
        perror("ioctl VIDIOC_QUERYCAP");
        exit(EXIT_FAILURE);
    }

    // Check if the camera supports the requested format
    fmt.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;
    ret = ioctl(fd, VIDIOC_S_FMT, &fmt);
    if (ret < 0) {
        perror("ioctl VIDIOC_S_FMT");
        exit(EXIT_FAILURE);
    }

    // Request a single memory-mapped buffer
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    ret = ioctl(fd, VIDIOC_REQBUFS, &buf);
    if (ret < 0) {
        perror("ioctl VIDIOC_REQBUFS");
        exit(EXIT_FAILURE);
    }

    // Get the number of available buffers
    ret = ioctl(fd, VIDIOC_GETCAP, &cap);
    if (ret < 0) {
        perror("ioctl VIDIOC_GETCAP");
        exit(EXIT_FAILURE);
    }
    if (cap.capabilities.cap_v4l2_buf < 1) {
        fprintf(stderr, "Not enough buffers available\n");
        exit(EXIT_FAILURE);
    }

    // Select the first buffer
    buf.index = 0;
    ret = ioctl(fd, VIDIOC_SELECTBUFS, &buf);
    if (ret < 0) {
        perror("ioctl VIDIOC_SELECTBUFS");
        exit(EXIT_FAILURE);
    }

    // Map the buffer
    buf_ptr = mmap(NULL, buf.maj.minpels * sizeof(uint8_t), PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.maj.index);
    if (buf_ptr == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }

    // Start streaming
    ret = ioctl(fd, VIDIOC_STREAMOFF, &buf);
    if (ret < 0) {
        perror("ioctl VIDIOC_STREAMOFF");
        exit(EXIT_FAILURE);
    }

    fp = fopen("cropped.yuv", "wb");
    if (!fp) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, [](int sig) {
        // Stop streaming
        ioctl(fd, VIDIOC_STREAMON, &buf);
        munmap(buf_ptr, buf.maj.minpels * sizeof(uint8_t));
        close(fd);
        fclose(fp);
        exit(EXIT_SUCCESS);
    });

    fd_set readfds;
    FD_ZERO(&readfds);
    FD_SET(fd, &readfds);

    struct timeval tv;
    tv.tv_sec = CAPTURE_TIMEOUT;
    tv.tv_usec = 0;

    while (1) {
        ret = select(fd + 1, &readfds, NULL, NULL, &tv);
        if (ret == -1) {
            perror("select");
            exit(EXIT_FAILURE);
        } else if (ret == 0) {
            fprintf(stderr, "Timeout\n");
            ioctl(fd, VIDIOC_STREAMON, &buf);
            munmap(buf_ptr, buf.maj.minpels * sizeof(uint8_t));
            close(fd);
            fclose(fp);
            exit(EXIT_FAILURE);
        }

        ret = ioctl(fd, VIDIOC_QBUF, &buf);
        if (ret < 0) {
            perror("ioctl VIDIOC_QBUF");
            exit(EXIT_FAILURE);
        }

        ret = ioctl(fd, VIDIOC_DQBUF, &buf);
        if (ret < 0) {
            perror("ioctl VIDIOC_DQBUF");
            exit(EXIT_FAILURE);
        }

        if (ret == 0) {
            continue;
        }

        // Check the returned width, height and pixel format
        ret = ioctl(fd, VIDIOC_G_FMT, &fmt);
        if (ret < 0) {
            perror("ioctl VIDIOC_G_FMT");
            exit(EXIT_FAILURE);
        }

        if (fmt.fmt.pix.width != WIDTH || fmt.fmt.pix.height != HEIGHT || fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_YUYV) {
            fprintf(stderr, "Mismatched format\n");
            ioctl(fd, VIDIOC_STREAMON, &buf);
            munmap(buf_ptr, buf.maj.minpels * sizeof(uint8_t));
            close(fd);
            fclose(fp);
            exit(EXIT_FAILURE);
        }

        // Copy the complete YUYV macroblocks to avoid color corruption
        for (int i = 0; i < HEIGHT; i++) {
            for (int j = 0; j < WIDTH; j++) {
                buf_ptr[j * 2 + i * WIDTH * 2] = fmt.fmt.pix.y0[i * WIDTH + j];
                buf_ptr[j * 2 + i * WIDTH * 2 + 1] = fmt.fmt.pix.u[i * WIDTH + j];
                buf_ptr[j * 2 + i * WIDTH * 2 + 2] = fmt.fmt.pix.y1[i * WIDTH + j];
                buf_ptr[j * 2 + i * WIDTH * 2 + 3] = fmt.fmt.pix.v[i * WIDTH + j];
            }
        }

        // Crop a 200 × 150 region
        for (int i = 0; i < HEIGHT; i++) {
            for (int j = 0; j < WIDTH; j++) {
                if (i >= 50 && i < 150 && j >= 0 && j < 200) {
                    buf_ptr[j * 2 + i * WIDTH * 2] = fmt.fmt.pix.y0[i * WIDTH + j];
                    buf_ptr[j * 2 + i * WIDTH * 2 + 1] = fmt.fmt.pix.u[i * WIDTH + j];
                    buf_ptr[j * 2 + i * WIDTH * 2 + 2] = fmt.fmt.pix.y1[i * WIDTH + j];
                    buf_ptr[j * 2 + i * WIDTH * 2 + 3] = fmt.fmt.pix.v[i * WIDTH + j];
                }
            }
        }

        // Write the cropped YUYV macroblocks to the file
        ret = fwrite(buf_ptr, FRAMESIZE, 1, fp);
        if (ret != 1) {
            perror("fwrite");
            exit(EXIT_FAILURE);
        }

        // Check the return value of fwrite
        if (ret < 0) {
            perror("fwrite");
            exit(EXIT_FAILURE);
        }
    }

    return 0;
}

