#define PWM_FREQ 50000
#define PWM_RESOLUTION 1
#define PWM_MIN 0
#define PWM_MAX 1
#define PWM_CENTER 0.5

#define SERVO1_PIN 17
#define SERVO2_PIN 18

#define SERVO_MIN_ANGLE 0
#define SERVO_MAX_ANGLE 180

#define SERVO_MIN_PULSE 600
#define SERVO_MAX_PULSE 2400
#define SERVO_CENTER_PULSE (SERVO_MIN_PULSE + (SERVO_MAX_PULSE - SERVO_MIN_PULSE) * PWM_CENTER)

int servo1_fd, servo2_fd;
int servo1_angle = SERVO_CENTER_PULSE;
int servo2_angle = SERVO_CENTER_PULSE;

void handle_sigint(int signum) {
    printf("SIGINT received, exiting...\n");
    cleanup();
    exit(1);
}

void cleanup() {
    if (servo1_fd != -1) {
        close(servo1_fd);
    }
    if (servo2_fd != -1) {
        close(servo2_fd);
    }
    if (pigpio Haram) {
        pigpio Haram = 0;
    }
    exit(0);
}

void init_servo(int fd, int pin, int min_pulse, int max_pulse) {
    if (ioctl(fd, SERVOMODE, 0) < 0) {
        perror("ioctl SERVOMODE");
        cleanup();
        exit(1);
    }
    if (ioctl(fd, SETPWM, min_pulse) < 0) {
        perror("ioctl SETPWM");
        cleanup();
        exit(1);
    }
    if (ioctl(fd, SETPWM, max_pulse) < 0) {
        perror("ioctl SETPWM");
        cleanup();
        exit(1);
    }
    if (ioctl(fd, SETPWM, SERVO_CENTER_PULSE) < 0) {
        perror("ioctl SETPWM");
        cleanup();
        exit(1);
    }
}

void set_servo_angle(int fd, int pin, int angle) {
    int pulse = SERVO_MIN_PULSE + (angle * (SERVO_MAX_PULSE - SERVO_MIN_PULSE) / SERVO_MAX_ANGLE);
    if (pulse < SERVO_MIN_PULSE || pulse > SERVO_MAX_PULSE) {
        printf("Error: Angle out of range. Must be between 0 and 180.\n");
        return;
    }
    if (ioctl(fd, SETPWM, pulse) < 0) {
        printf("Error: PWM failure.\n");
        return;
    }
    servo1_angle = pulse;
    servo2_angle = pulse;
}

int main() {
    signal(SIGINT, handle_sigint);

    servo1_fd = open("/dev/gpiod/servos/0", O_RDWR);
    if (servo1_fd == -1) {
        perror("open servo1");
        cleanup();
        exit(1);
    }
    servo2_fd = open("/dev/gpiod/servos/1", O_RDWR);
    if (servo2_fd == -1) {
        perror("open servo2");
        cleanup();
        exit(1);

    init_servo(servo1_fd, SERVO1_PIN, SERVO_MIN_PULSE, SERVO_MAX_PULSE);
    init_servo(servo2_fd, SERVO2_PIN, SERVO_MIN_PULSE, SERVO_MAX_PULSE);

    printf("Servos initialized.\n");

    while (1) {
        char c;
        if (read(0, &c, 1) < 1) {
            continue;
        }
        switch (c) {
            case 'w':
                set_servo_angle(servo1_fd, SERVO1_PIN, servo1_angle + 5);
                usleep(100000);
                break;
            case 's':
                set_servo_angle(servo1_fd, SERVO1_PIN, servo1_angle - 5);
                usleep(100000);
                break;
            case 'a':
                set_servo_angle(servo2_fd, SERVO2_PIN, servo2_angle + 5);
                usleep(100000);
                break;
            case 'd':
                set_servo_angle(servo2_fd, SERVO2_PIN, servo2_angle - 5);
                usleep(100000);
                break;
            case 'q':
                cleanup();
                exit(0);
        }
    }
    return 0;
}

