static int i2c_fd;
static unsigned char *buffer;
static int buffer_size;

static void i2c_error_handler(int err) {
    fprintf(stderr, "I2C error: %d\n", err);
    exit(EXIT_FAILURE);
}

static void i2c_write(int addr, unsigned char *buf, size_t size) {
    struct i2c_msg msg[1];
    struct i2c_rdwr_ioctl_msg ioctl_msg;
    msg[0].addr = addr;
    msg[0].flags = I2C_RDWR;
    msg[0].data.w = (unsigned long)buf;
    msg[0].data.len = (unsigned long)size;
    ioctl_msg.msgs = msg;
    ioctl_msg.num_msgs = 1;
    ioctl_msg.ioctl = I2C_RDWR;
    if (ioctl(i2c_fd, I2C_RDWR, &ioctl_msg) < 0) {
        i2c_error_handler(errno);
    }
}

static void i2c_read(int addr, unsigned char *buf, size_t size) {
    struct i2c_msg msg[1];
    struct i2c_rdwr_ioctl_msg ioctl_msg;
    msg[0].addr = addr;
    msg[0].flags = I2C_RDWR;
    msg[0].data.w = (unsigned long)buf;
    msg[0].data.len = (unsigned long)size;
    ioctl_msg.msgs = msg;
    ioctl_msg.num_msgs = 1;
    ioctl_msg.ioctl = I2C_RDWR;
    if (ioctl(i2c_fd, I2C_RDWR, &ioctl_msg) < 0) {
        i2c_error_handler(errno);
    }
}

static void i2c_init() {
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }
    if (ioctl(i2c_fd, I2C_SLAVE, SSD1306_ADDR) < 0) {
        i2c_error_handler(errno);
    }
    buffer = mmap(0, buffer_size, PROT_READ | PROT_WRITE, MAP_SHARED, i2c_fd, 0);
    if (buffer == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }
}

static void i2c_close() {
    munmap(buffer, buffer_size);
    close(i2c_fd);
}

static void display_clear() {
    i2c_write(SSD1306_ADDR, buffer, 1);
    buffer[0] = 0x80; // Command to clear the screen
}

static void display_text(const char *text) {
    int x = 0, y = 0;
    for (int i = 0; text[i]; i++) {
        if (isprint(text[i])) {
            int font_index = (y * SSD1306_WIDTH * SSD1306_FONT_SIZE) + (x * SSD1306_FONT_SIZE);
            for (int j = 0; j < SSD1306_FONT_SIZE; j++) {
                buffer[font_index + j] = font_data[text[i] - ' ' * SSD1306_FONT_SIZE + j];
            }
            x += SSD1306_FONT_SIZE;
            if (x >= SSD1306_WIDTH) {
                x = 0;
                y += SSD1306_LINE_HEIGHT;
            }
        }
    }
    display_clear();
}

static void display_cpu_temp(int temp) {
    char temp_str[10];
    sprintf(temp_str, "%d", temp);
    display_text(temp_str);
}

static void display_cpu_usage(int usage) {
    char usage_str[10];
    sprintf(usage_str, "%d", usage);
    display_text(usage_str);
}

static void display_update() {
    display_clear();
    display_cpu_temp(get_cpu_temp());
    display_cpu_usage(get_cpu_usage());
}

static int get_cpu_temp() {
    int fd = open(cpu_temp_file, O_RDONLY);
    if (fd < 0) {
        perror("open");
        return -1;
    }
    char temp_str[10];
    read(fd, temp_str, 10);
    close(fd);
    return atoi(temp_str);
}

static int get_cpu_usage() {
    int fd = open(cpu_usage_file, O_RDONLY);
    if (fd < 0) {
        perror("open");
        return -1;
    }
    char usage_str[10];
    read(fd, usage_str, 10);
    close(fd);
    return atoi(usage_str);
}

static void signal_handler(int signum) {
    i2c_close();
    exit(EXIT_SUCCESS);
}

int main() {
    signal(SIGINT, signal_handler);

    i2c_init();

    while (1) {
        display_update();
        usleep(1000000); // 1 second delay
    }

    return 0;
}

