#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/time.h>
#include <signal.h>
#include <string.h>

#define I2C_BUS 1
#define MLX75031_ADDR 0x29
#define MLX75031_REG_TIME 0x00
#define MLX75031_REG_DISTANCE 0x01
#define MLX75031_REG_CONTROL 0x0F

#define I2C_TIMEOUT 100
#define I2C_READ_TIMEOUT 100
#define I2C_WRITE_TIMEOUT 100
#define FILE_LOG "depth_log.csv"

typedef struct {
    int i2c_fd;
    int distance_fd;
    int log_fd;
    struct timeval start_time;
} SensorState;

void handle_sensor_init_error(SensorState *state) {
    fprintf(stderr, "Sensor initialization failed\n");
    if (state->i2c_fd > 0) {
        close(state->i2c_fd);
    }
    if (state->distance_fd > 0) {
        close(state->distance_fd);
    }
    if (state->log_fd > 0) {
        close(state->log_fd);
    }
    exit(EXIT_FAILURE);
}

void handle_i2c_read_error(SensorState *state) {
    fprintf(stderr, "I2C read error\n");
    if (state->i2c_fd > 0) {
        close(state->i2c_fd);
    }
    if (state->distance_fd > 0) {
        close(state->distance_fd);
    }
    if (state->log_fd > 0) {
        close(state->log_fd);
    }
    exit(EXIT_FAILURE);
}

void handle_i2c_write_error(SensorState *state) {
    fprintf(stderr, "I2C write error\n");
    if (state->i2c_fd > 0) {
        close(state->i2c_fd);
    }
    if (state->distance_fd > 0) {
        close(state->distance_fd);
    }
    if (state->log_fd > 0) {
        close(state->log_fd);
    }
    exit(EXIT_FAILURE);
}

void handle_file_open_error(SensorState *state) {
    fprintf(stderr, "File open error\n");
    if (state->log_fd > 0) {
        close(state->log_fd);
    }
    exit(EXIT_FAILURE);
}

void handle_signal(int signum) {
    if (state->i2c_fd > 0) {
        close(state->i2c_fd);
    }
    if (state->distance_fd > 0) {
        close(state->distance_fd);
    }
    if (state->log_fd > 0) {
        close(state->log_fd);
    }
    exit(EXIT_SUCCESS);
}

int i2c_read(int fd, uint8_t *buf, size_t size, int timeout) {
    int n = read(fd, buf, size);
    if (n < 0) {
        perror("read");
        return -1;
    }
    if (n != size) {
        fprintf(stderr, "I2C read error\n");
        return -1;
    }
    return 0;
}

int i2c_write(int fd, uint8_t *buf, size_t size, int timeout) {
    int n = write(fd, buf, size);
    if (n < 0) {
        perror("write");
        return -1;
    }
    return 0;
}

int i2c_init(int fd, int addr, int reg, uint8_t *buf, int timeout) {
    buf[0] = addr;
    if (write(fd, buf, 1) < 0) {
        perror("write");
        return -1;
    }
    if (i2c_read(fd, buf, 1, timeout) < 0) {
        return -1;
    }
    if (buf[0] != addr) {
        fprintf(stderr, "I2C read error\n");
        return -1;
    }
    buf[0] = reg;
    if (write(fd, buf, 1) < 0) {
        perror("write");
        return -1;
    }
    if (i2c_read(fd, buf, 1, timeout) < 0) {
        return -1;
    }
    return 0;
}

int main() {
    SensorState state;
    state.i2c_fd = -1;
    state.distance_fd = -1;
    state.log_fd = -1;
    state.start_time.tv_sec = 0;
    state.start_time.tv_usec = 0;

    state.i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (state.i2c_fd < 0) {
        perror("open");
        handle_sensor_init_error(&state);
    }

    if (ioctl(state.i2c_fd, I2C_SLAVE, MLX75031_ADDR) < 0) {
        perror("ioctl");
        handle_sensor_init_error(&state);
    }

    uint8_t buf[2];
    if (i2c_init(state.i2c_fd, MLX75031_ADDR, MLX75031_REG_CONTROL, buf, I2C_TIMEOUT) < 0) {
        handle_sensor_init_error(&state);
    }

    if (buf[0] & 0x10) {
        fprintf(stderr, "Sensor is in sleep mode\n");
        handle_sensor_init_error(&state);
    }

    state.distance_fd = open(FILE_LOG, O_CREAT | O_WRONLY | O_TRUNC, 0644);
    if (state.distance_fd < 0) {
        perror("open");
        handle_file_open_error(&state);
    }

    if (write(state.distance_fd, "timestamp,depth\n", 16) < 0) {
        perror("write");
        handle_file_open_error(&state);
    }

    while (1) {
        struct timeval now;
        gettimeofday(&now, NULL);
        if (now.tv_sec < state.start_time.tv_sec || (now.tv_sec == state.start_time.tv_sec && now.tv_usec < state.start_time.tv_usec)) {
            continue;
        }

        uint8_t distance_buf[2];
        if (i2c_read(state.i2c_fd, distance_buf, 2, I2C_READ_TIMEOUT) < 0) {
            handle_i2c_read_error(&state);
        }

        if (distance_buf[0] == 0xFF) {
            fprintf(stderr, "I2C read error\n");
            distance_buf[0] = 0xFF;
            distance_buf[1] = 0xFF;
        }

        int distance = (distance_buf[0] << 8) | distance_buf[1];
        if (distance < 0) {
            distance = -1;
        }

        if (write(state.distance_fd, "timestamp,"strptime(\"%s\", \"%s\").tv_sec,\",\", distance\n", now.tv_sec, now.tv_usec) < 0) {
            perror("write");
            handle_file_open_error(&state);
        }

        if (state.log_fd > 0) {
            if (ftruncate(state.log_fd, 0) < 0) {
                perror("ftruncate");
                handle_file_open_error(&state);
            }
            if (fseek(state.log_fd, 0, SEEK_SET) < 0) {
                perror("fseek");
                handle_file_open_error(&state);
            }
        }
    }

    signal(SIGINT, handle_signal);

    return 0;
}

