static void handleSigInt(int signum) {
    if (Si1145Handle->fd > 0) {
        close(Si1145Handle->fd);
    }
    if (fopen("biometric_log.txt", "a") == NULL) {
        perror("Error opening log file");
        exit(EXIT_FAILURE);
    }
    fclose(fopen("biometric_log.txt", "a"));
    exit(EXIT_SUCCESS);
}

static int i2cOpen(const char *dev) {
    int fd;
    if ((fd = open(dev, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return -1;
    }
    return fd;
}

static int i2cSetSlaveAddr(int fd, uint8_t addr) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to set I2C slave address");
        return -1;
    }
    return 0;
}

static int i2cRead8(int fd, uint8_t reg, uint8_t *value) {
    if (read(fd, value, SI1145_REG_SIZE) < 0) {
        perror("Failed to read I2C register");
        return -1;
    }
    return 0;
}

static int i2cWrite8(int fd, uint8_t reg, uint8_t value) {
    if (write(fd, &value, SI1145_REG_SIZE) < 0) {
        perror("Failed to write I2C register");
        return -1;
    }
    return 0;
}

static int i2cControl(int fd, uint8_t control) {
    if (write(fd, &control, 1) < 0) {
        perror("Failed to write I2C control register");
        return -1;
    }
    return 0;
}

static int i2cRead16(int fd, uint8_t *low, uint8_t *high) {
    if (read(fd, low, SI1145_REG_SIZE) < 0) {
        perror("Failed to read I2C register");
        return -1;
    }
    if (read(fd, high, SI1145_REG_SIZE) < 0) {
        perror("Failed to read I2C register");
        return -1;
    }
    return 0;
}

static int i2cRead32(int fd, uint32_t *value) {
    uint8_t low, high;
    if (i2cRead16(fd, &low, &high) < 0) {
        return -1;
    }
    *value = (uint32_t)high << 16 | (uint32_t)low;
    return 0;
}

static int i2cReadFloat(int fd, float *value) {
    uint32_t value32;
    if (i2cRead32(fd, &value32) < 0) {
        return -1;
    }
    *value = *(float *)&value32;
    return 0;
}

