static int i2cReadString(int fd, char *buffer, size_t size, uint8_t delimiter) {
    if (read(fd, buffer, size) < 0) {
        perror("Failed to read I2C string");
        return -1;
    }
    char *ptr = buffer;
    while (*ptr != delimiter && ptr < buffer + size) {
        ptr++;
    }
    *ptr = '\0';
    return 0;
}

