#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/time.h>
#include <signal.h>
#include <stdint.h>
#include <string.h>
#include <time.h>

#define I2C_BUS 1
#define SI1145_PART_ID 0x3D00

typedef struct {
    uint32_t proximity;
    uint16_t ambient_light;
} Si1145Data;

typedef struct {
    int fd;
    int i2c_fd;
    Si1145Data data;
} Si1145Handler;

static void sigint_handler(int signum) {
    if (Si1145Handler::instance->fd > 0) {
        close(Si1145Handler::instance->fd);
    }
    if (Si1145Handler::instance->i2c_fd > 0) {
        close(Si1145Handler::instance->i2c_fd);
    }
    Si1145Handler::instance->data.proximity = 0;
    Si1145Handler::instance->data.ambient_light = 0;
    Si1145Handler::instance->sensor_api_call();
    exit(0);
}

static Si1145Handler* Si1145Handler::instance = NULL;

Si1145Handler* Si1145Handler::getInstance() {
    if (!instance) {
        instance = (Si1145Handler*)malloc(sizeof(Si1145Handler));
        if (!instance) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
        instance->fd = -1;
        instance->i2c_fd = -1;
        instance->sensor_api_call = Si1145Handler::sensor_api_call;
        signal(SIGINT, sigint_handler);
    }
    return instance;
}

void Si1145Handler::sensor_api_call() {
    if (instance->fd > 0) {
        munmap(instance->buffer, 1024);
    }
    instance->fd = open("/dev/i2c-1", O_RDWR);
    if (instance->fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }
    if (ioctl(instance->fd, I2C_SLAVE, SI1145_PART_ID) < 0) {
        perror("Failed to set I2C slave address");
        exit(EXIT_FAILURE);
    }
    instance->i2c_fd = instance->fd;
    instance->buffer = mmap(0, 1024, PROT_READ | PROT_WRITE, MAP_SHARED, instance->fd, 0);
    if (instance->buffer == MAP_FAILED) {
        perror("Failed to mmap I2C buffer");
        exit(EXIT_FAILURE);
    }
    instance->data.proximity = *(uint32_t*)(instance->buffer + 0x00);
    instance->data.ambient_light = *(uint16_t*)(instance->buffer + 0x18);
}

void Si1145Handler::read_data() {
    if (instance->i2c_fd > 0) {
        munmap(instance->buffer, 1024);
    }
    instance->fd = open("/dev/i2c-1", O_RDWR);
    if (instance->fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }
    if (ioctl(instance->fd, I2C_SLAVE, SI1145_PART_ID) < 0) {
        perror("Failed to set I2C slave address");
        exit(EXIT_FAILURE);
    }
    instance->i2c_fd = instance->fd;
    instance->buffer = mmap(0, 1024, PROT_READ | PROT_WRITE, MAP_SHARED, instance->fd, 0);
    if (instance->buffer == MAP_FAILED) {
        perror("Failed to mmap I2C buffer");
        exit(EXIT_FAILURE);
    }
    instance->data.proximity = *(uint32_t*)(instance->buffer + 0x00);
    instance->data.ambient_light = *(uint16_t*)(instance->buffer + 0x18);
}

void Si1145Handler::write_data() {
    if (instance->i2c_fd > 0) {
        munmap(instance->buffer, 1024);
    }
    instance->fd = open("/dev/i2c-1", O_RDWR);
    if (instance->fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }
    if (ioctl(instance->fd, I2C_SLAVE, SI1145_PART_ID) < 0) {
        perror("Failed to set I2C slave address");
        exit(EXIT_FAILURE);
    }
    instance->i2c_fd = instance->fd;
    instance->buffer = mmap(0, 1024, PROT_READ | PROT_WRITE, MAP_SHARED, instance->fd, 0);
    if (instance->buffer == MAP_FAILED) {
        perror("Failed to mmap I2C buffer");
        exit(EXIT_FAILURE);
    }
    *(uint32_t*)(instance->buffer + 0x00) = instance->data.proximity;
    *(uint16_t*)(instance->buffer + 0x18) = instance->data.ambient_light;
    if (write(instance->i2c_fd, instance->buffer, 1024) < 0) {
        perror("Failed to write to I2C bus");
        exit(EXIT_FAILURE);
    }
}

void Si1145Handler::log_data() {
    char buffer[256];
    struct tm* timeinfo;
    time_t rawtime;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(buffer, 256, "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(stderr, "Logging: %s, Proximity: %u, Ambient Light: %u\n", buffer, instance->data.proximity, instance->data.ambient_light);
    if (fopen("biometric_data.log", "a") == NULL) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
    fprintf(stderr, "Logging to file\n");
    fprintf(stderr, "Date,Proximity,Ambient Light\n");
    fprintf(stderr, "%s,%u,%u\n", buffer, instance->data.proximity, instance->data.ambient_light);
    fflush(stderr);
    if (fclose("biometric_data.log") != 0) {
        perror("Failed to close log file");
        exit(EXIT_FAILURE);
    }
}

int main() {
    Si1145Handler* si1145 = Si1145Handler::getInstance();
    if (si1145->data.proximity == 0 || si1145->data.ambient_light == 0) {
        fprintf(stderr, "Sensor not found or not responding\n");
        return 1;
    }
    while (1) {
        si1145->log_data();
        sleep(1);
    }
    return 0;
}

