typedef struct {
    int fd;
    int i2c_fd;
    int color_fd;
    int proximity_fd;
    int proximity_value;
    int color_r;
    int color_g;
    int color_b;
    time_t timestamp;
} APDS9960State;

void init_i2c_bus(APDS9960State *state) {
    char i2c_filename[50];
    snprintf(i2c_filename, sizeof(i2c_filename), "/dev/i2c-%d", I2C_BUS);
    state->i2c_fd = open(i2c_filename, O_RDWR);
    if (state->i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }
    if (ioctl(state->i2c_fd, I2C_SLAVE, APDS9960_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        exit(EXIT_FAILURE);
    }
}

