#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/ioctl.h>
#include <linux/i2c.h>
#include <errno.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_DEVICE "/dev/i2c-1"
#define SI1182_ADDR 0x40
#define PROXIMITY_REG 0x00
#define AMBIENT_REG 0x01
#define PROXIMITY_OFFSET 0x00
#define AMBIENT_OFFSET 0x00
#define PROXIMITY_REG_SIZE 2
#define AMBIENT_REG_SIZE 2
#define I2C_TIMEOUT 100
#define I2C_RETRIES 3

typedef struct {
    int fd;
    int proximetry;
    int ambient;
} Si1182Handle;

void handleSigint(int signum) {
    if (Si1182Handle->fd > 0) {
        close(Si1182Handle->fd);
    }
    free(Si1182Handle);
    exit(0);
}

int i2cRead(int fd, unsigned char *buf, int size, int addr, int timeout) {
    struct i2c_msg msg[1];
    struct i2c_rdwr_ioctl_msg ioctl_msg;
    int ret;

    msg[0].addr = addr;
    msg[0].flags = I2C_M_RD;
    msg[0].len = size;
    memcpy(msg[0].data, buf, size);

    ioctl_msg.msgs = msg;
    ioctl_msg.nmsgs = 1;

    ret = ioctl(fd, I2C_RDWR, &ioctl_msg);
    if (ret < 0) {
        fprintf(stderr, "Error reading I2C: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int i2cWrite(int fd, unsigned char *buf, int size, int addr, int timeout) {
    struct i2c_msg msg[1];
    struct i2c_rdwr_ioctl_msg ioctl_msg;
    int ret;

    msg[0].addr = addr;
    msg[0].flags = I2C_M_WRITE;
    msg[0].len = size;
    memcpy(msg[0].data, buf, size);

    ioctl_msg.msgs = msg;
    ioctl_msg.nmsgs = 1;

    ret = ioctl(fd, I2C_RDWR, &ioctl_msg);
    if (ret < 0) {
        fprintf(stderr, "Error writing I2C: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main() {
    Si1182Handle *handle = NULL;
    int fd;
    unsigned char buf[PROXIMITY_REG_SIZE + AMBIENT_REG_SIZE];
    char timestamp[20];
    int proximetry, ambient;
    int retry = 0;
    struct timespec ts;

    fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    handle = malloc(sizeof(Si1182Handle));
    handle->fd = fd;

    signal(SIGINT, handleSigint);

    while (1) {
        if (i2cWrite(handle->fd, buf, PROXIMITY_REG_SIZE + AMBIENT_REG_SIZE, SI1182_ADDR, I2C_TIMEOUT) < 0) {
            fprintf(stderr, "Failed to write to I2C: %s\n", strerror(errno));
            continue;
        }

        retry = 0;
        while (retry < I2C_RETRIES) {
            if (i2cRead(handle->fd, buf, PROXIMITY_REG_SIZE + AMBIENT_REG_SIZE, SI1182_ADDR, I2C_TIMEOUT) < 0) {
                fprintf(stderr, "Failed to read from I2C: %s\n", strerror(errno));
                retry++;
                continue;
            }
            break;
        }

        if (retry == I2C_RETRIES) {
            fprintf(stderr, "Failed to read from I2C after %d retries\n", I2C_RETRIES);
            continue;
        }

        proximetry = (buf[PROXIMITY_REG] << 8) | buf[PROXIMITY_REG + 1];
        ambient = (buf[AMBIENT_REG] << 8) | buf[AMBIENT_REG + 1];

        if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec))) {
            printf("%s %d %d\n", timestamp, proximetry, ambient);
        }

        if (fopen("biometric_log.txt", "a") == NULL) {
            perror("Failed to open log file");
            return 1;
        }

