#define LED_PIN 17
#define LED_PIN_GPIO 1

#define DEFAULT_THRESHOLD 100000

int i2c_fd;
int gpio_fd;

void init_i2c() {
    if ((i2c_fd = open("/dev/i2c-ad0", O_RDWR)) < 0) {
        perror("Failed to open i2c device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set i2c slave address");
        exit(EXIT_FAILURE);
    }

    if (read_i2c_byte(WHO_AM_I) != 0) {
        perror("Failed to read WHO_AM_I register");
        exit(EXIT_FAILURE);
    }
}

int read_i2c_byte(uint8_t reg) {
    int ret;
    uint8_t data;

    ret = i2c_smbus_read_byte_data(i2c_fd, reg, &data);
    if (ret < 0) {
        perror("Failed to read i2c byte");
        return -1;
    }

    return 0;
}

int write_i2c_byte(uint8_t reg, uint8_t val) {
    int ret;
    ret = i2c_smbus_write_byte_data(i2c_fd, reg, val);
    if (ret < 0) {
        perror("Failed to write i2c byte");
        return -1;
    }

    return 0;
}

int read_i2c_word(uint8_t reg, uint8_t *data) {
    int ret;
    uint8_t data1, data2;

    ret = i2c_smbus_read_word_data(i2c_fd, reg, &data1, &data2);
    if (ret < 0) {
        perror("Failed to read i2c word");
        return -1;
    }

    *data = (data1 << 8) | data2;

    return 0;
}

int write_i2c_word(uint8_t reg, uint16_t val) {
    int ret;
    uint8_t data1, data2;

    data1 = (val >> 8) & 0xFF;
    data2 = val & 0xFF;

    ret = i2c_smbus_write_byte_data(i2c_fd, reg, data1, data2);
    if (ret < 0) {
        perror("Failed to write i2c word");
        return -1;
    }

    return 0;
}

void init_gpio() {
    if ((gpio_fd = wiringPiGpioInit()) < 0) {
        perror("Failed to initialize GPIO");
        exit(EXIT_FAILURE);
    }

    if (wiringPiGpioSetMode(gpio_fd, PI_OUTPUT) < 0) {
        perror("Failed to set GPIO mode");
        exit(EXIT_FAILURE);
    }

    if (wiringPiGpioSetPullUpDnControl(gpio_fd, LED_PIN_GPIO, PI_DISABLE) < 0) {
        perror("Failed to disable pull-up/down");
        exit(EXIT_FAILURE);
    }

    pinMode(LED_PIN, OUTPUT);
    digitalWrite(LED_PIN, LOW);
}

void cleanup_gpio() {
    if (gpio_fd >= 0) {
        wiringPiGpioUnexport(gpio_fd);
    }
}

void cleanup_i2c() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
}

void handle_error(int error_code) {
    if (error_code < 0) {
        perror("Error");
        cleanup_gpio();
        cleanup_i2c();
        exit(EXIT_FAILURE);
    }
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("Usage: %s <threshold>\n", argv[0]);
        return 1;
    }

    int threshold = atoi(argv[1]);
    if (threshold <= 0) {
        printf("Threshold must be a positive integer\n");
        return 1;
    }

    init_i2c();
    init_gpio();

    int measurement_interval = 50000; // 50 ms
    if (argc > 2) {
        measurement_interval = atoi(argv[2]);
    }

    uint8_t config[2] = {CONFIG_MEASUREMENT_INTERVAL, measurement_interval};
    if (write_i2c_byte(CONFIG, CONFIG_MEASUREMENT_INTERVAL) < 0) {
        handle_error(-1);
    }

    uint8_t resolution = 0x01;
    if (argc > 3) {
        resolution = atoi(argv[3]);
    }

    if (resolution < 0 || resolution > 0x03) {
        printf("Resolution must be 0x01, 0x02, or 0x03\n");
        cleanup_gpio();
        cleanup_i2c();
        return 1;
    }

    uint8_t config_resolution[2] = {CONFIG_MEASUREMENT_RESOLUTION, resolution};
    if (write_i2c_byte(CONFIG, CONFIG_MEASUREMENT_RESOLUTION) < 0) {
        handle_error(-1);
    }

    uint8_t timeout = 0x00;
    if (argc > 4) {
        timeout = atoi(argv[4]);
    }

    if (timeout < 0 || timeout > 0x3F) {
        printf("Timeout must be 0x00 to 0x3F\n");
        cleanup_gpio();
        cleanup_i2c();
        return 1;
    }

    uint8_t config_timeout[2] = {CONFIG_MEASUREMENT_TIMEOUT, timeout};
    if (write_i2c_byte(CONFIG, CONFIG_MEASUREMENT_TIMEOUT) < 0) {
        handle_error(-1);
    }

    uint8_t mode = 0x01;
    if (argc > 5) {
        mode = atoi(argv[5]);
    }

    if (mode < 0 || mode > 0x07) {
        printf("Mode must be 0x01 to 0x07\n");
        cleanup_gpio();
        cleanup_i2c();
        return 1;
    }

    uint8_t config_mode[2] = {CONFIG_MEASUREMENT_MODE, mode};
    if (write_i2c_byte(CONFIG, CONFIG_MEASUREMENT_MODE) < 0) {
        handle_error(-1);
    }

    uint8_t trigger = 0x00;
    if (argc > 6) {
        trigger = atoi(argv[6]);
    }

    if (trigger < 0 || trigger > 0x07) {
        printf("Trigger must be 0x00 to 0x07\n");
        cleanup_gpio();
        cleanup_i2c();
        return 1;
    }

    uint8_t config_trigger[2] = {CONFIG_MEASUREMENT_TRIGGER, trigger};
    if (write_i2c_byte(CONFIG, CONFIG_MEASUREMENT_TRIGGER) < 0) {
        handle_error(-1);
    }

    uint8_t source = 0x00;
    if (argc > 7) {
        source = atoi(argv[7]);
    }

    if (source < 0 || source > 0x07) {
        printf("Source must be 0x00 to 0x07\n");
        cleanup_gpio();
        cleanup_i2c();
        return 1;
    }

    uint8_t config_source[2] = {CONFIG_MEASUREMENT_TRIGGER_SOURCE, source};
    if (write_i2c_byte(CONFIG, CONFIG_MEASUREMENT_TRIGGER_SOURCE) < 0) {
        handle_error(-1);
    }

    uint8_t source_mode = 0x00;
    if (argc > 8) {
        source_mode = atoi(argv[8]);
    }

    if (source_mode < 0 || source_mode > 0x07) {
        printf("Source mode must be 0x00 to 0x07\n");
        cleanup_gpio();
        cleanup_i2c();
        return 1;
    }

    uint8_t config_source_mode[2] = {CONFIG_MEASUREMENT_TRIGGER_SOURCE_MODE_0, source_mode};
    if (write_i2c_byte(CONFIG, CONFIG_MEASUREMENT_TRIGGER_SOURCE_MODE_0) < 0) {
        handle_error(-1);
    }

    while (1) {
        int distance;
        if (read_i2c_word(MEASUREMENT, &distance) < 0) {
            handle_error(-1);
        }

        if (distance < threshold) {
            digitalWrite(LED_PIN, HIGH);
        } else {
            digitalWrite(LED_PIN, LOW);
        }

        char timestamp[20];
        struct tm *now = localtime(&time(NULL));
        strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", now);

        FILE *log_file = fopen("tof_log.txt", "a");
        if (log_file == NULL) {
            perror("Failed to open log file");
            cleanup_gpio();
            cleanup_i2c();
            return 1;
        }

        fprintf(log_file, "%s %d mm\n", timestamp, distance);
        fclose(log_file);

        usleep(measurement_interval * 1000);
    }

    cleanup_gpio();
    cleanup_i2c();

    return 0;
}

