#define MEASUREMENT_SAMPLE_DELAY 100000  // 100ms

#define LOG_FILE "/intrusion_log.txt"

#define LOG_HEADER "Timestamp: %Y-%m-%d %H:%M:%S, Average Distance: %f mm\n"

typedef struct {
    int i2c_fd;
    int sensor_present;
} SensorState;

void handle_sensor_absent(int i2c_fd) {
    if (i2c_fd > 0) {
        close(i2c_fd);
    }
}

void handle_bus_error(int i2c_fd) {
    if (i2c_fd > 0) {
        close(i2c_fd);
    }
}

void handle_sigint(int sig) {
    if (SIGINT == sig) {
        handle_sensor_absent(SensorState.i2c_fd);
        handle_bus_error(SensorState.i2c_fd);
        exit(0);
    }
}

int main() {
    struct iocb iocb;
    struct iovec iovec;
    char buffer[MEASUREMENT_RESPONSE_SIZE];
    SensorState sensor_state;
    FILE *log_file;
    int i, sample_count = 0;
    uint16_t distance;
    uint64_t timestamp;
    double average_distance;

    signal(SIGINT, handle_sigint);

    sensor_state.i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (sensor_state.i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    if (ioctl(sensor_state.i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        return 1;
    }

    iocb.iov_base = &buffer;
    iocb.iov_len = MEASUREMENT_RESPONSE_SIZE;

    while (1) {
        if (!sensor_state.sensor_present) {
            handle_sensor_absent(sensor_state.i2c_fd);
            continue;
        }

        if (ioctl(sensor_state.i2c_fd, I2C_SMBUS_WRITE, &MEASUREMENT_COMMAND) < 0) {
            perror("Failed to send measurement command");
            handle_bus_error(sensor_state.i2c_fd);
            continue;
        }

        if (ioctl(sensor_state.i2c_fd, I2C_SMBUS_READ, &MEASUREMENT_COMMAND) < 0) {
            perror("Failed to read measurement response");
            handle_bus_error(sensor_state.i2c_fd);
            continue;
        }

        if (read(sensor_state.i2c_fd, buffer, MEASUREMENT_RESPONSE_SIZE) < 0) {
            perror("Failed to read measurement response");
            handle_bus_error(sensor_state.i2c_fd);
            continue;
        }

        if (buffer[0] != MEASUREMENT_RESPONSE_HEADER) {
            fprintf(stderr, "Invalid measurement response header\n");
            handle_bus_error(sensor_state.i2c_fd);
            continue;
        }

        for (i = 0; i < MEASUREMENT_SAMPLE_COUNT; i++) {
            usleep(MEASUREMENT_SAMPLE_DELAY);
            if (read(sensor_state.i2c_fd, buffer, MEASUREMENT_RESPONSE_SIZE) < 0) {
                perror("Failed to read measurement response");
                handle_bus_error(sensor_state.i2c_fd);
                continue;
            }

            if (buffer[0] != MEASUREMENT_RESPONSE_HEADER) {
                fprintf(stderr, "Invalid measurement response header\n");
                handle_bus_error(sensor_state.i2c_fd);
                continue;
            }

            distance = (uint16_t) (((uint16_t) buffer[11] << 8) | (uint16_t) buffer[12]);
            average_distance += distance / MEASUREMENT_SAMPLE_COUNT;
        }

        if (average_distance < 1000) {
            timestamp = time(NULL);
            fprintf(log_file, LOG_HEADER, timestamp, average_distance * 1000);
        }

        sample_count++;
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <time.h>

#define I2C_DEVICE "/dev/i2c-1"
#define VL53L0X_ADDR 0x29
#define VL53L0X_REG_MODEL_ID 0x00
#define VL53L0X_REG_RESULT_STATUS 0x01
#define VL53L0X_REG_RESULT_VALUE 0x02

#define I2C_TIMEOUT 100
#define I2C_POLL_INTERVAL 500
#define I2C_POLL_TIMEOUT 100

volatile sig_atomic_t running = 1;

void cleanup() {
    if (i2c_device) {
        close(i2c_device);
    }
    if (vl53l0x) {
        vl53l0x_close(vl53l0x);
    }
    running = 0;
}

void handle_signal(int signum) {
    cleanup();
    running = 0;
    printf("Caught signal %d, exiting...\n", signum);
    exit(EXIT_SUCCESS);
}

int main() {
    struct i2c_msg messages[2];
    struct i2c_rdwr_ioctl_msg ioctl_msg;
    int i2c_fd;
    int result;
    int model_id;
    int distance;
    struct timespec timeout;

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sa.sa_flags = SA_RESTART;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    result = ioctl(i2c_fd, I2C_SLAVE, VL53L0X_ADDR);
    if (result < 0) {
        perror("Failed to set slave address");
        goto cleanup;
    }

    messages[0].addr = VL53L0X_ADDR;
    messages[0].flags = I2C_M_RD;
    messages[0].data[0] = VL53L0X_REG_MODEL_ID;
    messages[1].addr = VL53L0X_ADDR;
    messages[1].flags = I2C_M_RD;
    messages[1].data[0] = VL53L0X_REG_RESULT_STATUS;

    ioctl_msg.msgs = messages;
    ioctl_msg.nummsgs = 2;
    result = ioctl(i2c_fd, I2C_RDWR, &ioctl_msg);
    if (result < 0) {
        perror("Failed to read sensor model ID");
        goto cleanup;
    }

    model_id = messages[0].data[0];
    if (model_id != 0x52) {
        printf("Error: VL53L0X model ID does not match (expected 0x52, got 0x%02x)\n", model_id);
        goto cleanup;
    }

    vl53l0x = vl53l0x_open(I2C_DEVICE, VL53L0X_ADDR);
    if (!vl53l0x) {
        perror("Failed to open VL53L0X");
        goto cleanup;
    }

    timeout.tv_sec = I2C_POLL_TIMEOUT / 1000;
    timeout.tv_nsec = (I2C_POLL_TIMEOUT % 1000) * 1000;
    result = vl53l0x_read_result_status(vl53l0x, &distance, &timeout);
    if (result < 0) {
        perror("Failed to read distance from VL53L0X");
        goto cleanup;
    }

    while (running) {
        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);
        if (now.tv_sec * 1000 + now.tv_nsec / 1000 < last_print_time.tv_sec * 1000 + last_print_time.tv_nsec / 1000) {
            continue;
        }

        struct timespec timeout;
        timeout.tv_sec = I2C_POLL_TIMEOUT / 1000;
        timeout.tv_nsec = (I2C_POLL_TIMEOUT % 1000) * 1000;
        result = vl53l0x_read_result_status(vl53l0x, &distance, &timeout);
        if (result < 0) {
            fprintf(stderr, "Error reading VL53L0X: %s\n", strerror(errno));
            continue;
        }

        char buffer[128];
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", localtime(&now));
        printf("%s Distance: %d mm\n", buffer, distance);
        fflush(stdout);
        last_print_time = now;
        usleep(I2C_POLL_INTERVAL * 1000);
    }

cleanup:
    cleanup();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define PROX_DATA_REG 0x00
#define PROX_DATA_SIZE 2

#define I2C_DEVICE "/dev/i2c-" I2C_BUS

int i2c_fd = -1;
int prox_fd = -1;

void i2c_error_handler(int err) {
    if (err < 0) {
        perror("i2c ioctl");
        exit(EXIT_FAILURE);
    }
}

void prox_error_handler(int err) {
    if (err < 0) {
        perror("prox ioctl");
        exit(EXIT_FAILURE);
    }
}

void sigint_handler(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (prox_fd != -1) {
        close(prox_fd);
    }
    exit(EXIT_SUCCESS);
}

int main() {
    struct i2c_msg msg[1];
    struct i2c_rdma_msg rdma_msg[1];
    struct i2c_rdma_control control;

    signal(SIGINT, sigint_handler);

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd == -1) {
        perror("open i2c device");
        exit(EXIT_FAILURE);
    }

    i2c_error_handler(ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR));

    msg[0].addr = I2C_ADDR;
    msg[0].flags = I2C_M_RD;
    msg[0].data[0] = PROX_DATA_REG;
    msg[0].len = PROX_DATA_SIZE;

    prox_fd = open("/dev/i2c-prox", O_RDWR);
    if (prox_fd == -1) {
        perror("open prox device");
        exit(EXIT_FAILURE);
    }

    prox_error_handler(ioctl(prox_fd, I2C_SLAVE, I2C_ADDR));

    prox_fd = open("/dev/i2c-prox", O_RDWR);
    if (prox_fd == -1) {
        perror("open prox device");
        exit(EXIT_FAILURE);
    }

    prox_error_handler(ioctl(prox_fd, I2C_SLAVE, I2C_ADDR));

    while (1) {
        msg[0].len = PROX_DATA_SIZE;
        if (ioctl(i2c_fd, I2C_RDWR, msg) < 0) {
            i2c_error_handler(errno);
        }

        if (read(prox_fd, msg[0].data, PROX_DATA_SIZE) < 0) {
            prox_error_handler(errno);
        }

        printf("Proximity data: %u %u\n", msg[0].data[0], msg[0].data[1]);

        usleep(500000); // 500 ms
    }

    return 0;
}

