#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x28
#define GPIO17 1
#define GPIO18 2
#define I2C_TIMEOUT 100

typedef struct {
    int fd;
    int i2c_fd;
    int chip_fd;
    int gpio_fd;
    int gpio_line_fd;
    int status;
    char timestamp[256];
} I2CGPIOHandler;

static void handle_sigint(int signum) {
    I2CGPIOHandler handler;
    handler.status = -1;
    handler.fd = -1;
    handler.i2c_fd = -1;
    handler.chip_fd = -1;
    handler.gpio_fd = -1;
    handler.gpio_line_fd = -1;

    if (handler.chip_fd != -1) {
        close(handler.chip_fd);
    }
    if (handler.gpio_fd != -1) {
        close(handler.gpio_fd);
    }
    if (handler.gpio_line_fd != -1) {
        gpiod_device_free(&handler.gpio_line_fd);
    }
    if (handler.i2c_fd != -1) {
        close(handler.i2c_fd);
    }
    if (handler.fd != -1) {
        close(handler.fd);
    }
    printf("Graceful shutdown initiated.\n");
    exit(0);
}

static void handle_sigterm(int signum) {
    handle_sigint(signum);
}

static int i2c_open(const char *bus, int addr) {
    int fd;
    struct i2c_msg msg[1];
    struct i2c_rdwr_ioctl_data data;
    data.msgs = msg;
    data.nmsgs = 1;
    data.flags = I2C_RDWR;

    fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Failed to open i2c bus");
        return -1;
    }

    msg[0].addr = addr;
    msg[0].flags = I2C_M_RD;
    data.msgs[0] = msg[0];

    if (ioctl(fd, I2C_RDWR, &data) < 0) {
        perror("Failed to open i2c bus");
        return -1;
    }

    return fd;
}

static int i2c_read(int fd, int addr, char *buf, size_t len) {
    int status;
    struct i2c_msg msg[1];
    struct i2c_rdwr_ioctl_data data;
    data.msgs = msg;
    data.nmsgs = 1;
    data.flags = I2C_M_RD;

    msg[0].addr = addr;
    msg[0].len = len;
    msg[0].buf = buf;

    if (ioctl(fd, I2C_RDWR, &data) < 0) {
        perror("Failed to read from i2c bus");
        return -1;
    }

    status = I2C_SUCCESS;
    if (msg[0].status < 0) {
        status = msg[0].status;
    }

    return status;
}

static int gpio_open(int fd, int line) {
    int status;
    struct gpiod_chip *chip;
    struct gpiod_line *line_fd;

    status = gpiod_chip_open(fd, &chip);
    if (status < 0) {
        perror("Failed to open gpio chip");
        return -1;
    }

    status = gpiod_chip_request_line(chip, line, &line_fd);
    if (status < 0) {
        perror("Failed to request gpio line");
        return -1;
    }

    return line_fd;
}

static int gpio_read(int line_fd) {
    int status;
    struct gpiod_line *line;
    status = gpiod_line_get_fd(line_fd, &line);
    if (status < 0) {
        perror("Failed to get gpio line fd");
        return -1;
    }

    status = read(line_fd, &status, sizeof(status));
    if (status < 0) {
        perror("Failed to read gpio line");
        return -1;
    }

    return status;
}

static int gpio_write(int line_fd, int value) {
    int status;
    struct gpiod_line *line;
    status = gpiod_line_get_fd(line_fd, &line);
    if (status < 0) {
        perror("Failed to get gpio line fd");
        return -1;
    }

    status = write(line_fd, &value, sizeof(value));
    if (status < 0) {
        perror("Failed to write to gpio line");
        return -1;
    }

    return status;
}

static int gpio_close(int line_fd) {
    int status;
    status = gpiod_line_release_fd(line_fd);
    if (status < 0) {
        perror("Failed to release gpio line");
        return -1;
    }

    return status;
}

static int gpio_chip_close(struct gpiod_chip *chip) {
    int status;
    status = gpiod_chip_release(chip);
    if (status < 0) {
        perror("Failed to release gpio chip");
        return -1;
    }

    return status;
}

static int gpio_bus_close(int fd) {
    int status;
    status = close(fd);
    if (status < 0) {
        perror("Failed to close gpio bus");
        return -1;
    }

    return status;
}

static int i2c_gpio_handler(I2CGPIOHandler *handler) {
    int status;
    int value;
    char timestamp[256];

    status = i2c_open(handler->fd, handler->i2c_addr);
    if (status < 0) {
        printf("Failed to open i2c bus: %d\n", status);
        return -1;
    }

    handler->i2c_fd = handler->fd;

    status = gpio_open(handler->gpio_fd, GPIO17);
    if (status < 0) {
        printf("Failed to open gpio line for GPIO17: %d\n", status);
        return -1;
    }

    handler->gpio_fd = handler->gpio_fd;

    handler->gpio_line_fd = gpio_open(handler->gpio_fd, GPIO18);
    if (handler->gpio_line_fd < 0) {
        printf("Failed to open gpio line for GPIO18: %d\n", handler->gpio_line_fd);
        return -1;
    }

    handler->gpio_line_fd = handler->gpio_line_fd;

    status = i2c_read(handler->i2c_fd, handler->i2c_addr, &value, 1);
    if (status < 0) {
        printf("Failed to read from i2c bus: %d\n", status);
        return -1;
    }

    snprintf(handler->timestamp, sizeof(handler->timestamp), "%s", ctime(&time(NULL)));
    printf("Initial value: %d\n", value);

    while (1) {
        status = gpio_read(handler->gpio_line_fd);
        if (status < 0) {
            printf("Failed to read gpio line: %d\n", status);
            return -1;
        }

        if (value != status) {
            value = status;
            snprintf(handler->timestamp, sizeof(handler->timestamp), "%s", ctime(&time(NULL)));
            printf("Obstacle detected: %d\n", value);
            gpio_write(handler->gpio_line_fd, 1);
        } else {
            value = status;
            snprintf(handler->timestamp, sizeof(handler->timestamp), "%s", ctime(&time(NULL)));
            printf("Obstacle not detected: %d\n", value);
            gpio_write(handler->gpio_line_fd, 0);
        }

        status = i2c_read(handler->i2c_fd, handler->i2c_addr, &value, 1);
        if (status < 0) {
            printf("Failed to read from i2c bus: %d\n", status);
            return -1;
        }

        snprintf(handler->timestamp, sizeof(handler->timestamp), "%s", ctime(&time(NULL)));
        printf("Timestamp: %s\n", handler->timestamp);
        printf("Value: %d\n", value);

        status = usleep(100000);
        if (status < 0) {
            printf("Failed to sleep: %d\n", status);
            return -1;
        }
    }

    return 0;
}

int main() {
    I2CGPIOHandler handler;
    handler.fd = -1;
    handler.i2c_fd = -1;
    handler.chip_fd = -1;
    handler.gpio_fd = -1;
    handler.gpio_line_fd = -1;
    handler.status = -1;

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    handler.status = i2c_gpio_handler(&handler);
    if (handler.status < 0) {
        printf("Failed to initialize i2c gpio handler: %d\n", handler.status);
        return -1;
    }

    return 0;
}

