    float distance;
} SensorData;

void handle_i2c_error(int err) {
    if (err < 0) {
        perror("I2C error");
        exit(EXIT_FAILURE);
    }
}

void handle_gpio_error(int err) {
    if (err < 0) {
        perror("GPIO error");
        exit(EXIT_FAILURE);
    }
}

void handle_log_error(int err) {
    if (err < 0) {
        perror("Log file error");
        exit(EXIT_FAILURE);
    }
}

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        if (SensorData.log_fd != -1) {
            close(SensorData.log_fd);
        }
        if (SensorData.gpio_err == 0) {
            gpioTerminate();
        }
        exit(EXIT_SUCCESS);
    }
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sa.sa_flags = SA_RESTART;
    sigemptyset(&sa.sa_mask);

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    SensorData sensor_data;
    sensor_data.fd = -1;
    sensor_data.i2c_fd = -1;
    sensor_data.i2c_err = 0;
    sensor_data.gpio_err = 0;
    sensor_data.log_fd = -1;
    sensor_data.log_err = 0;

    // Open I2C device
    if ((sensor_data.i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR)) < 0) {
        handle_log_error(sensor_data.log_fd);
        exit(EXIT_FAILURE);
    }
    if (ioctl(sensor_data.i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        handle_i2c_error(sensor_data.i2c_err);
        exit(EXIT_FAILURE);
    }

    // Set up GPIO pin
    if (gpioInitialise() < 0) {
        handle_gpio_error(sensor_data.gpio_err);
        exit(EXIT_FAILURE);
    }
    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) < 0) {
        handle_gpio_error(sensor_data.gpio_err);
        exit(EXIT_FAILURE);
    }
    if (gpioSetPullUp(GPIO_PIN, 0) < 0) {
        handle_gpio_error(sensor_data.gpio_err);
        exit(EXIT_FAILURE);
    }

    // Open log file
    if ((sensor_data.log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644)) < 0) {
        handle_log_error(sensor_data.log_err);
        exit(EXIT_FAILURE);
    }

    // Read distance
    while (1) {
        if (sensor_data.i2c_err) {
            handle_i2c_error(sensor_data.i2c_err);
            continue;
        }
        if (sensor_data.gpio_err) {
            handle_gpio_error(sensor_data.gpio_err);
            continue;
        }
        if (sensor_data.log_err) {
            handle_log_error(sensor_data.log_err);
            continue;
        }

        // Read timestamp
        clock_gettime(CLOCK_MONOTONIC, &sensor_data.timestamp);

        // Read distance
        if (ioctl(sensor_data.i2c_fd, I2C_SMBUS_READ, 0x40) < 0) {
            sensor_data.i2c_err = -1;
            continue;
        }
        sensor_data.distance = (float) (sensor_data.timestamp.tv_nsec / 1e9);

        // Write to log file
        if (write(sensor_data.log_fd, LOG_FORMAT, sizeof(LOG_FORMAT)) < 0) {
            sensor_data.log_err = -1;
            continue;
        }
        if (write(sensor_data.log_fd, &sensor_data.distance, sizeof(sensor_data.distance)) < 0) {
            sensor_data.log_err = -1;
            continue;
        }

        // Check if distance is below 10.0 cm
        if (sensor_data.distance < 10.0) {
            gpioWrite(GPIO_PIN, 1);
        } else {
            gpioWrite(GPIO_PIN, 0);
        }

        // Sleep for 100 ms
        usleep(100000);
    }

    return 0;
}

