#define I2C_TIMEOUT 100
#define I2C_RETRY 3
#define I2C_RETRY_DELAY 100

#define DISTANCE_LOG_FILE "distance_log.csv"

typedef struct {
    int fd;
    int i2c_fd;
    int distance_log_fd;
    int distance_log_mode;
    int distance_log_size;
    int distance_log_offset;
    int distance_log_length;
    int distance_log_last_timestamp;
    int distance_log_last_distance;
} DistanceLogState;

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        fprintf(stderr, "Received signal %d, exiting...\n", signum);
        exit(EXIT_SUCCESS);
    }
}

void init_distance_log(DistanceLogState *state) {
    state->distance_log_fd = open(DISTANCE_LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (state->distance_log_fd == -1) {
        perror("Failed to open distance log file");
        exit(EXIT_FAILURE);
    }
    state->distance_log_mode = O_WRONLY | O_CREAT | O_APPEND;
    state->distance_log_size = 1024 * 1024; // 1MB buffer
    state->distance_log_offset = 0;
    state->distance_log_length = 0;
    state->distance_log_last_timestamp = 0;
    state->distance_log_last_distance = 0;
}

void cleanup_distance_log(DistanceLogState *state) {
    if (state->distance_log_fd != -1) {
        close(state->distance_log_fd);
    }
}

void write_distance_log(DistanceLogState *state, const char *timestamp, int distance_cm) {
    char buffer[128];
    snprintf(buffer, sizeof(buffer), "%s,%d\n", timestamp, distance_cm);
    if (state->distance_log_length + strlen(buffer) > state->distance_log_size) {
        fprintf(stderr, "Distance log buffer full, truncating...\n");
        state->distance_log_length = state->distance_log_size;
    }
    if (write(state->distance_log_fd, buffer, strlen(buffer)) != strlen(buffer)) {
        perror("Failed to write to distance log file");
        exit(EXIT_FAILURE);
    }
    state->distance_log_length += strlen(buffer);
}

void i2c_read(DistanceLogState *state, uint8_t *buffer, int length, int timeout) {
    int retries = 0;
    while (retries < I2C_RETRY) {
        if (state->i2c_fd == -1) {
            fprintf(stderr, "I2C device not initialized, retrying...\n");
            continue;
        }
        if (ioctl(state->i2c_fd, I2C_RDWR, (unsigned long)buffer) < 0) {
            perror("I2C read failed");
            if (errno == EIO) {
                fprintf(stderr, "I2C bus error, retrying...\n");
                usleep(I2C_RETRY_DELAY);
                retries++;
            } else {
                fprintf(stderr, "I2C read timeout, exiting...\n");
                exit(EXIT_FAILURE);
            }
        } else {
            break;
        }
    }
    if (retries == I2C_RETRY) {
        fprintf(stderr, "I2C read timeout, exiting...\n");
        exit(EXIT_FAILURE);
    }
}

void i2c_write(DistanceLogState *state, uint8_t *buffer, int length, int timeout) {
    int retries = 0;
    while (retries < I2C_RETRY) {
        if (state->i2c_fd == -1) {
            fprintf(stderr, "I2C device not initialized, retrying...\n");
            continue;
        }
        if (ioctl(state->i2c_fd, I2C_RDWR, (unsigned long)buffer) < 0) {
            perror("I2C write failed");
            if (errno == EIO) {
                fprintf(stderr, "I2C bus error, retrying...\n");
                usleep(I2C_RETRY_DELAY);
                retries++;
            } else {
                fprintf(stderr, "I2C write timeout, exiting...\n");
                exit(EXIT_FAILURE);
            }
        } else {
            break;
        }
    }
    if (retries == I2C_RETRY) {
        fprintf(stderr, "I2C write timeout, exiting...\n");
        exit(EXIT_FAILURE);
    }
}

void i2c_init(DistanceLogState *state) {
    state->i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (state->i2c_fd == -1) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }
    if (ioctl(state->i2c_fd, I2C_SLAVE, MLX75030_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        exit(EXIT_FAILURE);
    }
    state->distance_log_fd = open(DISTANCE_LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (state->distance_log_fd == -1) {
        perror("Failed to open distance log file");
        exit(EXIT_FAILURE);
    }
    state->distance_log_mode = O_WRONLY | O_CREAT | O_APPEND;
    state->distance_log_size = 1024 * 1024; // 1MB buffer
    state->distance_log_offset = 0;
    state->distance_log_length = 0;
    state->distance_log_last_timestamp = 0;
    state->distance_log_last_distance = 0;
}

void i2c_cleanup(DistanceLogState *state) {
    if (state->i2c_fd != -1) {
        close(state->i2c_fd);
    }
    if (state->distance_log_fd != -1) {
        close(state->distance_log_fd);
    }
}

void read_distance(DistanceLogState *state, uint8_t *buffer) {
    i2c_read(state, buffer, 2, I2C_TIMEOUT);
    if (state->distance_log_length + 7 > state->distance_log_size) {
        fprintf(stderr, "Distance log buffer full, truncating...\n");
        state->distance_log_length = state->distance_log_size;
    }
    if (write(state->distance_log_fd, buffer, 2) != 2) {
        perror("Failed to write to distance log file");
        exit(EXIT_FAILURE);
    }
    state->distance_log_length += 2;
    uint16_t distance = (buffer[0] << 8) | buffer[1];
    state->distance_log_last_timestamp = time(NULL);
    state->distance_log_last_distance = distance / 10;
    fprintf(stderr, "Distance: %d cm\n", state->distance_log_last_distance);
}

void write_distance(DistanceLogState *state, uint8_t *buffer) {
    i2c_write(state, buffer, 2, I2C_TIMEOUT);
    if (state->distance_log_length + 7 > state->distance_log_size) {
        fprintf(stderr, "Distance log buffer full, truncating...\n");
        state->distance_log_length = state->distance_log_size;
    }
    if (write(state->distance_log_fd, buffer, 2) != 2) {
        perror("Failed to write to distance log file");
        exit(EXIT_FAILURE);
    }
    state->distance_log_length += 2;
    uint16_t distance = (buffer[0] << 8) | buffer[1];
    state->distance_log_last_timestamp = time(NULL);
    state->distance_log_last_distance = distance / 10;
    fprintf(stderr, "Distance: %d cm\n", state->distance_log_last_distance);
}

int main() {
    DistanceLogState state;
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    init_distance_log(&state);
    i2c_init(&state);

    uint8_t buffer[2];
    struct timespec ts;
    ts.tv_sec = 0;
    ts.tv_nsec = 100000000; // 100ms

    while (1) {
        if (nanosleep(&ts, NULL) < 0) {
            perror("nanosleep failed");
            continue;
        }

        if (ioctl(state.i2c_fd, I2C_RDWR, (unsigned long)buffer) < 0) {
            perror("I2C read failed");
            continue;
        }

        if (state.distance_log_length + 7 > state.distance_log_size) {
            fprintf(stderr, "Distance log buffer full, truncating...\n");
            state.distance_log_length = state.distance_log_size;
        }

        if (write(state.distance_log_fd, buffer, 2) != 2) {
            perror("Failed to write to distance log file");
            continue;
        }

        state.distance_log_length += 2;
        uint16_t distance = (buffer[0] << 8) | buffer[1];
        state.distance_log_last_timestamp = time(NULL);
        state.distance_log_last_distance = distance / 10;
        fprintf(stderr, "Distance: %d cm\n", state.distance_log_last_distance);

        usleep(100000); // 100ms delay
    }

    cleanup_distance_log(&state);
    return 0;
}

