void init_sensor(int pin, Sensor *sensor) {
    int ret = gpiod_chip_open(sensor->chip, pin);
    if (ret < 0) {
        perror("gpiod_chip_open");
        exit(EXIT_FAILURE);
    }
    sensor->fd = ret;
    sensor->pin = pin;
    sensor->line = gpiod_chip_get_line(sensor->chip, pin);
    if (!sensor->line) {
        perror("gpiod_chip_get_line");
        exit(EXIT_FAILURE);
    }
    ret = gpiod_line_request_event(sensor->line, GPIOD_LINE_REQUEST_EDGE);
    if (ret < 0) {
        perror("gpiod_line_request_event");
        exit(EXIT_FAILURE);
    }
    ret = gpiod_line_request_callback(sensor->line, sensor->handle_event);
    if (ret < 0) {
        perror("gpiod_line_request_callback");
        exit(EXIT_FAILURE);
    }
    ret = gpiod_chip_request_release(sensor->chip, sensor->line);
    if (ret < 0) {
        perror("gpiod_chip_request_release");
        exit(EXIT_FAILURE);
    }
    sensor->last_value = 0;
