#include <stdint.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x38
#define MLX75030_I2C_SLAVE 0x3E
#define MLX75030_MEASUREMENT 0x00
#define MLX75030_MEASUREMENT_RESULT 0x01
#define MLX75030_MEASUREMENT_RESULT_HIGH 0x02
#define MLX75030_MEASUREMENT_RESULT_LOW 0x03
#define MLX75030_MEASUREMENT_RESULT_HIGH_LOW 0x04
#define MLX75030_MEASUREMENT_RESULT_HIGH_LOW_2 0x05
#define MLX75030_MEASUREMENT_RESULT_HIGH_LOW_3 0x06
#define MLX75030_MEASUREMENT_RESULT_HIGH_LOW_4 0x07
#define MLX75030_MEASUREMENT_RESULT_HIGH_LOW_5 0x08
#define MLX75030_MEASUREMENT_RESULT_HIGH_LOW_6 0x09
#define MLX75030_MEASUREMENT_RESULT_HIGH_LOW_7 0x0A
#define MLX75030_MEASUREMENT_RESULT_HIGH_LOW_8 0x0B
#define MLX75030_MEASUREMENT_RESULT_HIGH_LOW_9 0x0C
#define MLX75030_MEASUREMENT_RESULT_HIGH_LOW_10 0x0D
#define MLX75030_MEASUREMENT_RESULT_HIGH_LOW_11 0x0E
#define MLX75030_MEASUREMENT_RESULT_HIGH_LOW_12 0x0F

#define I2C_TIMEOUT 100
#define I2C_RETRY 3
#define I2C_DELAY 10

typedef struct {
    int fd;
    int retry_count;
    int i2c_timeout;
    int i2c_retry;
} I2CHandle;

static void i2c_read(I2CHandle *handle, uint8_t *buf, size_t size) {
    int i;
    for (i = 0; i < handle->i2c_retry; i++) {
        if (ioctl(handle->fd, I2C_SLAVE, handle->i2c_addr) < 0) {
            perror("ioctl I2C_SLAVE");
            return;
        }
        if (write(handle->fd, buf, size) != size) {
            perror("write");
            return;
        }
        if (read(handle->fd, buf, size) < 0) {
            perror("read");
            return;
        }
        if (handle->i2c_timeout > 0) {
            handle->i2c_timeout--;
        }
        if (handle->i2c_timeout == 0) {
            return;
        }
    }
}

static void i2c_write(I2CHandle *handle, uint8_t *buf, size_t size) {
    int i;
    for (i = 0; i < handle->i2c_retry; i++) {
        if (ioctl(handle->fd, I2C_SLAVE, handle->i2c_addr) < 0) {
            perror("ioctl I2C_SLAVE");
            return;
        }
        if (write(handle->fd, buf, size) != size) {
            perror("write");
            return;
        }
        if (handle->i2c_timeout > 0) {
            handle->i2c_timeout--;
        }
        if (handle->i2c_timeout == 0) {
            return;
        }
    }
}

static void i2c_close(I2CHandle *handle) {
    if (handle->fd > 0) {
        close(handle->fd);
    }
}

static void i2c_init(I2CHandle *handle) {
    handle->fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (handle->fd < 0) {
        perror("open");
        return;
    }
    if (ioctl(handle->fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        i2c_close(handle);
        return;
    }
    handle->retry_count = 0;
    handle->i2c_timeout = I2C_TIMEOUT;
    handle->i2c_retry = I2C_RETRY;
}

static void i2c_handle_close(int signum) {
    I2CHandle handle;
    i2c_init(&handle);
    i2c_close(&handle);
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = i2c_handle_close;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);

    I2CHandle handle;
    i2c_init(&handle);

    uint8_t buf[1];
    uint32_t distance;
    time_t timestamp;
    struct tm *timeinfo;
    char buffer[128];

    while (1) {
        i2c_write(&handle, &MLX75030_I2C_SLAVE, 1);
        i2c_read(&handle, buf, 1);
        if (buf[0] == MLX75030_MEASUREMENT) {
            i2c_write(&handle, &MLX75030_MEASUREMENT_RESULT, 1);
            i2c_read(&handle, buf, 1);
            if (buf[0] == MLX75030_MEASUREMENT_RESULT_HIGH) {
                i2c_write(&handle, &MLX75030_MEASUREMENT_RESULT_LOW, 1);
                i2c_read(&handle, buf, 1);
                distance = (buf[0] << 8) | buf[1];
            } else {
                distance = 0;
            }
        } else {
            distance = 0;
        }

        timestamp = time(NULL);
        timeinfo = localtime(&timestamp);
        strftime(buffer, 128, "%Y-%m-%d %H:%M:%S.%03d", timeinfo);

        printf("%s %d\n", buffer, distance);

        sleep(100);
    }

    return 0;
}

