#define I2C_BUS 1
#define I2C_ADDR 0x3C // Default address
#define GPIO27 27
#define PROXIMITY_INTERRUPT 0x01
#define PROXIMITY_DATA 0x02
#define PROXIMITY_DATA_CONFIG 0x03
#define PROXIMITY_DATA_STATUS 0x04
#define PROXIMITY_DATA_DATA 0x05
#define PROXIMITY_INTERRUPT_CONFIG 0x06
#define PROXIMITY_INTERRUPT_STATUS 0x07
#define PROXIMITY_INTERRUPT_DATA 0x08

#define PROXIMITY_LOG_FILE "proximity.log"
#define PROXIMITY_THRESHOLD 1000
#define PROXIMITY_LOG_FORMAT "%Y-%m-%d %H:%M:%S,%d,%s"

typedef struct {
    int i2c_fd;
    int gpio_fd;
    int interrupt_fd;
    int threshold;
    int i2c_address;
    int interrupt_config;
    int interrupt_status;
    int interrupt_data;
    int interrupt_data_config;
    int interrupt_data_status;
    int interrupt_data_data;
    int log_fd;
    char log_buffer[256];
    int log_buffer_size;
    int log_buffer_index;
    int log_buffer_full;
    int log_buffer_lock;
    pthread_mutex_t log_buffer_lock;
    int running;
    int interrupt_flag;
    int interrupt_data_flag;
} ProximitySensorState;

void *interrupt_handler(void *state) {
    ProximitySensorState *sensor = (ProximitySensorState *)state;
    while (sensor->running) {
        if (sensor->interrupt_flag) {
            sensor->interrupt_flag = 0;
            sensor->interrupt_data_flag = 1;
            int data = sensor->interrupt_data;
            struct timeval tv;
            gettimeofday(&tv, NULL);
            char timestamp[256];
            strftime(timestamp, sizeof(timestamp), PROXIMITY_LOG_FORMAT, &tv);
            char status[3];
            if (data <= sensor->threshold) {
                status[0] = 'S';
                status[1] = 'A';
                status[2] = 'F';
            } else {
                status[0] = 'A';
                status[1] = 'L';
                status[2] = 'E';
            }
            sensor->log_buffer[0] = '\0';
            snprintf(sensor->log_buffer, sensor->log_buffer_size, "%s,%d,%s", timestamp, data, status);
            pthread_mutex_lock(&sensor->log_buffer_lock);
            if (sensor->log_buffer_index < sensor->log_buffer_size - 1) {
                sensor->log_buffer[sensor->log_buffer_index++] = '\n';
            } else {
                sensor->log_buffer_full = 1;
                pthread_mutex_unlock(&sensor->log_buffer_lock);
                pthread_cond_signal(&sensor->log_buffer_cond);
            }
            pthread_mutex_unlock(&sensor->log_buffer_lock);
        }
    }
    return NULL;
}

void *sigint_handler(void *state) {
    ProximitySensorState *sensor = (ProximitySensorState *)state;
    if (sensor->log_fd > 0) {
        close(sensor->log_fd);
    }
    if (sensor->i2c_fd > 0) {
        close(sensor->i2c_fd);
    }
    if (sensor->gpio_fd > 0) {
        close(sensor->gpio_fd);
    }
    if (sensor->interrupt_fd > 0) {
        close(sensor->interrupt_fd);
    }
    free(state);
    return NULL;
}

int i2c_open(const char *dev, int addr) {
    int fd;
    if ((fd = open(dev, O_RDWR)) < 0) {
        perror("i2c_open");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("i2c_open");
        close(fd);
        return -1;
    }
    return fd;
}

