int gpio_open(int pin) {
    int fd;
    if ((fd = open("/dev/gpiod", O_RDWR)) < 0) {
        perror("gpio_open");
        return -1;
    }
    if (ioctl(fd, GPIOCGPWM, &pin) < 0) {
        perror("gpio_open");
        close(fd);
        return -1;
    }
    return fd;
}

int gpio_set_interrupt(int fd, int pin, int mode, int edge) {
    int config;
    if (ioctl(fd, GPIOCGRPINT, &config) < 0) {
        perror("gpio_set_interrupt");
        return -1;
    }
    config |= (1 << pin);
    if (ioctl(fd, GPIOCGRPINT, &config) < 0) {
        perror("gpio_set_interrupt");
        return -1;
    }
    if (mode == 0) {
        if (edge == 0) {
            config |= (1 << GPINT_EDGE_RISING);
        } else {
            config |= (1 << GPINT_EDGE_FALLING);
        }
    } else {
        if (edge == 0) {
            config |= (1 << GPINT_EDGE_RISING);
        } else {
            config |= (1 << GPINT_EDGE_FALLING);
        }
        config |= (1 << GPINT_MODE);
    }
    if (ioctl(fd, GPIOCGRPINT, &config) < 0) {
        perror("gpio_set_interrupt");
        return -1;
    }
    return 0;
}

