#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS 1
#define SI7005_ADDR 0x76
#define CONFIG_REG 0x16
#define TEMP_REG 0x41
#define HUMID_REG 0x42
#define CONFIG_REG_VALUE 0x00

#define I2C_TIMEOUT 10
#define READ_INTERVAL 2000

int i2c_fd = -1;
int config_written = 0;
int temp_read = 0;
int humidity_read = 0;

void handle_i2c_error(int err) {
    if (err < 0) {
        printf("I2C error: %d\n", err);
        i2c_fd = -1;
        config_written = 0;
        temp_read = 0;
        humidity_read = 0;
        if (i2c_fd != -1) {
            close(i2c_fd);
        }
        i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
        if (i2c_fd < 0) {
            perror("Failed to open I2C bus");
            exit(EXIT_FAILURE);
        }
    }
}

void handle_signal(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(EXIT_SUCCESS);
}

int main() {
    struct i2c_msg msg[2];
    struct i2c_rdma_request req;
    int err;

    signal(SIGINT, handle_signal);

    // Open I2C bus
    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    // Set I2C timeout
    if (ioctl(i2c_fd, I2C_SET_TIMEOUT, I2C_TIMEOUT) < 0) {
        perror("Failed to set I2C timeout");
        handle_i2c_error(errno);
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SET_ADDRESS, SI7005_ADDR) < 0) {
        perror("Failed to set I2C address");
        handle_i2c_error(errno);
    }

    // Write CONFIG register
    msg[0].addr = SI7005_ADDR;
    msg[0].flags = I2C_M_RD | I2C_M_WRITE;
    msg[0].len = 1;
    msg[0].data[0] = CONFIG_REG;
    if (ioctl(i2c_fd, I2C_RDWR, msg, 1, &req) < 0) {
        perror("Failed to write CONFIG register");
        handle_i2c_error(errno);
    }
    config_written = 1;

    // Read temperature and humidity
    while (1) {
        if (!config_written) {
            continue;
        }

        msg[0].addr = SI7005_ADDR;
        msg[0].flags = I2C_M_RD | I2C_M_WRITE;
        msg[0].len = 1;
        msg[0].data[0] = CONFIG_REG;
        if (ioctl(i2c_fd, I2C_RDWR, msg, 1, &req) < 0) {
            perror("Failed to read CONFIG register");
            handle_i2c_error(errno);
        }

        if (msg[0].data[0] != CONFIG_REG_VALUE) {
            printf("Failed to configure sensor\n");
            handle_i2c_error(errno);
        }

        msg[1].addr = SI7005_ADDR;
        msg[1].flags = I2C_M_RD | I2C_M_WRITE;
        msg[1].len = 1;
        msg[1].data[0] = TEMP_REG;
        if (ioctl(i2c_fd, I2C_RDWR, msg, 2, &req) < 0) {
            perror("Failed to read temperature");
            handle_i2c_error(errno);
        }
        temp_read = 1;

        msg[1].addr = SI7005_ADDR;
        msg[1].flags = I2C_M_RD | I2C_M_WRITE;
        msg[1].len = 1;
        msg[1].data[0] = HUMID_REG;
        if (ioctl(i2c_fd, I2C_RDWR, msg, 2, &req) < 0) {
            perror("Failed to read humidity");
            handle_i2c_error(errno);
        }
        humidity_read = 1;

        if (temp_read && humidity_read) {
            double temp = (msg[1].data[0] << 8) / 16384.0;
            double humidity = (msg[1].data[0] << 8) / 16384.0;
            printf("Temperature: %.2f°C, Humidity: %.2f%%\n", temp, humidity);
            fflush(stdout);
            sleep(READ_INTERVAL / 1000);
            temp_read = 0;
            humidity_read = 0;
        }
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#include "i2c.h"

#define I2C_BUS 1
#define I2C_ADDR 0x68
#define I2C_DEV "/dev/i2c-1"

#define WHO_AM_I 0x3D
#define ACCEL_XOUT 0x43
#define ACCEL_YOUT 0x45
#define ACCEL_ZOUT 0x47
#define TEMP_OUT_0 0x41
#define GYRO_XOUT 0x48
#define GYRO_YOUT 0x4A
#define GYRO_ZOUT 0x4C

#define ACCEL_X 0
#define ACCEL_Y 1
#define ACCEL_Z 2
#define TEMP 3
#define GYRO_X 4
#define GYRO_Y 5
#define GYRO_Z 6

#define BUFFER_SIZE 14

int i2c_fd;

void cleanup() {
    if (i2c_fd > 0) {
        i2c_close(i2c_fd);
    }
}

void handle_error(int err) {
    fprintf(stderr, "I2C error: %d\n", err);
    cleanup();
    exit(EXIT_FAILURE);
}

void handle_signal(int signum) {
    cleanup();
    exit(EXIT_SUCCESS);
}

int main() {
    struct i2c_msg msg[1];
    struct i2c_rdwr_ioctl_msg ioctl_msg;
    int err;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    i2c_fd = i2c_open(I2C_DEV, I2C_ADDR);
    if (i2c_fd < 0) {
        handle_error(i2c_fd);
    }

    msg[0].addr = I2C_ADDR;
    msg[0].flags = I2C_M_RD;
    msg[0].buf = malloc(BUFFER_SIZE);
    if (msg[0].buf == NULL) {
        handle_error(-1);
    }

    ioctl_msg.msgs = msg;
    ioctl_msg.nmsgs = 1;

    while (1) {
        err = i2c_ioctl(i2c_fd, I2C_RDWR, &ioctl_msg);
        if (err < 0) {
            handle_error(err);
        }

        if (msg[0].buf[0] == WHO_AM_I) {
            printf("Sensor present\n");
        } else {
            printf("Sensor not present\n");
            cleanup();
            exit(EXIT_FAILURE);
        }

        for (int i = 0; i < 7; i++) {
            switch (i) {
                case ACCEL_X:
                    printf("ACCEL_X: %d\n", (int16_t)(msg[0].buf[i * 2] << 8 | msg[0].buf[i * 2 + 1]));
                    break;
                case ACCEL_Y:
                    printf("ACCEL_Y: %d\n", (int16_t)(msg[0].buf[i * 2 + 2] << 8 | msg[0].buf[i * 2 + 3]));
                    break;
                case ACCEL_Z:
                    printf("ACCEL_Z: %d\n", (int16_t)(msg[0].buf[i * 2 + 4] << 8 | msg[0].buf[i * 2 + 5]));
                    break;
                case TEMP:
                    printf("TEMP: %d\n", (int16_t)(msg[0].buf[i * 2 + 6] << 8 | msg[0].buf[i * 2 + 7]));
                    break;
                case GYRO_X:
                    printf("GYRO_X: %d\n", (int16_t)(msg[0].buf[i * 2 + 8] << 8 | msg[0].buf[i * 2 + 9]));
                    break;
                case GYRO_Y:
                    printf("GYRO_Y: %d\n", (int16_t)(msg[0].buf[i * 2 + 10] << 8 | msg[0].buf[i * 2 + 11]));
                    break;
                case GYRO_Z:
                    printf("GYRO_Z: %d\n", (int16_t)(msg[0].buf[i * 2 + 12] << 8 | msg[0].buf[i * 2 + 13]));
                    break;
            }
        }

        printf("\n");

        usleep(100000);
    }

    free(msg[0].buf);
    i2c_close(i2c_fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>
#include <math.h>

#define I2C_BUS 1
#define I2C_ADDR 0x45
#define SHT40_I2C_DEVICE "/dev/i2c-1"

#define SHT40_MEASUREMENT_COMMAND 0x00
#define SHT40_MEASUREMENT_RESULT_LENGTH 6
#define SHT40_MEASUREMENT_RESULT_TEMPERATURE_OFFSET 0
#define SHT40_MEASUREMENT_RESULT_HUMIDITY_OFFSET 2
#define SHT40_MEASUREMENT_RESULT_CRC_OFFSET 4

#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT_VALUE 0

typedef struct {
    int i2c_fd;
    int temperature;
    int humidity;
} SHT40Sensor;

static void i2c_open(SHT40Sensor *sensor) {
    sensor->i2c_fd = open(SHT40_I2C_DEVICE, O_RDWR);
    if (sensor->i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }
}

static void i2c_close(SHT40Sensor *sensor) {
    close(sensor->i2c_fd);
}

static ssize_t i2c_write(SHT40Sensor *sensor, uint8_t *buf, size_t size) {
    ssize_t ret = write(sensor->i2c_fd, buf, size);
    if (ret < 0) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return ret;
}

static ssize_t i2c_read(SHT40Sensor *sensor, uint8_t *buf, size_t size) {
    ssize_t ret = read(sensor->i2c_fd, buf, size);
    if (ret < 0) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return ret;
}

static void crc8_calculate(uint8_t *buf, size_t len, uint8_t *crc) {
    uint8_t poly = CRC8_POLYNOMIAL;
    uint8_t init = CRC8_INIT_VALUE;
    uint8_t acc = init;
    for (size_t i = 0; i < len; i++) {
        acc ^= buf[i];
        for (int j = 0; j < 8; j++) {
            if (acc & 0x80) {
                acc = (acc << 1) ^ poly;
            } else {
                acc <<= 1;
            }
        }
    }
    *crc = acc;
}

static void crc8_verify(uint8_t *buf, size_t len, uint8_t *crc) {
    uint8_t calculated_crc = 0;
    crc8_calculate(buf, len, &calculated_crc);
    if (calculated_crc != *crc) {
        fprintf(stderr, "CRC8 verification failed\n");
    }
}

static void sht40_measure(SHT40Sensor *sensor, float *temperature, float *humidity) {
    uint8_t buf[SHT40_MEASUREMENT_RESULT_LENGTH];
    i2c_write(sensor, (uint8_t *)&SHT40_MEASUREMENT_COMMAND, sizeof(SHT40_MEASUREMENT_COMMAND));
    i2c_read(sensor, buf, SHT40_MEASUREMENT_RESULT_LENGTH);
    crc8_verify(buf, SHT40_MEASUREMENT_RESULT_LENGTH, &buf[SHT40_MEASUREMENT_RESULT_CRC_OFFSET]);
    *temperature = (float)(buf[SHT40_MEASUREMENT_RESULT_TEMPERATURE_OFFSET] - 0.5) * 0.01;
    *humidity = (float)(buf[SHT40_MEASUREMENT_RESULT_HUMIDITY_OFFSET] - 0.5) * 0.01;
}

static void sht40_log(float temperature, float humidity) {
    printf("%.2f C, %.2f%%\n", temperature, humidity);
}

static void sht40_handle_error(SHT40Sensor *sensor) {
    i2c_close(sensor);
    exit(EXIT_FAILURE);
}

static void sht40_handle_signal(int signum, siginfo_t *siginfo, void *context) {
    sht40_handle_error(&sensor);
    exit(EXIT_SUCCESS);
}

int main() {
    SHT40Sensor sensor;
    float temperature, humidity;

    signal(SIGINT, sht40_handle_signal);
    signal(SIGTERM, sht40_handle_signal);

    i2c_open(&sensor);
    while (1) {
        sht40_measure(&sensor, &temperature, &humidity);
        sht40_log(temperature, humidity);
        usleep(5000000); // 5 seconds
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <string.h>
#include <signal.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDR 0x5C
#define MLX90614_REG_TEMP_OBJECT 0x0D
#define MLX90614_REG_TEMP_AMBIENT 0x0E

typedef struct {
    int fd;
    int ambient;
    int object;
} Sensor;

void handle_sensor_error(Sensor *sensor) {
    if (sensor->fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }
    if (sensor->ambient < 0 || sensor->object < 0) {
        perror("Failed to read sensor registers");
        exit(EXIT_FAILURE);
    }
}

void handle_file_error(Sensor *sensor, FILE *file) {
    if (file == NULL) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
}

void handle_sigint(int signum) {
    if (sensor.fd < 0) {
        perror("I2C device not open");
        exit(EXIT_FAILURE);
    }
    if (sensor.ambient < 0 || sensor.object < 0) {
        perror("Sensor not found or read error");
        exit(EXIT_FAILURE);
    }
    if (log_file < 0) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
    close(sensor.fd);
    fclose(log_file);
    exit(EXIT_SUCCESS);
}

int main() {
    struct iocb iocb;
    struct i2c_msg msg[1];
    struct i2c_rdwr_ioctl_msg rdwr_msg;
    Sensor sensor;
    FILE *log_file;
    char timestamp[20];
    int ambient, object;

    signal(SIGINT, handle_sigint);

    // Open I2C device
    sensor.fd = open(I2C_DEVICE, O_RDWR);
    if (sensor.fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    // Set I2C address
    if (ioctl(sensor.fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        exit(EXIT_FAILURE);
    }

    // Initialize I2C read request
    iocb.msg = msg;
    iocb.mtype = I2C_M_READ;
    iocb.size = sizeof(struct i2c_msg);
    iocb.ioctl = I2C_RDWR;
    iocb.res = 0;
    iocb.resid = 0;

    // Read ambient and object temperatures
    msg[0].addr = I2C_ADDR;
    msg[0].len = 2;
    msg[0].buf = (unsigned char *) &ambient;
    msg[0].buf[0] = MLX90614_REG_TEMP_AMBIENT;
    msg[0].buf[1] = MLX90614_REG_TEMP_OBJECT;

