        perror("Failed to read sensor registers");
        handle_sensor_error(&sensor);
    }

    // Read timestamp
    time_t rawtime;
    struct tm *timeinfo;
    rawtime = time(NULL);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);

    // Open log file
    log_file = fopen("temperature_log.csv", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        handle_file_error(&sensor, log_file);
    }

    // Write log entry
    fprintf(log_file, "%s,%f,%f\n", timestamp, (float) ambient / 1000.0, (float) object / 1000.0);

    // Loop indefinitely
    while (1) {
        // Read ambient and object temperatures
        memset(msg, 0, sizeof(struct i2c_msg));
        msg[0].addr = I2C_ADDR;
        msg[0].len = 2;
        msg[0].buf = (unsigned char *) &ambient;
        msg[0].buf[0] = MLX90614_REG_TEMP_AMBIENT;
        msg[0].buf[1] = MLX90614_REG_TEMP_OBJECT;

        if (ioctl(sensor.fd, I2C_RDWR, msg) < 0) {
            perror("Failed to read sensor registers");
            handle_sensor_error(&sensor);
        }

        // Read timestamp
        rawtime = time(NULL);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);

        // Write log entry
        fprintf(log_file, "%s,%f,%f\n", timestamp, (float) ambient / 1000.0, (float) object / 1000.0);

        // Sleep for 5 seconds
        sleep(5);
    }

    return 0;
