#define CRC8_POLY 0x07
#define CRC8_INIT 0x00

typedef struct {
    uint8_t pressure[2];
    uint8_t pressure_crc;
    uint8_t temperature[2];
    uint8_t temperature_crc;
    uint8_t scale[2];
    uint8_t scale_crc;
} SensorData;

typedef struct {
    uint8_t address;
    uint8_t command;
    uint8_t data[9];
    uint8_t crc;
} I2CCommand;

void i2c_send_command(I2CCommand *cmd) {
    int fd = open("/dev/i2c-ad0", O_RDWR);
    if (fd < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }
    if (ioctl(fd, I2C_SLAVE, cmd->address) < 0) {
        perror("ioctl");
        close(fd);
        exit(EXIT_FAILURE);
    }
    if (write(fd, cmd, sizeof(*cmd)) < 0) {
        perror("write");
        close(fd);
        exit(EXIT_FAILURE);
    }
    close(fd);
}

void i2c_read_data(I2CCommand *cmd, SensorData *data) {
    int fd = open("/dev/i2c-ad0", O_RDWR);
    if (fd < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }
    if (ioctl(fd, I2C_SLAVE, cmd->address) < 0) {
        perror("ioctl");
        close(fd);
        exit(EXIT_FAILURE);
    }
    if (read(fd, data, sizeof(*data)) < 0) {
        perror("read");
        close(fd);
        exit(EXIT_FAILURE);
    }
    close(fd);
    data->pressure[0] = data->data[0];
    data->pressure[1] = data->data[1];
    data->temperature[0] = data->data[2];
    data->temperature[1] = data->data[3];
    data->scale[0] = data->data[4];
    data->scale[1] = data->data[5];
    data->pressure_crc = data->data[6];
    data->temperature_crc = data->data[7];
    data->scale_crc = data->data[8];
    uint8_t crc = 0;
    for (int i = 0; i < 8; i++) {
        crc = crc ^ data->data[i];
        crc = crc << 1;
        if (crc & 0x80) {
            crc ^= CRC8_POLY;
        }
    }
    if (crc != data->pressure_crc) {
        fprintf(stderr, "CRC error for pressure\n");
        exit(EXIT_FAILURE);
    }
    if (crc != data->temperature_crc) {
        fprintf(stderr, "CRC error for temperature\n");
        exit(EXIT_FAILURE);
    }
    if (crc != data->scale_crc) {
        fprintf(stderr, "CRC error for scale\n");
        exit(EXIT_FAILURE);
    }
}

void handle_sensor_absent() {
    fprintf(stderr, "Sensor not found\n");
    exit(EXIT_FAILURE);
}

void handle_bus_error() {
    fprintf(stderr, "Bus error\n");
    exit(EXIT_FAILURE);
}

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        fprintf(stderr, "Received signal %d\n", signum);
        exit(EXIT_SUCCESS);
    }
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    SensorData data;
    I2CCommand cmd;
    cmd.address = I2C_ADDR;
    cmd.command = CMD_MEASUREMENT;
    cmd.data[0] = CMD_MEASUREMENT;
    cmd.data[1] = CMD_MEASUREMENT;
    cmd.data[2] = CMD_MEASUREMENT;
    cmd.data[3] = CMD_MEASUREMENT;
    cmd.data[4] = CMD_MEASUREMENT;
    cmd.data[5] = CMD_MEASUREMENT;
    cmd.data[6] = 0;
    cmd.data[7] = 0;
    cmd.data[8] = 0;
    cmd.crc = 0;

    int fd = open("/dev/i2c-ad0", O_RDWR);
    if (fd < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("ioctl");
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (i2c_send_command(&cmd)) {
        handle_sensor_absent();
    }

    while (1) {
        i2c_read_data(&cmd, &data);
        uint32_t pressure = (uint32_t)data.pressure[0] << 8 | data.pressure[1];
        uint32_t temperature = (uint32_t)data.temperature[0] << 8 | data.temperature[1];
        uint32_t scale = (uint32_t)data.scale[0] << 8 | data.scale[1];
        double pressure_pa = (double)pressure / scale;
        double temperature_c = (double)temperature / scale - 273.15;
        char timestamp[26];
        struct tm *now = gmtime((time_t *) &now);
        strftime(timestamp, 26, "%Y-%m-%dT%H:%M:%S.%fZ", now);
        FILE *log_file = fopen("pressure_log.csv", "a");
        if (log_file == NULL) {
            perror("fopen");
            exit(EXIT_FAILURE);
        }
        if (fputs("timestamp,pressure,power\n", log_file) < 0) {
            perror("fputs");
            fclose(log_file);
            exit(EXIT_FAILURE);
        }
        if (fprintf(log_file, "%s,%f,%f\n", timestamp, pressure_pa, temperature_c) < 0) {
            perror("fprintf");
            fclose(log_file);
            exit(EXIT_FAILURE);
        }
        fclose(log_file);
        sleep(1);
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <math.h>

#define SHT40_ADDR 0x45
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0

#define I2C_FILE "/dev/i2c-1"

#define LOG_FILE "sht40_log.txt"

#define TEMPERATURE_OFFSET 0x40
#define HUMIDITY_OFFSET 0x42

#define CRC8_CHECKSUM 0x00

typedef struct {
    uint32_t timestamp;
    float temperature;
    float humidity;
} SHT40_LOG;

static int i2c_fd = -1;
static int log_fd = -1;

static void handle_error(const char *msg) {
    fprintf(stderr, "%s: %s\n", msg, strerror(errno));
    return;
}

static void close_resources() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_fd != -1) {
        close(log_fd);
    }
}

static void log_data(const SHT40_LOG *log) {
    if (log_fd == -1) {
        handle_error("Failed to open log file");
        return;
    }
    char buffer[128];
    struct tm *timeinfo;
    time_t rawtime;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
    sprintf(buffer + strlen(buffer), " %f %f\n", log->temperature, log->humidity);
    if (write(log_fd, buffer, strlen(buffer)) < 0) {
        handle_error("Failed to write to log file");
    }
}

static int i2c_read(int fd, uint8_t *buf, size_t size) {
    if (read(fd, buf, size) < 0) {
        handle_error("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

static int i2c_write(int fd, uint8_t *buf, size_t size) {
    if (write(fd, buf, size) < 0) {
        handle_error("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

static int i2c_ioctl(int fd, uint8_t *cmd, size_t size) {
    if (ioctl(fd, I2C_RDWR, cmd) < 0) {
        handle_error("Failed to issue I2C ioctl");
        return -1;
    }
    return 0;
}

static int crc8_check(uint8_t *buf, size_t size) {
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < size; i++) {
        crc ^= buf[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x01) {
                crc = (crc >> 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc >>= 1;
            }
        }
    }
    return crc;
}

static int main() {
    struct sigaction sa;
    sa.sa_handler = close_resources;
    sa.sa_flags = SA_RESTART;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_FILE, O_RDWR);
    if (i2c_fd == -1) {
        handle_error("Failed to open I2C device");
        return 1;
    }

    SHT40_LOG log;
    log.timestamp = 0;
    log.temperature = 0;
    log.humidity = 0;

    while (1) {
        uint8_t cmd[3] = {0x44, 0x00, 0x00};
        if (i2c_ioctl(i2c_fd, cmd, 3) < 0) {
            handle_error("Failed to issue high-repeatability measurement command");
            continue;
        }

        uint8_t data[6] = {0};
        if (i2c_read(i2c_fd, data, 6) < 0) {
            handle_error("Failed to read from I2C device");
            continue;
        }

        if (crc8_check(data, 6) != CRC8_CHECKSUM) {
            handle_error("CRC8 check failed");
            continue;
        }

        log.timestamp = time(NULL);
        log.temperature = (float)((data[TEMPERATURE_OFFSET] << 8) | data[TEMPERATURE_OFFSET + 1]) / 163.84 - 40;
        log.humidity = (float)((data[HUMIDITY_OFFSET] << 8) | data[HUMIDITY_OFFSET + 1]) / 245.00;

        log_data(&log);

        if (sleep(5) < 0) {
            handle_error("Failed to sleep for 5 seconds");
            continue;
        }
    }

    return 0;
}

