#define I2C_BUS 1
#define I2C_ADDR 0x76
#define SI7015_TEMP_CMD 0x00
#define SI7015_HUMID_CMD 0x01
#define SI7015_MEAS_READY 0x00
#define SI7015_MEAS_TIMEOUT 0x01
#define SI7015_MEAS_RESULT 0x02

#define LOG_FILE "sensor_data.txt"
#define LOG_FORMAT "%Y-%m-%d %H:%M:%S,%f,%d,%d\n"

typedef struct {
    int fd;
    int i2c_fd;
    int log_fd;
    bool initialized;
    bool i2c_opened;
    bool log_opened;
    bool running;
} SensorData;

static void handle_sigint(int signum) {
    if (SensorData::instance->running) {
        SensorData::instance->running = false;
        close(SensorData::instance->i2c_fd);
        close(SensorData::instance->log_fd);
        close(SensorData::instance->instance->fd);
        exit(EXIT_SUCCESS);
    }
}

static SensorData* instance = NULL;

static SensorData* create_sensor_data() {
    SensorData* data = malloc(sizeof(SensorData));
    if (!data) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    data->initialized = false;
    data->i2c_opened = false;
    data->log_opened = false;
    data->running = true;
    return data;
}

static void init_sensor_data(SensorData* data) {
    if (data->initialized) {
        return;
    }
    data->initialized = true;
    data->i2c_fd = -1;
    data->log_fd = -1;
    data->running = true;
}

static void close_sensor_data(SensorData* data) {
    if (data->initialized) {
        if (data->running) {
            data->running = false;
            close(data->i2c_fd);
            close(data->log_fd);
            close(data->fd);
        }
        free(data);
    }
}

static int open_i2c_bus(SensorData* data) {
    int i2c_fd = -1;
    if (data->i2c_opened) {
        return 0;
    }
    i2c_fd = open("/dev/i2c-n", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C address\n");
        return -1;
    }
    data->i2c_opened = true;
    data->i2c_fd = i2c_fd;
    return 0;
}

static int open_log_file(SensorData* data) {
    int log_fd = -1;
    if (data->log_opened) {
        return 0;
    }
    log_fd = open(LOG_FILE, O_APPEND | O_CREAT, 0644);
    if (log_fd < 0) {
        fprintf(stderr, "Failed to open log file\n");
        return -1;
    }
    data->log_opened = true;
    data->log_fd = log_fd;
    return 0;
}

static int read_i2c(SensorData* data, uint8_t* buf, int len) {
    if (data->i2c_opened) {
        if (read(data->i2c_fd, buf, len) < 0) {
