static int read_i2c_temp(SensorData* data, float* temp) {
    if (data->i2c_opened) {
        uint8_t cmd[1] = {SI7015_TEMP_CMD};
        if (write_i2c(data, cmd, 1) < 0) {
            return -1;
        }
        uint8_t result[2];
        if (read_i2c(data, result, 2) < 0) {
            return -1;
