#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x60
#define SDP800_MEASUREMENT_TRIGGER 0x00
#define SDP800_MEASUREMENT_RESULT 0x01
#define SDP800_MEASUREMENT_RESULT_LEN 9
#define SDP800_MEASUREMENT_RESULT_BYTES 3
#define SDP800_MEASUREMENT_RESULT_CRC 1

#define PRESSURE_OFFSET 0x00
#define TEMPERATURE_OFFSET 0x03
#define SCALEFACTOR_OFFSET 0x06

#define PRESSURE_UNIT 0.00001
#define TEMPERATURE_UNIT 0.1

#define LOG_FILE "airflow_data.txt"
#define LOG_HEADER "timestamp,pressure,temp\n"

typedef struct {
    uint8_t pressure[SDP800_MEASUREMENT_RESULT_BYTES];
    uint8_t temperature[SDP800_MEASUREMENT_RESULT_BYTES];
    uint8_t scalefactor[SDP800_MEASUREMENT_RESULT_BYTES];
    uint8_t crc;
} SensorData;

static void i2c_open(int *fd) {
    *fd = open(I2C_BUS, O_RDWR);
    if (*fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }
}

static void i2c_close(int fd) {
    close(fd);
}

static int i2c_write(int fd, uint8_t *buf, size_t len) {
    if (write(fd, buf, len) < 0) {
        perror("Failed to write to I2C bus");
        return -1;
    }
    return 0;
}

static int i2c_read(int fd, uint8_t *buf, size_t len) {
    if (read(fd, buf, len) < 0) {
        perror("Failed to read from I2C bus");
        return -1;
    }
    return 0;
}

static int i2c_ioctl(int fd, uint8_t *cmd, size_t len) {
    if (ioctl(fd, I2C_RDWR, cmd) < 0) {
        perror("Failed to issue I2C ioctl");
        return -1;
    }
    return 0;
}

static int i2c_read_result(int fd, SensorData *sensor) {
    uint8_t buf[SDP800_MEASUREMENT_RESULT_LEN];
    if (i2c_read(fd, buf, SDP800_MEASUREMENT_RESULT_LEN) < 0) {
        return -1;
    }
    sensor->pressure[0] = buf[PRESSURE_OFFSET];
    sensor->temperature[0] = buf[TEMPERATURE_OFFSET];
    sensor->scalefactor[0] = buf[SCALEFACTOR_OFFSET];
    sensor->crc = buf[SDP800_MEASUREMENT_RESULT_CRC];
    return 0;
}

static int i2c_validate_crc(SensorData *sensor) {
    uint8_t crc = 0;
    for (int i = 0; i < SDP800_MEASUREMENT_RESULT_BYTES; i++) {
        crc ^= sensor->pressure[i];
        crc ^= sensor->temperature[i];
        crc ^= sensor->scalefactor[i];
    }
    return crc == sensor->crc;
}

static void i2c_close_sensor(int fd) {
    i2c_close(fd);
}

static void log_data(const char *timestamp, double pressure, double temperature) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Failed to open log file");
        return;
    }
    fprintf(fp, "%s,%f,%f\n", timestamp, pressure, temperature);
    fclose(fp);
}

static void handle_error(int err, const char *msg) {
    perror(msg);
    i2c_close_sensor(fd);
    exit(EXIT_FAILURE);
}

int main() {
    int fd;
    i2c_open(&fd);
    i2c_ioctl(fd, &SDP800_MEASUREMENT_TRIGGER, sizeof(SDP800_MEASUREMENT_TRIGGER));
    uint8_t trigger = SDP800_MEASUREMENT_TRIGGER;
    i2c_ioctl(fd, &trigger, sizeof(trigger));

    while (1) {
        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);
        char timestamp[128];
        snprintf(timestamp, sizeof(timestamp), "%ld.%09ld", (long)ts.tv_sec, (long)ts.tv_nsec / 1000000);

        SensorData sensor;
        if (i2c_read_result(fd, &sensor) < 0) {
            handle_error(-1, "Failed to read sensor result");
        }

        if (!i2c_validate_crc(&sensor)) {
            handle_error(-1, "Invalid CRC");
        }

        double pressure = (sensor.pressure[0] << 16) + (sensor.pressure[1] << 8) + sensor.pressure[2];
        pressure *= PRESSURE_OFFSET;
        pressure /= PRESSURE_UNIT;

        double temperature = (sensor.temperature[0] << 16) + (sensor.temperature[1] << 8) + sensor.temperature[2];
        temperature *= TEMPERATURE_OFFSET;
        temperature /= TEMPERATURE_UNIT;

        log_data(timestamp, pressure, temperature);

        if (nanosleep(&ts, NULL) < 0) {
            handle_error(-1, "Failed to sleep");
        }
    }

    return 0;
}

