#include <sys/time.h>
#include <signal.h>
#include <stdint.h>
#include <math.h>

#define I2C_BUS 1
#define I2C_ADDR 0x76
#define CRC8_POLY 0x07
#define CRC8_INIT 0

#define TEMPERATURE_DATA_SIZE 3
#define CRC8_SIZE 1
#define CRC8_CHECKSUM 0x00

#define LOG_FILE "enclosure_temp_log.txt"
#define ERROR_LOG_FILE "error_log.txt"

#define MAX_READS 100
#define SLEEP_TIME 15

typedef struct {
    uint8_t data[TEMPERATURE_DATA_SIZE];
    uint8_t crc8[CRC8_SIZE];
} TemperatureData;

static int fd_i2c;
static int last_error = 0;
static int last_error_time = 0;

static void handle_error(int signum) {
    if (signum == SIGINT) {
        if (fd_i2c != -1) {
            close(fd_i2c);
        }
        exit(0);
    }
}

static void log_error(const char *message) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    char timestamp[32];
    sprintf(timestamp, "%lu.%06lu", tv.tv_sec, tv.tv_usec);
    FILE *error_log = fopen(ERROR_LOG_FILE, "a");
    if (error_log) {
        fprintf(error_log, "%s: %s\n", timestamp, message);
        fclose(error_log);
    } else {
        perror("Failed to open error log file");
    }
}

static void log_temperature(const char *timestamp) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        fprintf(log_file, "%s: %f\n", timestamp, *(float *)TemperatureData{.data[0]}, *(float *)TemperatureData{.data[1]});
        fclose(log_file);
    } else {
        perror("Failed to open temperature log file");
    }
}

static void init_i2c() {
    fd_i2c = open("/dev/i2c-1", O_RDWR);
    if (fd_i2c == -1) {
        perror("Failed to open i2c device");
        log_error("Failed to open i2c device");
        exit(1);
    }
}

static void read_temperature() {
    TemperatureData data;
    if (ioctl(fd_i2c, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set slave address");
        log_error("Failed to set slave address");
        return;
    }

    data.data[0] = 0x00;
    data.data[1] = 0x00;
    data.data[2] = 0x00;
    data.crc8[0] = 0x00;

    if (write(fd_i2c, &data, TEMPERATURE_DATA_SIZE) != TEMPERATURE_DATA_SIZE) {
        perror("Failed to write to i2c device");
        log_error("Failed to write to i2c device");
        return;
    }

    if (read(fd_i2c, data.data, TEMPERATURE_DATA_SIZE) != TEMPERATURE_DATA_SIZE) {
        perror("Failed to read from i2c device");
        log_error("Failed to read from i2c device");
        return;
    }

    if (data.crc8[0] != CRC8(data.data, CRC8_SIZE, CRC8_POLY, CRC8_INIT)) {
        perror("CRC8 mismatch");
        log_error("CRC8 mismatch");
        return;
    }

    log_temperature(get_current_time());
}

static void cleanup() {
    if (fd_i2c != -1) {
        close(fd_i2c);
    }
}

static void main_loop() {
    init_i2c();
    while (1) {
        read_temperature();
        usleep(SLEEP_TIME * 1000);
    }
}

static char *get_current_time() {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    char timestamp[32];
    sprintf(timestamp, "%lu.%06lu", tv.tv_sec, tv.tv_usec);
    return strdup(timestamp);
}

int main() {
    signal(SIGINT, handle_error);
    signal(SIGTERM, handle_error);

    for (int i = 0; i < MAX_READS; i++) {
        main_loop();
        cleanup();
        sleep(1);
    }

    return 0;
}

static uint8_t CRC8(uint8_t *data, int size, uint8_t poly, uint8_t init) {
    uint8_t crc = init;
    for (int i = 0; i < size; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ poly;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

