        time_t now = time(NULL);
        struct tm *gmt = gmtime(&now);
        strftime(log_buffer, sizeof(log_buffer), "%Y-%m-%d %H:%M:%S", gmt);
        log.timestamp = now;
        snprintf(log_buffer, sizeof(log_buffer), "%s, T=%.1f°C, RH=%.1f%%\n", log_buffer, log.temperature, log.humidity);
        if (fopen(log_filename, "a") < 0) {
            perror("Failed to open log file for append");
            continue;
        }
        if (fprintf(fopen(log_filename, "a"), log_buffer) < 0) {
            perror("Failed to write to log file");
            continue;
        }
        if (fclose(fopen(log_filename, "a")) < 0) {
            perror("Failed to close log file");
            continue;
        }

        // Wait 5 seconds before next measurement
        if (sleep(5) < 0) {
            perror("Failed to sleep 5 seconds");
            continue;
        }
    }

    return 0;
}

