#define SHT35_ADDR 0x45
#define SHT35_MEAS_CMD 0x3B
#define SHT35_MEAS_RESULT 0x3D
#define SHT35_MEAS_RESULT_LEN 6
#define SHT35_CRC_LEN 2
#define SHT35_MEAS_TIMEOUT 1000  // 1ms

typedef struct {
    int fd;
    int retries;
    int last_error;
} SHT35Context;

static void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        if (SHT35Context->fd > 0) {
            close(SHT35Context->fd);
        }
        if (SHT35Context->log_fd > 0) {
            close(SHT35Context->log_fd);
        }
        exit(EXIT_SUCCESS);
    }
}

static void init_sht35(SHT35Context *ctx) {
    char i2c_filename[100];
    snprintf(i2c_filename, sizeof(i2c_filename), "/dev/i2c-%d", ctx->i2c_bus);
    ctx->fd = open(i2c_filename, O_RDWR);
    if (ctx->fd < 0) {
        ctx->last_error = errno;
        return;
    }
    if (ioctl(ctx->fd, I2C_SLAVE, SHT35_ADDR) < 0) {
        ctx->last_error = errno;
        return;
    }
}

static void read_sht35(SHT35Context *ctx, double *temperature, double *humidity) {
    char buffer[SHT35_MEAS_RESULT_LEN + SHT35_CRC_LEN];
    struct i2c_msg msg[1];
    struct i2c_rdwr_ioctl_msg ioctl_msg;
    msg[0].addr = SHT35_ADDR;
    msg[0].flags = I2C_MSG_WRITE;
    msg[0].data[0] = SHT35_MEAS_CMD;
    ioctl_msg.msgs = msg;
    ioctl_msg.num_msgs = 1;
    ioctl_msg.flags = I2C_RDWR;
    ioctl_msg.ioctl = I2C_RDWR;
    ioctl_msg.request = I2C_RDWR;
    ioctl_msg.request_iov = msg;
    ioctl_msg.request_iovlen = 1;
    ioctl_msg.iovctl = I2C_I2C_RDWR;
    ioctl_msg.iovctlen = 1;
    ioctl_msg.iovdata = buffer;
    ioctl_msg.iovctlen = SHT35_MEAS_RESULT_LEN + SHT35_CRC_LEN;
    ioctl_msg.timeout = SHT35_MEAS_TIMEOUT;
    if (ioctl(ctx->fd, I2C_RDWR, &ioctl_msg) < 0) {
        ctx->last_error = errno;
        return;
    }
    if (buffer[0] != SHT35_MEAS_RESULT) {
        ctx->last_error = EINVAL;
        return;
    }
    if (buffer[1] != SHT35_MEAS_RESULT_LEN) {
        ctx->last_error = EINVAL;
        return;
    }
    if (buffer[2] != SHT35_MEAS_RESULT[0] || buffer[3] != SHT35_MEAS_RESULT[1]) {
        ctx->last_error = EINVAL;
        return;
    }
    if (buffer[4] != SHT35_MEAS_RESULT_LEN) {
        ctx->last_error = EINVAL;
        return;
    }
    if (buffer[5] != SHT35_MEAS_RESULT[2] || buffer[6] != SHT35_MEAS_RESULT[3]) {
        ctx->last_error = EINVAL;
        return;
    }
    if (buffer[7] != SHT35_MEAS_RESULT_LEN) {
        ctx->last_error = EINVAL;
        return;
    }
    if (buffer[8] != SHT35_MEAS_RESULT[4] || buffer[9] != SHT35_MEAS_RESULT[5]) {
        ctx->last_error = EINVAL;
        return;
    }
    if (buffer[10] != SHT35_CRC_LEN) {
        ctx->last_error = EINVAL;
    }
    if (buffer[11] != SHT35_CRC_LEN) {
        ctx->last_error = EINVAL;
    }
    uint16_t crc = 0;
    for (int i = 0; i < SHT35_MEAS_RESULT_LEN + SHT35_CRC_LEN; i++) {
        crc += buffer[i];
    }
    if (crc != (buffer[12] << 8 | buffer[13])) {
        ctx->last_error = EINVAL;
        return;
    }
    *temperature = (buffer[2] << 8 | buffer[3]) * 0.01 - 40;
    *humidity = (buffer[4] << 8 | buffer[5]) * 0.01;
}

static void write_sht35(SHT35Context *ctx, double temperature, double humidity) {
    char buffer[SHT35_MEAS_RESULT_LEN + SHT35_CRC_LEN];
    struct i2c_msg msg[1];
    struct i2c_rdwr_ioctl_msg ioctl_msg;
    msg[0].addr = SHT35_ADDR;
    msg[0].flags = I2C_MSG_WRITE;
    msg[0].data[0] = SHT35_MEAS_CMD;
    ioctl_msg.msgs = msg;
    ioctl_msg.num_msgs = 1;
    ioctl_msg.flags = I2C_RDWR;
    ioctl_msg.ioctl = I2C_RDWR;
    ioctl_msg.request = I2C_RDWR;
    ioctl_msg.request_iov = msg;
    ioctl_msg.request_iovlen = 1;
    ioctl_msg.iovctl = I2C_I2C_RDWR;
    ioctl_msg.iovctlen = 1;
    ioctl_msg.iovdata = buffer;
    ioctl_msg.iovctlen = SHT35_MEAS_RESULT_LEN + SHT35_CRC_LEN;
    ioctl_msg.timeout = SHT35_MEAS_TIMEOUT;
    if (ioctl(ctx->fd, I2C_RDWR, &ioctl_msg) < 0) {
        ctx->last_error = errno;
        return;
    }
    buffer[0] = SHT35_MEAS_RESULT;
    buffer[1] = SHT35_MEAS_RESULT_LEN;
    buffer[2] = (uint8_t)(temperature + 40) * 100;
    buffer[3] = (uint8_t)(temperature + 40) % 100;
    buffer[4] = SHT35_MEAS_RESULT_LEN;
    buffer[5] = SHT35_MEAS_RESULT_LEN;
    buffer[6] = (uint8_t)(humidity) * 100;
    buffer[7] = (uint8_t)(humidity) % 100;
    buffer[8] = SHT35_MEAS_RESULT_LEN;
    buffer[9] = SHT35_MEAS_RESULT_LEN;
    buffer[10] = (uint8_t)(temperature + 40) * 100;
    buffer[11] = (uint8_t)(temperature + 40) % 100;
    buffer[12] = SHT35_CRC_LEN;
    buffer[13] = (uint8_t)(crc16(buffer, SHT35_MEAS_RESULT_LEN + SHT35_CRC_LEN));
}

static uint16_t crc16(const void *data, size_t len) {
    uint16_t crc = 0;
    uint8_t *ptr = (uint8_t *)data;
    for (size_t i = 0; i < len; i++) {
        crc ^= *ptr++;
        crc = (crc << 8) | (crc >> 8);
        crc ^= *ptr++;
        crc = (crc << 8) | (crc >> 8);
    }
    return crc;
}

static void log_data(double temperature, double humidity) {
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[128];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S.%06Z", timeinfo);
    double offset_temperature = 2 * sin(2 * M_PI * (time(NULL) / 3600));
    double offset_humidity = 5 * sin(2 * M_PI * (time(NULL) / 3600));
    double logged_temperature = temperature + offset_temperature;
    double logged_humidity = humidity + offset_humidity;
    if (isnan(logged_temperature) || isnan(logged_humidity)) {
        fprintf(stderr, "NaN values logged\n");
    }
    fprintf(stderr, "Logged temperature: %.2f°C\n", logged_temperature);
    fprintf(stderr, "Logged humidity: %.2f%%\n");
    if (SHT35Context->log_fd < 0) {
        return;
    }
    fprintf(SHT35Context->log_fd, "%s %.2fC %.2f%%\n", buffer, logged_temperature, logged_humidity);
    fflush(SHT35Context->log_fd);
}

int main() {
    SHT35Context ctx;
    ctx.retries = 3;
    ctx.last_error = 0;
    ctx.i2c_bus = 1;
    init_sht35(&ctx);
    if (ctx.last_error != 0) {
        fprintf(stderr, "I2C initialization failed: %s\n", strerror(ctx.last_error));
        return EXIT_FAILURE;
    }
    ctx.log_fd = open("environmental_data.txt", O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (ctx.log_fd < 0) {
        ctx.last_error = errno;
        fprintf(stderr, "File open failed: %s\n", strerror(ctx.last_error));
        return EXIT_FAILURE;
    }
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);
    while (1) {
        double temperature, humidity;
        for (int i = 0; i < ctx.retries; i++) {
            if (ctx.last_error == 0) {
                read_sht35(&ctx, &temperature, &humidity);
                if (ctx.last_error == 0) {
                    log_data(temperature, humidity);
                    break;
                }
            }
            usleep(1000 * 1000); // 1 second delay
        }
        if (ctx.last_error != 0) {
            log_data(NAN, NAN);
        }
    }
    return EXIT_SUCCESS;
}

