typedef struct {
    uint8_t pressure[1];
    uint8_t temperature[1];
    uint8_t scale[1];
    uint8_t crc[1];
} SensorData;

typedef struct {
    int i2c_fd;
    int airflow_fd;
} AirflowState;

void i2c_open(const char *dev, int addr) {
    int fd = open(dev, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to set I2C slave address");
        exit(EXIT_FAILURE);
    }
    return fd;
}

void i2c_close(int fd) {
    close(fd);
}

void i2c_read(int fd, SensorData *data) {
    uint8_t buf[9];
    if (read(fd, buf, 9) < 0) {
        perror("Failed to read I2C data");
        exit(EXIT_FAILURE);
    }
    data->pressure[0] = buf[0];
    data->temperature[0] = buf[1];
    data->scale[0] = buf[2];
    data->crc[0] = buf[8];
}

void i2c_send_cmd(int fd, uint8_t cmd) {
    uint8_t buf[1];
    buf[0] = cmd;
    if (write(fd, buf, 1) < 0) {
        perror("Failed to write I2C command");
        exit(EXIT_FAILURE);
    }
}

void i2c_stop(int fd) {
    i2c_send_cmd(fd, CMD_STOP);
}

void i2c_reset(int fd) {
    i2c_send_cmd(fd, CMD_RESET);
}

void i2c_set_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2];
    buf[0] = CMD_SET_REG;
    buf[1] = reg;
    buf[2] = val;
    if (write(fd, buf, 3) < 0) {
        perror("Failed to write I2C register command");
        exit(EXIT_FAILURE);
    }
}

void i2c_get_reg(int fd, uint8_t reg, uint8_t *val) {
    uint8_t buf[2];
    buf[0] = CMD_GET_REG;
    buf[1] = reg;
    if (write(fd, buf, 2) < 0) {
        perror("Failed to write I2C register command");
        exit(EXIT_FAILURE);
    }
    if (read(fd, buf, 2) < 0) {
        perror("Failed to read I2C register data");
        exit(EXIT_FAILURE);
    }
    *val = buf[1];
}

void i2c_read_all(int fd, SensorData *data) {
    uint8_t buf[9];
    if (read(fd, buf, 9) < 0) {
        perror("Failed to read I2C data");
        exit(EXIT_FAILURE);
    }
    data->pressure[0] = buf[0];
    data->temperature[0] = buf[1];
    data->scale[0] = buf[2];
    data->crc[0] = buf[8];
}

void i2c_read_pressure_temperature(int fd, SensorData *data) {
    uint8_t buf[2];
    if (read(fd, buf, 2) < 0) {
        perror("Failed to read I2C data");
        exit(EXIT_FAILURE);
    }
    data->pressure[0] = buf[0];
    data->temperature[0] = buf[1];
}

void i2c_read_scale(int fd, uint8_t *scale) {
    uint8_t buf[1];
    if (read(fd, buf, 1) < 0) {
        perror("Failed to read I2C data");
        exit(EXIT_FAILURE);
    }
    *scale = buf[0];
}

void i2c_read_crc(int fd, uint8_t *crc) {
    uint8_t buf[1];
    if (read(fd, buf, 1) < 0) {
        perror("Failed to read I2C data");
        exit(EXIT_FAILURE);
    }
    *crc = buf[0];
}

void i2c_validate_crc(int fd, SensorData *data) {
    uint8_t crc = 0;
    for (int i = 0; i < 8; i++) {
        crc = crc ^ data->pressure[i];
        crc = crc << 1;
        if (crc & 0x80) {
            crc ^= CRC8_POLY;
        }
    }
    if (crc != data->crc[0]) {
        printf("CRC validation failed\n");
        exit(EXIT_FAILURE);
    }
}

void i2c_convert_pressure(SensorData *data, float *pressure) {
    uint8_t scale = data->scale[0];
    *pressure = (float)((data->pressure[0] << 8) / scale);
}

void i2c_convert_temperature(SensorData *data, float *temperature) {
    uint8_t temperature = data->temperature[0];
    *temperature = (float)((temperature - 0x80) / 0x7F);
}

void i2c_log_data(float pressure, float temperature) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char buffer[128];
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(airflow_fd, "%s,%f,%f\n", buffer, pressure, temperature);
}

void i2c_start(int *fd, AirflowState *state) {
    *fd = i2c_open("i2c-dev", I2C_ADDR);
    state->i2c_fd = *fd;
    state->airflow_fd = open("airflow.csv", O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (state->airflow_fd < 0) {
        perror("Failed to open airflow.csv");
        exit(EXIT_FAILURE);
    }
}

void i2c_stop(int *fd, AirflowState *state) {
    i2c_stop(*fd);
    i2c_close(*fd);
    close(state->airflow_fd);
}

void i2c_handle_error(int *fd, AirflowState *state) {
    i2c_stop(*fd, state);
    i2c_close(*fd);
    close(state->airflow_fd);
    exit(EXIT_FAILURE);
}

void i2c_handle_signal(int signum, siginfo_t *siginfo, void *context) {
    i2c_stop(&state->i2c_fd, &state);
    i2c_close(&state->i2c_fd);
    close(state->airflow_fd);
    exit(EXIT_SUCCESS);
}

int main() {
    AirflowState state;
    int i2c_fd;
    float pressure, temperature;
    SensorData data;
    struct sigaction sa;

    sa.sa_sigaction = i2c_handle_signal;
    sa.sa_flags = SA_SIGINFO;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_start(&i2c_fd, &state);

    while (1) {
        i2c_send_cmd(state.i2c_fd, CMD_CONT);
        i2c_read_pressure_temperature(state.i2c_fd, &data);
        i2c_read_scale(state.i2c_fd, &data.scale[0]);
        i2c_read_crc(state.i2c_fd, &data.crc[0]);
        i2c_validate_crc(state.i2c_fd, &data);
        i2c_convert_pressure(&data, &pressure);
        i2c_convert_temperature(&data, &temperature);
        i2c_log_data(pressure, temperature);
        sleep(1);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/time.h>
#include <signal.h>
#include <syslog.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <math.h>

#define I2C_FILE "/dev/i2c-1"
#define I2C_ADDR 0x40
#define SENSOR_RESET 0x3C
#define CRC8_POLY 0x31
#define CRC8_INIT 0x00

#define TIMESTAMP_FORMAT "%Y-%m-%d %H:%M:%S"

typedef struct {
    uint32_t timestamp;
    float temperature_C;
    float humidity_percent;
} SensorData;

typedef struct {
    int fd;
    int sensor_present;
    int i2c_opened;
    int i2c_read_count;
    int i2c_read_timeout;
    int i2c_read_error;
    int i2c_read_nack;
    int i2c_read_crc_error;
} SensorState;

void sigint_handler(int signum) {
    if (SensorState.state.i2c_opened) {
        close(SensorState.state.fd);
    }
    exit(EXIT_SUCCESS);
}

void init_sensor_state(SensorState *state) {
    state->fd = -1;
    state->sensor_present = 0;
    state->i2c_opened = 0;
    state->i2c_read_count = 0;
    state->i2c_read_timeout = 0;
    state->i2c_read_error = 0;
    state->i2c_read_nack = 0;
    state->i2c_read_crc_error = 0;
}

void open_i2c(SensorState *state) {
    if (state->i2c_opened) {
        return;
    }
    state->fd = open(I2C_FILE, O_RDWR);
    if (state->fd == -1) {
        state->i2c_opened = 0;
        state->i2c_open_error = errno;
        syslog(LOG_ERR, "Failed to open I2C device: %s", strerror(errno));
        return;
    }
    state->i2c_opened = 1;
}

void close_i2c(SensorState *state) {
    if (state->i2c_opened) {
        close(state->fd);
        state->i2c_opened = 0;
    }
}

void read_i2c(SensorState *state) {
    if (!state->i2c_opened) {
        return;
    }
    struct iovec iovec;
    iovec.iov_base = &state->i2c_read_buffer;
    iovec.iov_len = sizeof(state->i2c_read_buffer);
    state->i2c_read_count = 0;
    state->i2c_read_timeout = 100000; // 100ms
    while (state->i2c_read_count < 3) {
        if (ioctl(state->fd, I2C_SMBUS_READ, 0, &iovec) == -1) {
            state->i2c_read_error = errno;
            state->i2c_read_nack = 0;
            state->i2c_read_crc_error = 0;
            syslog(LOG_ERR, "I2C read error: %s", strerror(errno));
            return;
        }
        if (state->i2c_read_count == 0) {
            state->i2c_read_timeout = 0;
        }
        if (state->i2c_read_timeout > 0) {
            usleep(1000);
            state->i2c_read_timeout--;
        }
        if (state->i2c_read_count == 3) {
            break;
        }
    }
    if (state->i2c_read_count < 3) {
        state->i2c_read_nack = 1;
        syslog(LOG_ERR, "I2C read timeout");
        return;
    }
    if (state->i2c_read_error || state->i2c_read_nack) {
        return;
    }
    if (state->i2c_read_crc_error) {
        return;
    }
    state->i2c_read_error = 0;
    state->i2c_read_nack = 0;
    state->i2c_read_crc_error = 0;
}

void verify_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc = crc ^ data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x01) {
                crc = (crc >> 1) ^ CRC8_POLY;
            } else {
                crc = crc >> 1;
            }
        }
    }
    if (crc != data[len - 1]) {
        state->i2c_read_crc_error = 1;
        syslog(LOG_ERR, "CRC error");
    }
}

void read_sensor_data(SensorState *state) {
    if (!state->sensor_present) {
        return;
    }
    if (state->i2c_read_error || state->i2c_read_nack || state->i2c_read_crc_error) {
        return;
    }
    if (state->i2c_read_count < 3) {
        return;
    }
    uint8_t data[3];
    memcpy(data, state->i2c_read_buffer, 3);
    verify_crc8(data, 3);
    if (state->i2c_read_crc_error) {
        return;
    }
    state->sensor_data.temperature_C = (float)((data[0] << 8) | data[1]) / 163.84;
    state->sensor_data.humidity_percent = (float)((data[0] << 8) | data[1]) / 256.0;
    syslog(LOG_INFO, "Temperature: %.2f°C, Humidity: %.2f%%", state->sensor_data.temperature_C, state->sensor_data.humidity_percent);
}

void reset_sensor(SensorState *state) {
    if (state->i2c_opened) {
        ioctl(state->fd, I2C_SMBUS_WRITE, 0, &state->i2c_read_buffer);
        state->i2c_read_buffer[0] = SENSOR_RESET;
        ioctl(state->fd, I2C_SMBUS_WRITE, 0, &state->i2c_read_buffer);
    }
}

void log_data(SensorState *state) {
    if (state->sensor_present) {
        struct timeval tv;
        gettimeofday(&tv, NULL);
        char timestamp[128];
        strftime(timestamp, sizeof(timestamp), TIMESTAMP_FORMAT, &tv);
        char line[256];
        snprintf(line, sizeof(line), "%s,%f,%f", timestamp, state->sensor_data.temperature_C, state->sensor_data.humidity_percent);
        FILE *file = fopen("environment.log", "a");
        if (file) {
            fprintf(file, "%s\n", line);
            fclose(file);
        } else {
            syslog(LOG_ERR, "Failed to write to log file: %s", strerror(errno));
        }
    }
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sa.sa_flags = SA_RESTART;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        syslog(LOG_ERR, "Failed to set SIGINT handler: %s", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        syslog(LOG_ERR, "Failed to set SIGTERM handler: %s", strerror(errno));
        return EXIT_FAILURE;
    }
    SensorState state;
    init_sensor_state(&state);
    open_i2c(&state);
    if (!state.sensor_present) {
        syslog(LOG_ERR, "Sensor not present");
        return EXIT_FAILURE;
    }
    while (1) {
        read_i2c(&state);
        if (state.i2c_read_error || state.i2c_read_nack || state.i2c_read_crc_error) {
            reset_sensor(&state);
            continue;
        }
        read_sensor_data(&state);
        log_data(&state);
        usleep(500000); // 5 seconds
    }
    return EXIT_SUCCESS;
}

