#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <math.h>

#define STLM75_ADDR 0x90
#define BUFFER_SIZE 10
#define LED_PIN 17

typedef struct {
    float data[BUFFER_SIZE];
    float sum;
    int next;
} CircularBuffer;

void init_buffer(CircularBuffer *buf) {
    buf->sum = 0.0;
    buf->next = 0;
}

void add_to_buffer(CircularBuffer *buf, float value) {
    buf->data[buf->next] = value;
    buf->sum += value;
    buf->next = (buf->next + 1) % BUFFER_SIZE;
}

float get_average(CircularBuffer *buf) {
    return buf->sum / (float)BUFFER_SIZE;
}

void cleanup(CircularBuffer *buf) {
    free(buf);
}

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        // Turn off LED
        digitalWrite(LED_PIN, 0);
        // Close I2C handle
        close(i2c_fd);
        // Invoke library's cleanup call
        cleanup(&buffer);
        // Exit program
        exit(0);
    }
}

int main() {
    // Initialize signal handler
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize I2C device
    if (ioctl(i2c_fd, I2C_SLAVE, STLM75_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        cleanup(&buffer);
        return 1;
    }

    // Initialize buffer
    CircularBuffer *buf = malloc(sizeof(CircularBuffer));
    init_buffer(buf);

    // Initialize LED
    if (gpio_set_direction(LED_PIN, GPIO_OUT) < 0) {
        perror("gpio_set_direction");
        cleanup(&buffer);
        return 1;
    }

    // Initialize I2C read
    if (i2c_read(buf, STLM75_ADDR) < 0) {
        perror("i2c_read");
        cleanup(&buffer);
        return 1;
    }

    // Main loop
    while (1) {
        // Read temperature
        if (i2c_read(buf, STLM75_ADDR) < 0) {
            continue;
        }

        // Add to buffer
        add_to_buffer(buf, buf->data[0]);

        // Compute average
        float average = get_average(buf);

        // Turn LED on or off
        if (average > 28.0) {
            gpio_set_value(LED_PIN, 1);
        } else {
            gpio_set_value(LED_PIN, 0);
        }

        // Sleep for 1 second
        usleep(1000000);
    }

    // Cleanup
    cleanup(&buffer);

    return 0;
}

// Function stub for gpio_set_direction and gpio_set_value
