#define CO2_THRESHOLD_HIGH 1200

#define LOG_FILE "air_quality.log"

#define LOG_HEADER "timestamp,co2,temp,humidity\n"

typedef struct {
    int fd;
    struct gpiod_handle *handle;
    struct gpiod_line *line;
    struct gpiod_event *event;
} SCD30Handle;

static void sigint_handler(int signum) {
    SCD30Handle *handle = (SCD30Handle *) sigcontext->uc.ccontext;
    if (handle) {
        handle->line->close(handle->handle);
        handle->line = NULL;
        handle->event = NULL;
        handle->fd = -1;
        gpiod_handle_close(handle->handle);
    }
    exit(EXIT_SUCCESS);
}

static void log_error(const char *message) {
    FILE *log = fopen(LOG_FILE, "a");
    if (!log) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
    fprintf(log, "%s\n", message);
    fclose(log);
}

static void log_data(const char *timestamp, double co2, double temp, double humidity) {
    FILE *log = fopen(LOG_FILE, "a");
    if (!log) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
    fprintf(log, "%s,%f,%f,%f\n", timestamp, co2, temp, humidity);
    fclose(log);
}

