#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x5C
#define I2C_DEV_NAME "/dev/i2c-" I2C_BUS

#define PRESSURE_OFFSET 0
#define TEMPERATURE_OFFSET 1
#define SCALE_FACTOR_OFFSET 2

#define CRC8_POLYNOMIAL 0x07
#define CRC8_INIT 0xFF

typedef struct {
    int fd;
    struct gpiod_handle *handle;
    struct gpiod_line *line;
} I2CHandle;

static int i2c_open(I2CHandle *handle) {
    handle->fd = open(I2C_DEV_NAME, O_RDWR);
    if (handle->fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }
    return 0;
}

static int i2c_close(I2CHandle *handle) {
    if (handle->fd >= 0) {
        close(handle->fd);
    }
    if (handle->handle) {
        gpiod_close(handle->handle);
    }
    if (handle->line) {
        gpiod_line_unref(handle->line);
    }
    return 0;
}

static int i2c_ioctl(I2CHandle *handle, int cmd, void *buf, int len) {
    if (handle->fd < 0) {
        return -1;
    }
    if (ioctl(handle->fd, cmd, buf) < 0) {
        perror("I2C ioctl failed");
        return -1;
    }
    return 0;
}

static int i2c_read(I2CHandle *handle, void *buf, int len) {
    if (handle->fd < 0) {
        return -1;
    }
    if (len < 9) {
        return -1;
    }
    if (i2c_ioctl(handle, I2C_SLAVE, I2C_ADDR, I2C_READ) < 0) {
        return -1;
    }
    if (read(handle->fd, buf, len) < 0) {
        perror("Failed to read I2C data");
        return -1;
    }
    return 0;
}

static int i2c_crc8(const void *buf, int len, int poly, int init) {
    uint8_t crc = init;
    for (int i = 0; i < len; i++) {
        uint8_t data = ((uint8_t *)buf)[i];
        crc = (crc << 1) ^ (data == 0 ? init : (data ^ crc) & 0xFF);
    }
    return crc;
}

static int i2c_validate_crc8(const void *buf, int len, int poly, int init) {
    uint8_t crc = i2c_crc8(buf, len, poly, init);
    if (crc != init) {
        return -1;
    }
    return 0;
}

static int i2c_read_data(I2CHandle *handle, void *buf, int len) {
    if (i2c_read(handle, buf, len) < 0) {
        return -1;
    }
    if (i2c_validate_crc8(buf, len, CRC8_POLYNOMIAL, CRC8_INIT) < 0) {
        return -1;
    }
    return 0;
}

static int i2c_read_pressure_temperature_scale_factors(I2CHandle *handle, void *buf, int len) {
    if (i2c_read_data(handle, buf, len) < 0) {
        return -1;
    }
    return 0;
}

static int i2c_read_pressure(I2CHandle *handle, void *buf, int len) {
    if (i2c_read_data(handle, buf, len) < 0) {
        return -1;
    }
    return 0;
}

static int i2c_read_temperature(I2CHandle *handle, void *buf, int len) {
    if (i2c_read_data(handle, buf, len) < 0) {
        return -1;
    }
    return 0;
}

static int i2c_read_scale_factor(I2CHandle *handle, void *buf, int len) {
    if (i2c_read_data(handle, buf, len) < 0) {
        return -1;
    }
    return 0;
}

static int i2c_read_pressure_temperature_scale_factors_and_validate(I2CHandle *handle, void *buf, int len) {
    if (i2c_read_pressure_temperature_scale_factors(handle, buf, len) < 0) {
        return -1;
    }
    return 0;
}

static int i2c_read_pressure_temperature_scale_factors_and_validate_and_log(I2CHandle *handle, void *buf, int len) {
    if (i2c_read_pressure_temperature_scale_factors_and_validate(handle, buf, len) < 0) {
        return -1;
    }
    printf("Pressure: %f Pa\n", *(float *)(buf + PRESSURE_OFFSET));
    printf("Temperature: %f %cC\n", *(float *)(buf + TEMPERATURE_OFFSET), (buf[TEMPERATURE_OFFSET + 1] == 0xff ? 'F' : 'C'));
    printf("Scale Factor: %f\n", *(float *)(buf + SCALE_FACTOR_OFFSET));
    return 0;
}

static int i2c_read_once(I2CHandle *handle) {
    if (handle->fd < 0) {
        return -1;
    }
    if (gpiod_line_request(handle->line, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to request I2C device");
        return -1;
    }
    if (i2c_read_pressure_temperature_scale_factors_and_validate_and_log(handle, buf, 9) < 0) {
        return -1;
    }
    return 0;
}

static int i2c_read_periodically(I2CHandle *handle) {
    if (handle->fd < 0) {
        return -1;
    }
    if (gpiod_line_request(handle->line, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to request I2C device");
        return -1;
    }
    if (i2c_read_pressure_temperature_scale_factors_and_validate_and_log(handle, buf, 9) < 0) {
        return -1;
    }
    return 0;
}

static int i2c_read_once_and_log(I2CHandle *handle) {
    if (i2c_read_once(handle) < 0) {
        return -1;
    }
    return 0;
}

static int i2c_read_periodically_and_log(I2CHandle *handle) {
    if (i2c_read_periodically(handle) < 0) {
        return -1;
    }
    return 0;
}

static int i2c_read_once_and_log_with_delay(I2CHandle *handle) {
    if (i2c_read_once_and_log(handle) < 0) {
        return -1;
    }
    usleep(450000); // 45 ms delay
    return 0;
}

static int i2c_read_periodically_and_log_with_delay(I2CHandle *handle) {
    if (i2c_read_periodically_and_log(handle) < 0) {
        return -1;
    }
    usleep(450000); // 45 ms delay
    return 0;
}

static int i2c_read_once_and_log_with_delay_and_log(I2CHandle *handle) {
    if (i2c_read_once_and_log_with_delay(handle) < 0) {
        return -1;
    }
    return 0;
}

static int i2c_read_periodically_and_log_with_delay_and_log(I2CHandle *handle) {
    if (i2c_read_periodically_and_log_with_delay(handle) < 0) {
        return -1;
    }
    return 0;
}

static int i2c_read_once_and_log_with_delay_and_log_and_exit(I2CHandle *handle) {
    if (i2c_read_periodically_and_log_with_delay_and_log(handle) < 0) {
        return -1;
    }
    if (i2c_close(handle) < 0) {
        return -1;
    }
    return 0;
}

static int i2c_read_periodically_and_log_with_delay_and_log_and_exit(I2CHandle *handle) {
    if (i2c_read_periodically_and_log_with_delay_and_log(handle) < 0) {
        return -1;
    }
    if (i2c_close(handle) < 0) {
        return -1;
    }
    return 0;
}

static int i2c_read_once_and_log_with_delay_and_log_and_exit_and_signal(I2CHandle *handle) {
    if (i2c_read_periodically_and_log_with_delay_and_log_and_exit(handle) < 0) {
        return -1;
    }
    if (signal(SIGINT, [](int sig) { return 0; }) == SIG_ERR) {
        perror("Failed to set SIGINT handler");
        return -1;
    }
    if (signal(SIGTERM, [](int sig) { return 0; }) == SIG_ERR) {
        perror("Failed to set SIGTERM handler");
        return -1;
    }
    return 0;
}

static int i2c_read_periodically_and_log_with_delay_and_log_and_exit_and_signal_and_cleanup(I2CHandle *handle) {
    if (i2c_read_once_and_log_with_delay_and_log_and_exit_and_signal(handle) < 0) {
        return -1;
    }
    return 0;
}

int main() {
    I2CHandle handle;
    if (i2c_open(&handle) < 0) {
        return -1;
    }
    if (gpiod_init() < 0) {
        perror("Failed to initialize gpiod");
        return -1;
    }
    if (gpiod_new(&handle.handle) < 0) {
        perror("Failed to create gpiod handle");
        return -1;
    }
    if (gpiod_new_line(&handle.line, GPIOD_LINE_TYPE_I2C) < 0) {
        perror("Failed to create I2C line");
        return -1;
    }
    if (i2c_read_periodically_and_log_with_delay_and_log_and_exit_and_signal_and_cleanup(&handle) < 0) {
        return -1;
    }
    return 0;
}

#include <stdio.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c.h>
#include <linux/i2c-dev.h>
#include <string.h>
#include <signal.h>

#define I2C_BUS 1
#define I2C_ADDR 0x43
#define HDC1000_REG_TEMP 0x00
#define HDC1000_REG_HUMID 0x01
#define HDC1000_REG_CONTROL 0x0F
#define HDC1000_REG_DRDY 0x02

#define I2C_DEVICE "/dev/i2c-" I2C_BUS

int i2c_fd = -1;
int temp = 0;
int humidity = 0;

void handle_signal(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

int main() {
    struct i2c_msg msg[1];
    struct i2c_rdma_request req;
    struct i2c_rdma_request *req_ptr = &req;
    int err;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if ((i2c_fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set slave address");
        close(i2c_fd);
        return 1;
    }

    memset(msg, 0, sizeof(struct i2c_msg));
    msg[0].addr = I2C_ADDR;
    msg[0].flags = I2C_M_RD;
    msg[0].len = 2;
    msg[0].data[0] = HDC1000_REG_CONTROL;
    msg[0].data[1] = 0x00;

    req.request = msg[0];
    req.request_count = 1;
    req.flags = I2C_RDMA_NONE;

    if (ioctl(i2c_fd, I2C_RDWR, &req) < 0) {
        perror("Failed to send I2C request");
        close(i2c_fd);
        return 1;
    }

    usleep(20000); // Wait 20ms after conversion

    memset(msg, 0, sizeof(struct i2c_msg));
    msg[0].addr = I2C_ADDR;
    msg[0].flags = I2C_M_RD;
    msg[0].len = 2;
    msg[0].data[0] = HDC1000_REG_TEMP;
    msg[0].data[1] = 0x00;

    if (ioctl(i2c_fd, I2C_RDWR, &req) < 0) {
        perror("Failed to read temperature");
        close(i2c_fd);
        return 1;
    }

    if (msg[0].data[0] & 0x80) {
        printf("Temperature: Invalid\n");
    } else {
        temp = (msg[0].data[0] << 4) | (msg[0].data[1] >> 4);
        printf("Temperature: %.2f C\n", (float)temp / 16.0);
    }

    memset(msg, 0, sizeof(struct i2c_msg));
    msg[0].addr = I2C_ADDR;
    msg[0].flags = I2C_M_RD;
    msg[0].len = 2;
    msg[0].data[0] = HDC1000_REG_HUMID;
    msg[0].data[1] = 0x00;

    if (ioctl(i2c_fd, I2C_RDWR, &req) < 0) {
        perror("Failed to read humidity");
        close(i2c_fd);
        return 1;
    }

    if (msg[0].data[0] & 0x80) {
        printf("Humidity: Invalid\n");
    } else {
        humidity = (msg[0].data[0] << 4) | (msg[0].data[1] >> 4);
        printf("Humidity: %.2f %%\n", (float)humidity / 16.0);
    }

    while (1) {
        if (fprintf(stderr, "\n") < 0) {
            perror("Failed to write to stderr");
            continue;
        }

        if (fprintf(stdout, "Temperature: %.2f C, Humidity: %.2f %%\n", (float)temp / 16.0, (float)humidity / 16.0) < 0) {
            perror("Failed to write to stdout");
            continue;
        }

        if (fflush(stdout) < 0) {
            perror("Failed to flush stdout");
            continue;
        }

        if (sleep(5) < 0) {
            perror("Failed to sleep");
            continue;
        }

        memset(msg, 0, sizeof(struct i2c_msg));
        msg[0].addr = I2C_ADDR;
        msg[0].flags = I2C_M_RD;
        msg[0].len = 2;
        msg[0].data[0] = HDC1000_REG_CONTROL;
        msg[0].data[1] = 0x00;

        if (ioctl(i2c_fd, I2C_RDWR, &req) < 0) {
            perror("Failed to send I2C request");
            close(i2c_fd);
            return 1;
        }

        usleep(20000); // Wait 20ms after conversion
    }

    return 0;
}

