}

int i2c_write(int fd, int addr, uint8_t *buf, int len) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to set slave address");
        return -1;
    }
    if (write(fd, buf, len) < 0) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

int i2c_read(int fd, int addr, uint8_t *buf, int len, int timeout) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to set slave address");
        return -1;
    }
    if (read(fd, buf, len) < 0) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

int i2c_read_temp(int fd, int addr, int *temp) {
    uint8_t buf[2];
    buf[0] = 0x00;
    buf[1] = 0x00;
    if (i2c_read(fd, addr, buf, 2, TEMP_READ_TIMEOUT) < 0) {
        return -1;
    }
    *temp = (buf[0] << 8) | buf[1];
    return 0;
}

int main() {
    wiringPiSetupGpio();
    wiringPiI2CSetup(0);

    int i2c_fd = i2c_open(I2C_DEVICE);
    if (i2c_fd < 0) {
        return 1;
    }

    int temp;
    while (!shutdown) {
        if (i2c_read_temp(i2c_fd, SI7051_ADDR, &temp) < 0) {
            printf("I2C read error\n");
            sleep(1);
            continue;
        }
        printf("Temperature: %f°C\n", (float)temp / 10.0);
        sleep(TEMP_READ_INTERVAL / 1000000.0);
    }

    i2c_close(i2c_fd);
    return 0;
}

