#include <stdbool.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDR 0x34

#define MLX90833_REG_PRES 0x00
#define MLX90833_REG_STATUS 0x01
#define MLX90833_REG_CONTROL 0x02
#define MLX90833_REG_CONFIG 0x03
#define MLX90833_REG_TEMP 0x04
#define MLX90833_REG_MANUFACTURER_ID 0x05
#define MLX90833_REG_MODEL_ID 0x06
#define MLX90833_REG_VERSION 0x07
#define MLX90833_REG_STATUS_DATA 0x08
#define MLX90833_REG_STATUS_CONTROL 0x09
#define MLX90833_REG_STATUS_CONFIG 0x0A
#define MLX90833_REG_STATUS_TEMP 0x0B
#define MLX90833_REG_STATUS_MANUFACTURER_ID 0x0C
#define MLX90833_REG_STATUS_MODEL_ID 0x0D
#define MLX90833_REG_STATUS_VERSION 0x0E

#define I2C_TIMEOUT 100

typedef struct {
    int fd;
    bool initialized;
    bool sensor_present;
    bool status_data_valid;
    bool control_valid;
    bool config_valid;
    bool temp_valid;
    bool manufacturer_id_valid;
    bool model_id_valid;
    bool version_valid;
} MLX90833State;

void handle_signal(int signum) {
    MLX90833State* state = (MLX90833State*) malloc(sizeof(MLX90833State));
    if (!state) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    if (state->initialized) {
        free(state);
        return;
    }

    if (state->fd > 0) {
        close(state->fd);
    }

    free(state);
    exit(EXIT_SUCCESS);
}

int main() {
    MLX90833State state;
    state.initialized = false;
    state.sensor_present = false;
    state.status_data_valid = false;
    state.control_valid = false;
    state.config_valid = false;
    state.temp_valid = false;
    state.manufacturer_id_valid = false;
    state.model_id_valid = false;
    state.version_valid = false;
    state.fd = -1;

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction failed");
        exit(EXIT_FAILURE);
    }

    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction failed");
        exit(EXIT_FAILURE);
    }

    state.fd = open(I2C_DEVICE, O_RDWR);
    if (state.fd == -1) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(state.fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        exit(EXIT_FAILURE);
    }

    MLX90833State* state_ptr = &state;

    if (!state_ptr->initialized) {
        state_ptr->initialized = true;
        state_ptr->sensor_present = true;
    }

    while (1) {
        if (state_ptr->initialized) {
            uint8_t buffer[1];
            uint16_t pressure;
            uint16_t status_data;
            uint16_t control;
            uint16_t config;
            uint16_t temp;
            uint16_t manufacturer_id;
            uint16_t model_id;
            uint16_t version;

            if (ioctl(state_ptr->fd, MLX90833_GET_STATUS_DATA, buffer) < 0) {
                perror("Failed to read status data");
                continue;
            }
            status_data = (uint16_t) (buffer[0] << 8 | buffer[1]);

            if (ioctl(state_ptr->fd, MLX90833_GET_CONTROL, buffer) < 0) {
                perror("Failed to read control");
                continue;
            }
            control = (uint16_t) (buffer[0] << 8 | buffer[1]);

            if (ioctl(state_ptr->fd, MLX90833_GET_CONFIG, buffer) < 0) {
                perror("Failed to read config");
                continue;
            }
            config = (uint16_t) (buffer[0] << 8 | buffer[1]);

            if (ioctl(state_ptr->fd, MLX90833_GET_TEMP, buffer) < 0) {
                perror("Failed to read temp");
                continue;
            }
            temp = (uint16_t) (buffer[0] << 8 | buffer[1]);

            if (ioctl(state_ptr->fd, MLX90833_GET_MANUFACTURER_ID, buffer) < 0) {
                perror("Failed to read manufacturer ID");
                continue;
            }
            manufacturer_id = (uint16_t) (buffer[0] << 8 | buffer[1]);

            if (ioctl(state_ptr->fd, MLX90833_GET_MODEL_ID, buffer) < 0) {
                perror("Failed to read model ID");
                continue;
            }
            model_id = (uint16_t) (buffer[0] << 8 | buffer[1]);

            if (ioctl(state_ptr->fd, MLX90833_GET_VERSION, buffer) < 0) {
                perror("Failed to read version");
                continue;
            }
            version = (uint16_t) (buffer[0] << 8 | buffer[1]);

            if (status_data & 0x01) {
                state_ptr->status_data_valid = false;
            } else {
                state_ptr->status_data_valid = true;
            }

            if (control & 0x01) {
                state_ptr->control_valid = false;
            } else {
                state_ptr->control_valid = true;
            }

            if (config & 0x01) {
                state_ptr->config_valid = false;
            } else {
                state_ptr->config_valid = true;
            }

            if (temp & 0x01) {
                state_ptr->temp_valid = false;
            } else {
                state_ptr->temp_valid = true;
            }

            if (manufacturer_id & 0x01) {
                state_ptr->manufacturer_id_valid = false;
            } else {
                state_ptr->manufacturer_id_valid = true;
            }

            if (model_id & 0x01) {
                state_ptr->model_id_valid = false;
            } else {
                state_ptr->model_id_valid = true;
            }

            if (version & 0x01) {
                state_ptr->version_valid = false;
            } else {
                state_ptr->version_valid = true;
            }

            if (state_ptr->status_data_valid && state_ptr->control_valid && state_ptr->config_valid && state_ptr->temp_valid && state_ptr->manufacturer_id_valid && state_ptr->model_id_valid && state_ptr->version_valid) {
                pressure = (uint16_t) (buffer[2] << 8 | buffer[3]);
                printf("%s %u\n", "Pressure:", pressure);
            }
        }

        usleep(500 * 1000);
    }

    return 0;
}

