void i2c_init(I2CConfig *config) {
    config->fd = -1;
    config->i2c_fd = -1;
    config->i2c_slaves = 1;
    config->i2c_slave_addr = I2C_SLAVE_ADDR;
    config->i2c_bus = 1;
    config->i2c_speed = 1000000;
    config->i2c_mode = I2C_RDWR;
    config->i2c_stop = 0;
    config->i2c_restart = 0;
    config->i2c_ack = 1;
    config->i2c_nack = 0;
    config->i2c_no_stop = 0;
    config->i2c_no_restart = 0;
    config->i2c_no_ack = 0;
    config->i2c_no_nack = 0;
    config->i2c_no_stop_ack = 0;
    config->i2c_no_restart_ack = 0;
    config->i2c_stop_ack = 0;
    config->i2c_restart_ack = 0;
    config->i2c_ack_nack = 0;
    config->i2c_no_stop_ack_nack = 0;
    config->i2c_no_restart_ack_nack = 0;
    config->i2c_stop_nack_ack = 0;
    config->i2c_restart_nack_ack = 0;
    config->i2c_stop_nack_nack = 0;
    config->i2c_restart_nack_nack = 0;
}

void i2c_open(I2CConfig *config) {
    config->fd = open("/dev/i2c-" config->i2c_bus, O_RDWR);
    if (config->fd < 0) {
        perror("Failed to open i2c device");
        exit(EXIT_FAILURE);
    }
    config->i2c_fd = ioctl(config->fd, I2C_SLAVE, config->i2c_slave_addr);
    if (config->i2c_fd < 0) {
        perror("Failed to set i2c slave address");
        exit(EXIT_FAILURE);
    }
}

void i2c_close(I2CConfig *config) {
    if (config->i2c_fd >= 0) {
        close(config->i2c_fd);
    }
    if (config->fd >= 0) {
        close(config->fd);
    }
}

