#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x40
#define HIH6130_I2C_ID 0x00
#define HIH6130_I2C_ID_STATUS 0x01
#define HIH6130_I2C_ID_TEMP 0x02
#define HIH6130_I2C_ID_HUMID 0x03
#define HIH6130_I2C_ID_RESET 0x0E
#define HIH6130_I2C_ID_CONFIG 0x0F

#define I2C_TIMEOUT 100
#define I2C_READ_TIMEOUT 200
#define I2C_WRITE_TIMEOUT 100
#define I2C_READ_SIZE 64
#define I2C_WRITE_SIZE 32

#define ENVIRONMENTAL_DATA_LOG "environmental_data.log"
#define MAX_LOG_SIZE 1024 * 1024

typedef struct {
    uint8_t status;
    uint16_t temp;
    uint16_t humidity;
} HIH6130Data;

static int i2c_fd;
static bool i2c_initialized = false;

static void i2c_init() {
    if (i2c_initialized) {
        return;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        exit(EXIT_FAILURE);
    }

    i2c_initialized = true;
}

static void i2c_read(HIH6130Data *data) {
    uint8_t buf[I2C_READ_SIZE];
    int len = 0;

    if (ioctl(i2c_fd, I2C_RDWR, buf, I2C_READ_SIZE, I2C_TIMEOUT) < 0) {
        perror("Failed to read I2C data");
        return;
    }

    data->status = buf[HIH6130_I2C_ID_STATUS];
    data->temp = (buf[HIH6130_I2C_ID_TEMP] << 8) | buf[HIH6130_I2C_ID_TEMP + 1];
    data->humidity = (buf[HIH6130_I2C_ID_HUMID] << 8) | buf[HIH6130_I2C_ID_HUMID + 1];
}

static void i2c_write(uint8_t *buf, int len) {
    if (ioctl(i2c_fd, I2C_RDWR, buf, len, I2C_WRITE_TIMEOUT) < 0) {
        perror("Failed to write I2C data");
        return;
    }
}

static void i2c_reset() {
    uint8_t buf[1] = {HIH6130_I2C_ID_RESET};
    i2c_write(buf, 1);
}

static void i2c_config() {
    uint8_t buf[1] = {HIH6130_I2C_ID_CONFIG};
    i2c_write(buf, 1);
}

static void i2c_check_status(HIH6130Data *data) {
    if (data->status & 0x80) {
        fprintf(stderr, "Sensor error: %02x\n", data->status);
        return;
    }
}

static void log_data(HIH6130Data *data) {
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[128];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    snprintf(buffer, sizeof(buffer), "%04d-%02d-%02d %02d:%02d:%02d ",
             timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_mday,
             timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec);

    fprintf(stderr, "Logging data: %s %d.%02d%% %d.%02d\n",
            buffer, data->humidity, 100 - data->humidity, data->temp, 100 - data->temp);

    FILE *log_file = fopen(ENVIRONMENTAL_DATA_LOG, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }

    fprintf(log_file, "%s %d.%02d%% %d.%02d\n", buffer, data->humidity, 100 - data->humidity, data->temp, 100 - data->temp);
    fclose(log_file);

    if (fstat(fileno(log_file), &statbuf) < 0) {
        perror("Failed to get file status");
        return;
    }

    if (statbuf.st_size >= MAX_LOG_SIZE) {
        fprintf(stderr, "Truncating log file\n");
        truncate(ENVIRONMENTAL_DATA_LOG, 0);
    }
}

static void handle_i2c_error(int err) {
    if (err == EIO) {
        fprintf(stderr, "I2C error: %s\n", strerror(err));
        i2c_reset();
    }
}

static void handle_sensor_error(int err) {
    if (err == EIO) {
        fprintf(stderr, "Sensor error: %s\n", strerror(err));
        i2c_reset();
    }
}

static void handle_log_error(int err) {
    if (err == EIO) {
        fprintf(stderr, "Log file error: %s\n", strerror(err));
    }
}

static void signal_handler(int signum) {
    if (signum == SIGINT) {
        fprintf(stderr, "Received SIGINT, exiting...\n");
        exit(EXIT_SUCCESS);
    }
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    i2c_init();

    i2c_config();

    while (true) {
        HIH6130Data data;
        i2c_read(&data);
        i2c_check_status(&data);

        log_data(&data);

        usleep(5000000); // 5 seconds
    }

    return 0;
}

