    char filename[MAX_DATA_SIZE];
    struct timeval start;
    struct timeval end;
} LogEntry;

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        if (SensorData.sfd.fd > 0) {
            close(SensorData.sfd.fd);
        }
        exit(EXIT_SUCCESS);
    }
}

int i2c_read(int fd, unsigned char *buf, int len, int timeout) {
    struct iovec iov;
    iov.iov_base = buf;
    iov.iov_len = len;

    if (ioctl(fd, I2C_SLAVE, I2C_SLAVE) < 0) {
        perror("ioctl I2C_SLAVE");
        return -1;
    }

    if (write(fd, &I2C_SLAVE, 1) != 1) {
        perror("write I2C_SLAVE");
        return -1;
    }

    if (read(fd, buf, len) != len) {
        perror("read");
        return -1;
    }

    if (ioctl(fd, I2C_WAIT, timeout) < 0) {
        perror("ioctl I2C_WAIT");
        return -1;
    }

    return 0;
}

int i2c_read_data(int fd, unsigned char *buf, int len, int timeout) {
    int i;
    for (i = 0; i < len; i++) {
        if (i2c_read(fd, buf + i, 1, timeout) < 0) {
            return -1;
        }
    }
    return 0;
}

int i2c_read_status(int fd, unsigned char *buf, int timeout) {
    if (i2c_read(fd, buf, 1, timeout) < 0) {
        return -1;
    }
    return buf[0] == 0x00 ? 0 : -1;
}

int i2c_read_data_nibble(int fd, unsigned char *buf, int timeout) {
    if (i2c_read(fd, buf, 1, timeout) < 0) {
        return -1;
    }
    return buf[0] >= 0x12 && buf[0] <= 0x27A ? 0 : -1;
}

int i2c_read_data_nibbles(int fd, unsigned char *buf, int timeout) {
    if (i2c_read(fd, buf, 3, timeout) < 0) {
        return -1;
    }
    return buf[0] >= 0x12 && buf[0] <= 0x27A &&
           buf[1] >= 0x12 && buf[1] <= 0x27A &&
           buf[2] >= 0x12 && buf[2] <= 0x27A ? 0 : -1;
}

int i2c_read_checksum(int fd, unsigned char *buf, int timeout) {
    if (i2c_read(fd, buf, 1, timeout) < 0) {
        return -1;
    }
    return buf[0] >= 0x12 && buf[0] <= 0x27A ? 0 : -1;
}

void log_pressure(const char *filename, const char *time_str, double pressure) {
    struct tm *timeinfo;
    time_t rawtime;
    FILE *file;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    snprintf(filename, sizeof(filename), "%s", filename);
    file = fopen(filename, "a");
    if (!file) {
        perror("fopen");
        return;
    }

    fprintf(file, "%s, Pressure: %.2f Pa\n", time_str, pressure);
    fclose(file);
}

