    if (SensorData.fd < 0) {
        perror("open");
        return EXIT_FAILURE;
    }

    if (ioctl(SensorData.fd, I2C_SLAVE, I2C_SLAVE) < 0) {
        perror("ioctl I2C_SLAVE");
        close(SensorData.fd);
        return EXIT_FAILURE;
    }

    if (write(SensorData.fd, &I2C_SLAVE, 1) != 1) {
        perror("write I2C_SLAVE");
        close(SensorData.fd);
        return EXIT_FAILURE;
    }

    while (1) {
        gettimeofday(&log_entry.start, NULL);
        if (i2c_read_status(SensorData.fd, buf, I2C_TIMEOUT) < 0) {
            fprintf(stderr, "Sensor status error\n");
            continue;
        }

        if (buf[0] == 0x00) {
            fprintf(stderr, "Sensor absent\n");
            continue;
        }

        if (i2c_read_data_nibble(SensorData.fd, buf, I2C_TIMEOUT) < 0) {
            fprintf(stderr, "Nibble 1 error\n");
            continue;
        }

        if (i2c_read_data_nibble(SensorData.fd, buf + 1, I2C_TIMEOUT) < 0) {
            fprintf(stderr, "Nibble 2 error\n");
            continue;
        }

        if (i2c_read_data_nibble(SensorData.fd, buf + 2, I2C_TIMEOUT) < 0) {
            fprintf(stderr, "Nibble 3 error\n");
            continue;
        }

        if (i2c_read_checksum(SensorData.fd, buf + 3, I2C_TIMEOUT) < 0) {
            fprintf(stderr, "Checksum error\n");
            continue;
        }

        if (i2c_read_data_nibbles(SensorData.fd, buf, I2C_TIMEOUT) < 0) {
            fprintf(stderr, "Data nibbles error\n");
            continue;
        }

        for (i = 0; i < 4; i++) {
            pressure = (buf[4 + 2 * i] << 4) | buf[5 + 2 * i];
            pressure /= 10.0;
            log_pressure(log_entry.filename, ctime(&rawtime), pressure);
        }

        gettimeofday(&log_entry.end, NULL);
        fprintf(stderr, "Read pressure: %.2f Pa\n", pressure);
    }

    return EXIT_SUCCESS;
