#define SHT40_ADDR 0x45
#define SHT40_REG_TEMP_HOLD 0x00
#define SHT40_REG_HUM_HOLD 0x02
#define SHT40_REG_TEMP_MEAS 0x00
#define SHT40_REG_HUM_MEAS 0x02
#define CRC8_POLY 0x31
#define CRC8_INIT 0x00

typedef struct {
    int fd;
    int i2c_fd;
    int temp;
    int humidity;
    int crc8_temp;
    int crc8_humidity;
    int log_fd;
} SHT40State;

static void sigint_handler(int signum) {
    SHT40State *state = (SHT40State *)malloc(sizeof(SHT40State));
    if (state) {
        state->fd = fileno(stdin);
        state->i2c_fd = state->temp = state->humidity = state->crc8_temp = state->crc8_humidity = state->log_fd = -1;
        if (state->i2c_fd = open("/dev/i2c-ad0", O_RDWR)) {
            ioctl(state->i2c_fd, I2C_SLAVE, SHT40_ADDR);
        }
        if (state->log_fd = open("environmental_data.txt", O_WRONLY | O_CREAT | O_TRUNC, 0644)) {
            fprintf(state->log_fd, "timestamp,temp,humidity\n");
        }
        free(state);
    }
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sa.sa_flags = SA_RESTART;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);

    SHT40State state;
    state.fd = fileno(stdin);
    state.i2c_fd = state.temp = state.humidity = state.crc8_temp = state.crc8_humidity = state.log_fd = -1;

    if (state.i2c_fd = open("/dev/i2c-ad0", O_RDWR)) {
        ioctl(state.i2c_fd, I2C_SLAVE, SHT40_ADDR);
    }

    if (state.log_fd = open("environmental_data.txt", O_WRONLY | O_CREAT | O_TRUNC, 0644)) {
        fprintf(state.log_fd, "timestamp,temp,humidity\n");
    }

    while (1) {
        if (state.temp = ioctl(state.i2c_fd, I2C_SMBUS_READ, SHT40_REG_TEMP_MEAS, 2, 0)) {
            if (state.humidity = ioctl(state.i2c_fd, I2C_SMBUS_READ, SHT40_REG_HUM_MEAS, 2, 0)) {
                if (state.crc8_temp = state.humidity & 0xFF) {
                    if (state.crc8_humidity = state.humidity >> 8) {
                        if (state.crc8_temp == crc8(state.state.crc8_temp, state.temp)) {
                            if (state.crc8_humidity == crc8(state.state.crc8_humidity, state.humidity)) {
                                char timestamp[20];
                                struct tm *now = localtime(&time(NULL));
                                strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", now);
                                fprintf(state.log_fd, "%s,%d,%d\n", timestamp, state.temp, state.humidity);
                                fflush(state.log_fd);
                            }
                        }
                    }
                }
            }
        }
        usleep(8500);
        if (time(NULL) % 5000 == 0) {
            fprintf(state.log_fd, "timestamp,temp,humidity\n");
            fflush(state.log_fd);
        }
    }

    close(state.i2c_fd);
    close(state.log_fd);
    return 0;
}

uint8_t crc8(uint8_t crc, uint8_t data) {
    uint8_t i;
    uint8_t poly = CRC8_POLY;
    for (i = 0; i < 8; i++) {
        uint8_t bit = (data >> (7 - i)) & 1;
        if (crc & 1) {
            crc = (crc >> 1) ^ poly;
        } else {
            crc = (crc >> 1);
        }
        data >>= 1;
    }
    return crc;
}

