void init_sensor() {
    int fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, I2C_SLAVE, TMP117_ADDR) < 0) {
        perror("Failed to set slave address");
        close(fd);
        exit(EXIT_FAILURE);
    }

    int config = 0x00;
    if (ioctl(fd, I2C_SMBUS_WRITE, 0, (unsigned char *)&config, 1) < 0) {
        perror("Failed to configure TMP117");
        close(fd);
        exit(EXIT_FAILURE);
    }

    close(fd);
}

