        close(fd);
        return;
    }

    close(fd);
}

void flush_buffer() {
    int fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return;
    }

    if (ioctl(fd, I2C_SLAVE, TMP117_ADDR) < 0) {
        perror("Failed to set slave address");
        close(fd);
        return;
    }

    if (ioctl(fd, I2C_SMBUS_WRITE, 0, (unsigned char *)&TMP117_REG_CONFIG, 1) < 0) {
        perror("Failed to configure TMP117");
        close(fd);
        return;
    }

    close(fd);
}

void save_buffer() {
    int fd = open("temperature_log.dat", O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) {
        perror("Failed to open log file");
        return;
    }

    for (int i = 0; i < buffer.count; i++) {
        fwrite(&buffer.data[i], sizeof(buffer.data[i]), 1, fd);
    }

    close(fd);
}

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        save_buffer();
        flush_buffer();
        close(fd);
        exit(EXIT_SUCCESS);
    }
}

int main() {
    init_sensor();

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        read_temp();
        usleep(SAMPLE_INTERVAL * 1000000);
    }

    return 0;
}

