static void handle_sensor_error(int err, const char *message) {
    fprintf(stderr, "Error: %s\n", message);
    if (err == -1) {
        perror("Error");
    }
}

static void handle_sigint(int sig) {
    if (sig == SIGINT) {
        if (i2c_fd > 0) {
            close(i2c_fd);
        }
        handle_sensor_error(-1, "I2C handle closed");
        if (sensor != NULL) {
            sensor->cleanup();
        }
        exit(EXIT_SUCCESS);
    }
}

static void init_sensor() {
    if (i2c_fd < 0) {
        handle_sensor_error(-1, "Failed to open I2C device");
        return;
    }

    if (ioctl(i2c_fd, SHTC3_MEASUREMENT_COMMAND, 0) < 0) {
        handle_sensor_error(-1, "Failed to send measurement command");
        return;
    }

    usleep(SHTC3_MEASUREMENT_TIMEOUT * 1000);

    if (ioctl(i2c_fd, SHTC3_MEASUREMENT_RESULT_COMMAND, 0) < 0) {
        handle_sensor_error(-1, "Failed to read measurement result");
        return;
    }

    if (read(i2c_fd, &sensor->temperature, SHTC3_MEASUREMENT_RESULT_LENGTH) < 0) {
        handle_sensor_error(-1, "Failed to read temperature");
        return;
    }

    if (read(i2c_fd, &sensor->humidity, SHTC3_MEASUREMENT_RESULT_LENGTH) < 0) {
        handle_sensor_error(-1, "Failed to read humidity");
        return;
    }

    if (read(i2c_fd, &sensor->crc, 1) < 0) {
        handle_sensor_error(-1, "Failed to read CRC");
        return;
    }

    if (sensor->temperature < SHTC3_TEMPERATURE_MIN || sensor->temperature > SHTC3_TEMPERATURE_MAX) {
        handle_sensor_error(-1, "Temperature out of range");
        return;
    }

    if (sensor->humidity < SHTC3_HUMIDITY_MIN || sensor->humidity > SHTC3_HUMIDITY_MAX) {
        handle_sensor_error(-1, "Humidity out of range");
        return;
    }

    if (sensor->crc != (uint8_t) crc8(sensor->temperature, sensor->humidity, SHTC3_CRC8_POLYNOMIAL, SHTC3_CRC8_INIT_VALUE)) {
        handle_sensor_error(-1, "CRC mismatch");
        return;
    }

    if (log_file_fd < 0) {
        handle_sensor_error(-1, "Failed to open log file");
        return;
    }

    snprintf(log_line, sizeof(log_line), SHTC3_ENVIRONMENT_LOG_FILE, SHTC3_MEASUREMENT_RESULT_FORMAT, time(NULL));
    write(log_file_fd, log_line, strlen(log_line));

    if (stdout_fd < 0) {
        handle_sensor_error(-1, "Failed to open stdout");
        return;
    }

    snprintf(stdout_line, sizeof(stdout_line), SHTC3_ENVIRONMENT_LOG_FILE, SHTC3_MEASUREMENT_RESULT_FORMAT, time(NULL), sensor->temperature, sensor->humidity);
    write(stdout_fd, stdout_line, strlen(stdout_line));
}

static void cleanup_sensor() {
    if (i2c_fd > 0) {
        close(i2c_fd);
    }
    if (log_file_fd > 0) {
        close(log_file_fd);
    }
    if (stdout_fd > 0) {
        close(stdout_fd);
    }
}

static uint8_t crc8(uint8_t data1, uint8_t data2, uint8_t poly, uint8_t init) {
    uint8_t crc = init;
    for (int i = 0; i < 8; i++) {
        crc ^= (data1 << (7 - i)) | (data2 << (7 - (i + 1)));
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ poly;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

