#define I2C_ACK 0x00
#define I2C_NACK 0x80
#define I2C_SLAVE_ADDR 0x40

#define I2C_TIMEOUT 100
#define I2C_RETRIES 5

#define SLPM_OFFSET 0x00
#define TEMP_OFFSET 0x02
#define SLPM_MASK 0x3FF
#define TEMP_MASK 0x0FC

#define LOG_FILE "/home/pi/fm_flow_log.txt"

typedef struct {
    uint32_t timestamp;
    uint16_t slpm;
    uint16_t temp;
} FlowData;

void i2c_init(int *i2c_fd) {
    *i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (*i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }
}

void i2c_reinit(int *i2c_fd) {
    close(*i2c_fd);
    *i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (*i2c_fd < 0) {
        perror("Failed to re-open I2C device");
        exit(EXIT_FAILURE);
    }
}

void i2c_read(int *i2c_fd, uint8_t *buf, int len) {
    int retries = 0;
    while (retries < I2C_RETRIES) {
        if (read(*i2c_fd, buf, len) < 0) {
            perror("Failed to read I2C data");
            i2c_reinit(i2c_fd);
            retries++;
        } else {
            if (len == 4) {
                return;
            } else {
                perror("Invalid I2C data length");
                i2c_reinit(i2c_fd);
                retries++;
            }
        }
    }
    perror("Failed to read I2C data after retries");
    i2c_reinit(i2c_fd);
}

void i2c_write(int *i2c_fd, uint8_t *buf, int len) {
    int retries = 0;
    while (retries < I2C_RETRIES) {
        if (write(*i2c_fd, buf, len) < 0) {
            perror("Failed to write I2C data");
            i2c_reinit(i2c_fd);
            retries++;
        } else {
            return;
        }
    }
    perror("Failed to write I2C data after retries");
    i2c_reinit(i2c_fd);
}

void i2c_read_flow_data(int *i2c_fd, FlowData *data) {
    uint8_t buf[4];
    i2c_read(i2c_fd, buf, 4);
    data->timestamp = (uint32_t)buf[0] << 24 | (uint32_t)buf[1] << 16 | (uint32_t)buf[2] << 8 | (uint32_t)buf[3];
    data->slpm = (uint16_t)(buf[SLPM_OFFSET] & SLPM_MASK);
    data->temp = (uint16_t)(buf[TEMP_OFFSET] & TEMP_MASK);
}

void i2c_read_temp_data(int *i2c_fd, uint8_t *buf, int len) {
    i2c_read(i2c_fd, buf, len);
    if (len == 2) {
        return;
    } else {
        perror("Invalid I2C data length");
        i2c_reinit(i2c_fd);
    }
}

void i2c_read_temp_data(int *i2c_fd, uint16_t *temp) {
    uint8_t buf[2];
    i2c_read_temp_data(i2c_fd, buf, 2);
    *temp = (uint16_t)(buf[0] << 8 | buf[1]);
}

void i2c_write_flow_data(int *i2c_fd, FlowData *data) {
    uint8_t buf[4];
    buf[0] = (uint8_t)(data->timestamp >> 24);
    buf[1] = (uint8_t)(data->timestamp >> 16);
    buf[2] = (uint8_t)(data->timestamp >> 8);
    buf[3] = (uint8_t)(data->timestamp);
    buf[SLPM_OFFSET] = (uint8_t)(data->slpm);
    buf[TEMP_OFFSET] = (uint8_t)(data->temp);
    i2c_write(i2c_fd, buf, 4);
}

void i2c_write_temp_data(int *i2c_fd, uint16_t *temp) {
    uint8_t buf[2];
    buf[0] = (uint8_t)(temp[0] >> 8);
    buf[1] = (uint8_t)(temp[1]);
    i2c_write(i2c_fd, buf, 2);
}

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        if (i2c_fd != NULL) {
            close(i2c_fd);
        }
        if (fp != NULL) {
            fclose(fp);
        }
        exit(EXIT_SUCCESS);
    }
}

int main() {
    int i2c_fd = NULL;
    FlowData data;
    FILE *fp = NULL;
    struct sigaction sa;

    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_init(&i2c_fd);

    fp = fopen(LOG_FILE, "w");
    if (fp == NULL) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    while (1) {
        i2c_read_flow_data(&i2c_fd, &data);
        if (data.timestamp == 0) {
            // Handle first two reads after power-up
            if (i2c_fd != NULL) {
                i2c_reinit(&i2c_fd);
            }
            continue;
        }

        fprintf(fp, "%u %u %u\n", data.timestamp, data.slpm, data.temp);
        fflush(fp);

        // Sleep for 1 second
        usleep(1000000);
    }

    return 0;
}

