#define DHT11_PIN GPIO4
#define DHT11_PIN_NAME "/gpio/gpio4"
#define DHT11_FILE "dht11_readings.txt"
#define DHT11_HEADER "timestamp,humidity_int,humidity_dec,temperature_int,temperature_dec,checksum\n"

typedef struct {
    int fd;
    struct gpiod_handle handle;
    struct gpiod_line *line;
    struct gpiod_event *event;
} DHT11Device;

void cleanup(DHT11Device *d) {
    if (d->fd > 0) {
        close(d->fd);
    }
    if (d->line) {
        gpiod_line_free(d->line);
    }
    if (d->event) {
        gpiod_event_free(d->event);
    }
    gpiod_handle_free(d->handle);
}

void handle_signal(int signum) {
    cleanup((DHT11Device *)NULL);
    exit(EXIT_SUCCESS);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    DHT11Device d;
    d.fd = open(DHT11_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (d.fd < 0) {
        perror("Failed to open file");
        cleanup(&d);
        exit(EXIT_FAILURE);
    }

    int err = gpiod_open(DHT11_PIN_NAME, GPIOD_OPEN_FLAG_NEW | GPIOD_OPEN_FLAG_NONBLOCK, &d.handle);
    if (err < 0) {
        perror("Failed to open GPIO");
        cleanup(&d);
        exit(EXIT_FAILURE);
    }

    err = gpiod_get_line_by_number(d.handle, 0, &d.line);
    if (err < 0) {
        perror("Failed to get line");
        cleanup(&d);
        exit(EXIT_FAILURE);
    }

    err = gpiod_request_event(d.handle, d.line, GPIOD_EVENT_EDGE_RISING, &d.event);
    if (err < 0) {
        perror("Failed to request event");
        cleanup(&d);
        exit(EXIT_FAILURE);
    }

    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);

    while (1) {
        err = gpiod_read(d.handle, d.line, d.event, &d.event->data);
        if (err < 0) {
            if (d.event->data == 0) {
                // Line is low
                if (clock_gettime(CLOCK_MONOTONIC, &end) == -1) {
                    perror("Failed to get end time");
                    cleanup(&d);
                    exit(EXIT_FAILURE);
                }
                if ((end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) >= 18000000) {
                    // Start signal sent
                    start = end;
                    err = gpiod_write(d.handle, d.line, GPIOD_LINE_STATE_LOW, 0);
                    if (err < 0) {
                        perror("Failed to set line to low");
                        cleanup(&d);
                        exit(EXIT_FAILURE);
                    }
                } else {
                    // Timeout on start signal
                    fprintf(stderr, "Timeout on start signal: %ldms\n", (end.tv_sec - start.tv_sec) * 1000 + (end.tv_nsec - start.tv_nsec) / 1000000);
                    cleanup(&d);
                    exit(EXIT_FAILURE);
                }
            } else {
                // Line is high
                if (clock_gettime(CLOCK_MONOTONIC, &end) == -1) {
                    perror("Failed to get end time");
                    cleanup(&d);
                    exit(EXIT_FAILURE);
                }
                if ((end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) >= 18000000) {
                    // Start signal sent
                    start = end;
