#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <syslog.h>
#include <signal.h>
#include <time.h>
#include <math.h>

#define SHT31D_ADDR 0x45
#define SHT31D_MEASUREMENT_COMMAND 0x00
#define SHT31D_TEMP_MEASUREMENT_COMMAND 0x02
#define SHT31D_HUMIDITY_MEASUREMENT_COMMAND 0x04
#define SHT31D_TEMP_MEASUREMENT_SIZE 2
#define SHT31D_HUMIDITY_MEASUREMENT_SIZE 2
#define SHT31D_CRC8_POLYNOMIAL 0x31
#define SHT31D_CRC8_INIT 0x00

#define I2C_TIMEOUT 100
#define I2C_RETRY_COUNT 3
#define LOG_FILE "sht31d_data.log"

typedef struct {
    int i2c_fd;
    int log_fd;
    int temperature;
    int humidity;
    int crc8;
} SHT31DState;

static void handleSig(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        if (SHT31DState.i2c_fd > 0) {
            close(SHT31DState.i2c_fd);
        }
        if (SHT31DState.log_fd > 0) {
            close(SHT31DState.log_fd);
        }
        exit(EXIT_SUCCESS);
    }
}

static int i2cOpen(const char *device) {
    int fd;
    if ((fd = open(device, O_RDWR)) < 0) {
        syslog(LOG_ERR, "Failed to open I2C device: %s", strerror(errno));
        return -1;
    }
    return fd;
}

static int i2cWrite(int fd, uint8_t *buf, size_t size) {
    if (write(fd, buf, size) < 0) {
        syslog(LOG_ERR, "Failed to write to I2C device: %s", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2cRead(int fd, uint8_t *buf, size_t size) {
    if (read(fd, buf, size) < 0) {
        syslog(LOG_ERR, "Failed to read from I2C device: %s", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2cValidateCRC8(uint8_t *buf, size_t size) {
    uint8_t crc = 0;
    for (size_t i = 0; i < size - 1; i++) {
        crc ^= buf[i];
    }
    crc ^= SHT31D_CRC8_INIT;
    for (size_t i = 0; i < 8; i++) {
        crc = (crc & 1) ? (crc >> 1) ^ SHT31D_CRC8_POLYNOMIAL : crc >> 1;
    }
    return crc == buf[size - 1];
}

static int sht31dInit(SHT31DState *state) {
    int i2c_fd = i2cOpen("/dev/i2c-1");
    if (i2c_fd < 0) {
        return -1;
    }
    state->i2c_fd = i2c_fd;
    return 0;
}

static int sht31dMeasureTemperature(SHT31DState *state) {
    uint8_t buf[3];
    buf[0] = SHT31D_ADDR;
    buf[1] = SHT31D_MEASUREMENT_COMMAND;
    buf[2] = 0;
    if (i2cWrite(state->i2c_fd, buf, 3) < 0) {
        return -1;
    }
    for (int retry = 0; retry < I2C_RETRY_COUNT; retry++) {
        if (i2cRead(state->i2c_fd, buf, 2) < 0) {
            if (retry < I2C_RETRY_COUNT - 1) {
                usleep(15 * 1000);
            } else {
                syslog(LOG_ERR, "Failed to read from I2C device after %d retries: %s", retry + 1, strerror(errno));
                return -1;
            }
        }
        if (i2cValidateCRC8(buf, 2)) {
            state->temperature = (buf[0] << 8) | buf[1];
            return 0;
        }
    }
    return -1;
}

static int sht31dMeasureHumidity(SHT31DState *state) {
    uint8_t buf[3];
    buf[0] = SHT31D_ADDR;
    buf[1] = SHT31D_MEASUREMENT_COMMAND;
    buf[2] = 0x04;
    if (i2cWrite(state->i2c_fd, buf, 3) < 0) {
        return -1;
    }
    for (int retry = 0; retry < I2C_RETRY_COUNT; retry++) {
        if (i2cRead(state->i2c_fd, buf, 2) < 0) {
            if (retry < I2C_RETRY_COUNT - 1) {
                usleep(15 * 1000);
            } else {
                syslog(LOG_ERR, "Failed to read from I2C device after %d retries: %s", retry + 1, strerror(errno));
                return -1;
            }
        }
        if (i2cValidateCRC8(buf, 2)) {
            state->humidity = (buf[0] << 8) | buf[1];
            return 0;
        }
    }
    return -1;
}

static int sht31dLogData(SHT31DState *state) {
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[128];
    rawtime = time(NULL);
    timeinfo = localtime(&rawtime);
    strftime(buffer, 128, "%Y-%m-%d %H:%M:%S", timeinfo);
    if (fprintf(state->log_fd, "%s,%d,%d\n", buffer, state->temperature, state->humidity) < 0) {
        syslog(LOG_ERR, "Failed to write to log file: %s", strerror(errno));
        return -1;
    }
    return 0;
}

static int sht31dMain(SHT31DState *state) {
    if (sht31dInit(state) < 0) {
        return -1;
    }
    if (sht31dMeasureTemperature(state) < 0) {
        return -1;
    }
    if (sht31dMeasureHumidity(state) < 0) {
        return -1;
    }
    if (sht31dLogData(state) < 0) {
        return -1;
    }
    return 0;
}

int main() {
    SHT31DState state;
    signal(SIGINT, handleSig);
    signal(SIGTERM, handleSig);
    if (sht31dMain(&state) < 0) {
        syslog(LOG_ERR, "Failed to initialize SHT31D sensor");
        return EXIT_FAILURE;
    }
    while (1) {
        if (sht31dMain(&state) < 0) {
            syslog(LOG_ERR, "Failed to measure SHT31D sensor");
            break;
        }
        usleep(5000 * 1000);
    }
    return EXIT_SUCCESS;
}

