#define I2C_DEV "/dev/i2c-1"
#define ADPD105_ADDR 0x0d

#define I2C_TIMEOUT 100
#define I2C_RETRIES 3

#define LOG_FILE "cct_log.csv"

#define MAX_LINE_LENGTH 256

typedef struct {
    uint32_t timestamp;
    float average_cct;
} cct_log_entry;

static int fd;
static int sensor_present = 0;
static int sensor_fd;
static int sensor_fd2;
static int cct_log_fd;

static void handle_error(const char *msg) {
    fprintf(stderr, "%s: %s\n", msg, strerror(errno));
    exit(EXIT_FAILURE);
}

static void cleanup() {
    if (fd > 0) {
        close(fd);
    }
    if (sensor_fd > 0) {
        close(sensor_fd);
    }
    if (sensor_fd2 > 0) {
        close(sensor_fd2);
    }
    if (cct_log_fd > 0) {
        close(cct_log_fd);
    }
}

static void handle_signal(int signum) {
    cleanup();
    exit(EXIT_SUCCESS);
}

static int i2c_read(uint8_t *buf, size_t size) {
    int i;
    for (i = 0; i < I2C_RETRIES; i++) {
        fd = open(I2C_DEV, O_RDWR);
        if (fd < 0) {
            handle_error("Failed to open I2C device");
        }
        if (ioctl(fd, I2C_SLAVE, ADPD105_ADDR) < 0) {
            handle_error("Failed to set slave address");
        }
        if (read(fd, buf, size) < 0) {
            handle_error("Failed to read from I2C device");
        }
        if (buf[0] == 0) {
            break;
        }
        usleep(I2C_TIMEOUT * 1000);
    }
    if (i == I2C_RETRIES) {
        handle_error("Failed to read from I2C device after retries");
    }
    return 0;
}

static int i2c_write(uint8_t *buf, size_t size) {
    int i;
    for (i = 0; i < I2C_RETRIES; i++) {
        fd = open(I2C_DEV, O_RDWR);
        if (fd < 0) {
            handle_error("Failed to open I2C device");
        }
        if (ioctl(fd, I2C_SLAVE, ADPD105_ADDR) < 0) {
            handle_error("Failed to set slave address");
        }
        if (write(fd, buf, size) < 0) {
            handle_error("Failed to write to I2C device");
        }
        if (buf[0] == 0) {
            break;
        }
        usleep(I2C_TIMEOUT * 1000);
    }
    if (i == I2C_RETRIES) {
        handle_error("Failed to write to I2C device after retries");
    }
    return 0;
}

static float compute_cct(uint32_t r, uint32_t g, uint32_t b) {
    float x = (r * 0.2126) + (g * 0.7152) + (b * 0.0722);
    float y = (r * 0.2989) + (g * 0.5866) + (b * 0.2115);
    float z = (r * 0.0680) + (g * 0.0353) + (b * 0.0580);
    float cct = 10000.0 * (3.0 * y) / (x * z - y * y);
    return cct;
}

static void log_entry(const char *timestamp, float cct) {
    static char line[MAX_LINE_LENGTH];
    snprintf(line, MAX_LINE_LENGTH, "%s,%f", timestamp, cct);
    if (write(cct_log_fd, line, strlen(line)) < 0) {
        handle_error("Failed to write to log file");
    }
}

static void main_loop() {
    struct timeval tv;
    cct_log_entry entry;
    char timestamp[128];
    float cct;

    gettimeofday(&tv, NULL);
    sprintf(timestamp, "%ld.%06ld", (long)tv.tv_sec, (long)tv.tv_usec);

    if (!sensor_present) {
        fprintf(stderr, "Sensor not present\n");
        return;
    }

    if (i2c_read(sensor_fd, (uint8_t *)&entry.r) < 0) {
        fprintf(stderr, "Failed to read sensor data\n");
        return;
    }
    if (i2c_read(sensor_fd, (uint8_t *)&entry.g) < 0) {
        fprintf(stderr, "Failed to read sensor data\n");
        return;
    }
    if (i2c_read(sensor_fd, (uint8_t *)&entry.b) < 0) {
        fprintf(stderr, "Failed to read sensor data\n");
        return;
    }

    cct = compute_cct(entry.r, entry.g, entry.b);
    entry.timestamp = tv.tv_sec * 1000000 + tv.tv_usec;
    log_entry(timestamp, cct);

    if (cct_log_fd < 0) {
        handle_error("Failed to open log file");
    }
}

static void init() {
    fd = open(LOG_FILE, O_CREAT | O_WRONLY | O_TRUNC, 0644);
    if (fd < 0) {
        handle_error("Failed to open log file");
    }
    if (write(fd, "Timestamp,Average_CCT\n", 20) < 0) {
        handle_error("Failed to write header to log file");
    }
    cct_log_fd = fd;
    fd = open(I2C_DEV, O_RDWR);
    if (fd < 0) {
        handle_error("Failed to open I2C device");
    }
    if (ioctl(fd, I2C_SLAVE, ADPD105_ADDR) < 0) {
        handle_error("Failed to set slave address");
    }
    sensor_fd = open("/dev/i2c-1", O_RDWR);
    if (sensor_fd < 0) {
        handle_error("Failed to open sensor device");
    }
    if (ioctl(sensor_fd, I2C_SLAVE, ADPD105_ADDR) < 0) {
        handle_error("Failed to set slave address");
    }
    sensor_fd2 = open("/dev/i2c-1", O_RDWR);
    if (sensor_fd2 < 0) {
        handle_error("Failed to open sensor device");
    }
    if (ioctl(sensor_fd2, I2C_SLAVE, ADPD105_ADDR) < 0) {
        handle_error("Failed to set slave address");
    }
    sensor_present = 1;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    init();

    while (1) {
        main_loop();
        usleep(1000000); // 1 second delay
    }

    return 0;
}

