#define MLX90824_REG_TEMP 0x00
#define MLX90824_REG_PRES 0x01
#define MLX90824_REG_STATUS 0x02
#define MLX90824_REG_CONFIG 0x03

#define I2C_TIMEOUT 100

typedef struct {
    int fd;
    int status;
    uint8_t *buffer;
    size_t buffer_size;
} I2CHandle;

static I2CHandle i2c_handle;

static void i2c_init() {
    i2c_handle.fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_handle.fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }
    if (ioctl(i2c_handle.fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        exit(EXIT_FAILURE);
    }
    i2c_handle.buffer = malloc(2 * sizeof(uint8_t));
    i2c_handle.buffer_size = 2;
}

static void i2c_cleanup() {
    if (i2c_handle.fd > 0) {
        close(i2c_handle.fd);
    }
    free(i2c_handle.buffer);
}

static void i2c_read(uint8_t reg) {
    i2c_handle.status = ioctl(i2c_handle.fd, I2C_RDWR, (unsigned long)(reg << 1));
    if (i2c_handle.status < 0) {
        perror("Failed to read I2C register");
        exit(EXIT_FAILURE);
    }
}

static void i2c_write(uint8_t reg, uint8_t value) {
    i2c_handle.status = ioctl(i2c_handle.fd, I2C_RDWR, (unsigned long)((reg << 1) | 0x01));
    if (i2c_handle.status < 0) {
        perror("Failed to write I2C register");
        exit(EXIT_FAILURE);
    }
}

static void i2c_read_data() {
    i2c_read(MLX90824_REG_PRES);
    i2c_handle.buffer[0] = i2c_handle.buffer[0] & 0xFF;
    i2c_read(MLX90824_REG_TEMP);
    i2c_handle.buffer[1] = i2c_handle.buffer[1] & 0xFF;
}

static void i2c_write_config() {
    i2c_write(MLX90824_REG_CONFIG, 0x00);
}

static void i2c_read_status() {
    i2c_read(MLX90824_REG_STATUS);
    if (i2c_handle.buffer[0] & 0x80) {
        i2c_handle.status = -1;
    }
}

static void log_error(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[128];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(buffer, 128, "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(stderr, "%s: %s\n", buffer, message);
}

static void log_measurement(double pressure, double temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[128];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(buffer, 128, "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(stderr, "%s: Pressure: %.2f Pa, Temperature: %.2f°C\n", buffer, pressure, temperature);
}

static void write_to_log(const char *filename, double pressure, double temperature) {
    FILE *file = fopen(filename, "a");
    if (!file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
    fprintf(file, "%s Pressure: %.2f Pa, Temperature: %.2f°C\n", buffer, pressure, temperature);
    fclose(file);
}

static void run() {
    i2c_init();
    i2c_write_config();
    while (true) {
        i2c_read_status();
        if (i2c_handle.status == -1) {
            log_error("Sensor not found or communication error");
            continue;
        }
        i2c_read_data();
        double pressure = (i2c_handle.buffer[0] * 0.01) + 0.01;
        double temperature = (i2c_handle.buffer[1] * 0.01) + 0.01;
        log_measurement(pressure, temperature);
        write_to_log("pressure_log.txt", pressure, temperature);
        usleep(2000000); // 2 seconds
    }
    i2c_cleanup();
}

int main() {
    run();
    return 0;
}

