#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <string.h>
#include <signal.h>
#include <stdint.h>
#include <math.h>

#define I2C_SLAVE 0x00
#define I2C_WRITE 0x40
#define I2C_READ 0x00
#define I2C_STOP 0x80
#define I2C_RESTART 0xC0
#define I2C_ACK 0x80
#define I2C_NACK 0x00
#define I2C_TIMEOUT 100

#define CRC8_POLYNOMIAL 0x07
#define CRC8_INIT 0x00

#define PRESSURE_BYTES 2
#define TEMPERATURE_BYTES 2
#define SCALE_FACTOR_BYTES 3
#define TOTAL_BYTES 9

#define PRESSURE_OFFSET 0
#define TEMPERATURE_OFFSET 2
#define SCALE_FACTOR_OFFSET 5

#define PRESSURE_MIN 0.0
#define PRESSURE_MAX 500.0
#define TEMPERATURE_MIN -40.0
#define TEMPERATURE_MAX 85.0

#define LOG_FILE "flow_data.txt"

typedef struct {
    uint8_t data[TOTAL_BYTES];
    uint8_t crc[TOTAL_BYTES];
} SensorData;

void crc8_calculate(uint8_t *data, uint8_t *crc, uint8_t len) {
    uint8_t i, j;
    uint8_t xtime = 0;
    *crc = CRC8_INIT;
    for (i = 0; i < len; i++) {
        xtime ^= data[i];
        for (j = 0; j < 8; j++) {
            if ((xtime & 0x01) != 0) {
                xtime = (xtime >> 1) ^ CRC8_POLYNOMIAL;
            } else {
                xtime = xtime >> 1;
            }
        }
        *crc = *crc ^ xtime;
    }
}

void read_sensor_data(int fd, SensorData *sensor_data) {
    uint8_t buffer[9];
    int len = 9;
    int timeout = 0;
    while (timeout < I2C_TIMEOUT) {
        if (ioctl(fd, I2C_SLAVE, 0x76, I2C_WRITE, 0) < 0) {
            perror("ioctl I2C_SLAVE");
            return;
        }
        if (write(fd, &len, 1) < 0) {
            perror("write");
            return;
        }
        if (read(fd, buffer, len) < 0) {
            perror("read");
            return;
        }
        if (crc8_calculate(buffer, sensor_data->crc, len) != 0) {
            printf("CRC error\n");
            return;
        }
        memcpy(sensor_data->data, buffer, len);
        timeout++;
    }
    if (timeout >= I2C_TIMEOUT) {
        printf("Timeout\n");
        return;
    }
}

void handle_sensor_absent(int fd) {
    printf("Sensor absent\n");
    exit(EXIT_FAILURE);
}

void cleanup(int fd) {
    if (fd > 0) {
        close(fd);
    }
}

void signal_handler(int signum) {
    cleanup(fd);
    exit(EXIT_SUCCESS);
}

int main() {
    int fd;
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open");
        return EXIT_FAILURE;
    }
    if (ioctl(fd, I2C_SLAVE, 0x76, 0) < 0) {
        perror("ioctl I2C_SLAVE");
        cleanup(fd);
        return EXIT_FAILURE;
    }
    fd_set readfds;
    struct timeval tv;
    tv.tv_sec = 0;
    tv.tv_usec = 45 * 1000000;
    FD_ZERO(&readfds);
    FD_SET(fd, &readfds);
    if (select(fd + 1, &readfds, NULL, NULL, &tv) < 0) {
        perror("select");
        cleanup(fd);
        return EXIT_FAILURE;
    }
    if (ioctl(fd, I2C_STOP, 0) < 0) {
        perror("ioctl I2C_STOP");
        cleanup(fd);
        return EXIT_FAILURE;
    }
    SensorData sensor_data;
    read_sensor_data(fd, &sensor_data);
    double pressure = (sensor_data.data[PRESSURE_OFFSET] << 8) | sensor_data.data[PRESSURE_OFFSET + 1];
    pressure /= 256.0;
    double temperature = (sensor_data.data[TEMPERATURE_OFFSET] << 8) | sensor_data.data[TEMPERATURE_OFFSET + 1];
    temperature /= 256.0;
    double scale_factor = (sensor_data.data[SCALE_FACTOR_OFFSET] << 8) | sensor_data.data[SCALE_FACTOR_OFFSET + 1];
    scale_factor /= 256.0;
    scale_factor *= 0.01; // Convert to percentage
    double flow_rate = (pressure * scale_factor) / temperature;
    fprintf(stderr, "Pressure: %.2f Pa\n", pressure);
    fprintf(stderr, "Temperature: %.2f °C\n", temperature);
    fprintf(stderr, "Scale Factor: %.2f %\n", scale_factor * 100);
    fprintf(stderr, "Flow Rate: %.2f m³/s\n", flow_rate);
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen");
        cleanup(fd);
        return EXIT_FAILURE;
    }
    fprintf(fp, "%s Pressure: %.2f Pa\n", ctime(&time(NULL)), pressure);
    fprintf(fp, "%s Temperature: %.2f °C\n", ctime(&time(NULL)), temperature);
    fprintf(fp, "%s Scale Factor: %.2f %\n", ctime(&time(NULL)), scale_factor * 100);
    fprintf(fp, "%s Flow Rate: %.2f m³/s\n", ctime(&time(NULL)), flow_rate);
    fclose(fp);
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);
    signal(SIGKILL, signal_handler);
    while (1) {
        tv.tv_sec = 0;
        tv.tv_usec = 45 * 1000000;
        FD_ZERO(&readfds);
        FD_SET(fd, &readfds);
        if (select(fd + 1, &readfds, NULL, NULL, &tv) < 0) {
            perror("select");
            cleanup(fd);
            return EXIT_FAILURE;
        }
        if (ioctl(fd, I2C_STOP, 0) < 0) {
            perror("ioctl I2C_STOP");
            cleanup(fd);
            return EXIT_FAILURE;
        }
        read_sensor_data(fd, &sensor_data);
        pressure = (sensor_data.data[PRESSURE_OFFSET] << 8) | sensor_data.data[PRESSURE_OFFSET + 1];
        pressure /= 256.0;
        temperature = (sensor_data.data[TEMPERATURE_OFFSET] << 8) | sensor_data.data[TEMPERATURE_OFFSET + 1];
        temperature /= 256.0;
        scale_factor = (sensor_data.data[SCALE_FACTOR_OFFSET] << 8) | sensor_data.data[SCALE_FACTOR_OFFSET + 1];
        scale_factor /= 256.0;
        scale_factor *= 0.01; // Convert to percentage
        flow_rate = (pressure * scale_factor) / temperature;
        fprintf(stderr, "Pressure: %.2f Pa\n", pressure);
        fprintf(stderr, "Temperature: %.2f °C\n", temperature);
        fprintf(stderr, "Scale Factor: %.2f %\n", scale_factor * 100);
        fprintf(stderr, "Flow Rate: %.2f m³/s\n", flow_rate);
        fprintf(fp, "%s Pressure: %.2f Pa\n", ctime(&time(NULL)), pressure);
        fprintf(fp, "%s Temperature: %.2f °C\n", ctime(&time(NULL)), temperature);
        fprintf(fp, "%s Scale Factor: %.2f %\n", ctime(&time(NULL)), scale_factor * 100);
        fprintf(fp, "%s Flow Rate: %.2f m³/s\n", ctime(&time(NULL)), flow_rate);
    }
    return 0;
}

