#define I2C_DEVICE "/dev/i2c-1"
#define SI7021_ADDR 0x40
#define SI7021_MEASURE_RH_NO_HOLD 0x11
#define SI7021_MEASURE_TEMP_NO_HOLD 0x12
#define SI7021_READ_TEMP_FROM_RH 0x13
#define SI7021_MEASURE_RH 0x00
#define SI7021_MEASURE_TEMP 0x01
#define SI7021_TEMP_REG 0x08
#define SI7021_HUMID_REG 0x09
#define SI7021_CONTROL_REG 0x0A
#define SI7021_ID 0x3C
#define SI7021_REVISION 0x3D

#define LOG_FILE "environment.log"
#define TIMESTAMP_FORMAT "%Y-%m-%d %H:%M:%S"

typedef struct {
    int fd;
    gpiod_handle_t handle;
    gpiod_line_mfd_t *gpio;
    gpiod_line_t *i2c;
} Si7021Handler;

void i2c_read(Si7021Handler *handler, int reg, int *value) {
    int retries = 0;
    while (retries < 3) {
        if (ioctl(handler->fd, I2C_RDWR, (unsigned long)SI7021_ADDR, (unsigned long)reg, (unsigned long)value) < 0) {
            if (errno == EIO) {
                printf("I2C read error: %s\n", strerror(errno));
                retries++;
            } else {
                printf("I2C read error: %s\n", strerror(errno));
                return;
            }
        } else {
            break;
        }
    }
}

void i2c_write(Si7021Handler *handler, int reg, int value) {
    int retries = 0;
    while (retries < 3) {
        if (ioctl(handler->fd, I2C_RDWR, (unsigned long)SI7021_ADDR, (unsigned long)reg, (unsigned long)value) < 0) {
            if (errno == EIO) {
                printf("I2C write error: %s\n", strerror(errno));
                retries++;
            } else {
                printf("I2C write error: %s\n", strerror(errno));
                return;
            }
        } else {
            break;
        }
    }
}

void si7021_init(Si7021Handler *handler) {
    handler->fd = open(I2C_DEVICE, O_RDWR);
    if (handler->fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    gpiod_err_t err;
    handler->handle = gpiod_open("/dev/gpiod", &err);
    if (err) {
        perror("Failed to open gpiod");
        exit(EXIT_FAILURE);
    }

    handler->gpio = gpiod_get_line_table(handler->handle);
    if (!handler->gpio) {
        perror("Failed to get line table");
        exit(EXIT_FAILURE);
    }

    handler->i2c = gpiod_get_line_by_number(handler->handle, 0);
    if (!handler->i2c) {
        perror("Failed to get I2C line");
        exit(EXIT_FAILURE);
    }

    gpiod_set_direction(handler->i2c, GPIOD_DIR_INPUT);
    gpiod_set_pullup(handler->i2c, 0);
    gpiod_set_edge(handler->i2c, GPIOD_EDGE_FALLING);
    gpiod_enable(handler->i2c, 1);
}

void si7021_cleanup(Si7021Handler *handler) {
    gpiod_line_disable(handler->i2c);
    gpiod_line_free(handler->i2c);
    gpiod_close(handler->handle);
    close(handler->fd);
}

void log_data(double temp, double humidity) {
    char timestamp[128];
    struct tm *timeinfo;
    time_t now = time(NULL);
    timeinfo = localtime(&now);
    strftime(timestamp, sizeof(timestamp), TIMESTAMP_FORMAT, timeinfo);

    char log_line[256];
    snprintf(log_line, sizeof(log_line), "%s,%.1f,%.1f\n", timestamp, temp, humidity);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    if (fwrite(log_line, 1, strlen(log_line), log_file) != strlen(log_line)) {
        perror("Failed to write to log file");
        exit(EXIT_FAILURE);
    }

    fflush(log_file);
    fclose(log_file);

    printf("%s,%.1f,%.1f\n", timestamp, temp, humidity);
}

void handle_error(Si7021Handler *handler) {
    char timestamp[128];
    struct tm *timeinfo;
    time_t now = time(NULL);
    timeinfo = localtime(&now);
    strftime(timestamp, sizeof(timestamp), TIMESTAMP_FORMAT, timeinfo);

    char error_log_line[256];
    snprintf(error_log_line, sizeof(error_log_line), "%s,Error: Sensor not found\n", timestamp);

    FILE *error_file = fopen("error.log", "a");
    if (error_file == NULL) {
        perror("Failed to open error log file");
        exit(EXIT_FAILURE);
    }

    if (fwrite(error_log_line, 1, strlen(error_log_line), error_file) != strlen(error_log_line)) {
        perror("Failed to write to error log file");
        exit(EXIT_FAILURE);
    }

    fflush(error_file);
    fclose(error_file);

    printf("%s,Error: Sensor not found\n", timestamp);
    exit(EXIT_FAILURE);
}

