typedef struct {
    int fd;
    struct gpiod_handle *handle;
    struct gpiod_line *line;
    int i2c_fd;
    int co2;
    int temp;
    int humidity;
    int crc;
    int running;
} SCD40Driver;

typedef struct {
    char timestamp[20];
    int co2;
    int temp;
    int humidity;
} Record;

typedef struct {
    Record buffer[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    int size;
    int lock;
    pthread_mutex_t mutex;
} CircularBuffer;

void *logging_thread(void *arg) {
    SCD40Driver *driver = (SCD40Driver *)arg;
    CircularBuffer *buffer = &driver->buffer;
    char *filename = strdup(CSV_FILE_NAME);
    FILE *file = fopen(filename, "a");
    if (!file) {
        fprintf(stderr, "Failed to open %s for writing: %s\n", filename, strerror(errno));
        return NULL;
    }
    fprintf(file, "%s", CSV_HEADER);
    while (driver->running) {
        pthread_mutex_lock(&buffer->mutex);
        if (buffer->count >= buffer->size) {
            pthread_mutex_unlock(&buffer->mutex);
            continue;
        }
        Record record = buffer->buffer[buffer->head];
        buffer->head = (buffer->head + 1) % buffer->size;
        buffer->count--;
        fprintf(file, "%s,%d,%d,%d\n", record.timestamp, record.co2, record.temp, record.humidity);
        pthread_mutex_unlock(&buffer->mutex);
        free(filename);
        fclose(file);
        filename = strdup(CSV_FILE_NAME);
        file = fopen(filename, "a");
        if (!file) {
            fprintf(stderr, "Failed to open %s for writing: %s\n", filename, strerror(errno));
            return NULL;
        }
        fprintf(file, "%s", CSV_HEADER);
    }
    free(filename);
    fclose(file);
    return NULL;
}

void *main_loop(void *arg) {
    SCD40Driver *driver = (SCD40Driver *)arg;
    struct gpiod_line *line;
    struct gpiod_request *request;
    struct gpiod_event *event;
    struct gpiod_event_request *request_event;
    struct gpiod_event *event2;
    struct gpiod_request *request2;
    struct gpiod_error *error;
    int i2c_fd;
    int co2;
    int temp;
    int humidity;
    int crc;
    char timestamp[20];
    char error_message[256];
    char *log_filename = strdup(ERROR_FILE_NAME);
    FILE *error_file = fopen(log_filename, "a");
    if (!error_file) {
        fprintf(stderr, "Failed to open %s for writing: %s\n", log_filename, strerror(errno));
        return NULL;
    }
    struct timespec start_time;
    clock_gettime(CLOCK_MONOTONIC, &start_time);
    time_t timestamp_time = start_time.tv_sec;
    snprintf(timestamp, sizeof(timestamp), "%ld", timestamp_time);
    while (driver->running) {
        if (driver->i2c_fd < 0) {
            snprintf(error_message, sizeof(error_message), "Failed to open I2C device: %s", strerror(errno));
            fprintf(error_file, "%s\n", error_message);
            continue;
        }
        if (driver->co2 < 0 || driver->temp < 0 || driver->humidity < 0) {
            snprintf(error_message, sizeof(error_message), "Failed to read sensor: %s", strerror(errno));
            fprintf(error_file, "%s\n", error_message);
            continue;
        }
        if (driver->crc < 0) {
            snprintf(error_message, sizeof(error_message), "CRC error: %s", strerror(errno));
            fprintf(error_file, "%s\n", error_message);
            continue;
        }
        if (driver->i2c_fd < 0) {
            snprintf(error_message, sizeof(error_message), "Failed to close I2C device: %s", strerror(errno));
            fprintf(error_file, "%s\n", error_message);
            continue;
        }
        if (driver->line < 0) {
            snprintf(error_message, sizeof(error_message), "Failed to get I2C line: %s", strerror(errno));
            fprintf(error_file, "%s\n", error_message);
            continue;
        }
        if (driver->request < 0) {
            snprintf(error_message, sizeof(error_message), "Failed to get I2C request: %s", strerror(errno));
            fprintf(error_file, "%s\n", error_message);
            continue;
        }
        if (driver->event < 0) {
            snprintf(error_message, sizeof(error_message), "Failed to get I2C event: %s", strerror(errno));
            fprintf(error_file, "%s\n", error_message);
            continue;
        }
        if (driver->request_event < 0) {
            snprintf(error_message, sizeof(error_message), "Failed to get I2C event request: %s", strerror(errno));
            fprintf(error_file, "%s\n", error_message);
            continue;
        }
        if (driver->event2 < 0) {
            snprintf(error_message, sizeof(error_message), "Failed to get I2C event2: %s", strerror(errno));
            fprintf(error_file, "%s\n", error_message);
            continue;
        }
        if (driver->request2 < 0) {
            snprintf(error_message, sizeof(error_message), "Failed to get I2C request2: %s", strerror(errno));
            fprintf(error_file, "%s\n", error_message);
            continue;
        }
        if (driver->line->ops->read(driver->line, driver->request, driver->event, driver->request_event, driver->event2, driver->request2, &driver->co2, &driver->temp, &driver->humidity, &driver->crc) < 0) {
            snprintf(error_message, sizeof(error_message), "Failed to read sensor: %s", strerror(errno));
            fprintf(error_file, "%s\n", error_message);
            continue;
        }
        driver->head = (driver->head + 1) % BUFFER_SIZE;
        driver->count++;
        if (driver->count == BUFFER_SIZE) {
            driver->head = 0;
        }
        clock_gettime(CLOCK_MONOTONIC, &start_time);
        time_t current_time = start_time.tv_sec;
        snprintf(timestamp, sizeof(timestamp), "%ld", current_time);
        driver->buffer[driver->head].timestamp = strdup(timestamp);
        driver->buffer[driver->head].co2 = driver->co2;
        driver->buffer[driver->head].temp = driver->temp;
        driver->buffer[driver->head].humidity = driver->humidity;
        driver->tail = (driver->tail + 1) % BUFFER_SIZE;
        driver->size = BUFFER_SIZE;
        pthread_mutex_lock(&driver->lock);
        if (driver->count >= driver->size) {
            pthread_mutex_unlock(&driver->lock);
            continue;
        }
        pthread_mutex_unlock(&driver->lock);
        free(timestamp);
        free(driver->timestamp);
        free(log_filename);
        fclose(error_file);
        log_filename = strdup(ERROR_FILE_NAME);
        error_file = fopen(log_filename, "a");
        if (!error_file) {
            fprintf(stderr, "Failed to open %s for writing: %s\n", log_filename, strerror(errno));
            return NULL;
        }
        fprintf(error_file, "%s\n", error_message);
        free(error_message);
        free(log_filename);
        fclose(error_file);
    }
    return NULL;
}

void *init_driver(void *arg) {
    SCD40Driver *driver = (SCD40Driver *)arg;
    driver->running = 1;
    driver->i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (driver->i2c_fd < 0) {
        snprintf(driver->error_message, sizeof(driver->error_message), "Failed to open I2C device: %s", strerror(errno));
        fprintf(stderr, "%s\n", driver->error_message);
        return NULL;
    }
    driver->line = gpiod_request_line_open(driver->i2c_fd, I2C0, I2C0_LINE0);
    if (driver->line < 0) {
        snprintf(driver->error_message, sizeof(driver->error_message), "Failed to get I2C line: %s", strerror(errno));
        fprintf(stderr, "%s\n", driver->error_message);
        return NULL;
    }
    driver->request = gpiod_request_new(driver->line, I2C0, I2C0_LINE0, I2C0_READ, 0, 0, 0);
    if (driver->request < 0) {
        snprintf(driver->error_message, sizeof(driver->error_message), "Failed to get I2C request: %s", strerror(errno));
        fprintf(stderr, "%s\n", driver->error_message);
        return NULL;
    }
    driver->event = gpiod_event_new(driver->request, I2C0, I2C0_LINE0, I2C0_READ, 0, 0, 0);
    if (driver->event < 0) {
        snprintf(driver->error_message, sizeof(driver->error_message), "Failed to get I2C event: %s", strerror(errno));
        fprintf(stderr, "%s\n", driver->error_message);
        return NULL;
    }
    driver->request_event = gpiod_event_request_new(driver->event, I2C0, I2C0_LINE0, I2C0_READ, 0, 0, 0);
    if (driver->request_event < 0) {
        snprintf(driver->error_message, sizeof(driver->error_message), "Failed to get I2C event request: %s", strerror(errno));
        fprintf(stderr, "%s\n", driver->error_message);
        return NULL;
    }
    driver->event2 = gpiod_event_new(driver->request, I2C0, I2C0_LINE0, I2C0_READ, 0, 0, 0);
    if (driver->event2 < 0) {
        snprintf(driver->error_message, sizeof(driver->error_message), "Failed to get I2C event2: %s", strerror(errno));
        fprintf(stderr, "%s\n", driver->error_message);
        return NULL;
    }
    driver->request2 = gpiod_request_new(driver->event2, I2C0, I2C0_LINE0, I2C0_READ, 0, 0, 0);
    if (driver->request2 < 0) {
        snprintf(driver->error_message, sizeof(driver->error_message), "Failed to get I2C request2: %s", strerror(errno));
        fprintf(stderr, "%s\n", driver->error_message);
        return NULL;
    }
    driver->co2 = 0;
    driver->temp = 0;
    driver->humidity = 0;
    driver->crc = 0;
    driver->lock = 0;
    pthread_mutex_init(&driver->mutex, NULL);
    pthread_mutex_init(&driver->lock, NULL);
    return NULL;
}

void *stop_driver(void *arg) {
    SCD40Driver *driver = (SCD40Driver *)arg;
    driver->running = 0;
    return NULL;
}

int main() {
    SCD40Driver driver;
    pthread_t logging_thread;
    pthread_t main_loop_thread;
    pthread_t stop_thread;
    pthread_mutex_init(&driver.lock, NULL);
    pthread_mutex_init(&driver.mutex, NULL);
    pthread_create(&logging_thread, NULL, logging_thread, &driver);
    pthread_create(&main_loop_thread, NULL, main_loop, &driver);
    pthread_create(&stop_thread, NULL, stop_driver, &driver);
    pthread_join(logging_thread, NULL);
    pthread_join(main_loop_thread, NULL);
    pthread_join(stop_thread, NULL);
