}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x60

#define CRC8_POLY 0x07
#define CRC8_INIT 0x00

#define PRESSURE_BYTES 2
#define TEMPERATURE_BYTES 2
#define SCALE_FACTOR_BYTES 2
#define CRC_BYTES 1

#define PRESSURE_OFFSET 0
#define TEMPERATURE_OFFSET 2
#define SCALE_FACTOR_OFFSET 4

#define PRESSURE_MIN 0
#define PRESSURE_MAX 65535
#define TEMPERATURE_MIN -40
#define TEMPERATURE_MAX 85

#define LOG_FILE "sdp810_log.txt"

#define SAMPLE_RATE 1

typedef struct {
    uint64_t timestamp;
    float pressure;
    float temperature;
} LogEntry;

void sigint_handler(int signum) {
    close(i2c_fd);
    close(log_fd);
    munmap(i2c_map, i2c_size);
    exit(0);
}

int main() {
    struct i2c_msg i2c_msg[1];
    struct i2c_rdwr_ioctl_msg i2c_rdwr_msg;
    i2c_msg->flags = I2C_MSG_RD | I2C_MSG_RDXON;
    i2c_msg->addr = I2C_ADDR;
    i2c_msg->buf[0] = 0x00;
    i2c_msg->len = 1;
    i2c_rdwr_msg.msgs = &i2c_msg;
    i2c_rdwr_msg.nmsgs = 1;

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set slave address");
        return 1;
    }

    i2c_map = mmap(0, 0x1000, PROT_READ | PROT_WRITE, MAP_SHARED, i2c_fd, 0);
    if (i2c_map == MAP_FAILED) {
        perror("Failed to map I2C memory");
        return 1;
    }
    i2c_size = 0x1000;

    signal(SIGINT, sigint_handler);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return 1;
    }

    while (1) {
        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);
        uint64_t timestamp = ts.tv_sec * 1000000 + ts.tv_nsec / 1000;

        i2c_rdwr_msg.msgs = &i2c_msg;
        i2c_rdwr_msg.nmsgs = 1;
        if (ioctl(i2c_fd, I2C_RDWR, &i2c_rdwr_msg) < 0) {
            perror("Failed to read I2C data");
            fprintf(log_file, "Error reading I2C data: %s\n", strerror(errno));
            continue;
        }

        uint8_t *data = (uint8_t *)i2c_msg->buf;
        if (data[PRESSURE_OFFSET] != 0x00 || data[TEMPERATURE_OFFSET] != 0x00 || data[SCALE_FACTOR_OFFSET] != 0x00) {
            fprintf(log_file, "Invalid data: %02x %02x %02x\n", data[PRESSURE_OFFSET], data[TEMPERATURE_OFFSET], data[SCALE_FACTOR_OFFSET]);
            continue;
        }

        uint8_t crc = data[0x02 + PRESSURE_OFFSET];
        uint8_t crc_temp = data[0x02 + TEMPERATURE_OFFSET];
        uint8_t crc_scale = data[0x02 + SCALE_FACTOR_OFFSET];

        uint8_t crc_pressure = 0;
        for (int i = 0; i < PRESSURE_BYTES; i++) {
            crc_pressure ^= data[PRESSURE_OFFSET + i];
        }
        crc_pressure = crc_pressure >> 8;
        crc_pressure ^= crc_pressure << 4;
        crc_pressure ^= crc_pressure << 12;
        crc_pressure ^= crc_pressure << 5;
        crc_pressure ^= crc_pressure >> 17;
        crc_pressure ^= crc_pressure >> 26;

        if (crc_pressure != crc) {
            fprintf(log_file, "CRC pressure failed: %02x != %02x\n", crc_pressure, crc);
            continue;
        }

        uint8_t crc_temp = 0;
        for (int i = 0; i < TEMPERATURE_BYTES; i++) {
            crc_temp ^= data[TEMPERATURE_OFFSET + i];
        }
        crc_temp = crc_temp >> 8;
        crc_temp ^= crc_temp << 4;
        crc_temp ^= crc_temp << 12;
        crc_temp ^= crc_temp << 5;
        crc_temp ^= crc_temp >> 17;
        crc_temp ^= crc_temp >> 26;

        if (crc_temp != crc_temp) {
            fprintf(log_file, "CRC temperature failed: %02x != %02x\n", crc_temp, crc_temp);
            continue;
        }

        uint8_t crc_scale = 0;
        for (int i = 0; i < SCALE_FACTOR_BYTES; i++) {
            crc_scale ^= data[SCALE_FACTOR_OFFSET + i];
        }
        crc_scale = crc_scale >> 8;
        crc_scale ^= crc_scale << 4;
        crc_scale ^= crc_scale << 12;
        crc_scale ^= crc_scale << 5;
        crc_scale ^= crc_scale >> 17;
        crc_scale ^= crc_scale >> 26;

        if (crc_scale != crc_scale) {
            fprintf(log_file, "CRC scale failed: %02x != %02x\n", crc_scale, crc_scale);
            continue;
        }

        float pressure = (float)((data[PRESSURE_OFFSET + 0] << 8) | data[PRESSURE_OFFSET + 1]) / 256.0;
        float temperature = (float)((data[TEMPERATURE_OFFSET + 0] << 8) | data[TEMPERATURE_OFFSET + 1]) / 256.0 - 40.0;
        float scale_factor = (float)((data[SCALE_FACTOR_OFFSET + 0] << 8) | data[SCALE_FACTOR_OFFSET + 1]) / 256.0;

        pressure = pressure * scale_factor;
        temperature = temperature * scale_factor;

        fprintf(log_file, "%llu,%f,%f\n", timestamp, pressure, temperature);

        nanosleep((const struct timespec[]){{0, 500000000L}}, NULL);
    }

    fclose(log_file);
    munmap(i2c_map, i2c_size);
    close(i2c_fd);
    return 0;
}

