    uint8_t temperature;
} ICP10110Data;

typedef struct {
    int i2c_fd;
    int pressure_fd;
    int temperature_fd;
} ICP10110Sensor;

void sigint_handler(int signum) {
    ICP10110Sensor sensor;
    sensor.i2c_fd = -1;
    sensor.pressure_fd = -1;
    sensor.temperature_fd = -1;
    signal(SIGINT, sigint_handler);
    exit(EXIT_SUCCESS);
}

int i2c_open(const char *dev) {
    int fd;
    if ((fd = open(dev, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return -1;
    }
    return fd;
}

int i2c_read(I2C_SMBUS_BYTE_DATA *buf, int addr, int size, int fd) {
    int err;
    if ((err = ioctl(fd, I2C_SMBUS_READ, buf)) < 0) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return err;
}

int i2c_write(I2C_SMBUS_BYTE_DATA *buf, int addr, int size, int fd) {
    int err;
    if ((err = ioctl(fd, I2C_SMBUS_WRITE, buf)) < 0) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return err;
}

int i2c_close(int fd) {
    if (close(fd) < 0) {
        perror("Failed to close I2C device");
        return -1;
    }
    return 0;
}

int i2c_init_sensor(ICP10110Sensor *sensor, int i2c_fd) {
    ICP10110Data data;
    data.pressure = 0x00;
    data.temperature = 0x00;
    if (i2c_write(&data, ICP10110_ADDR, 2, i2c_fd) < 0) {
        return -1;
    }
    if (i2c_read(&data, ICP10110_ADDR, 2, i2c_fd) < 0) {
        return -1;
    }
    if (data.pressure != 0x00 || data.temperature != 0x00) {
        return -1;
    }
    sensor->i2c_fd = i2c_fd;
    return 0;
}

int i2c_read_pressure(ICP10110Sensor *sensor) {
    ICP10110Data data;
    if (i2c_read(&data, ICP10110_ADDR, 1, sensor->i2c_fd) < 0) {
        return -1;
    }
    return data.pressure;
}

int i2c_read_temperature(ICP10110Sensor *sensor) {
    ICP10110Data data;
    if (i2c_read(&data, ICP10110_ADDR, 1, sensor->i2c_fd) < 0) {
        return -1;
    }
    return data.temperature;
}

int main() {
    ICP10110Sensor sensor;
    int i2c_fd = i2c_open("/dev/i2c-1");
    if (i2c_fd < 0) {
        return EXIT_FAILURE;
    }
    if (i2c_init_sensor(&sensor, i2c_fd) < 0) {
        return EXIT_FAILURE;
    }
    signal(SIGINT, sigint_handler);
    FILE *file = fopen("environmental_data.txt", "a");
    if (!file) {
        perror("Failed to open environmental_data.txt");
        return EXIT_FAILURE;
    }
    char buffer[128];
    struct tm *timeinfo;
    time_t rawtime;
    while (1) {
        rawtime = time(NULL);
        timeinfo = localtime(&rawtime);
        strftime(buffer, 128, "%Y-%m-%d %H:%M:%S", timeinfo);
        fprintf(file, "%s ", buffer);
        int pressure = i2c_read_pressure(&sensor);
        if (pressure < 0) {
            fprintf(stderr, "Error reading pressure\n");
            continue;
        }
        int temperature = i2c_read_temperature(&sensor);
        if (temperature < 0) {
            fprintf(stderr, "Error reading temperature\n");
            continue;
        }
        fprintf(file, "%d %d\n", pressure, temperature);
        fprintf(stdout, "%s %d %d\n", buffer, pressure, temperature);
        usleep(10000); // 10 ms delay
    }
    fclose(file);
    i2c_close(sensor.i2c_fd);
    return EXIT_SUCCESS;
}

