        return;
    }

    // Calculate temperature and humidity
    int temperature = (buffer[SHT40_TEMPERATURE_OFFSET] << 8) | buffer[SHT40_TEMPERATURE_OFFSET + 1];
    temperature = (temperature * SHT40_TEMPERATURE_SCALE) >> 8;
    temperature += SHT40_TEMPERATURE_OFFSET;

    int humidity = (buffer[SHT40_HUMIDITY_OFFSET] << 8) | buffer[SHT40_HUMIDITY_OFFSET + 1];
    humidity = (humidity * SHT40_HUMIDITY_SCALE) >> 8;
    humidity += SHT40_HUMIDITY_OFFSET;

    humidity = (humidity * 100) / 1024;

    // Clamp humidity to 0-100%
    if (humidity < 0) humidity = 0;
    if (humidity > 100) humidity = 100;

    // Convert to float
    float temp = (float)temperature / 100.0f;
    float humidity_f = (float)humidity / 100.0f;

    // Print to stdout
    printf("%.1f,%.1f\n", temp, humidity_f);
}

void handle_i2c_error(I2CContext *ctx) {
    if (ctx->retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to read SHT40 measurement result after %d retries\n", ctx->retries);
        exit(EXIT_FAILURE);
    }
}

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        // Cleanly exit
        gpiod_device_destroy(ctx->device);
        gpiod_release_resources(ctx->device);
        close(ctx->fd);
        exit(EXIT_SUCCESS);
    }
}

int main() {
    I2CContext ctx;
    ctx.fd = open(I2C_DEVICE, O_RDWR);
    if (ctx.fd < 0) {
        perror("open I2C_DEVICE");
        return EXIT_FAILURE;
    }

    ctx.device = gpiod_device_new();
    if (ctx.device == NULL) {
        perror("gpiod_device_new");
        close(ctx->fd);
        return EXIT_FAILURE;
    }

    if (gpiod_device_add_device(ctx.device, ctx.fd) < 0) {
        perror("gpiod_device_add_device");
        gpiod_device_destroy(ctx.device);
        gpiod_release_resources(ctx.device);
        close(ctx->fd);
        return EXIT_FAILURE;
    }

    struct sockaddr_in server;
    int server_fd, client_fd, bytes_sent;
    socklen_t client_len = sizeof(client);
    server.sin_family = AF_INET;
    server.sin_addr.s_addr = INADDR_ANY;
    server.sin_port = htons(8080);

    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        perror("socket");
        close(ctx->fd);
        gpiod_device_destroy(ctx->device);
        gpiod_release_resources(ctx->device);
        return EXIT_FAILURE;
    }

    if (bind(server_fd, (struct sockaddr *)&server, sizeof(server)) < 0) {
        perror("bind");
        close(server_fd);
        close(ctx->fd);
        gpiod_device_destroy(ctx->device);
        gpiod_release_resources(ctx->device);
        return EXIT_FAILURE;
    }

    if (listen(server_fd, 3) < 0) {
        perror("listen");
        close(server_fd);
        close(ctx->fd);
        gpiod_device_destroy(ctx->device);
        gpiod_release_resources(ctx->device);
        return EXIT_FAILURE;
    }

    while (1) {
        if (ctx.retries == MAX_RETRIES) {
            handle_i2c_error(&ctx);
        }

        i2c_read(&ctx, ctx.buffer);

        // Create HTTP request
        char request[1024];
        snprintf(request, sizeof(request), "GET / HTTP/1.1\r\nHost: localhost:8080\r\nConnection: close\r\n\r\n");

        // Send HTTP request
        if ((client_fd = accept(server_fd, (struct sockaddr *)&client, &client_len)) < 0) {
            perror("accept");
            continue;
        }

        if (write(client_fd, request, strlen(request)) < 0) {
            perror("write");
            close(client_fd);
            continue;
        }

        // Read response
        char response[1024];
        ssize_t bytes_received;
        while ((bytes_received = read(client_fd, response, sizeof(response))) > 0) {
            if (write(STDOUT_FILENO, response, bytes_received) < 0) {
                perror("write");
                close(client_fd);
                continue;
            }
        }

        if (bytes_received < 0) {
            perror("read");
            close(client_fd);
            continue;
        }

        // Close client socket
        close(client_fd);
    }

    // Cleanly exit
    gpiod_device_destroy(ctx.device);
    gpiod_release_resources(ctx.device);
    close(ctx->fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <string.h>
#include <signal.h>
#include <sys/i2c.h>
#include <stdbool.h>

#define I2C_BUS 1
#define I2C_ADDR 0x40
#define TMP102_REG_TEMP 0x00
#define TMP102_REG_CONFIG 0x01

typedef struct {
    int fd;
    bool initialized;
    bool i2c_initialized;
} I2CHandle;

static I2CHandle i2c_handle;

static void i2c_init() {
    i2c_handle.fd = -1;
    i2c_handle.initialized = false;
    i2c_handle.i2c_initialized = false;

    if (i2c_handle.fd = open("/dev/i2c-" I2C_BUS, O_RDWR)) {
        if (ioctl(i2c_handle.fd, I2C_SLAVE, I2C_ADDR) == 0) {
            i2c_handle.initialized = true;
            i2c_handle.i2c_initialized = true;
        } else {
            fprintf(stderr, "Failed to set slave address: %d\n", errno);
        }
    } else {
        fprintf(stderr, "Failed to open i2c bus: %d\n", errno);
    }
}

static void i2c_close() {
    if (i2c_handle.initialized && i2c_handle.i2c_initialized) {
        close(i2c_handle.fd);
        i2c_handle.initialized = false;
        i2c_handle.i2c_initialized = false;
    }
}

static ssize_t i2c_read(uint8_t *buf, size_t len) {
    ssize_t ret = 0;
    if (i2c_handle.initialized && i2c_handle.i2c_initialized) {
        ret = read(i2c_handle.fd, buf, len);
        if (ret == -1) {
            fprintf(stderr, "Failed to read from i2c bus: %d\n", errno);
        }
    }
    return ret;
}

static ssize_t i2c_write(uint8_t *buf, size_t len) {
    ssize_t ret = 0;
    if (i2c_handle.initialized && i2c_handle.i2c_initialized) {
        ret = write(i2c_handle.fd, buf, len);
        if (ret == -1) {
            fprintf(stderr, "Failed to write to i2c bus: %d\n", errno);
        }
    }
    return ret;
}

static int32_t i2c_read_temp() {
    uint8_t buf[2];
    int32_t temp = 0;
    if (i2c_handle.initialized && i2c_handle.i2c_initialized) {
        if (i2c_read(buf, 2) == 2) {
            temp = (buf[0] << 8) | buf[1];
            temp = (temp - 0x8000) * 0.01;
        }
    }
    return temp;
}

static void sigint_handler(int signum) {
    i2c_close();
    if (i2c_handle.fd != -1) {
        close(i2c_handle.fd);
    }
    exit(EXIT_SUCCESS);
}

int main() {
    i2c_init();
    signal(SIGINT, sigint_handler);

    FILE *fp = fopen("temperature_log.csv", "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file: %d\n", errno);
        return EXIT_FAILURE;
    }

    while (1) {
        int32_t temp = i2c_read_temp();
        if (temp == -1) {
            fprintf(stderr, "Failed to read temperature: %d\n", errno);
            continue;
        }

        char timestamp[20];
        struct tm *now = gmtime(&time(NULL));
        strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", now);

        fprintf(fp, "%s,%f\n", timestamp, temp);

        if (ferror(fp)) {
            fprintf(stderr, "Failed to write to log file: %d\n", errno);
            fclose(fp);
            fp = NULL;
        }

        sleep(5);
    }

    fclose(fp);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>
#include <string.h>

#define I2C_BUS 1
#define I2C_ADDR 0x76
#define MEASUREMENT_CONFIG 0x00
#define MEASUREMENT_RESULT 0x01
#define MEASUREMENT_CONFIG_BIT0 0x01

volatile sig_atomic_t shutdown = 0;

void handle_sigint(int signum) {
    shutdown = 1;
}

int main() {
    struct i2c_msg messages[1];
    struct i2c_rdwr_ioctl_msg ioctl_msg;
    int i2c_fd;
    int result;
    int retries = 0;
    int timeout = 500000; // 500ms in microseconds
    int measurement_count = 0;
    int measurement_result;
    int temperature;
    int humidity;
    int config_result;
    int i;

    // Set up signal handler for Ctrl+C
    signal(SIGINT, handle_sigint);

    // Open I2C bus
    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        return 1;
    }

    // Initialize messages
    messages[0].addr = I2C_ADDR;
    messages[0].flags = I2C_M_RD;
    messages[0].data[0] = MEASUREMENT_CONFIG;
    messages[0].len = 1;

    while (!shutdown) {
        // Send measurement configuration
        result = ioctl(i2c_fd, I2C_RDWR, messages, &ioctl_msg);
        if (result < 0) {
            perror("Failed to send measurement configuration");
            continue;
        }

        // Read measurement result
        messages[0].addr = I2C_ADDR;
        messages[0].flags = I2C_M_RD;
        messages[0].data[0] = MEASUREMENT_RESULT;
        messages[0].len = 1;
        result = ioctl(i2c_fd, I2C_RDWR, messages, &ioctl_msg);
        if (result < 0) {
            perror("Failed to read measurement result");
            continue;
        }

        // Check if measurement result is valid
        measurement_result = messages[0].data[0];
        if (measurement_result == 0) {
            // Read temperature and humidity
            messages[0].addr = I2C_ADDR;
            messages[0].flags = I2C_M_RD;
            messages[0].data[0] = 0x00;
            messages[0].len = 1;
            result = ioctl(i2c_fd, I2C_RDWR, messages, &ioctl_msg);
            if (result < 0) {
                perror("Failed to read temperature and humidity");
                continue;
            }

            temperature = messages[0].data[0];
            humidity = messages[0].data[1];

            // Output readings
            printf("Temperature: %d.%02d C, Humidity: %d.%02d%%\n", temperature / 10, temperature % 10, humidity / 10, humidity % 10);
            measurement_count++;

            // Check for timeout
            if (measurement_count % 5 == 0) {
                sleep(5);
            }
        } else {
            // NAK or other error
            printf("NAK or other error\n");
        }

        // Check for missing sensor
        if (measurement_result == 0x00) {
            printf("Missing sensor\n");
        }

        // Check for bus errors
        if (result < 0) {
            printf("Bus error\n");
        }

        // Retry I2C failures
        if (retries < 3) {
            retries++;
            continue;
        } else {
            shutdown = 1;
        }
    }

    // Close I2C bus
    close(i2c_fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#include "sensirion_i2c.h"

#define I2C_BUS 1
#define I2C_ADDR 0x60
#define I2C_TIMEOUT 100
#define I2C_DELAY 45
#define I2C_READ_SIZE 6
#define I2C_WRITE_SIZE 2

#define CRC8_POLY 0x07
#define CRC8_INIT 0x00

#define PRESSURE_OFFSET 0x00
#define TEMPERATURE_OFFSET 0x02

#define PRESSURE_SIZE 2
#define TEMPERATURE_SIZE 2

#define PRESSURE_REG 0x00
#define TEMPERATURE_REG 0x02

#define LOG_FILE "sensirion_log.txt"

void handle_sigint(int signum) {
    if (i2c_handle) {
        i2c_close(i2c_handle);
    }
    i2c_cleanup();
    exit(EXIT_SUCCESS);
}

int main() {
    struct i2c_msg messages[1];
    struct i2c_rdma_request request;
    struct i2c_rdma_handle handle;
    int i2c_fd;
    int status;
    int pressure[2];
    int temperature[2];
    int crc8;
    int log_fd;
    char log_buffer[256];
    char *log_file_path = LOG_FILE;
    int log_file_status;

    signal(SIGINT, handle_sigint);

    i2c_handle = i2c_open(I2C_BUS, I2C_ADDR, I2C_TIMEOUT);
    if (i2c_handle == -1) {
        perror("i2c_open");
        exit(EXIT_FAILURE);
    }

    if (i2c_ioctl(i2c_handle, I2C_RDWR, messages, 1, &request, &handle) < 0) {
        perror("i2c_ioctl");
        i2c_close(i2c_handle);
        exit(EXIT_FAILURE);
    }

    log_fd = open(log_file_path, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd == -1) {
        perror("open");
        i2c_close(i2c_handle);
        exit(EXIT_FAILURE);
    }

    while (1) {
        messages[0].addr = I2C_ADDR;
        messages[0].flags = I2C_M_RD;
        messages[0].buf = (unsigned char *)pressure;
        messages[0].len = I2C_READ_SIZE;

        status = i2c_read(i2c_handle, messages, 1, &request, &handle);
        if (status < 0) {
            perror("i2c_read");
            i2c_close(i2c_handle);
            close(log_fd);
            exit(EXIT_FAILURE);
        }

        messages[0].addr = I2C_ADDR;
        messages[0].flags = I2C_M_RD;
        messages[0].buf = (unsigned char *)temperature;
        messages[0].len = I2C_READ_SIZE;

        status = i2c_read(i2c_handle, messages, 1, &request, &handle);
        if (status < 0) {
            perror("i2c_read");
            i2c_close(i2c_handle);
            close(log_fd);
            exit(EXIT_FAILURE);
        }

        crc8 = messages[0].buf[0];
        crc8 = messages[0].buf[1];
        crc8 = messages[0].buf[3];
        crc8 = messages[0].buf[4];

        if (crc8 != crc8_calculate(messages[0].buf, I2C_READ_SIZE, CRC8_POLY, CRC8_INIT)) {
            fprintf(stderr, "CRC8 mismatch\n");
            continue;
        }

        fprintf(stderr, "Pressure: %d %d\n", pressure[0], pressure[1]);
        fprintf(stderr, "Temperature: %d %d\n", temperature[0], temperature[1]);

        snprintf(log_buffer, sizeof(log_buffer), "%d %d %d %d\n", pressure[0], pressure[1], temperature[0], temperature[1]);
        write(log_fd, log_buffer, strlen(log_buffer));

        usleep(I2C_DELAY * 1000);
        usleep(500 * 1000);
    }

    close(log_fd);
    i2c_close(i2c_handle);
    i2c_cleanup();
    exit(EXIT_SUCCESS);
}

int crc8_calculate(unsigned char *buf, int len, int poly, int init) {
    unsigned char crc = init;
    for (int i = 0; i < len; i++) {
        crc ^= buf[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x01) {
                crc = (crc >> 1) ^ poly;
            } else {
                crc = crc >> 1;
            }
        }
    }
    return crc;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <sys/time.h>
#include <signal.h>
#include <w1-therm.h>
#include <w1-therm-1-w-gpio.h>

#define DS18B20_PIN "/sys/bus/w1/devices/28-00000..."
#define DS18B20_FILE "/sys/bus/w1/devices/28-00000..."
#define RELAY_PIN 17
#define PWM_PIN 18
#define LOG_FILE "greenhouse.log"

#define MAX_READS 10
#define LOG_INTERVAL 5

typedef struct {
    double setpoint;
    double Kp;
    double Ki;
    double Kd;
} PIDParameters;

typedef struct {
    double temperature;
    double pidOutput;
    double pwmDuty;
    int relayState;
} SensorData;

static int fd;
static int logFd;
static PIDParameters pidParams;
static SensorData sensorData;
static int sensorPresent = 0;
static int sensorAbsent = 0;
static int busError = 0;

static void handleSignal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        if (fd > 0) {
            close(fd);
        }
        if (logFd > 0) {
            close(logFd);
        }
        if (sensorData.relayState == 1) {
            digitalWrite(RELAY_PIN, 0);
        }
        if (sensorData.pwmDuty > 0) {
            pwmWrite(PWM_PIN, 0);
        }
        exit(EXIT_SUCCESS);
    }
}

static int readSensor() {
    char filename[128];
    snprintf(filename, sizeof(filename), "%s/w1_slave", DS18B20_FILE);
    int fd = open(filename, O_RDONLY);
    if (fd < 0) {
        busError = 1;
        return -1;
    }
    char buffer[128];
    read(fd, buffer, 128);
    close(fd);
    if (sscanf(buffer, "t=%lf", &sensorData.temperature) < 1) {
        busError = 1;
        return -1;
    }
    if (busError) {
        busError = 0;
        return -1;
    }
    char crcBuffer[3];
    int i;
    for (i = 0; i < 2; i++) {
        crcBuffer[i] = buffer[17 + 2 * i];
    }
    int crc = 0;
    for (i = 0; i < 2; i++) {
        crc ^= crcBuffer[i];
        crc = (crc << 2) | (crc >> 6);
    }
    if (crc != (buffer[17] - '0' + (buffer[18] - '0') * 10)) {
        busError = 1;
        return -1;
    }
    sensorPresent = 1;
    return 0;
}

static void initPID() {
    pidParams.setpoint = atoi(argv[1]);
    pidParams.Kp = atof(argv[2]);
    pidParams.Ki = atof(argv[3]);
    pidParams.Kd = atof(argv[4]);
}

static double computePID() {
    double error = sensorData.temperature - pidParams.setpoint;
    double pidOutput = pidParams.Kp * error + pidParams.Ki * error * sensorData.temperature + pidParams.Kd * error * fabs(error);
    return pidOutput;
}

static void setPWM(int dutyCycle) {
    if (dutyCycle > 100) {
        dutyCycle = 100;
    } else if (dutyCycle < 0) {
        dutyCycle = 0;
    }
    if (dutyCycle > 0) {
        pwmWrite(PWM_PIN, dutyCycle);
    } else {
        pwmWrite(PWM_PIN, 0);
    }
}

static void setRelay(int state) {
    digitalWrite(RELAY_PIN, state);
}

static void logData() {
    char timestamp[128];
    struct timeval tv;
    gettimeofday(&tv, NULL);
    snprintf(timestamp, sizeof(timestamp), "%ld.%06ld %lf %lf %lf %lf",
             (long)tv.tv_sec, (long)tv.tv_usec / 1000000.0, sensorData.temperature, pidParams.setpoint, sensorData.pidOutput, sensorData.pwmDuty);
    if (logFd > 0) {
        write(logFd, timestamp, strlen(timestamp));
    }
}

static void initGPIO() {
    fd = open("/dev/gpiod", O_RDWR);
    if (fd < 0) {
        perror("Failed to open gpiod");
        exit(EXIT_FAILURE);
    }
    struct gpiod_chip *chip = gpiod_chip_new(fd);
    if (!chip) {
        perror("Failed to create gpiod chip");
        exit(EXIT_FAILURE);
    }
    struct gpiod_line *line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!line) {
        perror("Failed to get relay line");
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_export(line) < 0) {
        perror("Failed to export relay line");
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_set_mode(line, GPIOD_MODE_OUTPUT) < 0) {
        perror("Failed to set relay mode");
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_set_value(line, 0) < 0) {
        perror("Failed to set relay value");
        exit(EXIT_FAILURE);
    }
    line = gpiod_chip_get_line(chip, PWM_PIN);
    if (!line) {
        perror("Failed to get pwm line");
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_export(line) < 0) {
        perror("Failed to export pwm line");
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_set_mode(line, GPIOD_MODE_PWM) < 0) {
        perror("Failed to set pwm mode");
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_set_pwm(line, 0) < 0) {
        perror("Failed to set pwm value");
        exit(EXIT_FAILURE);
    }
    if (gpiod_chip_close(chip) < 0) {
        perror("Failed to close gpiod chip");
        exit(EXIT_FAILURE);
    }
}

static void cleanupGPIO() {
    if (fd > 0) {
        close(fd);
    }
    if (sensorData.relayState == 1) {
        digitalWrite(RELAY_PIN, 0);
    }
    if (sensorData.pwmDuty > 0) {
        pwmWrite(PWM_PIN, 0);
    }
}

static int main(int argc, char *argv[]) {
    if (argc < 5) {
        fprintf(stderr, "Usage: %s <setpoint> <Kp> <Ki> <Kd>\n", argv[0]);
        exit(EXIT_FAILURE);
    }
    initGPIO();
    initPID();
    signal(SIGINT, handleSignal);
    signal(SIGTERM, handleSignal);
    logFd = open(LOG_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (logFd < 0) {
        perror("Failed to open log file");
        cleanupGPIO();
        exit(EXIT_FAILURE);
    }
    while (1) {
        if (readSensor()) {
            sensorAbsent = 1;
        } else {
            sensorAbsent = 0;
        }
        if (sensorAbsent) {
            logData();
            continue;
        }
        sensorData.pidOutput = computePID();
        sensorData.pwmDuty = 100 * (sensorData.pidOutput / 100);
        sensorData.relayState = 1;
        logData();
        usleep(500000);
    }
    cleanupGPIO();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <wiringPi.h>

#define I2C_FILE "/dev/i2c-1"
#define AHT20_ADDR 0x5C
#define AHT20_MEASUREMENT 0x00
#define AHT20_STATUS 0x01
#define AHT20_CALIBRATED 0x01
#define AHT20_BUSY 0x02
#define AHT20_TIMEOUT 100
#define AHT20_RETRY 3
#define AHT20_PAUSE 10
#define AHT20_INTERVAL 5000
#define GPIO17 17

void handleSig(int signum) {
    if (wiringPiStatus() == WIRINGPI_OK) {
        digitalWrite(GPIO17, 0);
    }
    close(i2cFile);
    exit(0);
}

int main() {
    struct i2c_msg messages[3];
    struct i2c_rdwr_ioctl_msg ioctl_msg;
    int retries = 0;
    int status;
    char buffer[6];
    char timestamp[20];
    char humidity[10];
    char error[100];
    int i2cFd;
    int humidityValue;
    int humidityExceeds;
    int humidityFallsBelow;
    int gpio17Status;

    wiringPiSetupGpio();
    signal(SIGINT, handleSig);
    signal(SIGTERM, handleSig);

    i2cFd = open(I2C_FILE, O_RDWR);
    if (i2cFd < 0) {
        snprintf(error, sizeof(error), "Failed to open I2C device at %s", I2C_FILE);
        perror(error);
        return 1;
    }

    if (ioctl(i2cFd, I2C_SLAVE, AHT20_ADDR) < 0) {
        snprintf(error, sizeof(error), "Failed to set I2C slave address to 0x%02X", AHT20_ADDR);
        perror(error);
        return 1;
    }

    while (1) {
        for (retries = 0; retries < AHT20_RETRY; retries++) {
            messages[0].addr = AHT20_ADDR;
            messages[0].flags = I2C_M_RD;
            messages[0].data[0] = AHT20_MEASUREMENT;
            messages[1].addr = AHT20_ADDR;
            messages[1].flags = I2C_M_RD;
            messages[1].data[0] = AHT20_STATUS;
            messages[2].addr = AHT20_ADDR;
            messages[2].flags = I2C_M_RD;
            messages[2].data[0] = 0;

            if (ioctl(i2cFd, I2C_RDWR, messages, &ioctl_msg) < 0) {
                snprintf(error, sizeof(error), "Failed to read I2C device at 0x%02X", AHT20_ADDR);
                perror(error);
                if (retries < AHT20_RETRY - 1) {
                    usleep(AHT20_PAUSE * 1000);
                }
                continue;
            }

            if (messages[1].data[0] == AHT20_CALIBRATED && messages[1].data[0] != AHT20_BUSY) {
                if (messages[0].data[0] == 0x00) {
                    if (read(i2cFd, buffer, 6) < 0) {
                        snprintf(error, sizeof(error), "Failed to read I2C device at 0x%02X", AHT20_ADDR);
                        perror(error);
                        if (retries < AHT20_RETRY - 1) {
                            usleep(AHT20_PAUSE * 1000);
                        }
                        continue;
                    }

                    humidityValue = (buffer[0] << 8) | buffer[1];
                    humidityValue |= (buffer[2] << 4) | (buffer[3] >> 4);
                    humidityValue |= (buffer[4] << 2) | (buffer[5] >> 2);

                    snprintf(timestamp, sizeof(timestamp), "%ld", time(NULL));
                    snprintf(humidity, sizeof(humidity), "%.2f", (float)humidityValue / 10.0);

                    if (humidityValue > 6000) {
                        humidityValue = 6000;
                    }

                    if (humidityValue > 6000) {
                        humidityExceeds = 1;
                    } else {
                        humidityExceeds = 0;
                    }

                    if (humidityValue < 5500) {
                        humidityFallsBelow = 1;
                    } else {
                        humidityFallsBelow = 0;
                    }

                    if (humidityExceeds) {
                        digitalWrite(GPIO17, 1);
                    } else if (humidityFallsBelow) {
                        digitalWrite(GPIO17, 0);
                    }

                    printf("%s %s %s\n", timestamp, humidity, "Dehumidifier: " GPIO17Status);
                } else {
                    snprintf(error, sizeof(error), "I2C device at 0x%02X is busy", AHT20_ADDR);
                    perror(error);
                    if (retries < AHT20_RETRY - 1) {
                        usleep(AHT20_PAUSE * 1000);
                    }
                }
            } else {
                snprintf(error, sizeof(error), "I2C device at 0x%02X is not calibrated", AHT20_ADDR);
                perror(error);
                if (retries < AHT20_RETRY - 1) {
                    usleep(AHT20_PAUSE * 1000);
                }
            }
        }

        if (retries == AHT20_RETRY) {
            snprintf(error, sizeof(error), "Failed to read I2C device at 0x%02X after %d retries", AHT20_ADDR, AHT20_RETRY);
            perror(error);
        }

        if (humidityExceeds) {
            gpio17Status = 1;
        } else if (humidityFallsBelow) {
            gpio17Status = 0;
        } else {
            gpio17Status = 0;
        }

        printf("%s %s %s\n", timestamp, humidity, "Dehumidifier: " GPIO17Status);
    }

    return 0;
}

