#include <linux/joystick.h>
#include <linux/pwm.h>
#include <linux/pigpio.h>

#define PWM_CHANNEL_RED 1
#define PWM_CHANNEL_GREEN 2
#define PWM_CHANNEL_BLUE 3

#define LED_OFF 0
#define LED_ON 1

#define PWM_MAX 255

int pwm_fd;

void handle_sigint(int signum) {
    printf("SIGINT received, turning off LED\n");
    pwm_set_mode(pwm_fd, PWM_OUTPUT, LED_OFF);
    pwm_set_duty_cycle(pwm_fd, PWM_CHANNEL_RED, 0);
    pwm_set_duty_cycle(pwm_fd, PWM_CHANNEL_GREEN, 0);
    pwm_set_duty_cycle(pwm_fd, PWM_CHANNEL_BLUE, 0);
    pigpio_write(pwm_fd, 0, 0, 0);
    exit(0);
}

void handle_sigterm(int signum) {
    printf("SIGTERM received, turning off LED\n");
    pwm_set_mode(pwm_fd, PWM_OUTPUT, LED_OFF);
    pwm_set_duty_cycle(pwm_fd, PWM_CHANNEL_RED, 0);
    pwm_set_duty_cycle(pwm_fd, PWM_CHANNEL_GREEN, 0);
    pwm_set_duty_cycle(pwm_fd, PWM_CHANNEL_BLUE, 0);
    pigpio_write(pwm_fd, 0, 0, 0);
    exit(0);
}

