void handle_signal(int signum) {
    sigint_received = 1;
    gpiod_channel_t channel;
    gpiod_line_t line;
    gpiod_edge_t edge;
    gpiod_pull_direction_t pull_dir;
    gpiod_value_t value;
    gpiod_ctrl_t ctrl;

    gpiod_error_t err = gpiod_open("/dev/gpiod", &channel);
    if (err) {
        perror("gpiod_open");
        exit(EXIT_FAILURE);
    }

    gpiod_line_list_t lines;
    err = gpiod_get_lines(channel, &lines);
    if (err) {
        perror("gpiod_get_lines");
        gpiod_close(channel);
        exit(EXIT_FAILURE);
    }

    for (gpiod_line_t *line = lines->elts; line; line = line->next) {
        if (line->number == GPIO17 || line->number == GPIO18 || line->number == GPIO27) {
            err = gpiod_get_line(channel, line, &line);
            if (err) {
                perror("gpiod_get_line");
                gpiod_close(channel);
                exit(EXIT_FAILURE);
            }

            err = gpiod_get_ctrl(line, &ctrl);
            if (err) {
                perror("gpiod_get_ctrl");
                gpiod_close(channel);
                exit(EXIT_FAILURE);
            }

            ctrl->value = PWM_RANGE * PWM_INVERTED;
            err = gpiod_set_ctrl(line, &ctrl);
            if (err) {
                perror("gpiod_set_ctrl");
                gpiod_close(channel);
                exit(EXIT_FAILURE);
            }

            err = gpiod_set_edge(line, &edge);
            if (err) {
                perror("gpiod_set_edge");
                gpiod_close(channel);
                exit(EXIT_FAILURE);
            }

            err = gpiod_set_pull_direction(line, &pull_dir);
            if (err) {
                perror("gpiod_set_pull_direction");
                gpiod_close(channel);
                exit(EXIT_FAILURE);
            }

            err = gpiod_set_value(line, &value);
            if (err) {
                perror("gpiod_set_value");
                gpiod_close(channel);
                exit(EXIT_FAILURE);
            }

            err = gpiod_close(channel);
            if (err) {
                perror("gpiod_close");
                exit(EXIT_FAILURE);
            }

            break;
        }
    }

    err = gpiod_close(channel);
    if (err) {
        perror("gpiod_close");
        exit(EXIT_FAILURE);
    }

    err = gpiod_close(lines);
    if (err) {
        perror("gpiod_close");
        exit(EXIT_FAILURE);
    }

    gpiod_line_list_free(lines);
    if (err) {
        perror("gpiod_line_list_free");
        exit(EXIT_FAILURE);
