#include <sys/ioctl.h>
#include <gpiod.h>
#include <syslog.h>
#include <json/json.h>

#define DHT22_PIN 4
#define DHT22_TIMEOUT 1000  // 1 ms
#define DHT22_RETRY_ATTEMPTS 3
#define DHT22_RETRY_DELAY 500  // 0.5 s

typedef struct {
    int sock;
    struct sockaddr_in server_addr;
    char *server_url;
    int retries_left;
    int last_error;
} DHT22Client;

static void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        if (dht_client.sock > 0) {
            close(dht_client.sock);
        }
        gpiod_device_destroy(dht_device);
        gpiod_release_device(dht_device);
        exit(EXIT_SUCCESS);
    }
}

static int dht22_read_data(int pin) {
    int fd = -1;
    int data[40];
    int checksum = 0;
    int i;

    fd = open("/dev/spi0.0", O_RDWR);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open SPI device");
        return -1;
    }

    // Set SPI mode to 0 (8-bit, 800 kHz)
    if (ioctl(fd, SPI_SET_MODE, 0) < 0) {
        syslog(LOG_ERR, "Failed to set SPI mode");
        close(fd);
        return -1;
    }

    // Set SPI speed to 800 kHz
    if (ioctl(fd, SPI_SET_SPEED, 8000000) < 0) {
        syslog(LOG_ERR, "Failed to set SPI speed");
        close(fd);
        return -1;
    }

    // Set SPI data mode to 0 (MSB first)
    if (ioctl(fd, SPI_SET_DATA_MODE, 0) < 0) {
        syslog(LOG_ERR, "Failed to set SPI data mode");
        close(fd);
        return -1;
    }

    // Set SPI bus to pin 4
    if (ioctl(fd, SPI_SET_CS, pin) < 0) {
        syslog(LOG_ERR, "Failed to set SPI bus to pin %d", pin);
        close(fd);
        return -1;
    }

    // Pull the line low for at least 1 ms
    if (write(fd, &0, 1) < 0) {
        syslog(LOG_ERR, "Failed to pull line low");
        close(fd);
        return -1;
    }

    usleep(DHT22_TIMEOUT);

    // Capture the full 40-bit response
    for (i = 0; i < 40; i++) {
        if (read(fd, &data[i], 1) < 0) {
            syslog(LOG_ERR, "Failed to read data");
            close(fd);
            return -1;
        }
    }

    // Calculate the checksum
    for (i = 0; i < 40; i += 2) {
        checksum += data[i] << 8 | data[i + 1];
    }

    // Validate the checksum
    if (checksum != data[40] << 8 | data[41]) {
        syslog(LOG_ERR, "Checksum mismatch");
        close(fd);
        return -1;
    }

    // Return the temperature and humidity values
    return (int)(data[0] << 8 | data[1]) / 10.0;
}

static void dht22_client_init(DHT22Client *client, const char *server_url) {
    int sock;
    struct sockaddr_in server_addr;
    struct json_object *json;

    client->server_url = server_url;
    client->retries_left = DHT22_RETRY_ATTEMPTS;
    client->last_error = 0;

    // Create a socket
    sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        client->last_error = errno;
        return;
    }

    // Set the server address
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(80);
    inet_pton(AF_INET, server_url, &server_addr.sin_addr);

    // Connect to the server
    if (connect(sock, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        client->last_error = errno;
        return;
    }

    client->sock = sock;
}

static void dht22_client_post(DHT22Client *client, int temperature, int humidity) {
    struct json_object *json;
    char *json_str;

    // Create a JSON object
    json = json_object_new_object();
    json_object_set_string_field(json, "temperature", json_number_string(temperature));
    json_object_set_string_field(json, "humidity", json_number_string(humidity));

    // Convert the JSON object to a string
    json_str = json_object_to_json_string(json);
    if (json_str == NULL) {
        client->last_error = errno;
        return;
    }

    // Send the JSON payload
    if (write(client->sock, json_str, strlen(json_str)) < 0) {
        client->last_error = errno;
        return;
    }

    // Free the JSON string
    free(json_str);
    json_object_clear(json);
}

static void dht22_client_cleanup(DHT22Client *client) {
    if (client->sock > 0) {
        close(client->sock);
    }
}

static void dht22_client_loop(DHT22Client *client) {
    int temperature;
    int humidity;
    int retry = 0;

    while (client->retries_left > 0) {
        temperature = dht22_read_data(DHT22_PIN);
        if (temperature == -1) {
            client->retries_left--;
            continue;
        }

        humidity = dht22_read_data(DHT22_PIN);
        if (humidity == -1) {
            client->retries_left--;
            continue;
        }

        dht22_client_post(client, temperature, humidity);
        client->retries_left = 0;
        break;
    }

    if (client->retries_left > 0) {
        client->last_error = ENOENT;
    }
}

