#define DHT22_PIN 4
#define DHT22_TIMEOUT 1000000  // 1ms
#define DHT22_RESPONSE_TIMEOUT 40000000  // 40µs
#define DHT22_RETRY_ATTEMPTS 3
#define DHT22_RETRY_BACKOFF 2000000  // 2s
#define DHT22_RESPONSE_SIZE 40
#define DHT22_CHECKSUM_SIZE 8
#define DHT22_RESPONSE_START 0x40
#define DHT22_RESPONSE_END 0x40 + DHT22_RESPONSE_SIZE - 1
#define DHT22_CHECKSUM_START 0x40 + DHT22_RESPONSE_SIZE
#define DHT22_CHECKSUM_END 0x40 + DHT22_RESPONSE_SIZE + DHT22_CHECKSUM_SIZE - 1

typedef struct {
    int pin;
    int direction;
    int edge;
    int edge_count;
    int edge_start;
    int edge_end;
    int edge_start_time;
    int edge_end_time;
} DHT22State;

static int dht22_pin = DHT22_PIN;
static int dht22_state = -1;
static int dht22_retry = 0;
static int dht22_response[DHT22_RESPONSE_SIZE];
static int dht22_checksum[DHT22_CHECKSUM_SIZE];
static int dht22_response_valid = 0;
static int dht22_response_valid_count = 0;
static int dht22_response_valid_start = 0;
static int dht22_response_valid_end = 0;
