static int dht22_response_valid_checksum_start = 0;
static int dht22_response_valid_checksum_end = 0;
static int dht22_response_valid_checksum_count = 0;

static int dht22_url = "http://your-library’s-API-call.com/api/humidity";
static int dht22_retry_post = 0;
static int dht22_response_code = 0;
static int dht22_response_body[DHT22_RESPONSE_SIZE];
static int dht22_response_body_valid = 0;
static int dht22_response_body_valid_count = 0;
static int dht22_response_body_valid_start = 0;
static int dht22_response_body_valid_end = 0;
static int dht22_response_body_valid_checksum = 0;
static int dht22_response_body_valid_checksum_start = 0;
static int dht22_response_body_valid_checksum_end = 0;
static int dht22_response_body_valid_checksum_count = 0;

static int dht22_init() {
    int fd = gpiod_open("/dev/gpiod");
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open gpiod device: %d", fd);
        return -1;
    }

    int pin_fd = gpiod_get_named_fd(fd, "gpio4");
    if (pin_fd < 0) {
        syslog(LOG_ERR, "Failed to get gpio4 fd: %d", pin_fd);
        gpiod_close(fd);
        return -1;
    }

    int direction = gpiod_direction_get(pin_fd);
    if (direction < 0) {
        syslog(LOG_ERR, "Failed to get gpio4 direction: %d", direction);
        gpiod_close(fd);
        return -1;
    }

    int edge = gpiod_edge_get(pin_fd);
    if (edge < 0) {
        syslog(LOG_ERR, "Failed to get gpio4 edge: %d", edge);
        gpiod_close(fd);
        return -1;
    }

    int edge_count = gpiod_edge_count(pin_fd);
    if (edge_count < 0) {
        syslog(LOG_ERR, "Failed to get gpio4 edge count: %d", edge_count);
        gpiod_close(fd);
        return -1;
    }

    DHT22State state;
    state.pin = pin_fd;
    state.direction = direction;
    state.edge = edge;
    state.edge_count = edge_count;
    state.edge_start = 0;
    state.edge_end = 0;
    state.edge_start_time = 0;
    state.edge_end_time = 0;

    dht22_state = gpiod_create_state(fd, &state);
    if (dht22_state < 0) {
        syslog(LOG_ERR, "Failed to create gpio4 state: %d", dht22_state);
        gpiod_close(fd);
        return -1;
    }

    gpiod_state_set_edge(dht22_state, DHT22_RESPONSE_START, DHT22_EDGE_RISING);
    gpiod_state_set_edge(dht22_state, DHT22_RESPONSE_END, DHT22_EDGE_FALLING);

    gpiod_state_enable(dht22_state, DHT22_RESPONSE_START);
    gpiod_state_enable(dht22_state, DHT22_RESPONSE_END);

    return 0;
}

static int dht22_read() {
    int attempts = 0;
    int response_valid = 0;
    int response_valid_count = 0;
    int response_valid_checksum = 0;
    int response_valid_checksum_count = 0;

    while (attempts < DHT22_RETRY_ATTEMPTS) {
        int pin_fd = dht22_state->pin;
        int direction = dht22_state->direction;
        int edge = dht22_state->edge;
        int edge_count = dht22_state->edge_count;

        int start_time = 0;
        int end_time = 0;

        // Set pin to low
        if (direction == DHT22_EDGE_RISING) {
            gpiod_state_set_value(dht22_state, DHT22_RESPONSE_START, 0);
        } else {
            gpiod_state_set_value(dht22_state, DHT22_RESPONSE_START, 1);
        }

        int start = 0;
        int end = 0;
        int start_time = 0;
        int end_time = 0;

        // Wait for DHT22 start signal
        while (start < DHT22_RESPONSE_START) {
            start = gpiod_state_get_value(dht22_state, DHT22_RESPONSE_START);
            if (start < 0) {
                syslog(LOG_ERR, "Failed to get gpio4 value: %d", start);
                return -1;
            }
            if (start == DHT22_RESPONSE_START) {
                start_time = gpiod_state_get_time(dht22_state, DHT22_RESPONSE_START);
                break;
            }
            usleep(DHT22_TIMEOUT);
        }

        if (start_time == 0) {
            syslog(LOG_ERR, "DHT22 start signal not received");
            return -1;
        }

        // Set pin to high
        gpiod_state_set_value(dht22_state, DHT22_RESPONSE_START, 1);

        // Wait for DHT22 response
        while (end < DHT22_RESPONSE_END) {
            end = gpiod_state_get_value(dht22_state, DHT22_RESPONSE_END);
            if (end < 0) {
                syslog(LOG_ERR, "Failed to get gpio4 value: %d", end);
                return -1;
            }
            if (end == DHT22_RESPONSE_END) {
                end_time = gpiod_state_get_time(dht22_state, DHT22_RESPONSE_END);
                break;
            }
            usleep(DHT22_RESPONSE_TIMEOUT);
        }

        if (end_time == 0) {
            syslog(LOG_ERR, "DHT22 response not received");
            return -1;
        }

        // Read response
        int i = 0;
        for (i = 0; i < DHT22_RESPONSE_SIZE; i++) {
            dht22_response[i] = gpiod_state_get_value(dht22_state, DHT22_RESPONSE_START + i);
            if (dht22_response[i] < 0) {
                syslog(LOG_ERR, "Failed to get gpio4 value: %d", dht22_response[i]);
                return -1;
            }
        }

        // Calculate checksum
        int checksum = 0;
        for (i = 0; i < DHT22_CHECKSUM_SIZE; i++) {
            checksum += dht22_response[DHT22_CHECKSUM_START + i];
        }
        dht22_checksum[0] = checksum & 0xFF;
        dht22_checksum[1] = checksum >> 8;

        // Validate checksum
        if (dht22_response[DHT22_RESPONSE_START + 4] == dht22_checksum[0] &&
            dht22_response[DHT22_RESPONSE_START + 5] == dht22_checksum[1]) {
            response_valid = 1;
            response_valid_count = DHT22_RESPONSE_SIZE;
            response_valid_checksum = 1;
            response_valid_checksum_count = DHT22_CHECKSUM_SIZE;
        } else {
            response_valid = 0;
        }

        if (response_valid) {
            break;
        }

        attempts++;
        usleep(DHT22_RETRY_BACKOFF);
    }

    if (attempts == DHT22_RETRY_ATTEMPTS) {
        syslog(LOG_ERR, "DHT22 read failed after %d attempts", attempts);
        return -1;
    }

    return 0;
}

static int dht22_post() {
    int attempts = 0;
    int response_code = 0;
    int response_body_valid = 0;
    int response_body_valid_count = 0;
    int response_body_valid_checksum = 0;
    int response_body_valid_checksum_count = 0;

    while (attempts < DHT22_RETRY_POST) {
        CURL *curl;
        CURLcode res;

        curl_global_init(CURL_GLOBAL_DEFAULT);
        curl = curl_easy_init();
        if(curl) {
            curl_easy_setopt(curl, CURLOPT_URL, dht22_url);
            curl_easy_setopt(curl, CURLOPT_POSTFIELDS, "{\"humidity\":");
            curl_easy_setopt(curl, CURLOPT_POSTFIELDS, dht22_response);
            curl_easy_setopt(curl, CURLOPT_POSTFIELDS, "}\n");
            curl_easy_setopt(curl, CURLOPT_HTTPHEADER, "Content-Type: application/json");
            res = curl_easy_perform(curl);
            if(res != CURLE_OK) {
                syslog(LOG_ERR, "CURL error: %s", curl_easy_strerror(res));
                curl_easy_cleanup(curl);
                break;
            }
            response_code = curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
            if (response_code < 0) {
                syslog(LOG_ERR, "Failed to get response code: %d", response_code);
                curl_easy_cleanup(curl);
                break;
            }
            if (response_code < 200 || response_code >= 300) {
                syslog(LOG_ERR, "HTTP response code: %d", response_code);
                curl_easy_cleanup(curl);
                break;
            }

            curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
            curl_easy_setopt(curl, CURLOPT_WRITEDATA, dht22_response_body);
            curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
            curl_easy_setopt(curl, CURLOPT_WRITEDATA, dht22_response_body);
            res = curl_easy_perform(curl);
            if(res != CURLE_OK) {
                syslog(LOG_ERR, "CURL error: %s", curl_easy_strerror(res));
                curl_easy_cleanup(curl);
                break;
            }
            response_body_valid = 1;
            response_body_valid_count = DHT22_RESPONSE_SIZE;
            response_body_valid_checksum = 1;
            response_body_valid_checksum_count = DHT22_CHECKSUM_SIZE;
        } else {
            syslog(LOG_ERR, "CURL initialization failed");
            break;
        }

        curl_easy_cleanup(curl);
        curl_global_cleanup();

        if (response_code >= 200 && response_code < 300) {
            break;
        }

        attempts++;
        usleep(DHT22_RETRY_BACKOFF);
    }

    if (attempts == DHT22_RETRY_POST) {
        syslog(LOG_ERR, "DHT22 post failed after %d attempts", attempts);
        return -1;
    }

    return 0;
}

static void write_callback(void *ptr, size_t size, size_t nmemb, void *userp) {
    if (size == CURLSIZEPARAM) {
        memcpy(userp, ptr, size);
    }
}

static void dht22_cleanup() {
    gpiod_state_disable(dht22_state);
    gpiod_state_free(dht22_state);
    gpiod_close(dht22_state->fd);
}

static void signal_handler(int signum) {
    dht22_cleanup();
    exit(0);
}

