void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        running = 0;
        if (fd_log > 0) {
            close(fd_log);
        }
        if (line) {
            gpiod_line_free(line);
            line = NULL;
        }
        if (edge) {
            gpiod_edge_free(edge);
            edge = NULL;
        }
        if (chip) {
            gpiod_chip_free(chip);
            chip = NULL;
        }
        if (gpiod_fd > 0) {
            gpiod_close(gpiod_fd);
            gpiod_fd = -1;
        }
        syslog(LOG_INFO, "Program terminated.");
        exit(EXIT_SUCCESS);
    }
}

