    syslog(LOG_INFO, "Audio Logger Started.");

    // Set GPIO18 to GAIN 60dB
    if (gpio_set_value(GPIO18, GAIN_60dB) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO18 to GAIN 60dB.");
        exit(EXIT_FAILURE);
    }

    // Initialize Gpiod
    if ((gpiod_fd = gpiod_open()) < 0) {
        syslog(LOG_ERR, "Failed to open Gpiod.");
        exit(EXIT_FAILURE);
    }

    if ((chip = gpiod_chip_open(gpiod_fd)) == NULL) {
        syslog(LOG_ERR, "Failed to open Gpiod chip.");
        exit(EXIT_FAILURE);
    }

    if ((line = gpiod_chip_get_line(chip, GPIO17)) == NULL) {
        syslog(LOG_ERR, "Failed to get GPIO17 line.");
        exit(EXIT_FAILURE);
    }

    if ((edge = gpiod_line_request_edge(line, GPIOD_EDGE_RISING)) == NULL) {
        syslog(LOG_ERR, "Failed to request edge on GPIO17.");
        exit(EXIT_FAILURE);
    }

    if ((fd_log = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644)) < 0) {
        syslog(LOG_ERR, "Failed to open log file.");
        exit(EXIT_FAILURE);
    }

    while (running) {
        if (edge->edge_count > 0) {
            level_detected = 1;
            struct timeval now;
            gettimeofday(&now, NULL);
            char timestamp[128];
            strftime(timestamp, sizeof(timestamp), LOG_FORMAT, localtime(&now.tv_sec));
            fprintf(fd_log, "%s %d\n", timestamp, level_detected);
            fflush(fd_log);
            level_detected = 0;
        }

        usleep(10 * 1000); // 10ms delay

        if (!running) {
            break;
        }
    }

    handle_signal(0); // Trigger signal handler to clean up

    if (fd_log > 0) {
        close(fd_log);
    }

    if (line) {
        gpiod_line_free(line);
        line = NULL;
    }

    if (edge) {
        gpiod_edge_free(edge);
        edge = NULL;
    }

    if (chip) {
        gpiod_chip_free(chip);
        chip = NULL;
    }

    if (gpiod_fd > 0) {
        gpiod_close(gpiod_fd);
        gpiod_fd = -1;
    }

    closelog();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS 1
#define I2C_ADDR 0x34

#define IAQ_INDEX ((eCO2 * 0.1) + (TVOC * 0.2) + 50)

typedef struct {
    int fd;
    int eCO2;
    int TVOC;
} SensorData;

void sigint_handler(int signum) {
    if (SensorData->fd > 0) {
        close(SensorData->fd);
    }
    if (SensorData->eCO2 > 0) {
        close(SensorData->eCO2);
    }
    if (SensorData->TVOC > 0) {
        close(SensorData->TVOC);
    }
    if (SensorData->fp > 0) {
        fclose(SensorData->fp);
    }
    exit(0);
}

int main() {
    struct iocb iocb;
    struct i2c_msg msg[1];
    struct i2c_rdwr_ioctl_msg rdwr_msg;
    SensorData sensor_data;
    char line[256];
    FILE *fp;

    signal(SIGINT, sigint_handler);

    sensor_data.fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (sensor_data.fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(sensor_data.fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        return 1;
    }

    memset(&iocb, 0, sizeof(iocb));
    iocb.mostsignificantbyte = I2C_MSB;
    iocb.ioctl = I2C_SMBUS_READBYTE;
    iocb.addr = I2C_ADDR;

    msg[0].addr = I2C_ADDR;
    msg[0].flags = I2C_M_RD;
    msg[0].data[0] = 0x00;

    if (ioctl(sensor_data.fd, I2C_SMBUS_I2CMSG ioctl, msg, 1, &rdwr_msg) < 0) {
        perror("Failed to send I2C message");
        return 1;
    }

    if (rdwr_msg.msgs_num > 0) {
        if (rdwr_msg.msgs[0].err) {
            perror("I2C read error");
            return 1;
        }
        sensor_data.eCO2 = msg[0].data[0];
        if (sensor_data.eCO2 == 0) {
            printf("eCO2 sensor not detected\n");
            return 1;
        }
    } else {
        printf("I2C read failed\n");
        return 1;
    }

    memset(&iocb, 0, sizeof(iocb));
    iocb.mostsignificantbyte = I2C_MSB;
    iocb.ioctl = I2C_SMBUS_READBYTE;
    iocb.addr = I2C_ADDR;

    msg[0].addr = I2C_ADDR;
    msg[0].flags = I2C_M_RD;
    msg[0].data[0] = 0x01;

    if (ioctl(sensor_data.fd, I2C_SMBUS_I2CMSG ioctl, msg, 1, &rdwr_msg) < 0) {
        perror("Failed to send I2C message");
        return 1;
    }

    if (rdwr_msg.msgs_num > 0) {
        if (rdwr_msg.msgs[0].err) {
            perror("I2C read error");
            return 1;
        }
        sensor_data.TVOC = msg[0].data[0];
        if (sensor_data.TVOC == 0) {
            printf("TVOC sensor not detected\n");
            return 1;
        }
    } else {
        printf("I2C read failed\n");
        return 1;
    }

    fp = fopen("air_quality_log.csv", "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    while (1) {
        sprintf(line, "%d,%d\n", IAQ_INDEX, sensor_data.TVOC);
        if (fwrite(line, strlen(line), 1, fp) != 1) {
            perror("Failed to write to log file");
            return 1;
        }

        usleep(5000000); // 5 seconds

        if (sensor_data.eCO2 > 0) {
            ioctl(sensor_data.fd, I2C_SMBUS_I2CMSG ioctl, msg, 1, &rdwr_msg);
            if (rdwr_msg.msgs_num > 0) {
                if (rdwr_msg.msgs[0].err) {
                    perror("I2C read error");
                    return 1;
                }
                sensor_data.eCO2 = msg[0].data[0];
            } else {
                printf("I2C read failed\n");
                return 1;
            }
        } else {
            printf("eCO2 sensor not detected\n");
            return 1;
        }

        if (sensor_data.TVOC > 0) {
            ioctl(sensor_data.fd, I2C_SMBUS_I2CMSG ioctl, msg, 1, &rdwr_msg);
            if (rdwr_msg.msgs_num > 0) {
                if (rdwr_msg.msgs[0].err) {
                    perror("I2C read error");
                    return 1;
                }
                sensor_data.TVOC = msg[0].data[0];
            } else {
                printf("I2C read failed\n");
                return 1;
            }
        } else {
            printf("TVOC sensor not detected\n");
            return 1;
        }
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <poll.h>
#include <sys/syscall.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_MAJOR 4
#define GPIO_MINOR 0
#define GPIO_BASE 0x40000000
#define GPIO_OFFSET 0x20000000

#define TTP223_TAMPER "ttp223_tamper"

#define TTP223_TIMEOUT 500000000  // 5 seconds in nanoseconds

int ttp223_fd;
struct gpiod_chip *chip;
struct gpiod_line *line;
struct gpiod_edge *edge;
struct gpiod_event *event;
struct timespec timeout;

void cleanup(void) {
    if (line) {
        gpiod_line_put(line);
        line = NULL;
    }
    if (edge) {
        gpiod_edge_put(edge);
        edge = NULL;
    }
    if (event) {
        gpiod_event_put(event);
        event = NULL;
    }
    if (chip) {
        gpiod_chip_put(chip);
        chip = NULL;
    }
    if (ttp223_fd > 0) {
        close(ttp223_fd);
        ttp223_fd = -1;
    }
}

void handle_signal(int signum) {
    cleanup();
    exit(EXIT_SUCCESS);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    timeout.tv_sec = 0;
    timeout.tv_nsec = TTP223_TIMEOUT;

    ttp223_fd = open("/dev/input/touchscreen", O_RDONLY);
    if (ttp223_fd < 0) {
        perror("open touchscreen");
        cleanup();
        exit(EXIT_FAILURE);
    }

    chip = gpiod_chip_open(GPIO_MAJOR, GPIO_MINOR, GPIO_BASE, GPIO_OFFSET);
    if (!chip) {
        perror("gpiod_chip_open");
        cleanup();
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip, TTP223_TAMPER);
    if (!line) {
        perror("gpiod_chip_get_line");
        cleanup();
        exit(EXIT_FAILURE);
    }

    edge = gpiod_line_request_edge(line, GPIOD_EDGE_BOTH);
    if (!edge) {
        perror("gpiod_line_request_edge");
        cleanup();
        exit(EXIT_FAILURE);
    }

    event = gpiod_edge_request_event(edge, 0);
    if (!event) {
        perror("gpiod_edge_request_event");
        cleanup();
        exit(EXIT_FAILURE);
    }

    if (gpiod_edge_enable(edge, GPIOD_EDGE_BOTH)) {
        printf("Edge detection enabled\n");
    } else {
        perror("gpiod_edge_enable");
        cleanup();
        exit(EXIT_FAILURE);
    }

    while (1) {
        poll(&timeout, 1, 100);
        if (ttp223_fd < 0) {
            perror("ttp223_fd");
            cleanup();
            exit(EXIT_FAILURE);
        }

        if (gpiod_event_get(event)) {
            if (gpiod_line_get_value(line) == 1) {
                // Touch detected
                printf("Touch detected\n");
                clock_gettime(CLOCK_MONOTONIC, &timeout);
                while (timeout.tv_sec < 5) {
                    clock_gettime(CLOCK_MONOTONIC, &timeout);
                    if (timeout.tv_sec >= 5) {
                        printf("Intrusion detected\n");
                        break;
                    }
                }
            }
        }
    }

    return 0;
}

