#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/time.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <syslog.h>
#include <gpiod.h>

#define GPIO4 4
#define GPIO18 18
#define PWM_FREQ 100
#define DEBOUNCE 50
#define LOG_FILE "flame_log.txt"

typedef struct {
    int fd;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_edge *edge;
    struct gpiod_event *event;
    struct gpiod_loop *loop;
} GPIOHandler;

void log_event(const char *event, const char *timestamp) {
    char buffer[256];
    struct tm *timeinfo;
    time_t now = time(NULL);
    timeinfo = localtime(&now);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(stderr, "%s: %s\n", timestamp, buffer);
    fprintf(stderr, "%s: %s\n", event, buffer);
    fflush(stderr);
}

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        if (GPIOHandler->fd > 0) {
            gpiod_loop_free(GPIOHandler->loop);
            gpiod_line_free(GPIOHandler->line);
            gpiod_chip_free(GPIOHandler->chip);
            close(GPIOHandler->fd);
        }
        exit(EXIT_SUCCESS);
    }
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_edge *edge;
    struct gpiod_event *event;
    struct gpiod_loop *loop;
    int fd;
    int result;
    char buffer[256];
    char timestamp[256];
    struct timeval tv;

    fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd < 0) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    result = gpiod_init(&chip);
    if (result < 0) {
        perror("Failed to initialize gpiod");
        close(fd);
        exit(EXIT_FAILURE);
    }

    result = gpiod_chip_request_line(chip, GPIO4, &line);
    if (result < 0) {
        perror("Failed to request GPIO4 line");
        close(fd);
        gpiod_chip_free(chip);
        exit(EXIT_FAILURE);
    }

    result = gpiod_chip_request_edge(chip, line, GPIOD_EDGE_EDGE_RISING, &edge);
    if (result < 0) {
        perror("Failed to request GPIO4 edge");
        close(fd);
        gpiod_chip_free(chip);
        gpiod_line_free(line);
        exit(EXIT_FAILURE);
    }

    result = gpiod_chip_request_event(chip, line, edge, &event);
    if (result < 0) {
        perror("Failed to request GPIO4 event");
        close(fd);
        gpiod_chip_free(chip);
        gpiod_line_free(line);
        gpiod_edge_free(edge);
        exit(EXIT_FAILURE);
    }

    result = gpiod_chip_request_loop(chip, line, &loop);
    if (result < 0) {
        perror("Failed to request GPIO4 loop");
        close(fd);
        gpiod_chip_free(chip);
        gpiod_line_free(line);
        gpiod_edge_free(edge);
        gpiod_event_free(event);
        exit(EXIT_FAILURE);
    }

    result = gpiod_chip_enable(chip, line, GPIOD_LINE_ENABLE_OUTPUT);
    if (result < 0) {
        perror("Failed to enable GPIO4 output");
        close(fd);
        gpiod_chip_free(chip);
        gpiod_line_free(line);
        gpiod_edge_free(edge);
        gpiod_event_free(event);
        gpiod_loop_free(loop);
        exit(EXIT_FAILURE);
    }

    result = gpiod_chip_request_pwm(chip, line, &loop);
    if (result < 0) {
        perror("Failed to request PWM");
        close(fd);
        gpiod_chip_free(chip);
        gpiod_line_free(line);
        gpiod_edge_free(edge);
        gpiod_event_free(event);
        gpiod_loop_free(loop);
        exit(EXIT_FAILURE);
    }

    result = gpiod_chip_request_pwm_frequency(chip, line, loop, PWM_FREQ);
    if (result < 0) {
        perror("Failed to set PWM frequency");
        close(fd);
        gpiod_chip_free(chip);
        gpiod_line_free(line);
        gpiod_edge_free(edge);
        gpiod_event_free(event);
        gpiod_loop_free(loop);
        exit(EXIT_FAILURE);
    }

    result = gpiod_chip_request_pwm_mode(chip, line, loop, GPIOD_PWM_MODE_ON);
    if (result < 0) {
        perror("Failed to set PWM mode");
        close(fd);
        gpiod_chip_free(chip);
        gpiod_line_free(line);
        gpiod_edge_free(edge);
        gpiod_event_free(event);
        gpiod_loop_free(loop);
        exit(EXIT_FAILURE);
    }

    result = gpiod_chip_request_pwm_duty(chip, line, loop, 0);
    if (result < 0) {
        perror("Failed to set PWM duty");
        close(fd);
        gpiod_chip_free(chip);
        gpiod_line_free(line);
        gpiod_edge_free(edge);
        gpiod_event_free(event);
        gpiod_loop_free(loop);
        exit(EXIT_FAILURE);
    }

    result = gpiod_chip_request_pwm_period(chip, line, loop, 1000000 / PWM_FREQ);
    if (result < 0) {
        perror("Failed to set PWM period");
        close(fd);
        gpiod_chip_free(chip);
        gpiod_line_free(line);
        gpiod_edge_free(edge);
        gpiod_event_free(event);
        gpiod_loop_free(loop);
        exit(EXIT_FAILURE);
    }

    result = gpiod_chip_request_pwm_start(chip, line, loop, 1);
    if (result < 0) {
        perror("Failed to start PWM");
        close(fd);
        gpiod_chip_free(chip);
        gpiod_line_free(line);
        gpiod_edge_free(edge);
        gpiod_event_free(event);
        gpiod_loop_free(loop);
        exit(EXIT_FAILURE);
    }

    result = gettimeofday(&tv, NULL);
    if (result < 0) {
        perror("Failed to get current time");
        close(fd);
        gpiod_chip_free(chip);
        gpiod_line_free(line);
        gpiod_edge_free(edge);
        gpiod_event_free(event);
        gpiod_loop_free(loop);
        exit(EXIT_FAILURE);
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&tv.tv_sec));
    fprintf(stderr, "System started at %s\n", timestamp);
    log_event("System started", timestamp);

    result = gpiod_chip_request_line(chip, GPIO18, &line);
    if (result < 0) {
        perror("Failed to request GPIO18 line");
        close(fd);
        gpiod_chip_free(chip);
        gpiod_line_free(line);
        gpiod_edge_free(edge);
        gpiod_event_free(event);
        gpiod_loop_free(loop);
        exit(EXIT_FAILURE);
    }

    result = gpiod_chip_request_edge(chip, line, GPIOD_EDGE_EDGE_RISING, &edge);
    if (result < 0) {
        perror("Failed to request GPIO18 edge");
        close(fd);
        gpiod_chip_free(chip);
        gpiod_line_free(line);
        gpiod_edge_free(edge);
        gpiod_event_free(event);
        gpiod_loop_free(loop);
        exit(EXIT_FAILURE);
    }

    result = gpiod_chip_request_event(chip, line, edge, &event);
    if (result < 0) {
        perror("Failed to request GPIO18 event");
        close(fd);
        gpiod_chip_free(chip);
        gpiod_line_free(line);
        gpiod_edge_free(edge);
        gpiod_event_free(event);
        gpiod_loop_free(loop);
        exit(EXIT_FAILURE);
    }

    result = gpiod_chip_request_loop(chip, line, &loop);
    if (result < 0) {
        perror("Failed to request GPIO18 loop");
        close(fd);
        gpiod_chip_free(chip);
        gpiod_line_free(line);
        gpiod_edge_free(edge);
        gpiod_event_free(event);
        gpiod_loop_free(loop);
        exit(EXIT_FAILURE);
    }

    result = gpiod_chip_request_pwm(chip, line, &loop);
    if (result < 0) {
        perror("Failed to request PWM");
        close(fd);
        gpiod_chip_free(chip);
        gpiod_line_free(line);
        gpiod_edge_free(edge);
        gpiod_event_free(event);
        gpiod_loop_free(loop);
        exit(EXIT_FAILURE);
    }

    result = gpiod_chip_request_pwm_frequency(chip, line, loop, PWM_FREQ);
    if (result < 0) {
        perror("Failed to set PWM frequency");
        close(fd);
        gpiod_chip_free(chip);
        gpiod_line_free(line);
        gpiod_edge_free(edge);
        gpiod_event_free(event);
        gpiod_loop_free(loop);
        exit(EXIT_FAILURE);
    }

    result = gpiod_chip_request_pwm_mode(chip, line, loop, GPIOD_PWM_MODE_ON);
    if (result < 0) {
        perror("Failed to set PWM mode");
        close(fd);
        gpiod_chip_free(chip);
        gpiod_line_free(line);
        gpiod_edge_free(edge);
        gpiod_event_free(event);
        gpiod_loop_free(loop);
        exit(EXIT_FAILURE);
    }

    result = gpiod_chip_request_pwm_duty(chip, line, loop, 0);
    if (result < 0) {
        perror("Failed to set PWM duty");
        close(fd);
        gpiod_chip_free(chip);
        gpiod_line_free(line);
        gpiod_edge_free(edge);
        gpiod_event_free(event);
        gpiod_loop_free(loop);
        exit(EXIT_FAILURE);
    }

    result = gpiod_chip_request_pwm_period(chip, line, loop, 1000000 / PWM_FREQ);
    if (result < 0) {
        perror("Failed to set PWM period");
        close(fd);
        gpiod_chip_free(chip);
        gpiod_line_free(line);
        gpiod_edge_free(edge);
        gpiod_event_free(event);
        gpiod_loop_free(loop);
        exit(EXIT_FAILURE);
    }

    result = gpiod_chip_request_pwm_start(chip, line, loop, 1);
    if (result < 0) {
        perror("Failed to start PWM");
        close(fd);
        gpiod_chip_free(chip);
        gpiod_line_free(line);
        gpiod_edge_free(edge);
        gpiod_event_free(event);
        gpiod_loop_free(loop);
        exit(EXIT_FAILURE);
    }

    result = gettimeofday(&tv, NULL);
    if (result < 0) {
        perror("Failed to get current time");
        close(fd);
        gpiod_chip_free(chip);
        gpiod_line_free(line);
        gpiod_edge_free(edge);
        gpiod_event_free(event);
        gpiod_loop_free(loop);
        exit(EXIT_FAILURE);
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&tv.tv_sec));
    fprintf(stderr, "System started at %s\n", timestamp);
    log_event("System started", timestamp);

    while (1) {
        result = gpiod_line_read(chip, line, event, 0);
        if (result < 0) {
            perror("Failed to read GPIO4");
            close(fd);
            gpiod_chip_free(chip);
            gpiod_line_free(line);
            gpiod_edge_free(edge);
            gpiod_event_free(event);
            gpiod_loop_free(loop);
            gpiod_chip_request_pwm(chip, line, &loop);
            gpiod_chip_request_pwm_frequency(chip, line, loop, PWM_FREQ);
            gpiod_chip_request_pwm_mode(chip, line, loop, GPIOD_PWM_MODE_ON);
            gpiod_chip_request_pwm_duty(chip, line, loop, 0);
            gpiod_chip_request_pwm_period(chip, line, loop, 1000000 / PWM_FREQ);
            gpiod_chip_request_pwm_start(chip, line, loop, 1);
            result = gettimeofday(&tv, NULL);
            if (result < 0) {
                perror("Failed to get current time");
                close(fd);
                gpiod_chip_free(chip);
                gpiod_line_free(line);
                gpiod_edge_free(edge);
                gpiod_event_free(event);
                gpiod_loop_free(loop);
                exit(EXIT_FAILURE);
            }
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&tv.tv_sec));
            fprintf(stderr, "Sensor absent, retrying...\n");
            log_event("Sensor absent", timestamp);
            usleep(DEBOUNCE * 1000);
        } else {
            if (event->edge == GPIOD_EDGE_EDGE_RISING) {
                result = gettimeofday(&tv, NULL);
                if (result < 0) {
                    perror("Failed to get current time");
                    close(fd);
                    gpiod_chip_free(chip);
                    gpiod_line_free(line);
                    gpiod_edge_free(edge);
                    gpiod_event_free(event);
                    gpiod_loop_free(loop);
                    gpiod_chip_request_pwm(chip, line, &loop);
                    gpiod_chip_request_pwm_frequency(chip, line, loop, PWM_FREQ);
                    gpiod_chip_request_pwm_mode(chip, line, loop, GPIOD_PWM_MODE_ON);
                    gpiod_chip_request_pwm_duty(chip, line, loop, 0);
                    gpiod_chip_request_pwm_period(chip, line, loop, 1000000 / PWM_FREQ);
                    gpiod_chip_request_pwm_start(chip, line, loop, 1);
                    result = gettimeofday(&tv, NULL);
                    if (result < 0) {
                        perror("Failed to get current time");
                        close(fd);
                        gpiod_chip_free(chip);
                        gpiod_line_free(line);
                        gpiod_edge_free(edge);
                        gpiod_event_free(event);
                        gpiod_loop_free(loop);
                        exit(EXIT_FAILURE);
                    }
                    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&tv.tv_sec));
                    fprintf(stderr, "Flame detected at %s\n", timestamp);
                    log_event("Flame detected", timestamp);
                    result = gpiod_line_request_pwm(chip, line, loop, 1);
                    if (result < 0) {
                        perror("Failed to request PWM");
                        close(fd);
                        gpiod_chip_free(chip);
                        gpiod_line_free(line);
                        gpiod_edge_free(edge);
                        gpiod_event_free(event);
                        gpiod_loop_free(loop);
                        exit(EXIT_FAILURE);
                    }
                }
            } else if (event->edge == GPIOD_EDGE_EDGE_FALLING) {
                result = gettimeofday(&tv, NULL);
                if (result < 0) {
                    perror("Failed to get current time");
                    close(fd);
                    gpiod_chip_free(chip);
                    gpiod_line_free(line);
                    gpiod_edge_free(edge);
                    gpiod_event_free(event);
                    gpiod_loop_free(loop);
                    gpiod_chip_request_pwm(chip, line, &loop);
                    gpiod_chip_request_pwm_frequency(chip, line, loop, PWM_FREQ);
                    gpiod_chip_request_pwm_mode(chip, line, loop, GPIOD_PWM_MODE_ON);
                    gpiod_chip_request_pwm_duty(chip, line, loop, 0);
                    gpiod_chip_request_pwm_period(chip, line, loop, 1000000 / PWM_FREQ);
                    gpiod_chip_request_pwm_start(chip, line, loop, 1);
                    result = gettimeofday(&tv, NULL);
                    if (result < 0) {
                        perror("Failed to get current time");
                        close(fd);
                        gpiod_chip_free(chip);
                        gpiod_line_free(line);
                        gpiod_edge_free(edge);
                        gpiod_event_free(event);
                        gpiod_loop_free(loop);
                        exit(EXIT_FAILURE);
                    }
                    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&tv.tv_sec));
                    fprintf(stderr, "Flame ended at %s\n", timestamp);
                    log_event("Flame ended", timestamp);
                    result = gpiod_line_request_pwm(chip, line, loop, 0);
                    if (result < 0) {
                        perror("Failed to request PWM");
                        close(fd);
                        gpiod_chip_free(chip);
                        gpiod_line_free(line);
                        gpiod_edge_free(edge);
                        gpiod_event_free(event);
                        gpiod_loop_free(loop);
                        exit(EXIT_FAILURE);
                    }
                }
            }
        }
    }

    return 0;
}

