#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <gpiod.h>
#include <errno.h>

#define GPIO_LINE 17
#define FLAME_DETECTED_NO "Flame Detected: NO"
#define FLAME_DETECTED_YES "Flame Detected: YES"
#define LOG_FORMAT "%Y-%m-%d %H:%M:%S"

volatile sig_atomic_t sigint_received = 0;

void sigint_handler(int sig) {
    sigint_received = 1;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_edge *edge;
    struct gpiod_loop *loop;
    struct gpiod_event *event;
    struct gpiod_request *request;
    int fd, status;

    // Set up signal handler
    signal(SIGINT, sigint_handler);

    // Open the GPIO chip
    if ((fd = gpiod_chip_open("/dev/gpiod")) < 0) {
        perror("gpiod_chip_open");
        return 1;
    }

    // Create a new line request
    if ((line = gpiod_chip_request_new(fd, GPIO_LINE, GPIOD_LINE_REQ_INPUT)) == NULL) {
        perror("gpiod_chip_request_new");
        gpiod_chip_close(fd);
        return 1;
    }

    // Create an edge request
    if ((edge = gpiod_line_request_edge_new(line, GPIOD_EDGE_EDGE_FALLING)) == NULL) {
        perror("gpiod_line_request_edge_new");
        gpiod_chip_request_line_free(line);
        gpiod_chip_close(fd);
        return 1;
    }

    // Create a loop request
    if ((loop = gpiod_edge_request_loop_new(edge, GPIOD_EDGE_LOOP)) == NULL) {
        perror("gpiod_edge_request_loop_new");
        gpiod_edge_request_edge_free(edge);
        gpiod_chip_request_line_free(line);
        gpiod_chip_close(fd);
        return 1;
    }

    // Create an event request
    if ((event = gpiod_loop_request_event_new(loop, 0)) == NULL) {
        perror("gpiod_loop_request_event_new");
        gpiod_edge_request_loop_free(loop);
        gpiod_line_request_edge_free(edge);
        gpiod_chip_request_line_free(line);
        gpiod_chip_close(fd);
        return 1;
    }

    // Create a request to read the line value
    if ((request = gpiod_line_request_read_new(line)) == NULL) {
        perror("gpiod_line_request_read_new");
        gpiod_loop_request_event_free(event);
        gpiod_edge_request_loop_free(loop);
        gpiod_line_request_edge_free(edge);
        gpiod_chip_request_line_free(line);
        gpiod_chip_close(fd);
        return 1;
    }

    // Start the loop
    if (gpiod_loop_request_start(loop) < 0) {
        perror("gpiod_loop_request_start");
        gpiod_loop_request_event_free(event);
        gpiod_edge_request_loop_free(loop);
        gpiod_line_request_edge_free(edge);
        gpiod_chip_request_line_free(line);
        gpiod_chip_close(fd);
        return 1;
    }

    // Main loop
    while (!sigint_received) {
        // Read the line value
        if (gpiod_line_request_read_status(request) < 0) {
            perror("gpiod_line_request_read_status");
            gpiod_loop_request_event_free(event);
            gpiod_edge_request_loop_free(loop);
            gpiod_line_request_edge_free(edge);
            gpiod_chip_request_line_free(line);
            gpiod_chip_close(fd);
            return 1;
        }

        // Check the line value
        if (gpiod_line_request_read_value(request) == 0) {
            printf("%s %s\n", LOG_FORMAT, FLAME_DETECTED_YES);
        } else {
            printf("%s %s\n", LOG_FORMAT, FLAME_DETECTED_NO);
        }

        // Sleep for 1 second
        usleep(1000000);
    }

    // Cleanup
    gpiod_line_request_event_free(event);
    gpiod_edge_request_loop_free(loop);
    gpiod_line_request_edge_free(edge);
    gpiod_chip_request_line_free(line);
    gpiod_chip_close(fd);

    return 0;
}

