#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <poll.h>
#include <gpiod.h>

#define TTP226_CHIP "/dev/ttys0"  // Change this to the correct device file
#define TTP226_MAX_LINES 8
#define TTP226_LINE_POLL_INTERVAL 100000  // 100ms

int ttp226_fd;
struct gpiod_chip *chip;
struct gpiod_line *line[TTP226_MAX_LINES];
struct gpiod_edge *edge;
int line_fd[TTP226_MAX_LINES];
int line_state[TTP226_MAX_LINES];

void handle_sigint(int signum) {
    printf("Graceful shutdown initiated.\n");
    for (int i = 0; i < TTP226_MAX_LINES; i++) {
        if (line_fd[i] > 0) {
            close(line_fd[i]);
        }
        if (line[i]) {
            gpiod_line_free(line[i]);
        }
    }
    if (chip) {
        gpiod_chip_free(chip);
    }
    exit(EXIT_SUCCESS);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    if ((ttp226_fd = open(TTP226_CHIP, O_RDONLY)) < 0) {
        perror("Failed to open TTP226 chip");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(ttp226_fd);
    if (!chip) {
        perror("Failed to open chip");
        close(ttp226_fd);
        return EXIT_FAILURE;
    }

    for (int i = 0; i < TTP226_MAX_LINES; i++) {
        line[i] = gpiod_chip_new(chip);
        if (!line[i]) {
            perror("Failed to create line");
            close(ttp226_fd);
            gpiod_chip_free(chip);
            return EXIT_FAILURE;
        }
        line_fd[i] = gpiod_chip_request_line(chip, line[i], 0);
        if (line_fd[i] < 0) {
            perror("Failed to request line");
            close(ttp226_fd);
            gpiod_chip_free(chip);
            for (int j = 0; j < TTP226_MAX_LINES; j++) {
                if (line[j]) {
                    gpiod_line_free(line[j]);
                }
            }
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < TTP226_MAX_LINES; i++) {
        line_state[i] = 0;
    }

    while (1) {
        struct pollfd pollfds[TTP226_MAX_LINES + 1];
        for (int i = 0; i < TTP226_MAX_LINES; i++) {
            pollfds[i].fd = line_fd[i];
            pollfds[i].events = POLLIN;
        }
        pollfds[TTP226_MAX_LINES].fd = -1;
        pollfds[TTP226_MAX_LINES].events = 0;

        int poll_result = poll(pollfds, TTP226_MAX_LINES + 1, TTP226_LINE_POLL_INTERVAL);
        if (poll_result < 0) {
            perror("Poll failed");
            break;
        }

        for (int i = 0; i < TTP226_MAX_LINES; i++) {
            if (poll_result > 0 && pollfds[i].revents & POLLIN) {
                int value = gpiod_line_read(line[i]);
                if (value < 0) {
                    perror("Failed to read line");
                    close(ttp226_fd);
                    gpiod_chip_free(chip);
                    for (int j = 0; j < TTP226_MAX_LINES; j++) {
                        if (line[j]) {
                            gpiod_line_free(line[j]);
                        }
                    }
                    return EXIT_FAILURE;
                }
                line_state[i] = value;
            }
        }

        for (int i = 0; i < TTP226_MAX_LINES; i++) {
            printf("%s %d\n", "TTP226", line_state[i]);
        }
        fflush(stdout);
    }

    close(ttp226_fd);
    gpiod_chip_free(chip);
    for (int i = 0; i < TTP226_MAX_LINES; i++) {
        if (line_fd[i] > 0) {
            close(line_fd[i]);
        }
        if (line[i]) {
            gpiod_line_free(line[i]);
        }
    }

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_BASE 0x3F200000
#define GPIO_SIZE 0x1000
#define GPIO_OFFSET 0x2000

#define GPIO_OUT1 2
#define GPIO_OUT2 3
#define GPIO_OUT3 4
#define GPIO_OUT4 5
#define GPIO_OUT5 6
#define GPIO_OUT6 7
#define GPIO_OUT7 8
#define GPIO_OUT8 9

#define GPIO_IN1 10
#define GPIO_IN2 11
#define GPIO_IN3 12
#define GPIO_IN4 13
#define GPIO_IN5 14
#define GPIO_IN6 15
#define GPIO_IN7 16
#define GPIO_IN8 17

#define SAMPLE_INTERVAL 100000  // 100 ms

int main() {
    int err;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_edge *edge;
    struct gpiod_loop *loop;
    struct gpiod_loop_state *state;
    struct gpiod_edge_request *request;
    int samples[8];
    char buffer[128];

    // Open the GPIO device
    chip = gpiod_chip_open(GPIO_BASE, GPIO_SIZE, GPIO_OFFSET);
    if (chip == NULL) {
        perror("gpiod_chip_open");
        return 1;
    }

    // Create a new line for each GPIO input
    for (int i = 0; i < 8; i++) {
        line = gpiod_chip_request_line(chip, GPIO_IN1 + i, GPIOD_LINE_INPUT);
        if (line == NULL) {
            perror("gpiod_chip_request_line");
            gpiod_chip_close(chip);
            return 1;
        }
    }

    // Create an edge for each line
    for (int i = 0; i < 8; i++) {
        edge = gpiod_line_request_edge(line[i], GPIOD_EDGE_EDGE_RISING);
        if (edge == NULL) {
            perror("gpiod_line_request_edge");
            gpiod_chip_close(chip);
            return 1;
        }
    }

    // Create a loop
    loop = gpiod_loop_new(chip, 0);
    if (loop == NULL) {
        perror("gpiod_loop_new");
        gpiod_chip_close(chip);
        return 1;
    }

    // Create a state for the loop
    state = gpiod_loop_state_new(loop, 0);
    if (state == NULL) {
        perror("gpiod_loop_state_new");
        gpiod_chip_close(chip);
        return 1;
    }

    // Create a request for each edge
    request = gpiod_loop_state_request_edge(state, edge[0]);
    if (request == NULL) {
        perror("gpiod_loop_state_request_edge");
        gpiod_chip_close(chip);
        return 1;
    }

    // Set the request to run
    gpiod_loop_state_set_state(state, GPIOD_LOOP_STATE_RUNNING);
    gpiod_loop_state_set_request_state(state, request, GPIOD_EDGE_STATE_ACTIVE);

    // Install signal handlers
    signal(SIGINT, [](int sig) {
        gpiod_loop_state_set_state(state, GPIOD_LOOP_STATE_STOPPED);
        gpiod_loop_state_request_edge(state, request, GPIOD_EDGE_STATE_IDLE);
        gpiod_loop_state_set_state(state, GPIOD_LOOP_STATE_STOPPED);
        gpiod_chip_close(chip);
        return 0;
    });

    signal(SIGTERM, [](int sig) {
        gpiod_loop_state_set_state(state, GPIOD_LOOP_STATE_STOPPED);
        gpiod_loop_state_request_edge(state, request, GPIOD_EDGE_STATE_IDLE);
        gpiod_chip_close(chip);
        return 0;
    });

    // Main loop
    while (1) {
        // Read the samples
        for (int i = 0; i < 8; i++) {
            samples[i] = gpiod_line_get_value(line[i]);
        }

        // Print the samples
        snprintf(buffer, sizeof(buffer), "[%d ms] CH1=%d CH2=%d CH3=%d CH4=%d CH5=%d CH6=%d CH7=%d CH8=%d",
                 SAMPLE_INTERVAL, samples[0], samples[1], samples[2], samples[3], samples[4], samples[5], samples[6], samples[7]);
        printf("%s\n", buffer);

        // Sleep for the sample interval
        usleep(SAMPLE_INTERVAL);
    }

    // Cleanup
    gpiod_loop_state_request_edge(state, request, GPIOD_EDGE_STATE_IDLE);
    gpiod_loop_state_set_state(state, GPIOD_LOOP_STATE_STOPPED);
    gpiod_chip_close(chip);

    return 0;
}

