#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <string.h>
#include <gpiod.h>

#define GPIO4 4
#define PULL_UP 1
#define INPUT 0
#define TILTED 0
#define NOT_TILTED 1

static int fd;
static struct gpiod_chip *chip;
static struct gpiod_line *line;

void handle_signal(int signum) {
    if (signum == SIGINT) {
        printf("Exiting due to SIGINT\n");
        gpiod_line_close(line);
        gpiod_chip_free(chip);
        close(fd);
        exit(EXIT_SUCCESS);
    }
}

int main() {
    // Initialize GPIO4 as input with pull-up resistor
    fd = open("/dev/gpiod", O_RDONLY | O_NONBLOCK);
    if (fd < 0) {
        perror("Failed to open /dev/gpiod");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(fd);
    if (!chip) {
        perror("Failed to open gpiod_chip");
        goto cleanup;
    }

    line = gpiod_chip_new(chip, GPIO4, INPUT, PULL_UP);
    if (!line) {
        perror("Failed to create line");
        goto cleanup;
    }

    // Set up signal handler
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to set up SIGINT handler");
        goto cleanup;
    }

    printf("Startup banner\n");

    while (1) {
        // Read the pin
        int value = gpiod_line_read(line);
        if (value < 0) {
            perror("Failed to read GPIO line");
            goto cleanup;
        }

        // Check the tilt state
        if (value == TILTED) {
            printf("Tilted\n");
        } else {
            printf("Not Tilted\n");
        }

        // Sleep for 100ms
        usleep(100000);
    }

cleanup:
    gpiod_line_close(line);
    gpiod_chip_free(chip);
    close(fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>
#include <stdbool.h>

#define I2C_BUS 1
#define SI1145_ADDR 0x60

#define UV_INDEX 0x10
#define AMBIENT_LIGHT 0x11

typedef struct {
    uint32_t timestamp;
    uint16_t uv_index;
    uint16_t ambient_light;
} SensorData;

void handleSigint(int signum) {
    fprintf(stderr, "Caught SIGINT signal, exiting...\n");
    exit(0);
}

void handleSigterm(int signum) {
    fprintf(stderr, "Caught SIGTERM signal, exiting...\n");
    exit(0);
}

void initI2C(int *fd) {
    *fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (*fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }
    if (ioctl(*fd, I2C_SLAVE, SI1145_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        exit(EXIT_FAILURE);
    }
}

void closeI2C(int fd) {
    if (fd >= 0) {
        close(fd);
    }
}

void readSensor(int fd, SensorData *data) {
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        perror("Failed to read sensor data");
        exit(EXIT_FAILURE);
    }
    data->timestamp = buf[0] << 8 | buf[1];
    if (read(fd, buf, 2) != 2) {
        perror("Failed to read sensor data");
        exit(EXIT_FAILURE);
    }
    data->uv_index = buf[0] << 8 | buf[1];
    if (read(fd, buf, 2) != 2) {
        perror("Failed to read sensor data");
        exit(EXIT_FAILURE);
    }
    data->ambient_light = buf[0] << 8 | buf[1];
}

void writeLog(const char *filename, const SensorData *data) {
    FILE *log_file = fopen(filename, "a");
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
    fprintf(log_file, "%lu,%u,%u\n", data->timestamp, data->uv_index, data->ambient_light);
    fclose(log_file);
}

int main() {
    int i2c_fd;
    initI2C(&i2c_fd);

    struct sigaction sa;
    sa.sa_handler = handleSigint;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (1) {
        SensorData data;
        readSensor(i2c_fd, &data);
        writeLog("uv_als_log.csv", &data);
        printf("%lu,%u,%u\n", data.timestamp, data.uv_index, data.ambient_light);
        sleep(1);
    }

    closeI2C(i2c_fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <string.h>
#include <math.h>

#define I2C_BUS "/dev/i2c‑1"
#define SLF3S_ADDR 0x40
#define SLF3S_MEAS_REG 0x00
#define SLF3S_CRC_REG 0x01
#define SLF3S_CONTROL_REG 0x02
#define SLF3S_RESET_REG 0x03
#define SLF3S_START_MEAS 0x01
#define SLF3S_STOP_MEAS 0x00
#define SLF3S_MEAS_POLY 0x0D
#define SLF3S_MEAS_INIT 0x00

#define GPIO17 17
#define LOG_FILE "flow_log.txt"

typedef struct {
    int fd;
    int sensor1_valid;
    int sensor2_valid;
    double sensor1_avg;
    double sensor2_avg;
    double alarm;
} SensorData;

void handle_error(int fd, const char *message) {
    if (fd > 0) {
        close(fd);
    }
    fprintf(stderr, "Error: %s\n", message);
    exit(EXIT_FAILURE);
}

void handle_sigint(int signum) {
    handle_errorSENSOR_DATA.sensor1_valid, SENSOR_DATA.sensor2_valid, SENSOR_DATA.sensor1_avg, SENSOR_DATA.sensor2_avg, SENSOR_DATA.alarm);
    exit(EXIT_SUCCESS);
}

int main() {
    struct iocb iocb1;
    struct iocb iocb2;
    struct i2c_msg msg1;
    struct i2c_msg msg2;
    struct i2c_rdwr_ioctl_msg rdwr_msg;
    SensorData SENSOR_DATA = {0};
    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        handle_error(i2c_fd, "Failed to open I2C bus");
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SLF3S_ADDR) < 0) {
        handle_error(i2c_fd, "Failed to set slave address");
    }

    memset(&iocb1, 0, sizeof(iocb1));
    iocb1.msg_io.written = 1;
    iocb1.msg_io.err = 0;
    iocb1.msg_rd.written = 0;
    iocb1.msg_rd.err = 0;
    iocb1.msg_rd.data_ptr = &SENSOR_DATA.sensor1_valid;
    iocb1.msg_rd.msg_len = sizeof(int);

    memset(&iocb2, 0, sizeof(iocb2));
    iocb2.msg_io.written = 1;
    iocb2.msg_io.err = 0;
    iocb2.msg_rd.written = 0;
    iocb2.msg_rd.err = 0;
    iocb2.msg_rd.data_ptr = &SENSOR_DATA.sensor2_valid;
    iocb2.msg_rd.msg_len = sizeof(int);

    msg1.msg_type = I2C_MSG_WRITE;
    msg1.addr = SLF3S_ADDR;
    msg1.flags = I2C_MSG_WRITE;
    msg1.data_len = 0;
    msg1.control = I2C_CMD_SET_I2C_BLOCKING;
    msg1.data = &iocb1;

    msg2.msg_type = I2C_MSG_WRITE;
    msg2.addr = SLF3S_ADDR;
    msg2.flags = I2C_MSG_WRITE;
    msg2.data_len = 0;
    msg2.control = I2C_CMD_SET_I2C_BLOCKING;
    msg2.data = &iocb2;

    rdwr_msg.msges = 2;
    rdwr_msg.msgs = &msg1;
    rdwr_msg.msgs += 1;
    rdwr_msg.msgs[1] = &msg2;

    if (ioctl(i2c_fd, I2C_RDWR, &rdwr_msg) < 0) {
        handle_error(i2c_fd, "Failed to set control registers");
    }

    if (ioctl(i2c_fd, I2C_START_MEAS, 0) < 0) {
        handle_error(i2c_fd, "Failed to start measurement");
    }

    usleep(100000); // Wait 100ms after start command

    while (1) {
        msg1.msg_type = I2C_MSG_READ;
        msg1.addr = SLF3S_ADDR;
        msg1.flags = I2C_MSG_READ;
        msg1.data_len = 0;
        msg1.data = &msg1;

        msg2.msg_type = I2C_MSG_READ;
        msg2.addr = SLF3S_ADDR;
        msg2.flags = I2C_MSG_READ;
        msg2.data_len = 0;
        msg2.data = &msg2;

        rdwr_msg.msges = 2;
        rdwr_msg.msgs = &msg1;
        rdwr_msg.msgs += 1;
        rdwr_msg.msgs[1] = &msg2;

        if (ioctl(i2c_fd, I2C_RDWR, &rdwr_msg) < 0) {
            handle_error(i2c_fd, "Failed to read from I2C");
        }

        if (msg1.data[0] == 0) {
            handle_error(i2c_fd, "Sensor 1 read error");
        } else if (msg2.data[0] == 0) {
            handle_error(i2c_fd, "Sensor 2 read error");
        }

        if (msg1.data[0] == 0) {
            SENSOR_DATA.sensor1_valid = 0;
        } else {
            SENSOR_DATA.sensor1_valid = 1;
            SENSOR_DATA.sensor1_avg += msg1.data[1] / 1000.0;
        }

        if (msg2.data[0] == 0) {
            SENSOR_DATA.sensor2_valid = 0;
        } else {
            SENSOR_DATA.sensor2_valid = 1;
            SENSOR_DATA.sensor2_avg += msg2.data[1] / 1000.0;
        }

        if (SENSOR_DATA.sensor1_valid && SENSOR_DATA.sensor2_valid) {
            SENSOR_DATA.alarm = 0;
            SENSOR_DATA.sensor1_avg /= 2.0;
            SENSOR_DATA.sensor2_avg /= 2.0;
            if (SENSOR_DATA.sensor1_avg < 0.5 || SENSOR_DATA.sensor2_avg < 0.5) {
                SENSOR_DATA.alarm = 1;
            }
        }

        FILE *log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            handle_error(i2c_fd, "Failed to open log file");
        }

        fprintf(log_file, "%f %f %f\n", SENSOR_DATA.sensor1_avg, SENSOR_DATA.sensor2_avg, SENSOR_DATA.alarm);
        fclose(log_file);

        if (SENSOR_DATA.alarm) {
            digitalWrite(GPIO17, HIGH);
        } else {
            digitalWrite(GPIO17, LOW);
        }

        usleep(1000000); // Wait 1 second
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <linux/i2c_smbus.h>
#include <gpiod.h>

#define BUFFER_SIZE 100
#define SAMPLE_INTERVAL 500000  // 50ms in microseconds

typedef struct {
    uint32_t timestamp;
    uint8_t state;
} Detection;

Detection buffer[BUFFER_SIZE];
int buffer_index = 0;
int buffer_full = 0;

int sensor_fd;
gpiod_device_t *dev;
gpiod_line_mixin_t *line_mixin;
gpiod_line_t *line;

void handle_signal(int sig) {
    if (sig == SIGINT) {
        // Release resources
        gpiod_line_unref(line);
        gpiod_line_mixin_unref(line_mixin);
        gpiod_device_unref(dev);
        close(sensor_fd);
        // Dump buffer
        for (int i = 0; i < BUFFER_SIZE; i++) {
            printf("%lu: %d\n", buffer[i].timestamp, buffer[i].state);
        }
        exit(EXIT_SUCCESS);
    }
}

int main() {
    // Register signal handler
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Open I2C device
    sensor_fd = open("/dev/i2c-1", O_RDWR);
    if (sensor_fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    // Set I2C address
    if (ioctl(sensor_fd, I2C_SLAVE, 0x21) < 0) {
        perror("Failed to set I2C address");
        exit(EXIT_FAILURE);
    }

    // Initialize I2C bus
    if (ioctl(sensor_fd, I2C_SLAVEX, 0) < 0) {
        perror("Failed to initialize I2C bus");
        exit(EXIT_FAILURE);
    }

    // Set up GPIO
    int line_number = 4; // GPIO4 (BCM pin 7)
    int gpio_fd = open("/dev/gpiod", O_RDWR);
    if (gpio_fd < 0) {
        perror("Failed to open GPIO device");
        exit(EXIT_FAILURE);
    }

    // Get device
    if (gpiod_get_device(gpio_fd, &dev) < 0) {
        perror("Failed to get device");
        exit(EXIT_FAILURE);
    }

    // Get line
    if (gpiod_get_line(dev, line_number, &line) < 0) {
        perror("Failed to get line");
        exit(EXIT_FAILURE);
    }

    // Set line to input with pull-up
    if (gpiod_line_set_mode(line, GPIOD_MODE_INPUT) < 0) {
        perror("Failed to set line mode");
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_set_pull(line, GPIOD_PULL_UP) < 0) {
        perror("Failed to set pull-up");
        exit(EXIT_FAILURE);
    }

    // Create line mixin
    if (gpiod_line_mixin_create(dev, &line_mixin) < 0) {
        perror("Failed to create line mixin");
        exit(EXIT_FAILURE);
    }

    // Add line to mixin
    if (gpiod_line_mixin_add(line_mixin, line) < 0) {
        perror("Failed to add line to mixin");
        exit(EXIT_FAILURE);
    }

    // Start mixin
    if (gpiod_line_mixin_start(line_mixin) < 0) {
        perror("Failed to start mixin");
        exit(EXIT_FAILURE);
    }

    // Initialize buffer
    memset(buffer, 0, sizeof(buffer));
    buffer_index = 0;
    buffer_full = 0;

    // Main loop
    while (1) {
        // Read sensor
        if (i2c_smbus_read_byte_data(sensor_fd, 0x00, &buffer_index)) {
            perror("Failed to read sensor");
            exit(EXIT_FAILURE);
        }

        // Check for detection
        if (buffer_index == 0) {
            if (line->value == 0) {
                // Obstacle detected
                buffer[buffer_index].timestamp = (uint32_t)time(NULL);
                buffer[buffer_index].state = 0;
                buffer_index = (buffer_index + 1) % BUFFER_SIZE;
                if (buffer_full) {
                    buffer_full = 0;
                } else {
                    buffer_full = 1;
                }
                printf("Detection at %lu\n", buffer[buffer_index].timestamp);
            } else {
                // No obstacle detected
                buffer[buffer_index].timestamp = (uint32_t)time(NULL);
                buffer[buffer_index].state = 1;
                buffer_index = (buffer_index + 1) % BUFFER_SIZE;
                if (buffer_full) {
                    buffer_full = 0;
                } else {
                    buffer_full = 1;
                }
            }
        } else {
            // Buffer is full, overwrite oldest entry
            if (buffer_full) {
                buffer[buffer_index].timestamp = (uint32_t)time(NULL);
                buffer[buffer_index].state = 1;
                buffer_index = (buffer_index + 1) % BUFFER_SIZE;
            } else {
                buffer[buffer_index].timestamp = (uint32_t)time(NULL);
                buffer[buffer_index].state = 1;
                buffer_index = (buffer_index + 1) % BUFFER_SIZE;
                buffer_full = 1;
            }
        }

        // Sleep for sample interval
        usleep(SAMPLE_INTERVAL);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <string.h>
#include <signal.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDR 0x38
#define I2C_MODE 0x00
#define I2C_START 0x01
#define I2C_STOP 0x00
#define I2C_READ 0x00
#define I2C_WRITE 0x01
#define I2C_REG 0x00
#define I2C_ACCEL_X 0x13
#define I2C_ACCEL_Y 0x14
#define I2C_ACCEL_Z 0x15
#define I2C_SAMPLE_RATE 0x10
#define I2C_SAMPLE_RATE_500HZ 0x01
#define I2C_SAMPLE_RATE_1000HZ 0x02
#define I2C_SAMPLE_RATE_2000HZ 0x03
#define I2C_SAMPLE_RATE_4000HZ 0x04
#define I2C_SAMPLE_RATE_8000HZ 0x05
#define I2C_SAMPLE_RATE_16000HZ 0x06
#define I2C_SAMPLE_RATE_32000HZ 0x07
#define I2C_SAMPLE_RATE_64000HZ 0x08

#define FAN_HEALTH_CSV "/home/pi/fan_health.csv"
#define FAN_HEALTH_CSV_HEADER "timestamp,X,Y,Z\n"

volatile sig_atomic_t running = 1;

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        if (close(i2c_fd) < 0) {
            perror("close i2c_fd");
            exit(EXIT_FAILURE);
        }
        if (close(csv_fd) < 0) {
            perror("close csv_fd");
            exit(EXIT_FAILURE);
        }
        running = 0;
    }
}

int main() {
    struct i2c_msg msg[2];
    struct i2c_rdlist request;
    struct i2c_rdlistroje *request_je;
    int i, ret;
    char buffer[9];
    char timestamp[24];
    double x, y, z;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("open i2c_fd");
        exit(EXIT_FAILURE);
    }

    ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR);
    if (ret < 0) {
        perror("ioctl I2C_SLAVE");
        exit(EXIT_FAILURE);
    }

    request_je = &request.je;
    request_je->request_count = 1;
    request_je->request_size = sizeof(struct i2c_rdlistroje);
    request_je->request = request_je;

    msg[0].addr = I2C_ADDR;
    msg[0].flags = I2C_M_RD;
    msg[0].data[0] = I2C_REG;
    msg[1].addr = I2C_ADDR;
    msg[1].flags = I2C_M_RD;
    msg[1].data[0] = I2C_ACCEL_X;

    request_je->request[0].addr = I2C_ADDR;
    request_je->request[0].flags = I2C_M_RD;
    request_je->request[0].data[0] = I2C_REG;
    request_je->request[1].addr = I2C_ADDR;
    request_je->request[1].flags = I2C_M_RD;
    request_je->request[1].data[0] = I2C_ACCEL_X;

    ret = ioctl(i2c_fd, I2C_RDWR, request);
    if (ret < 0) {
        perror("ioctl I2C_RDWR");
        exit(EXIT_FAILURE);
    }

    ret = ioctl(i2c_fd, I2C_START);
    if (ret < 0) {
        perror("ioctl I2C_START");
        exit(EXIT_FAILURE);
    }

    ret = ioctl(i2c_fd, I2C_STOP);
    if (ret < 0) {
        perror("ioctl I2C_STOP");
        exit(EXIT_FAILURE);
    }

    ret = ioctl(i2c_fd, I2C_MODE, I2C_MODE);
    if (ret < 0) {
        perror("ioctl I2C_MODE");
        exit(EXIT_FAILURE);
    }

    ret = ioctl(i2c_fd, I2C_START);
    if (ret < 0) {
        perror("ioctl I2C_START");
        exit(EXIT_FAILURE);
    }

    ret = ioctl(i2c_fd, I2C_SAMPLE_RATE, I2C_SAMPLE_RATE_1000HZ);
    if (ret < 0) {
        perror("ioctl I2C_SAMPLE_RATE");
        exit(EXIT_FAILURE);
    }

    ret = ioctl(i2c_fd, I2C_START);
    if (ret < 0) {
        perror("ioctl I2C_START");
        exit(EXIT_FAILURE);
    }

    while (running) {
        ret = ioctl(i2c_fd, I2C_READ, msg);
        if (ret < 0) {
            perror("ioctl I2C_READ");
            fprintf(stderr, "I2C read failed: %d\n", ret);
            continue;
        }

        for (i = 0; i < request_je->request_count; i++) {
            ret = read(i2c_fd, buffer, request_je->request[i].size);
            if (ret < 0) {
                perror("read");
                continue;
            }
            if (ret != request_je->request[i].size) {
                fprintf(stderr, "read size mismatch: %d\n", ret);
                continue;
            }

            switch (request_je->request[i].addr) {
                case I2C_REG:
                    strncpy(timestamp, buffer, 24);
                    break;
                case I2C_ACCEL_X:
                    x = *(double *)buffer;
                    break;
                case I2C_ACCEL_Y:
                    y = *(double *)buffer;
                    break;
                case I2C_ACCEL_Z:
                    z = *(double *)buffer;
                    break;
                default:
                    fprintf(stderr, "Unknown register: %d\n", request_je->request[i].addr);
                    continue;
            }

            if (csv_fd < 0) {
                csv_fd = open(FAN_HEALTH_CSV, O_CREAT | O_WRONLY | O_TRUNC, 0644);
                if (csv_fd < 0) {
                    perror("open FAN_HEALTH_CSV");
                    exit(EXIT_FAILURE);
                }
                if (write(csv_fd, FAN_HEALTH_CSV_HEADER, strlen(FAN_HEALTH_CSV_HEADER)) < 0) {
                    perror("write FAN_HEALTH_CSV_HEADER");
                    exit(EXIT_FAILURE);
                }
            }

            if (write(csv_fd, timestamp, strlen(timestamp)) < 0) {
                perror("write timestamp");
                continue;
            }
            if (write(csv_fd, ",") < 0) {
                perror("write comma");
                continue;
            }
            if (write(csv_fd, " ") < 0) {
                perror("write space");
                continue;
            }
            if (write(csv_fd, " ") < 0) {
                perror("write space");
                continue;
            }
            if (write(csv_fd, " ") < 0) {
                perror("write space");
                continue;
            }
            if (write(csv_fd, " ") < 0) {
                perror("write space");
                continue;
            }
            if (write(csv_fd, " ") < 0) {
                perror("write space");
                continue;
            }
            if (write(csv_fd, &x, sizeof(double)) < 0) {
                perror("write x");
                continue;
            }
            if (write(csv_fd, ",") < 0) {
                perror("write comma");
                continue;
            }
            if (write(csv_fd, " ") < 0) {
                perror("write space");
                continue;
            }
            if (write(csv_fd, " ") < 0) {
                perror("write space");
                continue;
            }
            if (write(csv_fd, " ") < 0) {
                perror("write space");
                continue;
            }
            if (write(csv_fd, " ") < 0) {
                perror("write space");
                continue;
            }
            if (write(csv_fd, " ") < 0) {
                perror("write space");
                continue;
            }
            if (write(csv_fd, &y, sizeof(double)) < 0) {
                perror("write y");
                continue;
            }
            if (write(csv_fd, ",") < 0) {
                perror("write comma");
                continue;
            }
            if (write(csv_fd, " ") < 0) {
                perror("write space");
                continue;
            }
            if (write(csv_fd, " ") < 0) {
                perror("write space");
                continue;
            }
            if (write(csv_fd, " ") < 0) {
                perror("write space");
                continue;
            }
            if (write(csv_fd, " ") < 0) {
                perror("write space");
                continue;
            }
            if (write(csv_fd, " ") < 0) {
                perror("write space");
                continue;
            }
            if (write(csv_fd, " ") < 0) {
                perror("write space");
                continue;
            }
            if (write(csv_fd, &z, sizeof(double)) < 0) {
                perror("write z");
                continue;
            }
            if (write(csv_fd, "\n") < 0) {
                perror("write newline");
                continue;
            }
        }

        usleep(500000);
    }

    if (close(i2c_fd) < 0) {
        perror("close i2c_fd");
        exit(EXIT_FAILURE);
    }
    if (close(csv_fd) < 0) {
        perror("close csv_fd");
        exit(EXIT_FAILURE);
    }

    return 0;
}

