#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/time.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <syslog.h>
#include <gpiod.h>

#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 18
#define STALL_LOG_FILE "stall_log.txt"
#define STALL_TIMEOUT 2000000  // 2 seconds in microseconds

typedef struct {
    int fd;
    struct gpiod_chip *chip;
    struct gpiod_line *line1;
    struct gpiod_line *line2;
    struct gpiod_event *event1;
    struct gpiod_event *event2;
    struct timeval start_time;
    struct timeval end_time;
} SensorMonitor;

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        if (monitor->fd != -1) {
            close(monitor->fd);
        }
        gpiod_chip_free(monitor->chip);
        gpiod_line_free(monitor->line1);
        gpiod_line_free(monitor->line2);
        gpiod_event_free(monitor->event1);
        gpiod_event_free(monitor->event2);
        free(monitor);
    }
    exit(EXIT_SUCCESS);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    SensorMonitor *monitor = malloc(sizeof(SensorMonitor));
    if (!monitor) {
        perror("Memory allocation failed");
        return EXIT_FAILURE;
    }

    int sensor1_fd = open("/dev/gpiod", O_RDONLY);
    if (sensor1_fd == -1) {
        perror("Failed to open gpiod device");
        return EXIT_FAILURE;
    }

    int sensor2_fd = open("/dev/gpiod", O_RDONLY);
    if (sensor2_fd == -1) {
        perror("Failed to open gpiod device");
        return EXIT_FAILURE;
    }

    if (ioctl(sensor1_fd, GIOP_IOCTL_GET_DEVICE, &monitor->chip) < 0) {
        perror("Failed to get device from gpiod");
        goto cleanup;
    }

    if (ioctl(sensor1_fd, GIOP_IOCTL_GET_LINE, &monitor->line1) < 0) {
        perror("Failed to get line from gpiod");
        goto cleanup;
    }

    if (ioctl(sensor1_fd, GIOP_IOCTL_GET_EVENT, &monitor->event1) < 0) {
        perror("Failed to get event from gpiod");
        goto cleanup;
    }

    if (ioctl(sensor2_fd, GIOP_IOCTL_GET_DEVICE, &monitor->chip) < 0) {
        perror("Failed to get device from gpiod");
        goto cleanup;
    }

    if (ioctl(sensor2_fd, GIOP_IOCTL_GET_LINE, &monitor->line2) < 0) {
        perror("Failed to get line from gpiod");
        goto cleanup;
    }

    if (ioctl(sensor2_fd, GIOP_IOCTL_GET_EVENT, &monitor->event2) < 0) {
        perror("Failed to get event from gpiod");
        goto cleanup;
    }

    monitor->fd = sensor1_fd;
    monitor->line1->direction = GPIOD_LINE_DIR_IN;
    monitor->line2->direction = GPIOD_LINE_DIR_IN;

    if (ioctl(monitor->line1->fd, GIOP_IOCTL_SET_LINE, &monitor->line1) < 0) {
        perror("Failed to set line direction");
        goto cleanup;
    }

    if (ioctl(monitor->line2->fd, GIOP_IOCTL_SET_LINE, &monitor->line2) < 0) {
        perror("Failed to set line direction");
        goto cleanup;
    }

    if (ioctl(monitor->event1->fd, GIOP_IOCTL_SET_EVENT, &monitor->event1) < 0) {
        perror("Failed to set event");
        goto cleanup;
    }

    if (ioctl(monitor->event2->fd, GIOP_IOCTL_SET_EVENT, &monitor->event2) < 0) {
        perror("Failed to set event");
        goto cleanup;
    }

    monitor->start_time.tv_sec = 0;
    monitor->start_time.tv_usec = 0;

    FILE *log_file = fopen(STALL_LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        goto cleanup;
    }

    while (1) {
        struct gpiod_event *event1 = gpiod_event_read(monitor->event1);
        struct gpiod_event *event2 = gpiod_event_read(monitor->event2);

        if (event1->value == 0 && event2->value == 0) {
            gettimeofday(&monitor->end_time, NULL);
            if ((monitor->end_time.tv_sec - monitor->start_time.tv_sec) * 1000000 +
                (monitor->end_time.tv_usec - monitor->start_time.tv_usec) >= STALL_TIMEOUT) {
                char log_entry[256];
                snprintf(log_entry, sizeof(log_entry), "%ld %ld\n", monitor->start_time.tv_sec,
                          monitor->start_time.tv_usec);
                if (fwrite(log_entry, 1, strlen(log_entry), log_file) != strlen(log_entry)) {
                    perror("Failed to write to log file");
                    goto cleanup;
                }
                monitor->start_time.tv_sec = 0;
                monitor->start_time.tv_usec = 0;
            }
        }

        if (ferror(log_file)) {
            perror("Error writing to log file");
            goto cleanup;
        }

        usleep(100000); // 100ms
    }

cleanup:
    if (monitor->fd != -1) {
        close(monitor->fd);
    }

    gpiod_chip_free(monitor->chip);
    gpiod_line_free(monitor->line1);
    gpiod_line_free(monitor->line2);
    gpiod_event_free(monitor->event1);
    gpiod_event_free(monitor->event2);
    free(monitor);

    if (log_file) {
        fclose(log_file);
    }

    return EXIT_SUCCESS;
}

