#include <stdint.h>
#include <stdbool.h>

#define TMAG5170_ADDR 0x0e
#define TMAG5170_CNTL_REG 0x00
#define TMAG5170_XOUT_REG 0x01
#define TMAG5170_YOUT_REG 0x02
#define TMAG5170_ZOUT_REG 0x03
#define TMAG5170_CNTL_REG_MASK 0x7F
#define TMAG5170_CNTL_REG_ENABLE 0x80

#define I2C_BUS "/dev/i2c-1"

typedef struct {
    int i2c_fd;
    int x, y, z;
    bool initialized;
    bool csv_opened;
    FILE *csv_file;
} TMAG5170;

void handle_sigint(int signum) {
    if (TMAG5170->csv_opened) {
        fclose(TMAG5170->csv_file);
    }
    if (TMAG5170->i2c_fd > 0) {
        close(TMAG5170->i2c_fd);
    }
    if (TMAG5170->csv_file) {
        free(TMAG5170->csv_file);
    }
    TMAG5170->initialized = false;
    TMAG5170->csv_opened = false;
    free(TMAG5170);
}

int main() {
    TMAG5170 *tmag5170 = malloc(sizeof(TMAG5170));
    if (!tmag5170) {
        perror("Memory allocation failed");
        return 1;
    }

    tmag5170->i2c_fd = open(I2C_BUS, O_RDWR);
    if (tmag5170->i2c_fd < 0) {
        perror("Failed to open I2C bus");
        free(tmag5170);
        return 1;
    }

    if (ioctl(tmag5170->i2c_fd, I2C_SLAVE, TMAG5170_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        free(tmag5170);
        return 1;
    }

    tmag5170->initialized = true;

    // Configure sensor
    uint8_t config = 0x00;
    config |= TMAG5170_CNTL_REG_ENABLE;
    if (ioctl(tmag5170->i2c_fd, I2C_RDWR, &config, TMAG5170_ADDR) < 0) {
        perror("Failed to configure sensor");
        free(tmag5170);
        return 1;
    }

    // Enable continuous conversion mode
    config = 0x01;
    if (ioctl(tmag5170->i2c_fd, I2C_RDWR, &config, TMAG5170_ADDR) < 0) {
        perror("Failed to enable continuous conversion mode");
        free(tmag5170);
        return 1;
    }

    // Enable all three axes
    config = 0x03;
    if (ioctl(tmag5170->i2c_fd, I2C_RDWR, &config, TMAG5170_ADDR) < 0) {
        perror("Failed to enable all three axes");
        free(tmag5170);
        return 1;
    }

    // Set range to 50 mT
    config = 0x04;
    if (ioctl(tmag5170->i2c_fd, I2C_RDWR, &config, TMAG5170_ADDR) < 0) {
        perror("Failed to set range to 50 mT");
        free(tmag5170);
        return 1;
    }

    // Read initial values
    tmag5170->x = tmag5170->y = tmag5170->z = 0;
    if (ioctl(tmag5170->i2c_fd, I2C_RDWR, &tmag5170->x, TMAG5170_ADDR) < 0) {
        perror("Failed to read initial X value");
        free(tmag5170);
        return 1;
    }
    if (ioctl(tmag5170->i2c_fd, I2C_RDWR, &tmag5170->y, TMAG5170_ADDR) < 0) {
        perror("Failed to read initial Y value");
        free(tmag5170);
        return 1;
    }
    if (ioctl(tmag5170->i2c_fd, I2C_RDWR, &tmag5170->z, TMAG5170_ADDR) < 0) {
        perror("Failed to read initial Z value");
        free(tmag5170);
        return 1;
    }

    // Open CSV file
    tmag5170->csv_file = fopen("magnetic_log.csv", "a");
    if (!tmag5170->csv_file) {
        perror("Failed to open CSV file for writing");
        free(tmag5170);
        return 1;
    }
    if (!fputs("timestamp,X,Y,Z\n", tmag5170->csv_file)) {
        perror("Failed to write header row");
        free(tmag5170);
        return 1;
    }

    // Register SIGINT handler
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to register SIGINT handler");
        free(tmag5170);
        return 1;
    }

    // Main loop
    while (1) {
        // Read sensor values
        if (ioctl(tmag5170->i2c_fd, I2C_RDWR, &tmag5170->x, TMAG5170_ADDR) < 0) {
            perror("Failed to read X value");
            continue;
        }
        if (ioctl(tmag5170->i2c_fd, I2C_RDWR, &tmag5170->y, TMAG5170_ADDR) < 0) {
            perror("Failed to read Y value");
            continue;
        }
        if (ioctl(tmag5170->i2c_fd, I2C_RDWR, &tmag5170->z, TMAG5170_ADDR) < 0) {
            perror("Failed to read Z value");
            continue;
        }

        // Read timestamp
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", localtime(&now));

        // Write to CSV file
        if (fprintf(tmag5170->csv_file, "%s,%d,%d,%d\n", timestamp, tmag5170->x, tmag5170->y, tmag5170->z) < 0) {
            perror("Failed to write to CSV file");
            free(tmag5170);
            return 1;
        }

        // Sleep for 100 ms
        usleep(100000);
    }

    free(tmag5170);
    return 0;
}

