#include <sys/stat.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO17 17
#define GPIO27 27
#define LOG_FILE "rotation_log.txt"
#define LOG_FORMAT "%Y-%m-%d %H:%M:%S.%03d"

typedef struct {
    int fd;
    int sensorA;
    int sensorB;
    int state;
    int prevState;
    int direction;
    int logFile;
    struct timespec logTime;
    sem_t mutex;
} SensorData;

static void *sensorHandler(void *data) {
    SensorData *sensor = (SensorData *)data;
    int sensorA = sensor->sensorA;
    int sensorB = sensor->sensorB;
    int state = sensor->state;
    int prevState = sensor->prevState;
    int direction = sensor->direction;
    int logFile = sensor->logFile;
    struct timespec logTime = sensor->logTime;

    while (1) {
        int edgeA = gpiod_get_edge(sensorA);
        int edgeB = gpiod_get_edge(sensorB);

        if (edgeA != prevState || edgeB != prevState) {
            sensor->prevState = edgeA;
            sensor->prevState = edgeB;

            if (edgeA && edgeB) {
                sensor->state = 1;
            } else if (!edgeA && !edgeB) {
                sensor->state = 0;
            } else {
                sensor->state = 3 - (edgeA + edgeB);
            }

            if (sensor->state != prevState) {
                sensor->direction = (sensor->state - prevState) / 2;
                prevState = sensor->state;

                if (sensor->logFile > 0) {
                    char buffer[128];
                    if (clock_gettime(CLOCK_MONOTONIC, &sensor->logTime) == 0) {
                        if (snprintf(buffer, sizeof(buffer), LOG_FORMAT, sensor->logTime.tv_sec, sensor->logTime.tv_nsec / 1000000LLU) == 0) {
                            if (write(sensor->logFile, buffer, strlen(buffer)) == strlen(buffer)) {
                                sem_post(&sensor->mutex);
                            }
                        }
                    }
                }
            }
        }
    }
    return NULL;
}

static void *logHandler(void *data) {
    SensorData *sensor = (SensorData *)data;
    int logFile = sensor->logFile;

    while (1) {
        sem_wait(&sensor->mutex);
        if (logFile > 0) {
            if (clock_gettime(CLOCK_MONOTONIC, &sensor->logTime) == 0) {
                if (snprintf(buffer, sizeof(buffer), LOG_FORMAT, sensor->logTime.tv_sec, sensor->logTime.tv_nsec / 1000000LLU) == 0) {
                    if (write(logFile, buffer, strlen(buffer)) == strlen(buffer)) {
                        sem_post(&sensor->mutex);
                    }
                }
            }
        }
        sem_post(&sensor->mutex);
        usleep(1000); // 1ms
    }
    return NULL;
}

