#include <sys/ioctl.h>
#include <sys/i2c.h>
#include <sys/stat.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x00
#define I2C_SENSOR 0x00
#define I2C_REG_HEART_RATE 0x00
#define I2C_REG_SPO2 0x01
#define I2C_REG_CONTROL 0x02

#define I2C_TIMEOUT 100

typedef struct {
    int fd;
    int i2c_fd;
    int spo2;
    int heart_rate;
} BiometricSensor;

BiometricSensor sensor;

void handle_sigint(int signum) {
    if (sensor.fd > 0) {
        close(sensor.fd);
    }
    if (sensor.i2c_fd > 0) {
        close(sensor.i2c_fd);
    }
    if (sensor.spo2 > 0) {
        close(sensor.spo2);
    }
    if (sensor.heart_rate > 0) {
        close(sensor.heart_rate);
    }
    exit(0);
}

int i2c_read(int fd, int addr, int reg, int *value) {
    struct i2c_msg msg[1];
    struct i2c_rdma_request req;
    struct i2c_rdma_return ret;

    msg[0].addr = addr;
    msg[0].flags = I2C_M_RD;
    msg[0].len = 1;
    msg[0].data[0] = reg;

    req.request = msg[0].data[0];
    req.addr = addr;
    req.flags = I2C_RDMA_RDMA_READ;
    req.rdma = I2C_RDMA_RDMA1;

    ret = ioctl(fd, I2C_RDWR, &req);

    if (ret < 0) {
        perror("i2c_read");
        return -1;
    }

    *value = msg[0].data[0];
    return 0;
}

int i2c_write(int fd, int addr, int reg, int value) {
    struct i2c_msg msg[1];
    struct i2c_rdma_request req;
    struct i2c_rdma_return ret;

    msg[0].addr = addr;
    msg[0].flags = I2C_M_RD;
    msg[0].len = 1;
    msg[0].data[0] = reg;
    msg[0].data[1] = value;

    req.request = msg[0].data[0];
    req.addr = addr;
    req.flags = I2C_RDMA_RDMA_WRITE;
    req.rdma = I2C_RDMA_RDMA1;

    ret = ioctl(fd, I2C_RDWR, &req);

    if (ret < 0) {
        perror("i2c_write");
        return -1;
    }

    return 0;
}

int main() {
    struct stat st;
    char filename[128];
    time_t now;
    struct tm *timeinfo;
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    sensor.fd = fd;
    sensor.i2c_fd = fd;

    if (ioctl(sensor.i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("ioctl");
        return 1;
    }

    if (i2c_write(sensor.i2c_fd, I2C_ADDR, I2C_REG_CONTROL, 0x01) < 0) {
        perror("i2c_write");
        return 1;
    }

    if (i2c_read(sensor.i2c_fd, I2C_ADDR, I2C_REG_HEART_RATE, &sensor.heart_rate) < 0) {
        perror("i2c_read");
        return 1;
    }

    if (i2c_read(sensor.i2c_fd, I2C_ADDR, I2C_REG_SPO2, &sensor.spo2) < 0) {
        perror("i2c_read");
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (1) {
        now = time(NULL);
        timeinfo = localtime(&now);
        strftime(filename, sizeof(filename), "%Y-%m-%d %H:%M:%S", timeinfo);
        fprintf(stderr, "Reading biometric data...\n");
        fprintf(stderr, "Heart Rate: %d BPM, SpO2: %d%%\n", sensor.heart_rate, sensor.spo2);
        fprintf(stderr, "Writing to log file...\n");

        snprintf(filename, sizeof(filename), "%s, Heart Rate: %d BPM, SpO2: %d%%", filename, sensor.heart_rate, sensor.spo2);
        FILE *log_file = fopen(filename, "a");
        if (log_file == NULL) {
            perror("fopen");
            continue;
        }
        fprintf(log_file, "%s\n", filename);
        fflush(log_file);
        fclose(log_file);

        usleep(1000000); // 1 second delay

        if (i2c_read(sensor.i2c_fd, I2C_ADDR, I2C_REG_HEART_RATE, &sensor.heart_rate) < 0) {
            perror("i2c_read");
            continue;
        }

        if (i2c_read(sensor.i2c_fd, I2C_ADDR, I2C_REG_SPO2, &sensor.spo2) < 0) {
            perror("i2c_read");
            continue;
        }
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/time.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO17 17
#define GPIO18 18
#define GPIO27 27
#define LOG_FILE "bridge_integrity.log"
#define SENSOR_TILT_START "tilt-start"
#define SENSOR_THRESHOLD_EXCEEDED "threshold-exceeded"
#define SENSOR_TILT_END "tilt-end"
#define ALARM_ACTIVE_HIGH 1
#define ALARM_ACTIVE_LOW 0
#define ALARM_TIMEOUT 2000  // 2 seconds

typedef struct {
    int fd;
    struct gpiod_handle handle;
    struct gpiod_line *line;
    struct gpiod_event *event;
} GPIODevice;

typedef struct {
    char event_name[256];
    int value;
    time_t timestamp;
} SensorEvent;

void alarm_handler(int sig) {
    if (GPIODevice->line) {
        gpiod_line_set_value(GPIODevice->line, ALARM_ACTIVE_HIGH);
    }
    close(GPIODevice->fd);
    exit(EXIT_SUCCESS);
}

void cleanup_gpio_device(GPIODevice *device) {
    if (device->line) {
        gpiod_line_free(device->line);
    }
    gpiod_handle_free(device->handle);
    close(device->fd);
}

int main() {
    GPIODevice device;
    int sensor1_value, sensor2_value;
    SensorEvent event;
    char log_buffer[256];
    char log_line[256];
    time_t current_time;
    struct tm *time_info;
    int alarm_active = 0;
    int alarm_timeout = 0;

    // Initialize GPIO device for sensor 1
    device.fd = gpiod_open(GPIO1, O_RDWR);
    if (device.fd == -1) {
        perror("gpiod_open failed");
        return EXIT_FAILURE;
    }

    device.handle = gpiod_init();
    if (device.handle == NULL) {
        perror("gpiod_init failed");
        gpiod_close(device.fd);
        return EXIT_FAILURE;
    }

    device.line = gpiod_new_line(device.handle, GPIO1, GPIO1, GPIO_DIN);
    if (device.line == NULL) {
        perror("gpiod_new_line failed");
        gpiod_close(device.fd);
        gpiod_handle_free(device.handle);
        return EXIT_FAILURE;
    }

    gpiod_line_request_event(device.line, SENSOR_TILT_START, &event);
    gpiod_line_request_event(device.line, SENSOR_THRESHOLD_EXCEEDED, &event);
    gpiod_line_request_event(device.line, SENSOR_TILT_END, &event);

    if (gpiod_line_request(device.line) < 0) {
        perror("gpiod_line_request failed");
        gpiod_close(device.fd);
        gpiod_handle_free(device.handle);
        return EXIT_FAILURE;
    }

    // Initialize GPIO device for sensor 2
    device.fd = gpiod_open(GPIO2, O_RDWR);
    if (device.fd == -1) {
        perror("gpiod_open failed");
        gpiod_close(device.fd);
        gpiod_handle_free(device.handle);
        return EXIT_FAILURE;
    }

    device.handle = gpiod_init();
    if (device.handle == NULL) {
        perror("gpiod_init failed");
        gpiod_close(device.fd);
        return EXIT_FAILURE;
    }

    device.line = gpiod_new_line(device.handle, GPIO2, GPIO2, GPIO_DIN);
    if (device.line == NULL) {
        perror("gpiod_new_line failed");
        gpiod_close(device.fd);
        gpiod_handle_free(device.handle);
        return EXIT_FAILURE;
    }

    gpiod_line_request_event(device.line, SENSOR_TILT_START, &event);
    gpiod_line_request_event(device.line, SENSOR_THRESHOLD_EXCEEDED, &event);
    gpiod_line_request_event(device.line, SENSOR_TILT_END, &event);

    if (gpiod_line_request(device.line) < 0) {
        perror("gpiod_line_request failed");
        gpiod_close(device.fd);
        gpiod_handle_free(device.handle);
        return EXIT_FAILURE;
    }

    // Initialize GPIO device for alarm
    device.fd = gpiod_open(GPIO3, O_RDWR);
    if (device.fd == -1) {
        perror("gpiod_open failed");
        gpiod_close(device.fd);
        gpiod_handle_free(device.handle);
        return EXIT_FAILURE;
    }

    device.handle = gpiod_init();
    if (device.handle == NULL) {
        perror("gpiod_init failed");
        gpiod_close(device.fd);
        return EXIT_FAILURE;
    }

    device.line = gpiod_new_line(device.handle, GPIO3, GPIO3, GPIO_DIN);
    if (device.line == NULL) {
        perror("gpiod_new_line failed");
        gpiod_close(device.fd);
        gpiod_handle_free(device.handle);
        return EXIT_FAILURE;
    }

    gpiod_line_request_event(device.line, ALARM_ACTIVE_HIGH, &event);
    if (gpiod_line_request(device.line) < 0) {
        perror("gpiod_line_request failed");
        gpiod_close(device.fd);
        gpiod_handle_free(device.handle);
        return EXIT_FAILURE;
    }

    alarm_handler(SIGINT);
    alarm_handler(SIGTERM);

    while (1) {
        // Read sensor 1 value
        if (gpiod_line_get_value(device.line, GPIO1, &sensor1_value) < 0) {
            perror("gpiod_line_get_value failed");
            gpiod_close(device.fd);
            gpiod_handle_free(device.handle);
            return EXIT_FAILURE;
        }

        // Read sensor 2 value
        if (gpiod_line_get_value(device.line, GPIO2, &sensor2_value) < 0) {
            perror("gpiod_line_get_value failed");
            gpiod_close(device.fd);
            gpiod_handle_free(device.handle);
            return EXIT_FAILURE;
        }

        // Check for tilt start event
        if (sensor1_value == ALARM_ACTIVE_HIGH || sensor2_value == ALARM_ACTIVE_HIGH) {
            alarm_active = 1;
            alarm_timeout = 0;
        } else {
            alarm_active = 0;
        }

        // Check for threshold exceeded event
        if (sensor1_value == ALARM_ACTIVE_HIGH && sensor2_value == ALARM_ACTIVE_HIGH) {
            event.value = 1;
            event.timestamp = time(NULL);
            snprintf(log_line, sizeof(log_line), "%s,%s,%s", event_name, event_name, event_name);
            write(device.fd, log_line, strlen(log_line));
            alarm_timeout = ALARM_TIMEOUT;
        } else {
            alarm_timeout = 0;
        }

        // Check for tilt end event
        if (sensor1_value == ALARM_ACTIVE_LOW && sensor2_value == ALARM_ACTIVE_LOW) {
            event.value = 0;
            event.timestamp = time(NULL);
            snprintf(log_line, sizeof(log_line), "%s,%s,%s", event_name, event_name, event_name);
            write(device.fd, log_line, strlen(log_line));
            alarm_active = 0;
        }

        // Log current time
        current_time = time(NULL);
        time_info = localtime(&current_time);
        snprintf(log_buffer, sizeof(log_buffer), "%s,%d,%d", asctime(time_info), sensor1_value, sensor2_value);
        write(device.fd, log_buffer, strlen(log_buffer));

        // Sleep for 100 ms
        usleep(100000);

        // Check for alarm timeout
        if (alarm_timeout > 0) {
            alarm_timeout--;
            if (alarm_timeout == 0) {
                event.value = 0;
                event.timestamp = time(NULL);
                snprintf(log_line, sizeof(log_line), "%s,%s,%s", event_name, event_name, event_name);
                write(device.fd, log_line, strlen(log_line));
                alarm_active = 0;
            }
        }
    }

    return EXIT_SUCCESS;
}

