#define I2C_BUS 1
#define SEIS_ADDR 0x40
#define SEIS_CTRL1 0x01
#define SEIS_CTRL2 0x02
#define SEIS_CTRL3 0x03
#define SEIS_CTRL4 0x04
#define SEIS_CTRL5 0x05
#define SEIS_CTRL6 0x06
#define SEIS_CTRL7 0x07
#define SEIS_CTRL8 0x08
#define SEIS_CTRL9 0x09
#define SEIS_CTRL10 0x0A
#define SEIS_CTRL11 0x0B
#define SEIS_CTRL12 0x0C
#define SEIS_CTRL13 0x0D
#define SEIS_CTRL14 0x0E
#define SEIS_CTRL15 0x0F
#define SEIS_CTRL16 0x10
#define SEIS_CTRL17 0x11
#define SEIS_CTRL18 0x12
#define SEIS_CTRL19 0x13
#define SEIS_CTRL20 0x14
#define SEIS_CTRL21 0x15
#define SEIS_CTRL22 0x16
#define SEIS_CTRL23 0x17
#define SEIS_CTRL24 0x18
#define SEIS_CTRL25 0x19
#define SEIS_CTRL26 0x1A
#define SEIS_CTRL27 0x1B
#define SEIS_CTRL28 0x1C
#define SEIS_CTRL29 0x1D
#define SEIS_CTRL30 0x1E
#define SEIS_CTRL31 0x1F
#define SEIS_DATA0 0x00
#define SEIS_DATA1 0x01
#define SEIS_DATA2 0x02
#define SEIS_DATA3 0x03
#define SEIS_DATA4 0x04
#define SEIS_DATA5 0x05
#define SEIS_DATA6 0x06
#define SEIS_DATA7 0x07
#define SEIS_DATA8 0x08
#define SEIS_DATA9 0x09
#define SEIS_DATA10 0x0A
#define SEIS_DATA11 0x0B
#define SEIS_DATA12 0x0C
#define SEIS_DATA13 0x0D
#define SEIS_DATA14 0x0E
#define SEIS_DATA15 0x0F

#define SEIS_VIBRATION_THRESHOLD 500
#define SEIS_ALERT_LED 17

#define I2C_DEVICE "/dev/i2c-" I2C_BUS

typedef struct {
    int fd;
    int retries;
    int last_error;
} I2CHandle;

I2CHandle i2c_handle;

void i2c_init() {
    i2c_handle.fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_handle.fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }
}

void i2c_read(int addr, int reg, void *buf, int size) {
    struct i2c_msg msg[1];
    struct i2c_rdma_request req;
    msg[0].addr = addr;
    msg[0].flags = I2C_M_RD;
    msg[0].data[0] = reg;
    msg[0].len = size;
    req.request = msg[0].data;
    req.request_size = msg[0].len;

    if (ioctl(i2c_handle.fd, I2C_RDWR, req) < 0) {
        i2c_handle.retries++;
        i2c_handle.last_error = errno;
        if (i2c_handle.retries > 3) {
            perror("Failed to read from I2C device");
            exit(EXIT_FAILURE);
        }
        i2c_read(addr, reg, buf, size);
    } else {
        memcpy(buf, msg[0].data, size);
    }
}

void i2c_write(int addr, int reg, void *buf, int size) {
    struct i2c_msg msg[1];
    struct i2c_rdma_request req;
    msg[0].addr = addr;
    msg[0].flags = I2C_M_WRITE;
    msg[0].data[0] = reg;
    msg[0].len = size;
    memcpy(msg[0].data + 1, buf, size);
    req.request = msg[0].data;
    req.request_size = msg[0].len;

    if (ioctl(i2c_handle.fd, I2C_RDWR, req) < 0) {
        i2c_handle.retries++;
        i2c_handle.last_error = errno;
        if (i2c_handle.retries > 3) {
            perror("Failed to write to I2C device");
            exit(EXIT_FAILURE);
        }
        i2c_write(addr, reg, buf, size);
    }
}

void i2c_clear_power_down() {
    i2c_write(SEIS_ADDR, SEIS_CTRL1, &0x00, sizeof(int));
}

void i2c_check_sensor_presence() {
    i2c_read(SEIS_ADDR, SEIS_DATA0, &i2c_handle.last_error, sizeof(int));
    if (i2c_handle.last_error == 0) {
        i2c_clear_power_down();
    } else {
        perror("Failed to read sensor data");
        exit(EXIT_FAILURE);
    }
}

void i2c_poll_sensor() {
    i2c_check_sensor_presence();
    i2c_read(SEIS_ADDR, SEIS_DATA0, &i2c_handle.last_error, sizeof(int));
    if (i2c_handle.last_error == 0) {
        int vibration = 0;
        for (int i = 0; i < 8; i++) {
            vibration += i2c_read(SEIS_ADDR, SEIS_DATAi, &i2c_handle.last_error, sizeof(int));
        }
        vibration /= 8;
        if (vibration > SEIS_VIBRATION_THRESHOLD) {
            // Log event
            char timestamp[26];
            struct tm *now = localtime(&time(NULL));
            strftime(timestamp, 26, "%Y-%m-%d %H:%M:%S", now);
            FILE *log_file = fopen("seismic_events.log", "a");
            if (log_file) {
                fprintf(log_file, "%s %d\n", timestamp, vibration);
                fclose(log_file);
            } else {
                perror("Failed to open log file");
                exit(EXIT_FAILURE);
            }

            // Turn on alert LED
            if (gpio_led_on(SEIS_ALERT_LED)) {
                perror("Failed to turn on LED");
                exit(EXIT_FAILURE);
            }
            usleep(1000000); // 1 second
            if (gpio_led_off(SEIS_ALERT_LED)) {
                perror("Failed to turn off LED");
                exit(EXIT_FAILURE);
            }
        }
    } else {
        perror("Failed to read sensor data");
        exit(EXIT_FAILURE);
    }
}

int gpio_led_on(int pin) {
    int fd = open("/dev/gpiod", O_RDWR);
    if (fd < 0) {
        perror("Failed to open GPIO driver");
        return 1;
    }
    struct gpiod_chip *chip = gpiod_chip_open(fd);
    if (!chip) {
        perror("Failed to open GPIO driver chip");
        close(fd);
        return 1;
    }
    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        perror("Failed to find GPIO line");
        close(fd);
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_set_direction(line, GPIOD_LINE_DIR_OUT)) {
        perror("Failed to set GPIO direction");
        close(fd);
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_set_value(line, 1)) {
        perror("Failed to set GPIO value");
        close(fd);
        gpiod_chip_close(chip);
        return 1;
    }
    close(fd);
    gpiod_chip_close(chip);
    return 0;
}

int gpio_led_off(int pin) {
    int fd = open("/dev/gpiod", O_RDWR);
    if (fd < 0) {
        perror("Failed to open GPIO driver");
        return 1;
    }
    struct gpiod_chip *chip = gpiod_chip_open(fd);
    if (!chip) {
        perror("Failed to open GPIO driver chip");
        close(fd);
        return 1;
    }
    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        perror("Failed to find GPIO line");
        close(fd);
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_set_direction(line, GPIOD_LINE_DIR_OUT)) {
        perror("Failed to set GPIO direction");
        close(fd);
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_set_value(line, 0)) {
        perror("Failed to set GPIO value");
        close(fd);
        gpiod_chip_close(chip);
        return 1;
    }
    close(fd);
    gpiod_chip_close(chip);
    return 0;
}

void signal_handler(int signum) {
    if (i2c_handle.fd > 0) {
        close(i2c_handle.fd);
    }
    if (i2c_handle.retries > 0) {
        printf("I2C handle closed after %d retries\n", i2c_handle.retries);
    }
    if (fopen("seismic_events.log", "r") == NULL) {
        perror("Failed to close log file");
    }
    exit(EXIT_SUCCESS);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_init();
    i2c_poll_sensor();

    while (1) {
        usleep(100000); // 100 ms
    }

    return 0;
}

