#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <linux/i2c_smbus.h>
#include <gpiod.h>

#define I2C_ADDR 0x3C
#define TOUCH_LOG_FILE "touch_log.txt"
#define LED_PIN 17
#define CHANNELS 8
#define DEBOUNCE_TIME 500000  // 50ms

int touch_fd;
gpiod_device_t *touch_dev;
gpiod_line_mixin_t *touch_line_mixin;
gpiod_line_mixin_state_t *touch_line_mixin_state;
gpiod_line_mixin_event_t *touch_line_mixin_event;
gpiod_line_mixin_event_callback_t *touch_line_mixin_event_callback;

void handle_touch_event(int channel, int state) {
    char timestamp[20];
    struct tm *timeinfo;
    time_t rawtime;
    rawtime = time(NULL);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
    char log_entry[100];
    snprintf(log_entry, 100, "%s – Channel %d Touched", timestamp, channel);
    FILE *log_file = fopen(TOUCH_LOG_FILE, "a");
    if (log_file) {
        fprintf(log_file, "%s\n", log_entry);
        fclose(log_file);
    } else {
        perror("Error writing to touch_log.txt");
        exit(EXIT_FAILURE);
    }

    if (state == 1) {
        // Turn LED on
        if (gpiod_line_mixin_state_get_value(touch_line_mixin_state, LED_PIN) == 0) {
            gpiod_line_mixin_state_set_value(touch_line_mixin_state, LED_PIN, 1);
        }
    } else {
        // Turn LED off
        if (gpiod_line_mixin_state_get_value(touch_line_mixin_state, LED_PIN) == 1) {
            gpiod_line_mixin_state_set_value(touch_line_mixin_state, LED_PIN, 0);
        }
    }
}

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        // Release resources
        gpiod_line_mixin_state_free(touch_line_mixin_state);
        gpiod_line_mixin_event_free(touch_line_mixin_event);
        gpiod_line_mixin_free(touch_line_mixin);
        gpiod_device_free(touch_dev);
        if (touch_fd > 0) {
            close(touch_fd);
        }
        exit(EXIT_SUCCESS);
    }
}

int main() {
    struct i2c_msg messages[1];
    struct i2c_rdwr_ioctl_msg ioctl_msg;
    char buffer[8];
    int status;

    // Initialize touch sensor
    touch_fd = open("/dev/i2c-1", O_RDWR);
    if (touch_fd < 0) {
        perror("Error opening i2c device");
        exit(EXIT_FAILURE);
    }
    status = ioctl(touch_fd, I2C_SLAVE, I2C_ADDR);
    if (status < 0) {
        perror("Error setting i2c slave address");
        exit(EXIT_FAILURE);
    }

    // Read touch sensor configuration
    messages[0].addr = I2C_ADDR;
    messages[0].data[0] = 0x00;
    messages[0].data[1] = 0x00;
    messages[0].data[2] = 0x00;
    messages[0].data[3] = 0x00;
    messages[0].data[4] = 0x00;
    messages[0].data[5] = 0x00;
    messages[0].data[6] = 0x00;
    messages[0].data[7] = 0x00;
    messages[0].size = 8;
    ioctl_msg.msgs = messages;
    ioctl_msg.nummsgs = 1;
    status = i2c_rdwr(&ioctl_msg);
    if (status < 0) {
        perror("Error reading touch sensor configuration");
        exit(EXIT_FAILURE);
    }

    // Set touch sensor to 8-channel mode
    messages[0].addr = I2C_ADDR;
    messages[0].data[0] = 0x00;
    messages[0].data[1] = 0x00;
    messages[0].data[2] = 0x00;
    messages[0].data[3] = 0x00;
    messages[0].data[4] = 0x00;
    messages[0].data[5] = 0x00;
    messages[0].data[6] = 0x00;
    messages[0].data[7] = 0x00;
    messages[0].size = 8;
    messages[0].flags = I2C_MSG_READ | I2C_MSG_WRITE;
    ioctl_msg.msgs = messages;
    ioctl_msg.nummsgs = 1;
    status = i2c_rdwr(&ioctl_msg);
    if (status < 0) {
        perror("Error setting touch sensor to 8-channel mode");
        exit(EXIT_FAILURE);
    }

    // Read touch sensor data
    messages[0].addr = I2C_ADDR;
    messages[0].data[0] = 0x00;
    messages[0].data[1] = 0x00;
    messages[0].data[2] = 0x00;
    messages[0].data[3] = 0x00;
    messages[0].data[4] = 0x00;
    messages[0].data[5] = 0x00;
    messages[0].data[6] = 0x00;
    messages[0].data[7] = 0x00;
    messages[0].size = 8;
    messages[0].flags = I2C_MSG_READ;
    ioctl_msg.msgs = messages;
    ioctl_msg.nummsgs = 1;
    status = i2c_read_i2c_device(touch_fd, &ioctl_msg);
    if (status < 0) {
        perror("Error reading touch sensor data");
        exit(EXIT_FAILURE);
    }

    // Initialize GPIO driver
    touch_dev = gpiod_new_device();
    if (!touch_dev) {
        perror("Error creating GPIO device");
        exit(EXIT_FAILURE);
    }

    touch_line_mixin = gpiod_new_line_mixin(touch_dev);
    if (!touch_line_mixin) {
        perror("Error creating GPIO line mixin");
        exit(EXIT_FAILURE);
    }

    touch_line_mixin_state = gpiod_line_mixin_state_new(touch_line_mixin);
    if (!touch_line_mixin_state) {
        perror("Error creating GPIO line mixin state");
        exit(EXIT_FAILURE);
    }

    touch_line_mixin_event = gpiod_line_mixin_event_new(touch_line_mixin, touch_line_mixin_state);
    if (!touch_line_mixin_event) {
        perror("Error creating GPIO line mixin event");
        exit(EXIT_FAILURE);
    }

    touch_line_mixin_event_callback = gpiod_line_mixin_event_callback_new(touch_line_mixin_event, handle_touch_event);
    if (!touch_line_mixin_event_callback) {
        perror("Error creating GPIO line mixin event callback");
        exit(EXIT_FAILURE);
    }

    gpiod_line_mixin_event_callback_add(touch_line_mixin_event, touch_line_mixin_event_callback);

    // Set GPIO pins to input with pull-down resistors
    for (int i = 0; i < CHANNELS; i++) {
        gpiod_line_mixin_line_new(touch_line_mixin, i, 2, GPIOD_LINE_ACTIVE_LOW, GPIOD_LINE_PUD_DOWN);
    }

    // Set GPIO pin for LED to output
    gpiod_line_mixin_line_new(touch_line_mixin, LED_PIN, 1, GPIOD_LINE_ACTIVE_LOW, GPIOD_LINE_OUTPUT);

    // Set signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Main loop
    while (1) {
        // Read touch sensor data
        messages[0].addr = I2C_ADDR;
        messages[0].data[0] = 0x00;
        messages[0].data[1] = 0x00;
        messages[0].data[2] = 0x00;
        messages[0].data[3] = 0x00;
        messages[0].data[4] = 0x00;
        messages[0].data[5] = 0x00;
        messages[0].data[6] = 0x00;
        messages[0].data[7] = 0x00;
        messages[0].size = 8;
        messages[0].flags = I2C_MSG_READ;
        ioctl_msg.msgs = messages;
        ioctl_msg.nummsgs = 1;
        status = i2c_read_i2c_device(touch_fd, &ioctl_msg);
        if (status < 0) {
            perror("Error reading touch sensor data");
            exit(EXIT_FAILURE);
        }

        // Debounce each channel
        for (int i = 0; i < CHANNELS; i++) {
            if (gpiod_line_mixin_line_get_value(touch_line_mixin, i) == 0 && gpiod_line_mixin_line_get_value(touch_line_mixin, i, 1) == 1) {
                gpiod_line_mixin_line_set_value(touch_line_mixin, i, 1);
            } else if (gpiod_line_mixin_line_get_value(touch_line_mixin, i) == 1 && gpiod_line_mixin_line_get_value(touch_line_mixin, i, 1) == 0) {
                gpiod_line_mixin_line_set_value(touch_line_mixin, i, 0);
            }
        }

        // Sleep for 50ms
        usleep(DEBOUNCE_TIME);

        // Check for touch events
        for (int i = 0; i < CHANNELS; i++) {
            if (gpiod_line_mixin_line_get_value(touch_line_mixin, i) == 1 && gpiod_line_mixin_line_get_value(touch_line_mixin, i, 1) == 0) {
                handle_touch_event(i + 1, 1);
            } else if (gpiod_line_mixin_line_get_value(touch_line_mixin, i) == 0 && gpiod_line_mixin_line_get_value(touch_line_mixin, i, 1) == 1) {
                handle_touch_event(i + 1, 0);
            }
        }
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
