#include <signal.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

#define I2C_BUS 1
#define OPT3001_ADDR 0x29
#define OPT3001_REG_ID 0x00
#define OPT3001_REG_LUX 0x41
#define OPT3001_REG_CONTROL 0x82

#define LIGHT_DATA_FILE "light_data.txt"

#define ERROR_CODE -1
#define SUCCESS 0

typedef struct {
    int i2c_fd;
    int lux_fd;
} Opt3001Config;

static void sigint_handler(int signum) {
    if (Opt3001Config.i2c_fd > 0) {
        close(Opt3001Config.i2c_fd);
    }
    if (Opt3001Config.lux_fd > 0) {
        close(Opt3001Config.lux_fd);
    }
    if (ferror(stdout)) {
        perror("stdout");
    }
    if (ferror(stderr)) {
        perror("stderr");
    }
    if (fclose(stdout)) {
        perror("stdout");
    }
    if (fclose(stderr)) {
        perror("stderr");
    }
    if (fclose(Opt3001Config.lux_fd)) {
        perror("lux_fd");
    }
    if (fclose(Opt3001Config.i2c_fd)) {
        perror("i2c_fd");
    }
}

static void init_opt3001(Opt3001Config *config) {
    config->i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (config->i2c_fd == ERROR_CODE) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    config->lux_fd = ioctl(config->i2c_fd, I2C_SLAVE, OPT3001_ADDR);
    if (config->lux_fd == ERROR_CODE) {
        perror("Failed to set I2C slave address");
        exit(EXIT_FAILURE);
    }

    if (ioctl(config->lux_fd, OPT3001_REG_ID, 0) == ERROR_CODE) {
        perror("Failed to read sensor ID");
        exit(EXIT_FAILURE);
    }

    if (ioctl(config->lux_fd, OPT3001_REG_CONTROL, 0x00) == ERROR_CODE) {
        perror("Failed to set control register");
        exit(EXIT_FAILURE);
    }

    if (ioctl(config->lux_fd, OPT3001_REG_CONTROL, 0x80) == ERROR_CODE) {
        perror("Failed to set control register");
        exit(EXIT_FAILURE);
    }

    if (ioctl(config->lux_fd, OPT3001_REG_LUX, 0) == ERROR_CODE) {
        perror("Failed to read lux value");
        exit(EXIT_FAILURE);
    }
}

static void read_lux(Opt3001Config *config, uint32_t *lux) {
    uint16_t temp[2];
    if (read(config->lux_fd, temp, sizeof(temp)) == ERROR_CODE) {
        perror("Failed to read lux value");
        exit(EXIT_FAILURE);
    }

    *lux = (temp[0] << 8) | temp[1];
    if (temp[0] > 0x7F) {
        *lux = 65535 - *lux;
    }
}

static void write_config(Opt3001Config *config) {
    if (ioctl(config->lux_fd, OPT3001_REG_CONTROL, 0x00) == ERROR_CODE) {
        perror("Failed to write control register");
        exit(EXIT_FAILURE);
    }
}

static void cleanup(Opt3001Config *config) {
    if (config->lux_fd > 0) {
        close(config->lux_fd);
    }
    if (config->i2c_fd > 0) {
        close(config->i2c_fd);
    }
}

int main() {
    Opt3001Config config;
    uint32_t lux;
    char buffer[128];
    struct timeval tv;
    struct tm *timeinfo;
    time_t rawtime;
    FILE *fp;

    signal(SIGINT, sigint_handler);

    init_opt3001(&config);

    while (1) {
        tv.tv_sec = 1;
        tv.tv_usec = 0;
        if (settimeofday(&tv, NULL) == ERROR_CODE) {
            perror("Failed to set time");
            exit(EXIT_FAILURE);
        }

        write_config(&config);

        read_lux(&config, &lux);

        time(&rawtime);
        timeinfo = localtime(&rawtime);

        snprintf(buffer, sizeof(buffer), "%04d-%02d-%02d %02d:%02d:%02d, %.2f",
                 timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_mday,
                 timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec,
                 (float)lux / 100.0f);

        fp = fopen(LIGHT_DATA_FILE, "a");
        if (fp == NULL) {
            perror("Failed to open light_data.txt");
            exit(EXIT_FAILURE);
        }

        if (fprintf(fp, "%s\n", buffer) == ERROR_CODE) {
            perror("Failed to write to light_data.txt");
            fclose(fp);
            exit(EXIT_FAILURE);
        }

        if (fclose(fp)) {
            perror("Failed to close light_data.txt");
            exit(EXIT_FAILURE);
        }

        printf("%s\n", buffer);
        if (ferror(stdout)) {
            perror("stdout");
            exit(EXIT_FAILURE);
        }

        usleep(100000); // 100ms delay
    }

    cleanup(&config);

    return 0;
}

