#include <gpiod.h>

#define GPIO_PIN 4
#define LOG_FILE "touch_log.txt"
#define LOG_FORMAT "%Y-%m-%d %H:%M:%S:%d: "
#define LOG_DEBOUNCE_MS 50000

int fd_gpio;
struct gpiod_chip *chip;
struct gpiod_line *line;
struct gpiod_edge *edge;
struct gpiod_event *event;
struct gpiod_loop *loop;
struct timeval tv;

void handle_signal(int signum) {
    if (fd_gpio != -1) {
        gpiod_line_put(line, GPIOD_LINE_CTRL, GPIOD_LINE_STATE_OFF);
        close(fd_gpio);
    }
    if (fd_log != -1) {
        close(fd_log);
    }
    exit(EXIT_FAILURE);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    fd_gpio = open("/dev/gpiod", O_RDONLY | O_NONBLOCK);
    if (fd_gpio == -1) {
        perror("Failed to open /dev/gpiod");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(fd_gpio);
    if (chip == NULL) {
        perror("Failed to open gpiod_chip");
        goto cleanup;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (line == NULL) {
        perror("Failed to get GPIO line");
        goto cleanup;
    }

    line = gpiod_line_request_edge(line, GPIOD_EDGE_BOTH);
    if (line == NULL) {
        perror("Failed to request edge");
        goto cleanup;
    }

    edge = gpiod_line_request_event(line, GPIOD_EDGE_BOTH, GPIOD_EVENT_EDGE);
    if (edge == NULL) {
        perror("Failed to request event");
        goto cleanup;
    }

    loop = gpiod_line_request_loop(edge, GPIOD_LOOP_EDGE);
    if (loop == NULL) {
        perror("Failed to request loop");
        goto cleanup;
    }

    event = gpiod_loop_request_event(loop, GPIOD_EVENT_EDGE);
    if (event == NULL) {
        perror("Failed to request event");
        goto cleanup;
    }

    gettimeofday(&tv, NULL);
    char buffer[128];
    sprintf(buffer, "%s 00:00:00:0", LOG_FORMAT);
    write(fd_log, buffer, strlen(buffer));

    while (1) {
        gettimeofday(&tv, NULL);
        if ((tv.tv_sec * 1000000 + tv.tv_usec) - (tv_last.tv_sec * 1000000 + tv_last.tv_usec) >= LOG_DEBOUNCE_MS) {
            tv_last = tv;
            fd_gpio_read(line, edge, event);
            if (event->edge == GPIOD_EDGE_RISING) {
                gettimeofday(&tv, NULL);
                char buffer[128];
                sprintf(buffer, "%s Touch Detected", LOG_FORMAT);
                write(fd_log, buffer, strlen(buffer));
            } else if (event->edge == GPIOD_EDGE_FALLING) {
                gettimeofday(&tv, NULL);
                char buffer[128];
                sprintf(buffer, "%s Touch Released", LOG_FORMAT);
                write(fd_log, buffer, strlen(buffer));
            }
        }
    }

cleanup:
    if (event) {
        gpiod_event_free(event);
    }
    if (edge) {
        gpiod_edge_free(edge);
    }
    if (loop) {
        gpiod_loop_free(loop);
    }
    if (line) {
        gpiod_line_free(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    close(fd_gpio);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
