#define TMAG5110A1_GPIO4 4
#define TMAG5110A1_GPIO17 17
#define TMAG5110A1_GPIO27 27
#define LOG_FILE "magnet_log.txt"
#define POLL_INTERVAL 100000  // 100ms

int main() {
    int fd;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_edge *edge;
    struct gpiod_event *event;
    struct timespec ts;
    char buffer[256];
    char sensor_id[3];
    char timestamp[26];
    int state;
    int error;

    // Open the GPIO device
    if ((fd = open("/dev/gpiod", O_RDONLY)) < 0) {
        perror("Failed to open GPIO device");
        return 1;
    }

    // Get the GPIO chip
    if ((chip = gpiod_chip_open(fd)) == NULL) {
        perror("Failed to get GPIO chip");
        close(fd);
        return 1;
    }

    // Get the GPIO line for each sensor
    if ((line = gpiod_chip_get_line(chip, TMAG5110A1_GPIO4)) == NULL) {
        perror("Failed to get GPIO line for sensor 1");
        close(fd);
        gpiod_chip_close(chip);
        return 1;
    }
    if ((line = gpiod_chip_get_line(chip, TMAG5110A1_GPIO17)) == NULL) {
        perror("Failed to get GPIO line for sensor 2");
        close(fd);
        gpiod_chip_close(chip);
        gpiod_line_close(line);
        return 1;
    }
    if ((line = gpiod_chip_get_line(chip, TMAG5110A1_GPIO27)) == NULL) {
        perror("Failed to get GPIO line for sensor 3");
        close(fd);
        gpiod_chip_close(chip);
        gpiod_line_close(line);
        gpiod_line_close(gpiod_chip_get_line(chip, TMAG5110A1_GPIO4));
        gpiod_chip_close(chip);
        return 1;
    }

    // Set each line to input with pull-up enabled
    if ((error = gpiod_line_mode_set(line, GPIOD_MODE_INPUT)) != 0) {
        perror("Failed to set GPIO line mode");
        close(fd);
        gpiod_chip_close(chip);
        gpiod_line_close(line);
        gpiod_line_close(gpiod_chip_get_line(chip, TMAG5110A1_GPIO17));
        gpiod_chip_close(chip);
        gpiod_line_close(gpiod_chip_get_line(chip, TMAG5110A1_GPIO27));
        return 1;
    }
    if ((error = gpiod_line_pull_set(line, GPIOD_PULL_UP)) != 0) {
        perror("Failed to set GPIO line pull");
        close(fd);
        gpiod_chip_close(chip);
        gpiod_line_close(line);
        gpiod_line_close(gpiod_chip_get_line(chip, TMAG5110A1_GPIO17));
        gpiod_chip_close(chip);
        gpiod_line_close(gpiod_chip_get_line(chip, TMAG5110A1_GPIO27));
        return 1;
    }

    // Record initial state
    if ((error = gpiod_line_read(line, &state)) != 0) {
        perror("Failed to read GPIO line");
        close(fd);
        gpiod_chip_close(chip);
        gpiod_line_close(line);
        gpiod_line_close(gpiod_chip_get_line(chip, TMAG5110A1_GPIO17));
        gpiod_chip_close(chip);
        gpiod_line_close(gpiod_chip_get_line(chip, TMAG5110A1_GPIO27));
        return 1;
    }

    // Prepare timestamp format
    if (clock_gettime(CLOCK_MONOTONIC, &ts) == -1) {
        perror("Failed to get current time");
        close(fd);
        gpiod_chip_close(chip);
        gpiod_line_close(line);
        gpiod_line_close(gpiod_chip_get_line(chip, TMAG5110A1_GPIO17));
        gpiod_chip_close(chip);
        gpiod_line_close(gpiod_chip_get_line(chip, TMAG5110A1_GPIO27));
        return 1;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S.%3f", &ts);

    // Open log file
    if ((fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644)) < 0) {
        perror("Failed to open log file");
        close(fd);
        gpiod_chip_close(chip);
        gpiod_line_close(line);
        gpiod_line_close(gpiod_chip_get_line(chip, TMAG5110A1_GPIO17));
        gpiod_chip_close(chip);
        gpiod_line_close(gpiod_chip_get_line(chip, TMAG5110A1_GPIO27));
        return 1;
    }

    // Prepare sensor IDs
    snprintf(sensor_id, sizeof(sensor_id), "1");
    snprintf(sensor_id, sizeof(sensor_id), "2");
    snprintf(sensor_id, sizeof(sensor_id), "3");

    // Main loop
    while (1) {
        // Read each line
        for (int i = 0; i < 3; i++) {
            if ((error = gpiod_line_read(line, &state)) != 0) {
                fprintf(stderr, "Error reading GPIO line %d: %s\n", i + 1, strerror(error));
                continue;
            }

            // Check for state change
            if (state != 0) {
                // Log state change
                if (clock_gettime(CLOCK_MONOTONIC, &ts) == -1) {
                    perror("Failed to get current time");
                    close(fd);
                    gpiod_chip_close(chip);
                    gpiod_line_close(line);
                    gpiod_line_close(gpiod_chip_get_line(chip, TMAG5110A1_GPIO17));
                    gpiod_chip_close(chip);
                    gpiod_line_close(gpiod_chip_get_line(chip, TMAG5110A1_GPIO27));
                    return 1;
                }
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S.%3f", &ts);
                snprintf(buffer, sizeof(buffer), "%s %s\n", timestamp, sensor_id);
                if (write(fd, buffer, strlen(buffer)) != strlen(buffer)) {
                    perror("Failed to write to log file");
                    close(fd);
                    gpiod_chip_close(chip);
                    gpiod_line_close(line);
                    gpiod_line_close(gpiod_chip_get_line(chip, TMAG5110A1_GPIO17));
                    gpiod_chip_close(chip);
                    gpiod_line_close(gpiod_chip_get_line(chip, TMAG5110A1_GPIO27));
                    return 1;
                }
            }
        }

        // Poll interval
        if (nanosleep(&ts, NULL) == -1) {
            perror("Failed to sleep");
            close(fd);
            gpiod_chip_close(chip);
            gpiod_line_close(line);
            gpiod_line_close(gpiod_chip_get_line(chip, TMAG5110A1_GPIO17));
            gpiod_chip_close(chip);
            gpiod_line_close(gpiod_chip_get_line(chip, TMAG5110A1_GPIO27));
            return 1;
        }
    }

    // Clean shutdown
    close(fd);
    gpiod_chip_close(chip);
    gpiod_line_close(line);
    gpiod_line_close(gpiod_chip_get_line(chip, TMAG5110A1_GPIO17));
    gpiod_chip_close(chip);
    gpiod_line_close(gpiod_chip_get_line(chip, TMAG5110A1_GPIO27));

    return 0;
}

