typedef struct {
    int fd;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int value;
} GPIO;

void handle_sigint(int sig) {
    GPIO *gpio = (GPIO *)malloc(sizeof(GPIO));
    gpio->fd = -1;
    gpio->chip = NULL;
    gpio->line = NULL;
    gpio->value = 0;

    if (gpio->line) {
        gpiod_line_free(gpio->line);
    }
    if (gpio->chip) {
        gpiod_chip_free(gpio->chip);
    }
    free(gpio);

    if (gpio->fd != -1) {
        close(gpio->fd);
    }

    if (gpio->line) {
        gpiod_line_unref(gpio->line);
    }
    if (gpio->chip) {
        gpiod_chip_unref(gpio->chip);
    }

    if (gpio->fd != -1) {
        close(gpio->fd);
    }

    printf("Graceful shutdown initiated.\n");
    gpio->value = 0;
    if (gpio->line) {
        gpiod_line_set_value(gpio->line, gpio->value);
    }
    if (gpio->chip) {
        gpiod_chip_unexport(gpio->chip);
    }
    if (gpio->fd != -1) {
        close(gpio->fd);
    }
    free(gpio);
    exit(0);
}

