        perror("Failed to get value from line");
        goto cleanup;
    }

    if ((led.chip->export = gpiod_chip_export(chip)) == -1) {
        perror("Failed to export chip");
        goto cleanup;
    }

    if ((led.chip->unexport = gpiod_chip_unexport(chip)) == -1) {
        perror("Failed to unexport chip");
        goto cleanup;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        goto cleanup;
    }

    // Set up timer
    tv.tv_sec = 0.1;
    tv.tv_usec = 0;
    setitimer(ITIMER_REAL, &tv, NULL);

    while (1) {
        // Read sensor1
        if ((gpio1.value = gpiod_line_get_value(gpio1.line)) == -1) {
            perror("Failed to read sensor1");
            goto cleanup;
        }

        // Read sensor2
        if ((gpio2.value = gpiod_line_get_value(gpio2.line)) == -1) {
            perror("Failed to read sensor2");
            goto cleanup;
        }

        // Read LED
        if ((led.value = gpiod_line_get_value(led.line)) == -1) {
            perror("Failed to read LED");
            goto cleanup;
        }

        // Log data
        if (fprintf(log_file, "%ld,%d,%d,%d\n", (long int)time(NULL), gpio1.value, gpio2.value, led.value) < 0) {
            perror("Failed to log data");
            goto cleanup;
        }
        fflush(log_file);

        // Update LED
        if (gpio1.value == 0 && gpio2.value == 0) {
            if (led.value == 0) {
                if (gpiod_line_set_value(led.line, 1) == -1) {
                    perror("Failed to set LED to high");
                    goto cleanup;
                }
            } else {
                if (gpiod_line_set_value(led.line, 0) == -1) {
                    perror("Failed to set LED to low");
                    goto cleanup;
                }
            }
        }

        // Check for SIGINT
        if (sigwaitinfo(NULL, NULL)) {
            handle_sigint(0);
        }
    }

cleanup:
    if (gpio1.fd != -1) {
        close(gpio1.fd);
    }
    if (gpio1.line) {
        gpiod_line_unref(gpio1.line);
    }
    if (gpio1.chip) {
        gpiod_chip_unref(gpio1.chip);
    }

    if (gpio2.fd != -1) {
        close(gpio2.fd);
    }
    if (gpio2.line) {
        gpiod_line_unref(gpio2.line);
    }
    if (gpio2.chip) {
        gpiod_chip_unref(gpio2.chip);
    }

    if (led.fd != -1) {
        close(led.fd);
    }
    if (led.line) {
        gpiod_line_unref(led.line);
    }
    if (led.chip) {
        gpiod_chip_unref(led.chip);
    }

    if (log_file) {
        fclose(log_file);
    }

    return 0;
}

