#define TCS34725_REG_CLEAR54 0x7F

#define I2C_TIMEOUT 100

typedef struct {
    int i2c_fd;
    int rgb_led_fd;
} TCS34725;

void i2c_open(TCS34725 *sensor) {
    sensor->i2c_fd = open(I2C_BUS, O_RDWR);
    if (sensor->i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }
    if (ioctl(sensor->i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        exit(EXIT_FAILURE);
    }
}

void i2c_close(TCS34725 *sensor) {
    close(sensor->i2c_fd);
}

void i2c_read(TCS34725 *sensor, int reg, unsigned char *buf, int len) {
    if (read(sensor->i2c_fd, buf, len) < 0) {
        perror("Failed to read I2C register");
        exit(EXIT_FAILURE);
    }
}

void i2c_write(TCS34725 *sensor, int reg, unsigned char *buf, int len) {
    if (write(sensor->i2c_fd, buf, len) < 0) {
        perror("Failed to write I2C register");
        exit(EXIT_FAILURE);
    }
}

void i2c_reinit(TCS34725 *sensor) {
    i2c_close(sensor);
    i2c_open(sensor);
}

void rgb_led_open(TCS34725 *sensor) {
    sensor->rgb_led_fd = open("/dev/gpiod/major:4", O_RDWR);
    if (sensor->rgb_led_fd < 0) {
        perror("Failed to open GPIO line");
        exit(EXIT_FAILURE);
    }
}

void rgb_led_close(TCS34725 *sensor) {
    close(sensor->rgb_led_fd);
}

void rgb_led_set(TCS34725 *sensor, int value) {
    if (write(sensor->rgb_led_fd, &value, 1) < 0) {
        perror("Failed to set GPIO line");
        exit(EXIT_FAILURE);
    }
}

void i2c_read_rgb(TCS34725 *sensor, unsigned char *rgb) {
    i2c_read(sensor, TCS34725_REG_RGB, rgb, 3);
}

void i2c_read_clear(TCS34725 *sensor, unsigned char *clear) {
    i2c_read(sensor, TCS34725_REG_CLEAR, clear, 3);
}

