#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <linux/sensors.h>
#include <linux/delay.h>

#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define GPIO18 18

#define MAX_RETRIES 5
#define RETRY_DELAY_MS 100

typedef struct {
    int fd;
    int i2c_fd;
    int bh1750_fd;
    int gpio_fd;
    int retry_count;
    int retry_delay;
} BH1750Config;

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        if (bh1750Config.gpio_fd > 0) {
            gpio_close(bh1750Config.gpio_fd);
        }
        if (bh1750Config.bh1750_fd > 0) {
            i2c_close(bh1750Config.i2c_fd);
            close(bh1750Config.bh1750_fd);
        }
        if (bh1750Config.fd > 0) {
            close(bh1750Config.fd);
        }
        exit(EXIT_SUCCESS);
    }
}

int i2c_read(int fd, int addr, uint8_t *buf, int len) {
    struct i2c_msg msg[1];
    struct i2c_rdwr_ioctl_data data;
    data.msgs = msg;
    data.nmsgs = 1;
    data.tx_buf = buf;
    data.len = len;
    data.addr = addr;

    if (ioctl(fd, I2C_RDWR, &data) < 0) {
        perror("ioctl");
        return -1;
    }

    return 0;
}

int i2c_write(int fd, int addr, uint8_t *buf, int len) {
    struct i2c_msg msg[1];
    struct i2c_rdwr_ioctl_data data;
    data.msgs = msg;
    data.nmsgs = 1;
    data.tx_buf = buf;
    data.len = len;
    data.addr = addr;

    if (ioctl(fd, I2C_RDWR, &data) < 0) {
        perror("ioctl");
        return -1;
    }

    return 0;
}

int bh1750_read(int fd, uint8_t *buf) {
    if (i2c_read(bh1750Config.i2c_fd, BH1750_ADDR, buf, 1) < 0) {
        return -1;
    }

    return 0;
}

int bh1750_write(int fd, uint8_t *buf) {
    if (i2c_write(bh1750Config.i2c_fd, BH1750_ADDR, buf, 1) < 0) {
        return -1;
    }

    return 0;
}

int gpio_pwm(int fd, int value) {
    if (ioctl(fd, GPIO_PWM, value) < 0) {
        perror("ioctl");
        return -1;
    }

    return 0;
}

int gpio_write(int fd, int value) {
    if (ioctl(fd, GPIO_SET, value) < 0) {
        perror("ioctl");
        return -1;
    }

    return 0;
}

int gpio_read(int fd) {
    int value;
    if (ioctl(fd, GPIO_GET, &value) < 0) {
        perror("ioctl");
        return -1;
    }

    return value;
}

int main() {
    BH1750Config config;
    config.fd = 0;
    config.i2c_fd = 0;
    config.bh1750_fd = 0;
    config.gpio_fd = 0;
    config.retry_count = 0;
    config.retry_delay = RETRY_DELAY_MS;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    config.fd = open("/dev/i2c-1", O_RDWR);
    if (config.fd < 0) {
        perror("open");
        return EXIT_FAILURE;
    }

    config.i2c_fd = config.fd;
    config.bh1750_fd = i2c_open(config.i2c_fd, BH1750_ADDR);

    if (config.bh1750_fd < 0) {
        perror("i2c_open");
        goto cleanup;
    }

    config.gpio_fd = gpio_open(GPIO18);
    if (config.gpio_fd < 0) {
        perror("gpio_open");
        goto cleanup;
    }

    if (gpio_pwm(config.gpio_fd, 1) < 0) {
        perror("gpio_pwm");
        goto cleanup;
    }

    while (1) {
        uint8_t buf[1];
        int lux = 0;
        int retries = 0;

        while (retries < MAX_RETRIES) {
            if (bh1750_write(config.i2c_fd, buf) < 0) {
                perror("bh1750_write");
                retries++;
                usleep(config.retry_delay * 1000);
                continue;
            }

            if (bh1750_read(config.i2c_fd, buf) < 0) {
                perror("bh1750_read");
                retries++;
                usleep(config.retry_delay * 1000);
                continue;
            }

            lux = (buf[0] << 1) | (buf[0] >> 7);
            if (lux == 0b11111111) {
                lux = 0;
            }

            int brightness = 255 * (log2(lux) / 6.0);
            int brightness_val = (brightness + 1) / 2;

            if (gpio_write(config.gpio_fd, brightness_val) < 0) {
                perror("gpio_write");
                retries++;
                usleep(config.retry_delay * 1000);
                continue;
            }

            break;
        }

        if (retries == MAX_RETRIES) {
            printf("BH1750 sensor not found. Exiting...\n");
            goto cleanup;
        }

        usleep(180000); // 180ms delay
    }

cleanup:
    if (config.gpio_fd > 0) {
        gpio_close(config.gpio_fd);
    }
    if (config.bh1750_fd > 0) {
        i2c_close(config.bh1750_fd);
        close(config.bh1750_fd);
    }
    if (config.fd > 0) {
        close(config.fd);
    }

    return EXIT_SUCCESS;
}

