#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDR 0x23
#define APA102_DEVICE "/dev/spidev0.0"
#define APA102_SPI_CS 0
#define APA102_SPI_SPEED 1000000
#define APA102_SPI_BITS 8
#define APA102_SPI_MODE 0

typedef struct {
    int i2c_fd;
    int spi_fd;
    int led_count;
    int *led_brightness;
} APA102Config;

void handle_i2c_error(int i2c_fd, int error) {
    if (error) {
        perror("i2c ioctl");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void handle_spi_error(int spi_fd, int error) {
    if (error) {
        perror("spi ioctl");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }
}

void handle_sigint(int signum) {
    if (APA102Config->spi_fd > 0) {
        // Turn off all LEDs
        for (int i = 0; i < APA102Config->led_count; i++) {
            APA102Config->led_brightness[i] = 0;
        }
        // Close SPI device
        close(APA102Config->spi_fd);
    }
    // Close I2C device
    close(APA102Config->i2c_fd);
    exit(EXIT_SUCCESS);
}

int main() {
    // Initialize APA102 configuration
    APA102Config config;
    config.led_count = 0;
    config.i2c_fd = open(I2C_DEVICE, O_RDWR);
    handle_i2c_error(config.i2c_fd, 0);
    config.spi_fd = open(APA102_DEVICE, O_RDWR | O_CLOEXEC);
    handle_spi_error(config.spi_fd, 0);

    // Initialize I2C device
    if (ioctl(config.i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("I2C device initialization");
        handle_i2c_error(config.i2c_fd, -1);
    }

    // Initialize SPI device
    if (ioctl(config.spi_fd, SPI_SET_CS_MODE, APA102_SPI_CS) < 0) {
        perror("SPI device initialization");
        handle_spi_error(config.spi_fd, -1);
    }

    // Initialize APA102 LED strip
    if (ioctl(config.spi_fd, SPI_SET@SuppressWarnings("unused") SPI_MODE, APA102_SPI_MODE) < 0) {
        perror("SPI device mode initialization");
        handle_spi_error(config.spi_fd, -1);
    }

    // Read BH1750 sensor data
    while (1) {
        // Wait for sensor conversion
        usleep(120000); // 120 ms

        // Read BH1750 sensor data
        int i2c_error = ioctl(config.i2c_fd, I2C_SMBUS_READ, 0, 0, 0, 0, 0, 0, 0);
        handle_i2c_error(config.i2c_fd, i2c_error);

        // Scale LED brightness
        for (int i = 0; i < config.led_count; i++) {
            config.led_brightness[i] = (uint16_t)(config.led_brightness[i] * (config.led_brightness[i] / 65535.0) * (255.0 / 100.0));
        }

        // Write APA102 data stream
        uint32_t data[4];
        for (int i = 0; i < config.led_count; i++) {
            data[0] = 0x00000000; // 32-bit zero start frame
            data[1] = config.led_brightness[i]; // 32-bit brightness
            data[2] = 0x000000FF; // 32-bit blue
            data[3] = 0x0000FF00; // 32-bit green
        }
        data[4] = 0x00000000; // 32-bit end frame

        int spi_error = ioctl(config.spi_fd, SPI_IOC_MESSAGE(1), data);
        handle_spi_error(config.spi_fd, spi_error);

        // Check for SIGINT
        if (signal(SIGINT, handle_sigint) == SIG_ERR) {
            perror("SIGINT signal handling");
            exit(EXIT_FAILURE);
        }
    }

    return 0;
}

