#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/signal.h>
#include <sys/time.h>
#include <math.h>

#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define BUFFER_SIZE 60
#define LED_GPIO 17

typedef struct {
    uint8_t data[3];
    uint32_t lux;
    uint32_t count;
} BH1750Data;

static BH1750Data buffer[BUFFER_SIZE];
static uint32_t buffer_index = 0;
static uint32_t buffer_full = 0;
static uint32_t buffer_empty = 0;

static int i2c_fd;
static int led_fd;

static void i2c_open() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        exit(EXIT_FAILURE);
    }
}

static void i2c_close() {
    close(i2c_fd);
}

static void i2c_read() {
    if (buffer_full) {
        return;
    }
    if (ioctl(i2c_fd, I2C_SMBUS_READ, 0) < 0) {
        perror("Failed to read from I2C bus");
        return;
    }
    if (buffer_index >= BUFFER_SIZE) {
        buffer_empty = 1;
    }
    buffer[buffer_index].lux = (buffer[buffer_index].data[0] << 16) |
                               (buffer[buffer_index].data[1] << 8) |
                               buffer[buffer_index].data[2];
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

static void i2c_write() {
    if (buffer_empty) {
        return;
    }
    if (ioctl(i2c_fd, I2C_SMBUS_WRITE, 0) < 0) {
        perror("Failed to write to I2C bus");
        return;
    }
    buffer_empty = 0;
}

static void i2c_loop() {
    i2c_read();
    i2c_write();
}

static void gpio_open() {
    led_fd = open("/sys/class/gpio/gpio" __FILE__, O_RDWR);
    if (led_fd < 0) {
        perror("Failed to open GPIO");
        exit(EXIT_FAILURE);
    }
}

static void gpio_close() {
    close(led_fd);
    unexport(LED_GPIO);
}

static void gpio_write(int value) {
    if (write(led_fd, &value, 1) < 0) {
        perror("Failed to write to GPIO");
        exit(EXIT_FAILURE);
    }
}

static void gpio_loop() {
    struct timespec ts;
    ts.tv_sec = 1;
    ts.tv_nsec = 0;
    nanosleep(&ts, NULL);
    gpio_write(1);
    nanosleep(&ts, NULL);
    gpio_write(0);
}

static void signal_handler(int signum) {
    if (signum == SIGINT) {
        gpio_close();
        i2c_close();
        exit(EXIT_SUCCESS);
    }
}

static void init() {
    signal(SIGINT, signal_handler);
    i2c_open();
    gpio_open();
    buffer_index = 0;
    buffer_full = 0;
    buffer_empty = 0;
}

static void cleanup() {
    gpio_close();
    i2c_close();
}

int main() {
    init();
    while (1) {
        i2c_loop();
        if (buffer_full) {
            uint32_t lux = buffer[buffer_index].lux;
            float avg_lux = 0.0f;
            if (buffer_empty) {
                avg_lux = (float) lux;
            } else {
                avg_lux = (float) (buffer[buffer_index].lux + buffer[buffer_empty].lux) / 2.0f;
            }
            float duty_cycle = 0.5f + (avg_lux / 1000.0f) * 0.5f;
            int duty = (int) (duty_cycle * 1000);
            gpio_write(duty / 10);
        }
    }
    cleanup();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <linux/i2c.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDR 0x78
#define SEVEN_SEGMENT_DATA 0x40

int main() {
    int i2c_fd;
    int err;
    struct i2c_msg msg[1];
    struct i2c_rdwr_ioctl_msg rdwr_msg;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_edge *edge;
    struct gpiod_loop *loop;
    int data_pin = 17;
    int clock_pin = 18;
    int latch_pin = 27;
    int data_out[8] = {1, 0, 0, 0, 0, 0, 0, 0};
    int data_in[8] = {0, 0, 0, 0, 0, 0, 0, 0};
    int i;

    // Open I2C device
    if ((i2c_fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("open I2C device");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("ioctl I2C slave");
        return 1;
    }

    // Initialize GPIO lines
    if ((err = gpiod_chip_open("/dev/gpiod")) < 0) {
        perror("gpiod_chip_open");
        return 1;
    }

    if ((chip = gpiod_chip_new()) == NULL) {
        perror("gpiod_chip_new");
        return 1;
    }

    if ((err = gpiod_chip_request_line(chip, data_pin, GPIOD_LINE_DIR_OUT)) < 0) {
        perror("gpiod_chip_request_line");
        return 1;
    }

    if ((err = gpiod_chip_request_line(chip, clock_pin, GPIOD_LINE_DIR_OUT)) < 0) {
        perror("gpiod_chip_request_line");
        return 1;
    }

    if ((err = gpiod_chip_request_line(chip, latch_pin, GPIOD_LINE_DIR_OUT)) < 0) {
        perror("gpiod_chip_request_line");
        return 1;
    }

    // Create a loop for the latch
    if ((loop = gpiod_loop_new(chip)) == NULL) {
        perror("gpiod_loop_new");
        return 1;
    }

    if ((edge = gpiod_edge_new(chip, GPIOD_EDGE_EDGE_RISING)) == NULL) {
        perror("gpiod_edge_new");
        return 1;
    }

    if ((err = gpiod_edge_request(chip, edge)) < 0) {
        perror("gpiod_edge_request");
        return 1;
    }

    if ((err = gpiod_loop_add_edge(loop, edge)) < 0) {
        perror("gpiod_loop_add_edge");
        return 1;
    }

    // Set up the shift register
    for (i = 0; i < 8; i++) {
        data_out[i] = 0;
    }

    data_out[0] = 0b11111110; // Segment a, b, c, d, e, f off, dp on
    data_out[1] = 0b00000001; // Segment g on

    // Send the data to the shift register
    for (i = 0; i < 8; i++) {
        msg[0].addr = I2C_ADDR;
        msg[0].flags = I2C_MSG_WRITE;
        msg[0].data[0] = SEVEN_SEGMENT_DATA | data_out[i];
        msg[0].len = 1;

        if ((err = i2c_rdwr(msg, 1, &rdwr_msg)) < 0) {
            perror("i2c_rdwr");
            return 1;
        }
    }

    // Latch the data
    gpiod_line_set_value(latch_pin, 1);

    // Main loop
    while (1) {
        // Send the data to the shift register
        for (i = 0; i < 8; i++) {
            msg[0].addr = I2C_ADDR;
            msg[0].flags = I2C_MSG_WRITE;
            msg[0].data[0] = SEVEN_SEGMENT_DATA | data_out[i];
            msg[0].len = 1;

            if ((err = i2c_rdwr(msg, 1, &rdwr_msg)) < 0) {
                perror("i2c_rdwr");
                return 1;
            }
        }

        // Latch the data
        gpiod_line_set_value(latch_pin, 1);

        // Delay for 500 ms
        usleep(500000);

        // Clear the latch
        gpiod_line_set_value(latch_pin, 0);

        // Delay for 500 ms
        usleep(500000);

        // Toggle the display
        data_out[0] = 0b11111110; // Segment a, b, c, d, e, f off, dp on
        data_out[1] = 0b00000001; // Segment g on
    }

    // Clean up
    gpiod_loop_destroy(loop);
    gpiod_edge_free(edge);
    gpiod_chip_free(chip);
    close(i2c_fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <sys/time.h>
#include <gpiod.h>

#define GPIO5 5

int main() {
    int fd;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_edge *edge;
    struct gpiod_event *event;
    struct timespec delay;

    // Initialize the driver
    if ((fd = gpiod_open(NULL)) < 0) {
        perror("gpiod_open");
        return 1;
    }

    if ((chip = gpiod_chip_new(fd)) == NULL) {
        perror("gpiod_chip_new");
        gpiod_close(fd);
        return 1;
    }

    // Find the GPIO5 line
    if ((line = gpiod_chip_get_line(chip, GPIO5)) == NULL) {
        perror("gpiod_chip_get_line");
        gpiod_chip_delete(chip);
        gpiod_close(fd);
        return 1;
    }

    // Set the line to output mode
    if (gpiod_line_set_mode(line, GPIOD_MODE_OUTPUT) < 0) {
        perror("gpiod_line_set_mode");
        gpiod_chip_delete(chip);
        gpiod_close(fd);
        return 1;
    }

    // Set the line to low (off) state
    if (gpiod_line_set_value(line, 0) < 0) {
        perror("gpiod_line_set_value");
        gpiod_chip_delete(chip);
        gpiod_close(fd);
        return 1;
    }

    // Set up an edge detection event
    if ((edge = gpiod_line_create_edge(line, GPIOD_EDGE_BOTH)) == NULL) {
        perror("gpiod_line_create_edge");
        gpiod_chip_delete(chip);
        gpiod_close(fd);
        return 1;
    }

    if ((event = gpiod_edge_create_event(edge, NULL)) == NULL) {
        perror("gpiod_edge_create_event");
        gpiod_chip_delete(chip);
        gpiod_close(fd);
        return 1;
    }

    // Set the event to trigger on both rising and falling edges
    if (gpiod_event_set_edge(event, GPIOD_EDGE_BOTH) < 0) {
        perror("gpiod_event_set_edge");
        gpiod_chip_delete(chip);
        gpiod_close(fd);
        return 1;
    }

    // Set the event to trigger on both rising and falling edges
    if (gpiod_event_set_value(event, 1) < 0) {
        perror("gpiod_event_set_value");
        gpiod_chip_delete(chip);
        gpiod_close(fd);
        return 1;
    }

    // Set up the event handler
    if (gpiod_event_enable(event) < 0) {
        perror("gpiod_event_enable");
        gpiod_chip_delete(chip);
        gpiod_close(fd);
        return 1;
    }

    // Set the delay
    delay.tv_sec = 0;
    delay.tv_nsec = 750000000; // 750 ms

    // Main loop
    while (1) {
        // Set the line to high (on) state
        if (gpiod_line_set_value(line, 1) < 0) {
            perror("gpiod_line_set_value");
            gpiod_chip_delete(chip);
            gpiod_close(fd);
            return 1;
        }

        printf("LED ON\n");
        fflush(stdout);

        // Sleep for 750 ms
        nanosleep(&delay, NULL);

        // Set the line to low (off) state
        if (gpiod_line_set_value(line, 0) < 0) {
            perror("gpiod_line_set_value");
            gpiod_chip_delete(chip);
            gpiod_close(fd);
            return 1;
        }

        printf("LED OFF\n");
        fflush(stdout);

        // Sleep for 750 ms
        nanosleep(&delay, NULL);
    }

    // Handle SIGINT
    signal(SIGINT, [](int sig) {
        // Cleanly turn off the LED
        if (gpiod_line_set_value(line, 0) < 0) {
            perror("gpiod_line_set_value");
            gpiod_chip_delete(chip);
            gpiod_close(fd);
            return 1;
        }

        // Terminate the driver library
        gpiod_chip_delete(chip);

        // Release all driver resources
        gpiod_line_unref(line);
        gpiod_chip_unref(fd);

        // Exit with code 0
        return 0;
    });

    return 0;
}

