#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <string.h>
#include <gpiod.h>

#define GPIO_PIN_R 24
#define GPIO_PIN_G 23
#define GPIO_PIN_B 18

#define PWM_FREQ 100000000  // 100 Hz
#define PWM_RESOLUTION 100  // 0-100 intensity

void signal_handler(int sig) {
    gpiod_close(gpio);
    gpiod_free_resources(gpio);
    exit(0);
}

int main() {
    struct gpiod_handle *gpio;
    struct gpiod_line *line;
    struct gpiod_state *state;
    struct gpiod_edge *edge;
    struct gpiod_value *value;
    struct timespec req;

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("SIGINT handler setup failed");
        return 1;
    }

    gpio = gpiod_open("/dev/gpiod");
    if (gpio == NULL) {
        perror("Failed to open gpiod");
        return 1;
    }

    if (gpiod_get_resources(gpio, &gpio)) {
        perror("Failed to get resources");
        return 1;
    }

    gpio->flags |= GPIOD_FLAG_EXPORT;
    if (gpiod_export(gpio)) {
        perror("Failed to export resources");
        return 1;
    }

    line = gpiod_get_line(gpio, GPIO_PIN_R);
    if (line == NULL) {
        perror("Failed to get line for GPIO PIN_R");
        return 1;
    }

    line->flags |= GPIOD_FLAG_PWM;
    if (gpiod_set_pwm(line, PWM_FREQ, PWM_RESOLUTION, 0, 0, 0)) {
        perror("Failed to set PWM for GPIO PIN_R");
        return 1;
    }

    line = gpiod_get_line(gpio, GPIO_PIN_G);
    if (line == NULL) {
        perror("Failed to get line for GPIO PIN_G");
        return 1;
    }

    line->flags |= GPIOD_FLAG_PWM;
    if (gpiod_set_pwm(line, PWM_FREQ, PWM_RESOLUTION, 0, 0, 0)) {
        perror("Failed to set PWM for GPIO PIN_G");
        return 1;
    }

    line = gpiod_get_line(gpio, GPIO_PIN_B);
    if (line == NULL) {
        perror("Failed to get line for GPIO PIN_B");
        return 1;
    }

    line->flags |= GPIOD_FLAG_PWM;
    if (gpiod_set_pwm(line, PWM_FREQ, PWM_RESOLUTION, 0, 0, 0)) {
        perror("Failed to set PWM for GPIO PIN_B");
        return 1;
    }

    state = gpiod_get_state(line);
    if (state == NULL) {
        perror("Failed to get state for GPIO PIN_R");
        return 1;
    }

    edge = gpiod_get_edge(state, GPIOD_EDGE_BOTH);
    if (edge == NULL) {
        perror("Failed to get edge for GPIO PIN_R");
        return 1;
    }

    value = gpiod_get_value(edge);
    if (value == NULL) {
        perror("Failed to get value for GPIO PIN_R");
        return 1;
    }

    while (1) {
        int r = rand() % PWM_RESOLUTION;
        int g = rand() % PWM_RESOLUTION;
        int b = rand() % PWM_RESOLUTION;

        req.tv_sec = 0;
        req.tv_nsec = 1000000000 / 100; // 10 ms

        clock_nanosleep(CLOCK_MONOTONIC, 0, &req, NULL);

        if (gpiod_set_value(value, r, g, b)) {
            perror("Failed to set PWM value");
            return 1;
        }

        req.tv_sec = 0;
        req.tv_nsec = 1000000000 / 100; // 10 ms

        clock_nanosleep(CLOCK_MONOTONIC, 0, &req, NULL);

        if (gpiod_get_value(value, &r, &g, &b)) {
            perror("Failed to get PWM value");
            return 1;
        }

        if (rand() % 100 == 0) {
            r = rand() % PWM_RESOLUTION;
            g = rand() % PWM_RESOLUTION;
            b = rand() % PWM_RESOLUTION;
        }
    }

    return 0;
}

