void handle_sigint(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(EXIT_SUCCESS);
}

void init_i2c() {
    if ((i2c_fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        exit(EXIT_FAILURE);
    }
}

void read_whoami() {
    char buf[2];
    if (write(i2c_fd, &WHO_AM_I, 1) != 1) {
        perror("Failed to write to I2C device");
        exit(EXIT_FAILURE);
    }
    if (read(i2c_fd, buf, 1) != 1) {
        perror("Failed to read from I2C device");
        exit(EXIT_FAILURE);
    }
    if (buf[0] != 0x28) {
        fprintf(stderr, "WHO_AM_I mismatch\n");
        exit(EXIT_FAILURE);
    }
}

void read_accel_config() {
    if (write(i2c_fd, &ACCEL_CONFIG, 1) != 1) {
        perror("Failed to write to I2C device");
        exit(EXIT_FAILURE);
    }
    if (read(i2c_fd, accel_data, 3) != 3) {
        perror("Failed to read from I2C device");
        exit(EXIT_FAILURE);
    }
    if (accel_data[0] & 0x80) {
        fprintf(stderr, "Invalid acceleration configuration\n");
        exit(EXIT_FAILURE);
    }
    if (accel_data[1] & 0x80) {
        fprintf(stderr, "Invalid acceleration configuration\n");
        exit(EXIT_FAILURE);
    }
    if (accel_data[2] & 0x80) {
        fprintf(stderr, "Invalid acceleration configuration\n");
        exit(EXIT_FAILURE);
    }
}

void read_mag_config() {
    if (write(i2c_fd, &MAGNETIC_CONFIG, 1) != 1) {
        perror("Failed to write to I2C device");
        exit(EXIT_FAILURE);
    }
    if (read(i2c_fd, mag_data, 3) != 3) {
        perror("Failed to read from I2C device");
        exit(EXIT_FAILURE);
    }
    if (mag_data[0] & 0x80) {
        fprintf(stderr, "Invalid magnetic configuration\n");
        exit(EXIT_FAILURE);
    }
    if (mag_data[1] & 0x80) {
        fprintf(stderr, "Invalid magnetic configuration\n");
        exit(EXIT_FAILURE);
    }
    if (mag_data[2] & 0x80) {
        fprintf(stderr, "Invalid magnetic configuration\n");
        exit(EXIT_FAILURE);
    }
}

void read_int_enable() {
    if (write(i2c_fd, &INT_ENABLE_1, 1) != 1) {
        perror("Failed to write to I2C device");
        exit(EXIT_FAILURE);
    }
    if (read(i2c_fd, accel_data, 1) != 1) {
        perror("Failed to read from I2C device");
        exit(EXIT_FAILURE);
    }
    if (accel_data[0] & 0x80) {
        fprintf(stderr, "Invalid INT_ENABLE configuration\n");
        exit(EXIT_FAILURE);
    }
}

void read_accel_data() {
    if (write(i2c_fd, &ACCEL_X, 1) != 1) {
        perror("Failed to write to I2C device");
        exit(EXIT_FAILURE);
    }
    if (read(i2c_fd, accel_data, 3) != 3) {
        perror("Failed to read from I2C device");
        exit(EXIT_FAILURE);
    }
    accel_data[0] = (accel_data[0] & 0x7F) << 8;
    accel_data[1] = (accel_data[1] & 0x7F) << 16;
    accel_data[2] = (accel_data[2] & 0x3F) << 24;
}

void read_mag_data() {
    if (write(i2c_fd, &MAGNETIC_X, 1) != 1) {
        perror("Failed to write to I2C device");
        exit(EXIT_FAILURE);
    }
    if (read(i2c_fd, mag_data, 3) != 3) {
        perror("Failed to read from I2C device");
        exit(EXIT_FAILURE);
    }
    mag_data[0] = (mag_data[0] & 0x7F) << 8;
    mag_data[1] = (mag_data[1] & 0x7F) << 16;
    mag_data[2] = (mag_data[2] & 0x3F) << 24;
}

void read_temp_data() {
    if (write(i2c_fd, &TEMP, 1) != 1) {
        perror("Failed to write to I2C device");
        exit(EXIT_FAILURE);
    }
    if (read(i2c_fd, temp_data, 1) != 1) {
        perror("Failed to read from I2C device");
        exit(EXIT_FAILURE);
    }
}

void read_data() {
    read_whoami();
    read_accel_config();
    read_mag_config();
    read_int_enable();
    read_accel_data();
    read_mag_data();
    read_temp_data();
}

void compute_magnitude() {
    double x = (double)accel_data[0] / 16384.0;
    double y = (double)accel_data[1] / 16384.0;
    double z = (double)accel_data[2] / 16384.0;
    double magnitude = sqrt(x * x + y * y + z * z);
    return magnitude;
}

void log_impact() {
    char timestamp[20];
    struct tm *timeinfo;
    time_t rawtime;
    rawtime = time(NULL);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(stderr, "Impact detected: %s, x=%.3f, y=%.3f, z=%.3f, magnitude=%.3f\n", timestamp, (double)accel_data[0] / 16384.0, (double)accel_data[1] / 16384.0, (double)accel_data[2] / 16384.0, compute_magnitude());
    fprintf(stderr, "Writing to log file...\n");
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
    fprintf(log_file, "%s,%f,%f,%f,%f\n", timestamp, (double)accel_data[0] / 16384.0, (double)accel_data[1] / 16384.0, (double)accel_data[2] / 16384.0, compute_magnitude());
    fclose(log_file);
    impact_count++;
    fprintf(stderr, "Impact logged. Count: %d\n", impact_count);
}

void main_loop() {
    while (1) {
        read_data();
        double magnitude = compute_magnitude();
        if (magnitude > IMPACT_THRESHOLD) {
            log_impact();
        }
        usleep(50000); // 50ms
    }
}

int main() {
    signal(SIGINT, handle_sigint);
    init_i2c();
    read_data();
    main_loop();
    return 0;
}

