#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/time.h>
#include <signal.h>
#include <stdint.h>
#include <string.h>
#include <math.h>

#define I2C_BUS 1
#define ADXL345_ID 0x53
#define ADXL345_CONFIG_REG 0x27
#define ADXL345_FULL_RES_MODE 0x00
#define ADXL345_RANGE_2G 0x00

#define LOG_FILE "accel_log.txt"
#define LOG_FORMAT "%ld,%f,%f,%f"

#define LED_GPIO 17

#define I2C_TIMEOUT 100

typedef struct {
    int fd;
    int i2c_fd;
    int gpio_fd;
} Adxl345Config;

void adxl345_init(Adxl345Config *config) {
    config->fd = open("/dev/i2c-1", O_RDWR);
    if (config->fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    config->i2c_fd = ioctl(config->fd, I2C_SLAVE, ADXL345_ID);
    if (config->i2c_fd < 0) {
        perror("Failed to set I2C slave address");
        exit(EXIT_FAILURE);
    }

    config->gpio_fd = open("/dev/gpiod", O_RDWR);
    if (config->gpio_fd < 0) {
        perror("Failed to open GPIO device");
        exit(EXIT_FAILURE);
    }

    config->gpio_fd = ioctl(config->gpio_fd, IGPIO_GET_FD, LED_GPIO);
    if (config->gpio_fd < 0) {
        perror("Failed to get GPIO fd");
        exit(EXIT_FAILURE);
    }

