#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <string.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/time.h>
#include <signal.h>
#include <stdint.h>
#include <math.h>

#define I2C_BUS 1
#define LSM303DLHC_ADDR 0x1C6B

#define GYRO_RATE 250
#define ACCEL_RATE 250
#define MAG_RATE 250

#define ACCEL_X 0x01
#define ACCEL_Y 0x02
#define ACCEL_Z 0x03
#define GYRO_X 0x04
#define GYRO_Y 0x05
#define GYRO_Z 0x06
#define MAG_X 0x07
#define MAG_Y 0x08
#define MAG_Z 0x09

#define TILT_COMPENSATION 0.98

typedef struct {
    int fd;
    int gyro_fd;
    int accel_fd;
    int mag_fd;
} LSM303DLHC;

void handle_sigint(int signum) {
    LSM303DLHC lsm;
    lsm.fd = -1;
    lsm.gyro_fd = -1;
    lsm.accel_fd = -1;
    lsm.mag_fd = -1;
    close(lsm.fd);
    close(lsm.gyro_fd);
    close(lsm.accel_fd);
    close(lsm.mag_fd);
    exit(0);
}

void handle_sigterm(int signum) {
    handle_sigint(signum);
}

int i2c_open(int bus, int addr) {
    int fd;
    fd = open("/dev/i2c-" bus, O_RDWR);
    if (fd < 0) {
        perror("Failed to open i2c bus");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to set slave address");
        close(fd);
        return -1;
    }
    return fd;
}

int i2c_read(int fd, uint8_t *buf, int len) {
    int n;
    n = read(fd, buf, len);
    if (n < 0) {
        perror("Failed to read from i2c bus");
        return -1;
    }
    return n;
}

int i2c_write(int fd, uint8_t *buf, int len) {
    int n;
    n = write(fd, buf, len);
    if (n < 0) {
        perror("Failed to write to i2c bus");
        return -1;
    }
    return n;
}

void init_lsm303dlhc(LSM303DLHC *lsm) {
    int fd;
    fd = i2c_open(lsm->fd, LSM303DLHC_ADDR);
    if (fd < 0) {
        return;
    }
    lsm->fd = fd;
    i2c_write(lsm->fd, (uint8_t *) {0x00}, 1);
    i2c_write(lsm->fd, (uint8_t *) {0x02}, 1);
    i2c_write(lsm->fd, (uint8_t *) {0x01}, 1);
    i2c_write(lsm->fd, (uint8_t *) {0x03}, 1);
    i2c_write(lsm->fd, (uint8_t *) {0x04}, 1);
    i2c_write(lsm->fd, (uint8_t *) {0x05}, 1);
    i2c_write(lsm->fd, (uint8_t *) {0x06}, 1);
    i2c_write(lsm->fd, (uint8_t *) {0x07}, 1);
    i2c_write(lsm->fd, (uint8_t *) {0x08}, 1);
    i2c_write(lsm->fd, (uint8_t *) {0x09}, 1);
    lsm->gyro_fd = i2c_open(lsm->fd, LSM303DLHC_ADDR);
    if (lsm->gyro_fd < 0) {
        close(lsm->fd);
        return;
    }
    lsm->accel_fd = i2c_open(lsm->fd, LSM303DLHC_ADDR);
    if (lsm->accel_fd < 0) {
        close(lsm->fd);
        close(lsm->gyro_fd);
        return;
    }
    lsm->mag_fd = i2c_open(lsm->fd, LSM303DLHC_ADDR);
    if (lsm->mag_fd < 0) {
        close(lsm->fd);
        close(lsm->gyro_fd);
        close(lsm->accel_fd);
        return;
    }
}

void read_accel(LSM303DLHC *lsm, float *accel) {
    uint8_t buf[14];
    int n;
    n = i2c_read(lsm->accel_fd, buf, 14);
    if (n < 0) {
        return;
    }
    accel[0] = (float) buf[ACCEL_X] * 0.00392;
    accel[1] = (float) buf[ACCEL_Y] * 0.00392;
    accel[2] = (float) buf[ACCEL_Z] * 0.00392;
}

void read_gyro(LSM303DLHC *lsm, float *gyro) {
    uint8_t buf[6];
    int n;
    n = i2c_read(lsm->gyro_fd, buf, 6);
    if (n < 0) {
        return;
    }
    gyro[0] = (float) buf[GYRO_X] * 0.00098;
    gyro[1] = (float) buf[GYRO_Y] * 0.00098;
    gyro[2] = (float) buf[GYRO_Z] * 0.00098;
}

void read_mag(LSM303DLHC *lsm, float *mag) {
    uint8_t buf[16];
    int n;
    n = i2c_read(lsm->mag_fd, buf, 16);
    if (n < 0) {
        return;
    }
    mag[0] = (float) buf[MAG_X] * 0.00098;
    mag[1] = (float) buf[MAG_Y] * 0.00098;
    mag[2] = (float) buf[MAG_Z] * 0.00098;
}

void compute_heading(float *accel, float *mag, float *heading) {
    float x, y, z, mx, my, mz, hx, hy, hz;
    x = accel[0];
    y = accel[1];
    z = accel[2];
    mx = mag[0];
    my = mag[1];
    mz = mag[2];
    hx = x / sqrt(x * x + y * y + z * z);
    hy = y / sqrt(x * x + y * y + z * z);
    hz = z / sqrt(x * x + y * y + z * z);
    hx = hx - mx;
    hy = hy - my;
    hz = hz - mz;
    hx = hx / sqrt(hx * hx + hy * hy + hz * hz);
    hy = hy / sqrt(hx * hx + hy * hy + hz * hz);
    *heading = atan2(hy, hx) * 180.0 / M_PI;
    *heading = *heading + 90.0;
    *heading = *heading * TILT_COMPENSATION;
}

void log_data(float *accel, float *gyro, float *mag, float heading) {
    char filename[256];
    struct timeval tv;
    FILE *fp;
    gettimeofday(&tv, NULL);
    sprintf(filename, "compass_log_%d.txt", (int) tv.tv_sec);
    if (access(filename, F_OK) == 0) {
        fp = fopen(filename, "a");
    } else {
        fp = fopen(filename, "w");
        fprintf(fp, "timestamp,heading,accel_x,accel_y,accel_z,mag_x,mag_y,mag_z\n");
    }
    if (fp == NULL) {
        perror("Failed to open log file");
        return;
    }
    fprintf(fp, "%ld,%f,%f,%f,%f,%f,%f,%f\n", (long) tv.tv_sec + tv.tv_usec / 1e6, heading, accel[0], accel[1], accel[2], mag[0], mag[1], mag[2]);
    fclose(fp);
}

int main() {
    LSM303DLHC lsm;
    float accel[3], gyro[3], mag[3], heading;
    int i, n;
    struct sigaction sa;

    sa.sa_handler = handle_sigint;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    init_lsm303dlhc(&lsm);
    if (lsm.fd < 0) {
        return 1;
    }

    while (1) {
        read_accel(&lsm, accel);
        read_gyro(&lsm, gyro);
        read_mag(&lsm, mag);
        compute_heading(accel, mag, &heading);
        log_data(accel, gyro, mag, heading);
        usleep(100000);
    }

    return 0;
}

#include <stdio.h>
