#define I2C_BUS 1
#define I2C_DEVICE "/dev/i2c-1"
#define SENSOR1_ADDR 0x40
#define SENSOR2_ADDR 0x41
#define SAMPLE_RATE 10000
#define SAMPLES_PER_CHANNEL 16
#define BUFFER_SIZE (SAMPLES_PER_CHANNEL * 2)
#define CSV_HEADER "sec,nsec,sensor1,sensor2,tdoa\n"

typedef struct {
    int fd;
    int sensor1_fd;
    int sensor2_fd;
    gpiod_device_t *dev;
    gpiod_line_mixin_t *line_mix;
    gpiod_line_t *line1;
    gpiod_line_t *line2;
} I2CManager;

void handle_sigint(int sig) {
    if (I2CManager->fd > 0) {
        close(I2CManager->fd);
    }
    if (I2CManager->sensor1_fd > 0) {
        close(I2CManager->sensor1_fd);
    }
    if (I2CManager->sensor2_fd > 0) {
        close(I2CManager->sensor2_fd);
    }
    if (I2CManager->dev) {
        gpiod_device_unref(I2CManager->dev);
    }
    if (I2CManager->line_mix) {
        gpiod_line_mix_unref(I2CManager->line_mix);
    }
    if (I2CManager->line1) {
        gpiod_line_unref(I2CManager->line1);
    }
    if (I2CManager->line2) {
        gpiod_line_unref(I2CManager->line2);
    }
    exit(EXIT_SUCCESS);
}

int main() {
    I2CManager I2CManager;
    I2CManager.fd = 0;
    I2CManager.sensor1_fd = 0;
    I2CManager.sensor2_fd = 0;
    I2CManager.dev = NULL;
    I2CManager.line_mix = NULL;
    I2CManager.line1 = NULL;
    I2CManager.line2 = NULL;

    struct i2c_rdwr_ioctl_data i2c_rdwr;
    i2c_rdwr.ioctl_cmd = I2C_SLAVE;
    i2c_rdwr.i2c_slave_addr = I2C_DEVICE;
    i2c_rdwr.flags = I2C_RDWR;

    if ((I2CManager.fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(I2CManager.fd, I2C_SLAVE, I2C_BUS) < 0) {
        perror("Failed to set I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(I2CManager.fd, I2C_RD_ACCESS, 0) < 0) {
        perror("Failed to enable read access");
        return EXIT_FAILURE;
    }

    if ((I2CManager.dev = gpiod_device_new()) < 0) {
        perror("Failed to create I2C device");
        return EXIT_FAILURE;
    }

    if ((I2CManager.line_mix = gpiod_line_mix_new()) < 0) {
        perror("Failed to create line mixer");
        return EXIT_FAILURE;
    }

    if ((I2CManager.line1 = gpiod_line_new()) < 0) {
        perror("Failed to create line 1");
        return EXIT_FAILURE;
    }

    if ((I2CManager.line2 = gpiod_line_new()) < 0) {
        perror("Failed to create line 2");
        return EXIT_FAILURE;
    }

    if (gpiod_line_mix_add_line(I2CManager.line_mix, I2CManager.line1, 0) < 0) {
        perror("Failed to add line 1 to mixer");
        return EXIT_FAILURE;
    }

    if (gpiod_line_mix_add_line(I2CManager.line_mix, I2CManager.line2, 1) < 0) {
        perror("Failed to add line 2 to mixer");
        return EXIT_FAILURE;
    }

    if (gpiod_line_set_pull_up(I2CManager.line1, 1) < 0) {
        perror("Failed to set pull-up for line 1");
        return EXIT_FAILURE;
    }

    if (gpiod_line_set_pull_up(I2CManager.line2, 1) < 0) {
        perror("Failed to set pull-up for line 2");
        return EXIT_FAILURE;
    }

    if (gpiod_line_set_edge(I2CManager.line1, GPIOD_EDGE_BOTH) < 0) {
        perror("Failed to set edge for line 1");
        return EXIT_FAILURE;
    }

    if (gpiod_line_set_edge(I2CManager.line2, GPIOD_EDGE_BOTH) < 0) {
        perror("Failed to set edge for line 2");
        return EXIT_FAILURE;
    }

    if (gpiod_line_mix_enable(I2CManager.line_mix) < 0) {
        perror("Failed to enable line mixer");
        return EXIT_FAILURE;
    }

    if (gpiod_device_enable(I2CManager.dev) < 0) {
        perror("Failed to enable device");
        return EXIT_FAILURE;
    }

    if (gpiod_line_enable(I2CManager.line1) < 0) {
        perror("Failed to enable line 1");
        return EXIT_FAILURE;
    }

    if (gpiod_line_enable(I2CManager.line2) < 0) {
        perror("Failed to enable line 2");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, handle_sigint) == SIG_ERR) {
        perror("Failed to set SIGINT handler");
        return EXIT_FAILURE;
    }

    FILE *fp = fopen("audio_log.dat", "a");
    if (!fp) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    fprintf(fp, "%s", CSV_HEADER);

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    uint32_t sample_count = 0;
    while (1) {
        if (sample_count % SAMPLES_PER_CHANNEL == 0) {
            clock_gettime(CLOCK_REALTIME, &ts);
            fprintf(fp, "%lu,%lu,", ts.tv_sec, ts.tv_nsec);
        }

        uint16_t data1 = 0;
        uint16_t data2 = 0;
        int ret1 = i2c_rdwr(I2CManager.fd, &i2c_rdwr, 1, SENSOR1_ADDR, 2, &data1);
        if (ret1 < 0) {
            perror("Failed to read sensor 1");
            continue;
        }

        int ret2 = i2c_rdwr(I2CManager.fd, &i2c_rdwr, 1, SENSOR2_ADDR, 2, &data2);
        if (ret2 < 0) {
            perror("Failed to read sensor 2");
            continue;
        }

        if (sample_count % SAMPLES_PER_CHANNEL == SAMPLES_PER_CHANNEL - 1) {
            clock_gettime(CLOCK_REALTIME, &ts);
            fprintf(fp, "%lu,%lu,%d,%d,%llu\n", ts.tv_sec, ts.tv_nsec, data1, data2, (ts.tv_sec * 1000000 + ts.tv_nsec) - (ts.tv_sec * 1000000 + ts.tv_nsec - (data1 - data2)));
        }

        sample_count++;
    }

    fclose(fp);
    return EXIT_SUCCESS;
}

