    ioctl(driver->spi, SPI_IOC_WR_MODE, SPI_MODE);
    ioctl(driver->spi, SPI_IOC_WR_MOSI, SPI0_MOSI);
    ioctl(driver->spi, SPI_IOC_WR_MISO, SPI0_MISO);
    ioctl(driver->spi, SPI_IOC_WR_MCK, SPI_CLOCK);
    ioctl(driver->spi, SPI_IOC_WR_CS, SPI0_CS);
    ioctl(driver->spi, SPI_IOC_RD_MCK, SPI_CLOCK);
    ioctl(driver->spi, SPI_IOC_RD_MOSI, SPI0_MOSI);
    ioctl(driver->spi, SPI_IOC_RD_MISO, SPI0_MISO);
    ioctl(driver->spi, SPI_IOC_RD_CS, SPI0_CS);
}

void i2c_init(ImuDriver *driver) {
    driver->i2c = open(driver->i2c_fd, O_RDWR);
    if (driver->i2c < 0) {
        handle_error(driver->i2c, "open I2C device");
    }
    ioctl(driver->i2c, I2C_SLAVE, IMU_ADDR);
}

