#define GYRO_RANGE 0x10
#define DATA_RATE 0x10
#define CONFIG 0x01
#define CONFIG_ACCEL_RANGE 0x00
#define CONFIG_GYRO_RANGE 0x00
#define CONFIG_DATA_RATE 0x10

#define SENSOR_ADDR (0x6b << I2C_BUS)
#define SENSOR_SIZE 32

typedef struct {
    uint32_t timestamp;
    float x, y, z;
    float gx, gy, gz;
