void handle_sensor_error(int err) {
    fprintf(stderr, "Sensor error: %d\n", err);
    exit(EXIT_FAILURE);
}

void handle_i2c_error(int err) {
    fprintf(stderr, "I2C error: %d\n", err);
    exit(EXIT_FAILURE);
}

void handle_sigint(int sig) {
    fprintf(stderr, "Caught SIGINT, exiting...\n");
    exit(EXIT_SUCCESS);
}

void handle_sigterm(int sig) {
    fprintf(stderr, "Caught SIGTERM, exiting...\n");
    exit(EXIT_SUCCESS);
}

void init_gpio() {
    if (ioctl(fd, SIOCSGPCLK, SCL_PIN) < 0) {
        handle_i2c_error(errno);
    }
    if (ioctl(fd, SIOCSGPCLK, SDA_PIN) < 0) {
        handle_i2c_error(errno);
    }
}

void init_sensor() {
    if (ioctl(fd, SIOCSGPCLK, SCL_PIN) < 0) {
        handle_i2c_error(errno);
    }
    if (ioctl(fd, SIOCSGPCLK, SDA_PIN) < 0) {
        handle_i2c_error(errno);
    }

    if (ioctl(fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        handle_i2c_error(errno);
    }

    if (ioctl(fd, I2C_RDWR, 0) < 0) {
        handle_i2c_error(errno);
    }

    if (ioctl(fd, I2C_SET_CONFIG, CONFIG) < 0) {
        handle_i2c_error(errno);
    }

    if (ioctl(fd, I2C_SET_CONFIG_ACCEL_RANGE, CONFIG_ACCEL_RANGE) < 0) {
        handle_i2c_error(errno);
    }

    if (ioctl(fd, I2C_SET_CONFIG_GYRO_RANGE, CONFIG_GYRO_RANGE) < 0) {
        handle_i2c_error(errno);
    }

    if (ioctl(fd, I2C_SET_CONFIG_DATA_RATE, DATA_RATE) < 0) {
        handle_i2c_error(errno);
    }

    if (ioctl(fd, I2C_SET_CONFIG, CONFIG) < 0) {
        handle_i2c_error(errno);
    }

    if (ioctl(fd, I2C_WHO_AM_I, WHO_AM_I) < 0) {
        handle_i2c_error(errno);
    }

    if (ioctl(fd, I2C_WHO_AM_I, WHO_AM_I) != 0x3D) {
        handle_i2c_error(errno);
    }
}

