#define I2C_BUS "/dev/i2c-4"
#define I2C_ADDR 0x28
#define IR_SENSOR_ADDR 0x01
#define IR_SENSOR_REG 0x00
#define IR_SENSOR_VALUE 0x01

#define GPIO_CHIP 4
#define GPIO_LINE 17

#define IR_SENSOR_TIMEOUT 1000000  // 1 second

void handle_sigint(int signum) {
    printf("Received SIGINT signal. Shutting down.\n");
    // Release GPIO line
    gpio_free(GPIO_CHIP, GPIO_LINE);
    // Close I2C bus
    close(i2c_fd);
    // Exit
    exit(EXIT_SUCCESS);
}

int main() {
    struct i2c_msg msg[1];
    struct i2c_rdwr_ioctl_msg rdwr_msg;
    int i2c_fd;
    int ret;
    int value;
    int timeout = IR_SENSOR_TIMEOUT;

    // Set up SIGINT handler
    signal(SIGINT, handle_sigint);

    // Open I2C bus
    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        goto cleanup;
    }

    // Initialize I2C message
    memset(msg, 0, sizeof(struct i2c_msg));
    msg[0].addr = I2C_ADDR;
    msg[0].flags = I2C_MSG_RESTART | I2C_MSG_WRITE;
    msg[0].len = 2;
    msg[0].data[0] = IR_SENSOR_ADDR;
    msg[0].data[1] = IR_SENSOR_REG;

    // Initialize I2C control message
    memset(&rdwr_msg, 0, sizeof(struct i2c_rdwr_ioctl_msg));
    rdwr_msg.msgs_num = 1;
    rdwr_msg.msgs = msg;

    // Write and read from I2C
    if (ioctl(i2c_fd, I2C_RDWR, &rdwr_msg) < 0) {
        perror("Failed to write/read from I2C");
        goto cleanup;
    }

    // Read value
    value = msg[0].data[1];

    // Release resources
    close(i2c_fd);

    // Main loop
    while (1) {
        // Open GPIO chip
        if ((ret = gpiochip_open(GPIO_CHIP)) < 0) {
            perror("Failed to open GPIO chip");
            goto cleanup;
        }

        // Request GPIO line
        if ((ret = gpio_request_one(GPIO_CHIP, GPIO_LINE, "ir_sensor")) < 0) {
            perror("Failed to request GPIO line");
            goto cleanup;
        }

        // Read GPIO value
        if ((ret = gpio_get_value(GPIO_CHIP, GPIO_LINE)) < 0) {
            perror("Failed to read GPIO value");
            goto cleanup;
        }

        // Check if obstacle detected
        if (ret == 0) {
            printf("Obstacle detected. Self-parking sequence started.\n");
            // Simulate routine completion
            sleep(1);
            printf("Self-parking sequence completed.\n");
        }

        // Release GPIO line
        if ((ret = gpio_free(GPIO_CHIP, GPIO_LINE)) < 0) {
            perror("Failed to release GPIO line");
            goto cleanup;
        }

        // Close GPIO chip
        if ((ret = gpiochip_close(GPIO_CHIP)) < 0) {
            perror("Failed to close GPIO chip");
            goto cleanup;
        }

        // Sleep for 1 second
        usleep(1000000);
    }

cleanup:
    // Exit
    return EXIT_FAILURE;
}

