void init_gpio(GPIOController *controller) {
    int ret;
    controller->fd = open("/dev/gpiod", O_RDONLY | O_NONBLOCK);
    if (controller->fd < 0) {
        perror("Failed to open /dev/gpiod");
        exit(EXIT_FAILURE);
    }

    ret = ioctl(controller->fd, GIOCGCHIPS, &controller->chip);
    if (ret < 0) {
        perror("Failed to get chip list");
        goto cleanup;
    }

    controller->chip = controller->chip->next;
    if (!controller->chip) {
        perror("No chip found");
        goto cleanup;
    }

    ret = ioctl(controller->fd, GIOCGLINE, &controller->line);
    if (ret < 0) {
        perror("Failed to get line");
        goto cleanup;
    }

    controller->line = controller->line->next;
    if (!controller->line) {
        perror("No line found");
        goto cleanup;
    }

    controller->pin = controller->line->number;
    controller->direction = controller->line->direction;
