#define I2C_BUS 1
#define I2C_ADDR 0x1C
#define I2C_REG_MAG_Z 0x09
#define I2C_REG_MAG_X 0x0A
#define I2C_REG_MAG_Y 0x0B
#define I2C_REG_MAG_XY 0x0C
#define I2C_REG_MAG_ZX 0x0D
#define I2C_REG_MAG_ZY 0x0E
#define I2C_REG_MAG_XYZ 0x0F
#define I2C_REG_MAG_XYZ_2 0x10
#define I2C_REG_MAG_XYZ_4 0x11
#define I2C_REG_MAG_XYZ_8 0x12
#define I2C_REG_MAG_XYZ_16 0x13
#define I2C_REG_MAG_XYZ_32 0x14
#define I2C_REG_MAG_XYZ_64 0x15
#define I2C_REG_MAG_XYZ_128 0x16
#define I2C_REG_MAG_XYZ_256 0x17
#define I2C_REG_MAG_XYZ_512 0x18
#define I2C_REG_MAG_XYZ_1024 0x19
#define I2C_REG_MAG_XYZ_2048 0x1A
#define I2C_REG_MAG_XYZ_4096 0x1B
#define I2C_REG_MAG_XYZ_8192 0x1C
#define I2C_REG_MAG_XYZ_16384 0x1D
#define I2C_REG_MAG_XYZ_32768 0x1E
#define I2C_REG_MAG_XYZ_65536 0x1F

#define LED_PIN 17
#define PWM_FREQ 1000000
#define PWM_RESOLUTION 10

#define LOG_FILE "/var/log/magnetometer.log"

void handle_sigint(int signum) {
    if (close(pwm_fd) < 0) {
        perror("Failed to close PWM file descriptor");
        exit(EXIT_FAILURE);
    }
    if (close(i2c_fd) < 0) {
        perror("Failed to close I2C file descriptor");
        exit(EXIT_FAILURE);
    }
    if (close(log_fd) < 0) {
        perror("Failed to close log file descriptor");
        exit(EXIT_FAILURE);
    }
    exit(EXIT_SUCCESS);
}

void log_error(const char *message) {
    if (log_fd < 0) {
        perror("Failed to open log file");
        return;
    }
    struct timeval tv;
    gettimeofday(&tv, NULL);
    char buffer[128];
    snprintf(buffer, sizeof(buffer), "%s %lu %lu %s\n", "Error", tv.tv_sec, tv.tv_usec, message);
    if (write(log_fd, buffer, strlen(buffer)) < 0) {
        perror("Failed to write to log file");
    }
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sa.sa_flags = SA_RESTART;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set signal handler");
        return EXIT_FAILURE;
    }

    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        log_error("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        log_error("Failed to set I2C slave address");
        return EXIT_FAILURE;
    }

    void *i2c_map = mmap(0, 512, PROT_READ | PROT_WRITE, MAP_SHARED, i2c_fd, 0);
    if (i2c_map == MAP_FAILED) {
        perror("Failed to mmap I2C memory");
        log_error("Failed to mmap I2C memory");
        return EXIT_FAILURE;
    }

    int pwm_fd = open("/dev/pwm0", O_RDWR);
    if (pwm_fd < 0) {
        perror("Failed to open PWM device");
        log_error("Failed to open PWM device");
        return EXIT_FAILURE;
    }

    if (ioctl(pwm_fd, PWM_SET_FREQ, PWM_FREQ) < 0) {
        perror("Failed to set PWM frequency");
        log_error("Failed to set PWM frequency");
        return EXIT_FAILURE;
    }

    if (ioctl(pwm_fd, PWM_SET_RESOLUTION, PWM_RESOLUTION) < 0) {
        perror("Failed to set PWM resolution");
        log_error("Failed to set PWM resolution");
        return EXIT_FAILURE;
    }

    char *pwm_buf = mmap(0, 4, PROT_READ | PROT_WRITE, MAP_SHARED, pwm_fd, 0);
    if (pwm_buf == MAP_FAILED) {
        perror("Failed to mmap PWM buffer");
        log_error("Failed to mmap PWM buffer");
        return EXIT_FAILURE;
    }

    while (1) {
        int error = 0;
        if (ioctl(i2c_fd, I2C_RDWR, i2c_map) < 0) {
            error = 1;
        }

        if (error) {
            log_error("I2C bus error");
            continue;
        }

        int z_axis = *(int *) (i2c_map + I2C_REG_MAG_Z);
        int x_axis = *(int *) (i2c_map + I2C_REG_MAG_X);
        int y_axis = *(int *) (i2c_map + I2C_REG_MAG_Y);

        double magnitude = sqrt(pow(x_axis, 2) + pow(y_axis, 2) + pow(z_axis, 2));
        double brightness = (magnitude / 32768.0) * 255.0;

        if (brightness < 0) brightness = 0;
        if (brightness > 255) brightness = 255;

        if (write(pwm_fd, pwm_buf, 4) < 0) {
            perror("Failed to write to PWM buffer");
            log_error("Failed to write to PWM buffer");
        }

        if (write(log_fd, "Sampled Z-axis magnitude: %f\n", magnitude) < 0) {
            perror("Failed to write to log file");
        }
    }

    return EXIT_SUCCESS;
}

