void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        running = 0;
        gpiod_exit();
        exit(0);
    }
}

int i2c_fd;
int i2c_handle;

void i2c_init() {
    if ((i2c_fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        exit(EXIT_FAILURE);
    }

    i2c_handle = 0;
}

void i2c_read(int reg) {
    if (ioctl(i2c_fd, I2C_RDWR, (unsigned long)&i2c_handle, reg) < 0) {
        perror("Failed to read I2C register");
        fprintf(stderr, "Error reading I2C register 0x%02x\n", reg);
        exit(EXIT_FAILURE);
    }
}

void i2c_write(int reg, int value) {
    if (ioctl(i2c_fd, I2C_RDWR, (unsigned long)&i2c_handle, reg, value) < 0) {
        perror("Failed to write I2C register");
        fprintf(stderr, "Error writing I2C register 0x%02x with value 0x%02x\n", reg, value);
        exit(EXIT_FAILURE);
    }
}

void i2c_config() {
    int config = 0x00;
    config |= 0x02; // Enable continuous conversion
    i2c_write(I2C_REG_CONFIG, config);
}

