#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <gpiod.h>

#define GPIO17 17
#define GPIO27 27

int main() {
    int fd[2];
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_edge *edge;
    struct gpiod_event *event;
    int ret;

    // Open GPIO device
    ret = gpiod_open("/dev/gpiod", O_RDWR);
    if (ret < 0) {
        perror("gpiod_open");
        return 1;
    }

    // Get the first chip
    ret = gpiod_chip_get_next(chip, 0);
    if (ret < 0) {
        perror("gpiod_chip_get_next");
        goto cleanup;
    }

    // Create a line for GPIO17
    ret = gpiod_chip_request_line(chip, GPIO17, 0);
    if (ret < 0) {
        perror("gpiod_chip_request_line");
        goto cleanup;
    }

    // Create a line for GPIO27
    ret = gpiod_chip_request_line(chip, GPIO27, 0);
    if (ret < 0) {
        perror("gpiod_chip_request_line");
        goto cleanup;
    }

    // Set both lines to LOW
    ret = gpiod_line_set_value(line, 0);
    if (ret < 0) {
        perror("gpiod_line_set_value");
        goto cleanup;
    }

    // Create an edge for GPIO17
    ret = gpiod_line_request_edge(line, GPIOD_EDGE_BOTH);
    if (ret < 0) {
        perror("gpiod_line_request_edge");
        goto cleanup;
    }

    // Create an event for GPIO17
    ret = gpiod_line_request_event(line, 0);
    if (ret < 0) {
        perror("gpiod_line_request_event");
        goto cleanup;
    }

    // Set the event to trigger on both edges
    ret = gpiod_event_set_edge(event, GPIOD_EDGE_BOTH);
    if (ret < 0) {
        perror("gpiod_event_set_edge");
        goto cleanup;
    }

    // Set the event to trigger on both edges
    ret = gpiod_event_set_callback(event, 0, 0, 0);
    if (ret < 0) {
        perror("gpiod_event_set_callback");
        goto cleanup;
    }

    // Create an edge for GPIO27
    ret = gpiod_line_request_edge(line, GPIOD_EDGE_BOTH);
    if (ret < 0) {
        perror("gpiod_line_request_edge");
        goto cleanup;
    }

    // Create an event for GPIO27
    ret = gpiod_line_request_event(line, 0);
    if (ret < 0) {
        perror("gpiod_line_request_event");
        goto cleanup;
    }

    // Set the event to trigger on both edges
    ret = gpiod_event_set_edge(event, GPIOD_EDGE_BOTH);
    if (ret < 0) {
        perror("gpiod_event_set_edge");
        goto cleanup;
    }

    // Set the event to trigger on both edges
    ret = gpiod_event_set_callback(event, 0, 0, 0);
    if (ret < 0) {
        perror("gpiod_event_set_callback");
        goto cleanup;
    }

    // Install SIGINT/SIGTERM handler
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        // Switch solenoid 1
        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value");
            fprintf(stderr, "Error setting GPIO17 to LOW\n");
            continue;
        }
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value");
            fprintf(stderr, "Error setting GPIO17 to HIGH\n");
            continue;
        }
        usleep(500000); // 500ms delay

        // Switch solenoid 2
        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value");
            fprintf(stderr, "Error setting GPIO27 to LOW\n");
            continue;
        }
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value");
            fprintf(stderr, "Error setting GPIO27 to HIGH\n");
            continue;
        }
        usleep(500000); // 500ms delay
    }

cleanup:
    // Free all resources
    while (line) {
        gpiod_line_free(line);
        line = gpiod_line_get_next(line);
    }
    gpiod_chip_free(chip);
    gpiod_close(fd[0]);
    gpiod_close(fd[1]);
    return 0;
}

void handle_signal(int signum) {
    // Release both lines
    ret = gpiod_line_set_value(line, 0);
    if (ret < 0) {
        perror("gpiod_line_set_value");
        fprintf(stderr, "Error setting GPIO17 to LOW\n");
    }
    ret = gpiod_line_set_value(line, 0);
    if (ret < 0) {
        perror("gpiod_line_set_value");
        fprintf(stderr, "Error setting GPIO27 to LOW\n");
    }

    // Free all driver library resources
    while (line) {
        gpiod_line_free(line);
        line = gpiod_line_get_next(line);
    }
    gpiod_chip_free(chip);
    gpiod_close(fd[0]);
    gpiod_close(fd[1]);
    exit(0);
}

