#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <gpiod.h>

#define GPIO_RED 17
#define GPIO_GREEN 22
#define GPIO_BLUE 27
#define PWM_FREQ 1000

int main() {
    int red_fd, green_fd, blue_fd;
    int err;

    // Initialize GPIO subsystem
    err = gpiod_init();
    if (err) {
        perror("gpiod_init");
        return 1;
    }

    // Create GPIO pull-down resources
    err = gpiod_request(&red_fd, GPIO_REQUEST_DIRECTION_OUTPUT, GPIO_NUM_GPIO(GPIO_RED));
    if (err) {
        perror("gpiod_request for red");
        gpiod_destroy();
        return 1;
    }
    err = gpiod_request(&green_fd, GPIO_REQUEST_DIRECTION_OUTPUT, GPIO_NUM_GPIO(GPIO_GREEN));
    if (err) {
        perror("gpiod_request for green");
        gpiod_destroy();
        return 1;
    }
    err = gpiod_request(&blue_fd, GPIO_REQUEST_DIRECTION_OUTPUT, GPIO_NUM_GPIO(GPIO_BLUE));
    if (err) {
        perror("gpiod_request for blue");
        gpiod_destroy();
        return 1;
    }

    // Set GPIO values to 1 (on)
    err = gpiod_set_value(&red_fd, 1);
    if (err) {
        perror("gpiod_set_value for red");
        gpiod_destroy();
        return 1;
    }
    err = gpiod_set_value(&green_fd, 1);
    if (err) {
        perror("gpiod_set_value for green");
        gpiod_destroy();
        return 1;
    }
    err = gpiod_set_value(&blue_fd, 1);
    if (err) {
        perror("gpiod_set_value for blue");
        gpiod_destroy();
        return 1;
    }

    // Create PWM resources
    err = gpiod_request_pwm(&red_pwm, PWM_REQUEST_MIN_MAX, PWM_FREQ, 0, 1);
    if (err) {
        perror("gpiod_request_pwm for red");
        gpiod_destroy();
        return 1;
    }
    err = gpiod_request_pwm(&green_pwm, PWM_REQUEST_MIN_MAX, PWM_FREQ, 0, 1);
    if (err) {
        perror("gpiod_request_pwm for green");
        gpiod_destroy();
        return 1;
    }
    err = gpiod_request_pwm(&blue_pwm, PWM_REQUEST_MIN_MAX, PWM_FREQ, 0, 1);
    if (err) {
        perror("gpiod_request_pwm for blue");
        gpiod_destroy();
        return 1;
    }

    // Set PWM to 0% duty cycle
    err = gpiod_pwm_set_duty(&red_pwm, 0);
    if (err) {
        perror("gpiod_pwm_set_duty for red");
        gpiod_destroy();
        return 1;
    }
    err = gpiod_pwm_set_duty(&green_pwm, 0);
    if (err) {
        perror("gpiod_pwm_set_duty for green");
        gpiod_destroy();
        return 1;
    }
    err = gpiod_pwm_set_duty(&blue_pwm, 0);
    if (err) {
        perror("gpiod_pwm_set_duty for blue");
        gpiod_destroy();
        return 1;
    }

    // Define sine wave function
    double sine_wave(double t) {
        return sin(2 * M_PI * t);
    }

    // Main loop
    while (1) {
        double t = (double)time(NULL) / 1000.0;
        double r = sine_wave(t);
        double g = sine_wave(t + 2 * M_PI / 3);
        double b = sine_wave(t + 4 * M_PI / 3);

        // Set PWM duty cycles
        err = gpiod_pwm_set_duty(&red_pwm, r * 255);
        if (err) {
            perror("gpiod_pwm_set_duty for red");
            gpiod_destroy();
            return 1;
        }
        err = gpiod_pwm_set_duty(&green_pwm, g * 255);
        if (err) {
            perror("gpiod_pwm_set_duty for green");
            gpiod_destroy();
            return 1;
        }
        err = gpiod_pwm_set_duty(&blue_pwm, b * 255);
        if (err) {
            perror("gpiod_pwm_set_duty for blue");
            gpiod_destroy();
            return 1;
        }

        // Sleep for 1ms
        usleep(1000);
    }

    // Cleanup
    gpiod_destroy();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <errno.h>
#include <time.h>

#define MPU6050_ADDR 0x68
#define I2C_BUS "/dev/i2c-1"
#define I2C_TIMEOUT 100
#define I2C_READ_TIMEOUT 100
#define I2C_WRITE_TIMEOUT 100
#define I2C_READ_SIZE 2
#define I2C_WRITE_SIZE 2
#define I2C_READ_SIZE_DATA 14
#define I2C_WRITE_SIZE_DATA 2

#define GYRO_X_OFFSET 0x01
#define GYRO_Y_OFFSET 0x02
#define GYRO_Z_OFFSET 0x03
#define ACCEL_X_OFFSET 0x04
#define ACCEL_Y_OFFSET 0x05
#define ACCEL_Z_OFFSET 0x06

#define GYRO_SCALE 0.015625
#define ACCEL_SCALE 0.015625

#define FILE_LOG "gyro_log.txt"

void handle_error(int err, const char *msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}

void handle_i2c_error(int err) {
    handle_error(err, "I2C error");
}

void handle_file_error(int err) {
    handle_error(err, "File error");
}

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        close(gyro_fd);
        exit(EXIT_SUCCESS);
    }
}

int main() {
    struct i2c_msg i2c_msg;
    struct i2c_rdwr_ioctl_msg i2c_rdwr_msg;
    int i2c_fd;
    int gyro_fd;
    int err;
    uint8_t data[I2C_READ_SIZE_DATA];
    uint16_t gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;
    uint64_t timestamp;
    char buffer[128];
    struct timespec ts;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        handle_file_error(err);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        handle_i2c_error(err);
    }

    if ((gyro_fd = open(FILE_LOG, O_CREAT | O_WRONLY | O_APPEND)) < 0) {
        handle_file_error(err);
    }

    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &ts);
        timestamp = (uint64_t)ts.tv_sec * 1000000 + (uint64_t)ts.tv_nsec / 1000;

        i2c_msg.addr = MPU6050_ADDR;
        i2c_msg.flags = I2C_M_RD;
        i2c_msg.buf = data;
        i2c_msg.len = I2C_READ_SIZE_DATA;

        i2c_rdwr_msg.msgs = &i2c_msg;
        i2c_rdwr_msg.nmsgs = 1;

        if (ioctl(i2c_fd, I2C_RDWR, &i2c_rdwr_msg) < 0) {
            handle_i2c_error(err);
        }

        if (data[0] & 0x80) {
            handle_error(0, "Invalid data");
        }

        gyro_x = (data[GYRO_X_OFFSET] << 8) | data[GYRO_X_OFFSET + 1];
        gyro_y = (data[GYRO_Y_OFFSET] << 8) | data[GYRO_Y_OFFSET + 1];
        gyro_z = (data[GYRO_Z_OFFSET] << 8) | data[GYRO_Z_OFFSET + 1];
        accel_x = (data[ACCEL_X_OFFSET] << 8) | data[ACCEL_X_OFFSET + 1];
        accel_y = (data[ACCEL_Y_OFFSET] << 8) | data[ACCEL_Y_OFFSET + 1];
        accel_z = (data[ACCEL_Z_OFFSET] << 8) | data[ACCEL_Z_OFFSET + 1];

        gyro_x *= GYRO_SCALE;
        gyro_y *= GYRO_SCALE;
        gyro_z *= GYRO_SCALE;
        accel_x *= ACCEL_SCALE;
        accel_y *= ACCEL_SCALE;
        accel_z *= ACCEL_SCALE;

        snprintf(buffer, sizeof(buffer), "%ld %f %f %f\n", timestamp, gyro_x, gyro_y, gyro_z);
        write(gyro_fd, buffer, strlen(buffer));

        if (sleep(100) == -1) {
            handle_error(0, "Sleep error");
        }
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <linux/sensors.h>
#include <linux/joystick.h>
#include <linux/pwm.h>
#include <linux/pigpio.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>

#define BUTTON_PIN 17
#define BUZZER_PIN 18
#define DEBOUNCE_MS 50000
#define MAX_TONES 10
#define TONE_FREQS[] { 392, 494, 587, 659, 784, 880, 988, 1046, 1175, 1319 }
#define TONE_DURATIONS[] { 100, 200, 300, 400, 500, 600, 700, 800, 900, 1000 }

volatile int button_pressed = 0;
volatile int play_flag = 0;
volatile int play_flag2 = 0;

void isr_button() {
    static int last_state = 0;
    int current_state = digitalRead(BUTTON_PIN);
    if (current_state != last_state) {
        last_state = current_state;
        if (current_state == 0) {
            button_pressed = 1;
            play_flag = 1;
        } else {
            button_pressed = 0;
        }
    }
}

void isr_play_stop() {
    if (play_flag == 1) {
        play_flag = 0;
        play_flag2 = 1;
    } else if (play_flag2 == 1) {
        play_flag2 = 0;
        play_flag = 1;
    }
}

void play_tone(int freq, int duration) {
    pwmSetMode(PWM_OUTPUT);
    pwmSetClock(1920000);
    pwmSetRange(512);
    pwmWrite(BUZZER_PIN, 256);
    usleep(duration * 1000000);
    pwmWrite(BUZZER_PIN, 0);
}

void play_melody() {
    int i;
    for (i = 0; i < MAX_TONES; i++) {
        play_tone(TONE_FREQS[i], TONE_DURATIONS[i]);
        usleep(1000000);
    }
}

void cleanup() {
    pwmCloseDevice(BUZZER_PIN);
    wiringPiI2C_close(PI2C_ID);
    wiringPiGpioUnexport(BUTTON_PIN);
    wiringPiGpioUnexport(BUZZER_PIN);
    printf("Cleanup complete.\n");
}

void handle_signal(int signum) {
    cleanup();
    printf("Received signal %d. Cleanup complete.\n", signum);
    exit(0);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    wiringPiSetupGpio();
    wiringPiI2CSetup(PI2C_ID);
    wiringPiGpioSetPullUpDnCallback(BUTTON_PIN, isr_button);

    play_flag = 0;
    play_flag2 = 0;

    while (1) {
        if (button_pressed == 1) {
            button_pressed = 0;
            play_flag = 1;
            play_melody();
        }
        if (play_flag == 1 && play_flag2 == 0) {
            play_flag2 = 1;
        }
        if (play_flag2 == 1) {
            play_flag2 = 0;
            play_flag = 1;
        }
        usleep(DEBOUNCE_MS);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/time.h>
#include <syslog.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO17 17
#define VIBRATION_LOG_FILE "vibration_events.log"
#define DEFAULT_POLL_TIMEOUT 1000
#define MAX_EVENTS 5

volatile sig_atomic_t exit_flag = 0;

typedef struct {
    int timestamp;
    int value;
} Event;

Event events[MAX_EVENTS];

int main(int argc, char *argv[]) {
    int poll_timeout = DEFAULT_POLL_TIMEOUT;
    if (argc > 1) {
        poll_timeout = atoi(argv[1]);
    }

    int fd = gpiod_open("/dev/gpiod");
    if (fd < 0) {
        perror("gpiod_open");
        return 1;
    }

    int line = gpiod_get_line(fd, GPIO17);
    if (line < 0) {
        perror("gpiod_get_line");
        goto cleanup;
    }

    int edge = gpiod_request_edge(line, GPIOD_EDGE_BOTH);
    if (edge < 0) {
        perror("gpiod_request_edge");
        goto cleanup;
    }

    struct gpiod_edge *edge_ptr = gpiod_get_edge(edge);
    if (!edge_ptr) {
        perror("gpiod_get_edge");
        goto cleanup;
    }

    struct gpiod_edge_handler handler;
    handler.edge = GPIOD_EDGE_BOTH;
    handler.callback = edge_handler;
    handler.data = NULL;

    if (gpiod_request_handler(edge_ptr, &handler) < 0) {
        perror("gpiod_request_handler");
        goto cleanup;
    }

    struct timeval tv;
    gettimeofday(&tv, NULL);
    time_t timestamp = (time_t)tv.tv_sec;
    char timestamp_str[128];
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", localtime(&timestamp));

    FILE *log_file = fopen(VIBRATION_LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        goto cleanup;
    }

    while (!exit_flag) {
        struct gpiod_edge *edge_ptr = gpiod_get_edge(edge);
        if (!edge_ptr) {
            continue;
        }

        struct gpiod_edge_value *value_ptr = gpiod_get_value(edge_ptr);
        if (!value_ptr) {
            continue;
        }

        int value = gpiod_get_value_value(value_ptr);
        if (value) {
            events[0] = {timestamp, 1};
            for (int i = 1; i < MAX_EVENTS; i++) {
                events[i] = events[i - 1];
            }
            events[MAX_EVENTS - 1] = {timestamp, 1};
        } else {
            events[0] = {timestamp, 0};
            for (int i = 1; i < MAX_EVENTS; i++) {
                events[i] = events[i - 1];
            }
            events[MAX_EVENTS - 1] = {timestamp, 0};
        }

        for (int i = 0; i < MAX_EVENTS; i++) {
            if (events[i].value == 1) {
                if (i >= 2) {
                    if (events[i - 2].value == 1) {
                        printf("EARTHQUAKE ALERT\n");
                        syslog(LOG_INFO, "EARTHQUAKE ALERT");
                        char timestamp_str[128];
                        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", localtime(&timestamp));
                        fprintf(log_file, "%s %s\n", timestamp_str, "EARTHQUAKE ALERT");
                        fflush(log_file);
                    }
                }
            }
        }

        gettimeofday(&tv, NULL);
        timestamp = (time_t)tv.tv_sec;
        char timestamp_str[128];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", localtime(&timestamp));

        fprintf(log_file, "%s %d\n", timestamp_str, value);
        fflush(log_file);

        usleep(poll_timeout * 1000);
    }

cleanup:
    gpiod_release_value(value_ptr);
    gpiod_release_edge(edge_ptr);
    gpiod_release_handler(handler);
    gpiod_close(fd);
    fclose(log_file);
    return 0;
}

void edge_handler(struct gpiod_edge *edge, void *data) {
    struct gpiod_edge_value *value_ptr = gpiod_get_value(edge);
    if (!value_ptr) {
        return;
    }

    int value = gpiod_get_value_value(value_ptr);
    if (value) {
        struct timeval tv;
        gettimeofday(&tv, NULL);
        time_t timestamp = (time_t)tv.tv_sec;
        char timestamp_str[128];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", localtime(&timestamp));

        fprintf(stderr, "Rising edge detected at %s\n", timestamp_str);
        fprintf(stderr, "Value: %d\n", value);
        fflush(stderr);

        struct gpiod_edge *edge_ptr = gpiod_get_edge(edge);
        if (!edge_ptr) {
            return;
        }

        struct gpiod_edge_value *value_ptr2 = gpiod_get_value(edge_ptr);
        if (!value_ptr2) {
            return;
        }

        gpiod_set_value_value(value_ptr2, 0);
    } else {
        struct timeval tv;
        gettimeofday(&tv, NULL);
        time_t timestamp = (time_t)tv.tv_sec;
        char timestamp_str[128];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", localtime(&timestamp));

        fprintf(stderr, "Falling edge detected at %s\n", timestamp_str);
        fprintf(stderr, "Value: %d\n", value);
        fflush(stderr);

        struct gpiod_edge *edge_ptr = gpiod_get_edge(edge);
        if (!edge_ptr) {
            return;
        }

        struct gpiod_edge_value *value_ptr2 = gpiod_get_value(edge_ptr);
        if (!value_ptr2) {
            return;
        }

        gpiod_set_value_value(value_ptr2, 1);
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/time.h>
#include <math.h>
#include <string.h>

#define I2C_DEV "/dev/i2c-1"
#define I2C_ADDR 0x1C
#define LSM303DLHC_REG_XYZ 0x01
#define LSM303DLHC_REG_MAG 0x07
#define LSM303DLHC_REG_CONFIG 0x0E
#define LSM303DLHC_REG_STATUS 0x0A
#define LSM303DLHC_REG_RESULT 0x0D
#define LSM303DLHC_REG_TEMP 0x0F

#define X_OFFSET 10
#define Y_OFFSET -5
#define Z_OFFSET 20

#define DEBUG 0

typedef struct {
    double timestamp;
    double x;
    double y;
    double z;
    double heading;
    char direction[9];
} MagData;

void log_data(MagData data) {
    char filename[256];
    FILE *fp;

    snprintf(filename, sizeof(filename), "%s", "mag_log.csv");
    fp = fopen(filename, "a");
    if (!fp) {
        perror("fopen");
        return;
    }

    fprintf(fp, "%.6f, %.2f, %.2f, %.2f, %.2f, %s\n", 
            data.timestamp, data.x, data.y, data.z, data.heading, data.direction);
    fclose(fp);
}

void handle_i2c_error(int fd, int err) {
    if (err) {
        fprintf(stderr, "I2C read error: %d\n", err);
        return;
    }
}

void read_mag_data(int fd, double *x, double *y, double *z) {
    int status;
    char buffer[16];
    double result[3];

    status = ioctl(fd, I2C_SLAVE, I2C_ADDR);
    if (status < 0) {
        handle_i2c_error(fd, status);
        return;
    }

    ioctl(fd, I2C_RDWR, buffer, LSM303DLHC_REG_MAG);
    if (DEBUG) {
        fprintf(stderr, "I2C read: %s\n", buffer);
    }

    result[0] = (double) (buffer[0] << 8 | buffer[1]) / 0x80;
    result[1] = (double) (buffer[2] << 8 | buffer[3]) / 0x80;
    result[2] = (double) (buffer[4] << 8 | buffer[5]) / 0x80;

    *x = result[0] - X_OFFSET;
    *y = result[1] - Y_OFFSET;
    *z = result[2] - Z_OFFSET;

    status = ioctl(fd, I2C_RDWR, buffer, LSM303DLHC_REG_STATUS);
    if (status < 0) {
        handle_i2c_error(fd, status);
        return;
    }

    if (buffer[0] & 0x01) {
        status = ioctl(fd, I2C_RDWR, buffer, LSM303DLHC_REG_RESULT);
        if (status < 0) {
            handle_i2c_error(fd, status);
            return;
        }

        result[0] = (double) (buffer[0] << 8 | buffer[1]) / 0x80;
        result[1] = (double) (buffer[2] << 8 | buffer[3]) / 0x80;
        result[2] = (double) (buffer[4] << 8 | buffer[5]) / 0x80;

        *x = result[0] - X_OFFSET;
        *y = result[1] - Y_OFFSET;
        *z = result[2] - Z_OFFSET;
    }
}

void read_xyz(int fd, double *x, double *y, double *z) {
    int status;
    char buffer[16];
    double result[3];

    status = ioctl(fd, I2C_SLAVE, I2C_ADDR);
    if (status < 0) {
        handle_i2c_error(fd, status);
        return;
    }

    ioctl(fd, I2C_RDWR, buffer, LSM303DLHC_REG_XYZ);
    if (DEBUG) {
        fprintf(stderr, "I2C read: %s\n", buffer);
    }

    result[0] = (double) (buffer[0] << 8 | buffer[1]) / 0x80;
    result[1] = (double) (buffer[2] << 8 | buffer[3]) / 0x80;
    result[2] = (double) (buffer[4] << 8 | buffer[5]) / 0x80;

    *x = result[0] - X_OFFSET;
    *y = result[1] - Y_OFFSET;
    *z = result[2] - Z_OFFSET;

    status = ioctl(fd, I2C_RDWR, buffer, LSM303DLHC_REG_STATUS);
    if (status < 0) {
        handle_i2c_error(fd, status);
        return;
    }
}

void read_temp(int fd, double *temp) {
    int status;
    char buffer[16];
    double result;

    status = ioctl(fd, I2C_SLAVE, I2C_ADDR);
    if (status < 0) {
        handle_i2c_error(fd, status);
        return;
    }

    ioctl(fd, I2C_RDWR, buffer, LSM303DLHC_REG_TEMP);
    if (DEBUG) {
        fprintf(stderr, "I2C read: %s\n", buffer);
    }

    result = (double) (buffer[0] << 8 | buffer[1]) / 0x80;
    *temp = result - 48.0;

    status = ioctl(fd, I2C_RDWR, buffer, LSM303DLHC_REG_STATUS);
    if (status < 0) {
        handle_i2c_error(fd, status);
        return;
    }
}

double heading(double x, double y) {
    double heading = atan2(y, x) * 180.0 / M_PI;
    if (heading < 0) {
        heading += 360.0;
    }
    return heading;
}

void print_direction(double heading) {
    if (heading < 45.0) {
        strcpy(direction, "N");
    } else if (heading < 135.0) {
        strcpy(direction, "NE");
    } else if (heading < 225.0) {
        strcpy(direction, "E");
    } else if (heading < 315.0) {
        strcpy(direction, "SE");
    } else if (heading < 45.0) {
        strcpy(direction, "S");
    } else if (heading < 135.0) {
        strcpy(direction, "SW");
    } else if (heading < 225.0) {
        strcpy(direction, "W");
    } else {
        strcpy(direction, "NW");
    }
}

int main() {
    int fd;
    double x, y, z, temp;
    struct timeval tv;
    struct timezone tz;
    double heading;
    char direction[9];

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("ioctl");
        close(fd);
        return 1;
    }

    if (DEBUG) {
        fprintf(stderr, "I2C slave address set\n");
    }

    tv.tv_sec = 1;
    tv.tv_usec = 0;
    tz.tz_minuteserver = 0;
    tz.tz_hourserver = 0;

    while (1) {
        read_xyz(fd, &x, &y, &z);
        read_temp(&temp);

        gettimeofday(&tv, &tz);
        x += X_OFFSET;
        y += Y_OFFSET;
        z += Z_OFFSET;

        heading = heading(x, y);
        print_direction(heading);

        MagData data;
        data.timestamp = tv.tv_sec + tv.tv_usec / 1000000.0;
        data.x = x;
        data.y = y;
        data.z = z;
        data.heading = heading;
        strcpy(direction, data.direction);

        log_data(data);

        if (DEBUG) {
            fprintf(stderr, "Timestamp: %.6f, X: %.2f, Y: %.2f, Z: %.2f, Heading: %.2f, Direction: %s\n", 
                    data.timestamp, data.x, data.y, data.z, data.heading, data.direction);
        }
    }

    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <gpiod.h>

#define GPIO4 4
#define GPIO17 17
#define PULL_DOWN 0
#define RELAY_LOG_FILE "relay_log.json"
#define RELAY_STATE_ON "ON"
#define RELAY_STATE_OFF "OFF"
#define DEBOUNCE_MS 200

typedef struct {
    int fd;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int state;
    time_t last_touch;
} RelayState;

void handle_sigint(int signum) {
    RelayState *rs = (RelayState *)malloc(sizeof(RelayState));
    if (!rs) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    rs->fd = open(RELAY_LOG_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (rs->fd == -1) {
        perror("Failed to open log file");
        free(rs);
        exit(EXIT_FAILURE);
    }

    char log_entry[256];
    struct tm *now = localtime(&time(NULL));
    strftime(log_entry, sizeof(log_entry), "%Y-%m-%dT%H:%M:%S", now);
    snprintf(log_entry + strlen(log_entry), sizeof(log_entry), ",\"relay_state\": \"%s\"", RELAY_STATE_OFF);
    write(rs->fd, log_entry, strlen(log_entry));

    close(rs->fd);
    free(rs);
    gpiod_chip_free(rs->chip);
    gpiod_line_free(rs->line);
    gpiod_exit(0);
    exit(EXIT_SUCCESS);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_edge *edge;
    int ret;
    RelayState *rs = (RelayState *)malloc(sizeof(RelayState));
    if (!rs) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    rs->fd = open(RELAY_LOG_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (rs->fd == -1) {
        perror("Failed to open log file");
        free(rs);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_open(&chip);
    if (ret < 0) {
        perror("Failed to open gpiod device");
        free(rs);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_chip_request_line(chip, GPIO4, PULL_DOWN, &line);
    if (ret < 0) {
        perror("Failed to request GPIO4 line");
        free(rs);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_chip_request_edge(chip, line, GPIOD_EDGE_BOTH, &edge);
    if (ret < 0) {
        perror("Failed to request edge");
        free(rs);
        exit(EXIT_FAILURE);
    }

    rs->line = line;
    rs->chip = chip;
    rs->state = 0;
    rs->last_touch = 0;

    signal(SIGINT, handle_sigint);

    while (1) {
        ret = gpiod_line_get_value(line, &rs->state);
        if (ret < 0) {
            perror("Failed to read GPIO4 value");
            free(rs);
            exit(EXIT_FAILURE);
        }

        if (rs->state && (time(NULL) - rs->last_touch) >= DEBOUNCE_MS) {
            rs->last_touch = time(NULL);
            ret = gpiod_line_edge_trigger(line, edge, GPIOD_EDGE_RISING);
            if (ret < 0) {
                perror("Failed to trigger edge");
                free(rs);
                exit(EXIT_FAILURE);
            }

            char log_entry[256];
            struct tm *now = localtime(&time(NULL));
            strftime(log_entry, sizeof(log_entry), "%Y-%m-%dT%H:%M:%S", now);
            snprintf(log_entry + strlen(log_entry), sizeof(log_entry), ",\"relay_state\": \"%s\"", RELAY_STATE_ON);
            write(rs->fd, log_entry, strlen(log_entry));

            ret = gpiod_line_edge_trigger(line, edge, GPIOD_EDGE_FALLING);
            if (ret < 0) {
                perror("Failed to trigger edge");
                free(rs);
                exit(EXIT_FAILURE);
            }
        }
    }

    free(rs);
    gpiod_chip_free(rs->chip);
    gpiod_line_free(rs->line);
    gpiod_exit(0);
    return 0;
}

