int main() {
    int fd_log = open(LOG_FILE, O_APPEND | O_CREAT | O_WRONLY, 0644);
    if (fd_log == -1) {
        perror("Failed to open log file");
        return 1;
    }

    int gpiod_fd = gpiod_open(NULL);
    if (gpiod_fd == -1) {
        perror("Failed to open gpiod");
        close(fd_log);
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_new(gpiod_fd);
    if (!chip) {
        perror("Failed to create gpiod chip");
        close(fd_log);
        gpiod_close(gpiod_fd);
        return 1;
    }

    struct gpiod_line *line = NULL;
    for (int i = 0; i < 4; i++) {
        int gpio = GPIO17 + i;
        struct gpiod_line *line = gpiod_chip_get_line(chip, gpio);
        if (!line) {
            fprintf(stderr, "Failed to find GPIO line %d\n", gpio);
            close(fd_log);
            gpiod_chip_delete(chip);
            gpiod_close(gpiod_fd);
            return 1;
        }

        if (gpiod_line_request_output(line, 1) == -1) {
            fprintf(stderr, "Failed to request output for GPIO %d\n", gpio);
            close(fd_log);
            gpiod_chip_delete(chip);
            gpiod_close(gpiod_fd);
            return 1;
        }

        line = gpiod_chip_get_line(chip, gpio);
    }

    srand(time(NULL));
    int moisture = rand() % 101;

    while (1) {
        int moisture = rand() % 101;
        char log_line[128];
        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);
        strftime(log_line, sizeof(log_line), LOG_FORMAT, &ts);
        sprintf(log_line + strlen(log_line), ",%d", moisture);

        if (moisture < 30) {
            for (int i = 0; i < 4; i++) {
                int gpio = GPIO17 + i;
                struct gpiod_line *line = gpiod_chip_get_line(chip, gpio);
                if (gpiod_line_set_value(line, 0) == -1) {
                    fprintf(stderr, "Failed to set GPIO %d to 0\n", gpio);
                    close(fd_log);
                    gpiod_chip_delete(chip);
                    gpiod_close(gpiod_fd);
                    return 1;
                }
                usleep(5000000);
                gpiod_line_set_value(line, 1);
                usleep(1000000);
            }
        }

        if (write(fd_log, log_line, strlen(log_line)) == -1) {
            fprintf(stderr, "Failed to write to log file\n");
            close(fd_log);
            gpiod_chip_delete(chip);
            gpiod_close(gpiod_fd);
            return 1;
        }

        usleep(10000000);
    }

    gpiod_chip_delete(chip);
    gpiod_close(gpiod_fd);
    close(fd_log);
    return 0;
}

