void init_gpio(int fd, int gpio) {
    if (ioctl(fd, GPIO_GET_LINE gpio, 0) < 0) {
        perror("Failed to get line state for GPIO");
        exit(EXIT_FAILURE);
    }
    if (gpio_set_direction(fd, gpio, GPIO_DIR_OUT)) {
        perror("Failed to set GPIO direction");
        exit(EXIT_FAILURE);
    }
    if (gpio_set_value(fd, gpio, 1)) {
        perror("Failed to set GPIO value");
        exit(EXIT_FAILURE);
    }
}

void release_gpio(int fd) {
    if (gpio_unexport(fd, GPIO_NUM)) {
        perror("Failed to unexport GPIO");
        exit(EXIT_FAILURE);
    }
    if (gpio_unexport(fd, GPIO_NUM2)) {
        perror("Failed to unexport GPIO");
        exit(EXIT_FAILURE);
    }
    if (gpio_unexport(fd, GPIO_NUM3)) {
        perror("Failed to unexport GPIO");
        exit(EXIT_FAILURE);
    }
    if (gpio_unexport(fd, GPIO_NUM4)) {
        perror("Failed to unexport GPIO");
        exit(EXIT_FAILURE);
    }
    if (close(fd)) {
        perror("Failed to close GPIO device");
        exit(EXIT_FAILURE);
    }
}

