#include <sys/mman.h>
#include <sys/time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define MPU6050_ADDR 0x68
#define I2C_BUS 1
#define LED_GPIO 17
#define LED_PIN 1
#define LED_MODE 0x01

#define BUFFER_SIZE 100
#define SAMPLE_RATE 20
#define BUFFER_OFFSET (sizeof(uint16_t) * 3)

typedef struct {
    uint16_t timestamp;
    uint16_t x;
    uint16_t y;
    uint16_t z;
} MPU6050Data;

MPU6050Data buffer[BUFFER_SIZE];
uint8_t bufferIndex = 0;
uint8_t bufferFull = 0;
int i2c_fd;
int i2cInit = 0;
int i2cReInitCount = 0;

void cleanup() {
    if (i2c_fd > 0) {
        close(i2c_fd);
    }
    munmap(i2c_map, i2c_size);
    i2c_fd = -1;
    i2cInit = 0;
    i2cReInitCount = 0;
}

void handleSig(int sig) {
    cleanup();
    if (i2c_fd > 0) {
        close(i2c_fd);
    }
    exit(0);
}

int i2cInitCheck() {
    if (i2c_fd > 0) {
        return 0;
    }
    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        return -1;
    }
    i2cInit = 1;
    return 0;
}

int i2cRead() {
    if (i2cInitCheck() < 0) {
        return -1;
    }
    if (i2cReInitCount >= 3) {
        return -1;
    }
    i2cReInitCount++;
    if (i2cInitCheck() < 0) {
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SMBUS_READ, 0x78) < 0) {
        perror("Failed to read MPU6050 register");
        return -1;
    }
    uint8_t data[14];
    if (read(i2c_fd, data, 14) < 0) {
        perror("Failed to read MPU6050 data");
        return -1;
    }
    uint16_t x = (data[0] << 8) | data[1];
    uint16_t y = (data[2] << 8) | data[3];
    uint16_t z = (data[4] << 8) | data[5];
    uint32_t timestamp = (data[6] << 16) | (data[7] << 8) | data[8];
    buffer[bufferIndex].timestamp = timestamp;
    buffer[bufferIndex].x = x;
    buffer[bufferIndex].y = y;
    buffer[bufferIndex].z = z;
    bufferIndex = (bufferIndex + 1) % BUFFER_SIZE;
    if (bufferIndex == 0 && bufferFull) {
        bufferFull = 0;
    }
    return 0;
}

void checkBuffer() {
    for (int i = 0; i < BUFFER_SIZE; i++) {
        if (abs(buffer[i].x) > 250 || abs(buffer[i].y) > 250 || abs(buffer[i].z) > 250) {
            digitalWrite(LED_GPIO, HIGH);
            break;
        }
    }
    if (bufferFull) {
        digitalWrite(LED_GPIO, LOW);
    }
}

int main() {
    signal(SIGINT, handleSig);
    signal(SIGTERM, handleSig);
    if (i2cInitCheck() < 0) {
        return -1;
    }
    if (mmap(NULL, 1024, PROT_READ | PROT_WRITE, MAP_SHARED, i2c_fd, 0) < 0) {
        perror("Failed to mmap I2C device");
        return -1;
    }
    i2c_map = mmap_base;
    i2c_size = 1024;
    while (1) {
        if (i2cRead() < 0) {
            if (i2cReInitCount < 3) {
                usleep(50 * 1000);
            } else {
                cleanup();
                return -1;
            }
        }
        checkBuffer();
        usleep(50 * 1000);
    }
    return 0;
}

