#include <sys/spi/spidev.h>

#define SPI_DEV "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS 8
#define SPI_ORDER MSB_FIRST
#define SPI_CS_GPIO "/dev/gpiochip0"
#define SPI_CS_OFFSET 8
#define SPI_CS_LINE 8
#define SPI_CS_LINE_NAME "gpio8"

#define LOG_FILE "gyro_log.txt"
#define LOG_FILE_MODE (O_CREAT | O_WRONLY | O_APPEND)
#define LOG_FILE_PERMISSIONS (S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH)

#define MAX_RETRIES 3
#define SPI_TIMEOUT 10

#define LOG_HEADER "timestamp,x_rate,y_rate,z_rate\n"

typedef struct {
    int fd;
    struct gpiod_handle handle;
    struct gpiod_line *line;
    struct spi_ioc_transfer transfer;
} SpiGpio;

void spi_init(SpiGpio *spi) {
    spi->fd = open(SPI_DEV, O_RDWR);
    if (spi->fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    spi->handle = gpiod_open(SPI_CS_GPIO);
    if (spi->handle == NULL) {
        perror("Failed to open GPIO device");
        exit(EXIT_FAILURE);
    }

    spi->line = gpiod_get_line(spi->handle, SPI_CS_LINE_NAME);
    if (spi->line == NULL) {
        perror("Failed to get GPIO line");
        exit(EXIT_FAILURE);
    }

    spi->transfer.msb = SPI_ORDER;
    spi->transfer.bits_per_word = SPI_BITS;
    spi->transfer.speed_hz = SPI_SPEED;
    spi->transfer.mode = SPI_MODE;
    spi->transfer.delay_us = 0;
    spi->transfer.nbytes = 3;

    spi->transfer.tx_buf = (unsigned long)&spi->transfer;
    spi->transfer.rx_buf = (unsigned long)&spi->transfer;
    spi->transfer.cs_change = 1;
    spi->transfer.cs_change_type = SPI_CS_CHANGE_EDGE;
    spi->transfer.cs_change_edge = SPI_CS_CHANGE_EDGE_FALLING;
}

void spi_deinit(SpiGpio *spi) {
    gpiod_close(spi->handle);
    gpiod_line_unref(spi->line);
    close(spi->fd);
}

void log_record(const char *timestamp, double x_rate, double y_rate, double z_rate) {
    FILE *log_file = fopen(LOG_FILE, LOG_FILE_MODE);
    if (log_file == NULL) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    fprintf(log_file, "%s,%f,%f,%f\n", timestamp, x_rate, y_rate, z_rate);
    fclose(log_file);
}

void handle_spi_error(int err) {
    fprintf(stderr, "SPI communication error: %d\n", err);
    sleep(1); // Wait for 1 second before retrying
}

void handle_log_error(int err) {
    fprintf(stderr, "Failed to write to log file: %d\n", err);
}

void handle_sigint(int sig) {
    spi_deinit(&spi);
    exit(EXIT_SUCCESS);
}

int main() {
    SpiGpio spi;
    char timestamp[128];
    double x_rate, y_rate, z_rate;
    int retries = 0;
    struct timespec ts;

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    spi_init(&spi);

    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &ts);
        long long timestamp_ns = ts.tv_sec * 1000000000LL + ts.tv_nsec;
        snprintf(timestamp, sizeof(timestamp), "%lld", timestamp_ns);

        retries = 0;
        while (retries < MAX_RETRIES) {
            spi->transfer.cs_value = 0;
            spi_transfer(spi->fd, &spi->transfer, SPI_TIMEOUT);
            if (spi->transfer.err != 0) {
                handle_spi_error(spi->transfer.err);
                retries++;
            } else {
                x_rate = (double)(spi->transfer.rx_buf[0] << 16) / 32768.0;
                y_rate = (double)(spi->transfer.rx_buf[1] << 16) / 32768.0;
                z_rate = (double)(spi->transfer.rx_buf[2] << 16) / 32768.0;
                log_record(timestamp, x_rate, y_rate, z_rate);
                break;
            }
        }

        if (retries == MAX_RETRIES) {
            handle_log_error(errno);
        }
    }

    return 0;
}

void spi_transfer(int fd, struct spi_ioc_transfer *transfer, long timeout) {
    int err = ioctl(fd, SPI_IOC_RDWR, transfer);
    if (err < 0) {
        fprintf(stderr, "SPI ioctl error: %d\n", err);
        return;
    }
}

