#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/time.h>
#include <time.h>
#include <gpiod.h>

#define GPIO17 17
#define GPIO23 23
#define GPIO24 24
#define LOG_FILE "seismic_events.txt"

typedef struct {
    int fd;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_edge *edge;
    int edge_type;
    int edge_count;
    int high_count;
    int high_start;
    int high_end;
    int high_duration;
    int high_duration_threshold;
    int high_duration_flag;
} SeismicSensor;

SeismicSensor sensors[2] = {{0}, {0}};

void handle_seismic_event(SeismicSensor *sensor) {
    char timestamp[128];
    struct timeval tv;
    struct tm *t;
    gettimeofday(&tv, NULL);
    t = localtime(&tv.tv_sec);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(sensors[0].fd, "%s - Seismic event detected!\n", timestamp);
    fflush(sensors[0].fd);
    usleep(2000000); // 2 seconds
    if (sensors[0].line->direction == GPIOD_LINE_DIR_OUT) {
        gpio_set_value(sensors[0].line->number, 0);
    }
}

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        for (int i = 0; i < 2; i++) {
            if (sensors[i].line) {
                gpio_set_value(sensors[i].line->number, 0);
            }
        }
        close(sensors[0].fd);
        exit(EXIT_SUCCESS);
    }
}

int main() {
    int result;
    SeismicSensor sensor1, sensor2;

    // Initialize GPIO driver
    result = gpiod_init();
    if (result < 0) {
        perror("gpiod_init");
        exit(EXIT_FAILURE);
    }

    // Create chip
    sensor1.chip = gpiod_chip_new();
    if (!sensor1.chip) {
        perror("gpiod_chip_new");
        gpiod_chip_unref(sensor1.chip);
        exit(EXIT_FAILURE);
    }

    // Create line for GPIO23
    sensor1.line = gpiod_chip_request_line(sensor1.chip, GPIO23, GPIOD_LINE_DIR_IN);
    if (!sensor1.line) {
        perror("gpiod_chip_request_line");
        gpiod_chip_unref(sensor1.chip);
        exit(EXIT_FAILURE);
    }

    // Create edge for GPIO23
    sensor1.edge = gpiod_line_request_edge(sensor1.line, GPIOD_EDGE_BOTH);
    if (!sensor1.edge) {
        perror("gpiod_line_request_edge");
        gpiod_chip_unref(sensor1.chip);
        gpiod_line_unref(sensor1.line);
        exit(EXIT_FAILURE);
    }

    // Set edge type to rising and falling
    sensor1.edge_type = GPIOD_EDGE_BOTH;
    sensor1.edge_count = 2;
    sensor1.high_count = 0;
    sensor1.high_start = 0;
    sensor1.high_end = 0;
    sensor1.high_duration = 0;
    sensor1.high_duration_threshold = 500000; // 500ms
    sensor1.high_duration_flag = 0;

    // Register callback for GPIO23
    result = gpiod_edge_register_callback(sensor1.edge, handle_seismic_event, NULL);
    if (result < 0) {
        perror("gpiod_edge_register_callback");
        gpiod_chip_unref(sensor1.chip);
        gpiod_line_unref(sensor1.line);
        gpiod_edge_unref(sensor1.edge);
        exit(EXIT_FAILURE);
    }

    // Create chip for GPIO24
    sensor2.chip = gpiod_chip_new();
    if (!sensor2.chip) {
        perror("gpiod_chip_new");
        gpiod_chip_unref(sensor1.chip);
        exit(EXIT_FAILURE);
    }

    // Create line for GPIO24
    sensor2.line = gpiod_chip_request_line(sensor2.chip, GPIO24, GPIOD_LINE_DIR_IN);
    if (!sensor2.line) {
        perror("gpiod_chip_request_line");
        gpiod_chip_unref(sensor1.chip);
        gpiod_line_unref(sensor1.line);
        exit(EXIT_FAILURE);
    }

    // Create edge for GPIO24
    sensor2.edge = gpiod_line_request_edge(sensor2.line, GPIOD_EDGE_BOTH);
    if (!sensor2.edge) {
        perror("gpiod_line_request_edge");
        gpiod_chip_unref(sensor2.chip);
        gpiod_line_unref(sensor2.line);
        exit(EXIT_FAILURE);
    }

    // Set edge type to rising and falling
    sensor2.edge_type = GPIOD_EDGE_BOTH;
    sensor2.edge_count = 2;
    sensor2.high_count = 0;
    sensor2.high_start = 0;
    sensor2.high_end = 0;
    sensor2.high_duration = 0;
    sensor2.high_duration_threshold = 500000; // 500ms
    sensor2.high_duration_flag = 0;

    // Register callback for GPIO24
    result = gpiod_edge_register_callback(sensor2.edge, handle_seismic_event, NULL);
    if (result < 0) {
        perror("gpiod_edge_register_callback");
        gpiod_chip_unref(sensor2.chip);
        gpiod_line_unref(sensor2.line);
        gpiod_edge_unref(sensor2.edge);
        exit(EXIT_FAILURE);
    }

    // Open log file
    sensor1.fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (sensor1.fd < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    // Install signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Run indefinitely
    while (1) {
        // Check if both sensors are HIGH for at least 500ms
        if (sensor1.high_duration_flag && sensor2.high_duration_flag && sensor1.high_duration >= sensor1.high_duration_threshold && sensor2.high_duration >= sensor1.high_duration_threshold) {
            handle_seismic_event(&sensor1);
            handle_seismic_event(&sensor2);
        }
    }

    return 0;
}

