#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/time.h>
#include <signal.h>
#include <syslog.h>
#include <errno.h>
#include <time.h>

#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <linux/i2c_smbus.h>

#include <mpr121.h>

#define I2C_BUS 1
#define GPIO17 17
#define RELAY_PIN 17
#define DEBOUNCE 100
#define POLL_INTERVAL 10

#define LOG_FILE "touch_relay.log"

#define LOG_LEVEL 1

void log_error(const char *msg, int level, const char *file, int line) {
    char timestamp[20];
    struct timeval tv;
    gettimeofday(&tv, NULL);
    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", localtime(&tv.tv_sec));
    char log_msg[256];
    snprintf(log_msg, 256, "%s [%d] %s %s:%d: %s\n", timestamp, level, msg, file, line, strerror(errno));
    FILE *log = fopen(LOG_FILE, "a");
    if (log) {
        fprintf(log, log_msg);
        fclose(log);
    } else {
        perror("Failed to open log file");
    }
}

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        log_error("Received signal", LOG_LEVEL, __FILE__, __LINE__);
        close_i2c();
        close_gpio(RELAY_PIN);
        fclose(fopen(LOG_FILE, "r+"));
        exit(EXIT_SUCCESS);
    }
}

void close_i2c() {
    if (i2c_fd > 0) {
        close(i2c_fd);
        log_error("Closed I2C interface", LOG_LEVEL, __FILE__, __LINE__);
    }
}

void close_gpio(int pin) {
    if (gpio_fd > 0) {
        close(gpio_fd);
        log_error("Released GPIO pin", LOG_LEVEL, __FILE__, __LINE__);
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        log_error("Failed to open I2C bus", LOG_LEVEL, __FILE__, __LINE__);
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, 0x19) < 0) {
        log_error("Failed to set I2C slave address", LOG_LEVEL, __FILE__, __LINE__);
        close_i2c();
        return EXIT_FAILURE;
    }

    if (mpr121_init(i2c_fd) < 0) {
        log_error("Failed to initialize MPR121", LOG_LEVEL, __FILE__, __LINE__);
        close_i2c();
        return EXIT_FAILURE;
    }

    if (mpr121_set_electrode_mode(0, MPR121_ELECTRODE_MODE_NORMAL) < 0) {
        log_error("Failed to set electrode mode", LOG_LEVEL, __FILE__, __LINE__);
        close_i2c();
        return EXIT_FAILURE;
    }

    if (mpr121_set_electrode_threshold(0, 50) < 0) {
        log_error("Failed to set electrode threshold", LOG_LEVEL, __FILE__, __LINE__);
        close_i2c();
        return EXIT_FAILURE;
    }

    if (mpr121_set_electrode_bounce(0, DEBOUNCE) < 0) {
        log_error("Failed to set electrode bounce", LOG_LEVEL, __FILE__, __LINE__);
        close_i2c();
        return EXIT_FAILURE;
    }

    if (mpr121_set_electrode_callback(0, mpr121_electrode_touch, 0) < 0) {
        log_error("Failed to set electrode callback", LOG_LEVEL, __FILE__, __LINE__);
        close_i2c();
        return EXIT_FAILURE;
    }

    if (mpr121_set_electrode_callback(0, mpr121_electrode_release, 0) < 0) {
        log_error("Failed to set electrode release callback", LOG_LEVEL, __FILE__, __LINE__);
        close_i2c();
        return EXIT_FAILURE;
    }

    if (mpr121_set_electrode_callback(0, mpr121_electrode_state, 0) < 0) {
        log_error("Failed to set electrode state callback", LOG_LEVEL, __FILE__, __LINE__);
        close_i2c();
        return EXIT_FAILURE;
    }

    if (mpr121_set_electrode_callback(0, mpr121_electrode_state, 0) < 0) {
        log_error("Failed to set electrode state callback", LOG_LEVEL, __FILE__, __LINE__);
        close_i2c();
        return EXIT_FAILURE;
    }

    int gpio_fd = open("/dev/gpiod", O_RDWR);
    if (gpio_fd < 0) {
        log_error("Failed to open GPIO device", LOG_LEVEL, __FILE__, __LINE__);
        close_i2c();
        return EXIT_FAILURE;
    }

    if (gpio_request_pin(RELAY_PIN) < 0) {
        log_error("Failed to request GPIO pin", LOG_LEVEL, __FILE__, __LINE__);
        close_gpio(RELAY_PIN);
        close_i2c();
        return EXIT_FAILURE;
    }

    if (gpio_direction_set(RELAY_PIN, GPIOHANDLE_OUTPUT)) {
        log_error("Failed to set GPIO pin direction", LOG_LEVEL, __FILE__, __LINE__);
        close_gpio(RELAY_PIN);
        close_i2c();
        return EXIT_FAILURE;
    }

    if (gpio_set_value(RELAY_PIN, 0) < 0) {
        log_error("Failed to set GPIO pin value", LOG_LEVEL, __FILE__, __LINE__);
        close_gpio(RELAY_PIN);
        close_i2c();
        return EXIT_FAILURE;
    }

    while (1) {
        struct i2c_smbus_ioctl_args args;
        args.read = 1;
        args.flags = I2C_SMBUS_READ;
        args.size = 1;
        args.data = (unsigned char *) &mpr121_state;
        if (mpr121_poll(i2c_fd, &args) < 0) {
            log_error("Failed to poll MPR121", LOG_LEVEL, __FILE__, __LINE__);
            close_i2c();
            return EXIT_FAILURE;
        }

        if (mpr121_state.electrode[0].state == MPR121_STATE_TOUCHED) {
            if (mpr121_state.electrode[0].timestamp > mpr121_state.electrode[0].last_touch) {
                mpr121_state.electrode[0].last_touch = mpr121_state.electrode[0].timestamp;
                if (gpio_set_value(RELAY_PIN, 1) < 0) {
                    log_error("Failed to set GPIO pin value", LOG_LEVEL, __FILE__, __LINE__);
                    close_gpio(RELAY_PIN);
                    close_i2c();
                    return EXIT_FAILURE;
                }
            }
        }

        usleep(POLL_INTERVAL * 1000000);
    }

    return EXIT_SUCCESS;
}

void mpr121_electrode_touch(int fd, mpr121_electrode_t *electrode) {
    log_error("Electrode 0 touched", LOG_LEVEL, __FILE__, __LINE__);
    if (gpio_set_value(RELAY_PIN, 1) < 0) {
        log_error("Failed to set GPIO pin value", LOG_LEVEL, __FILE__, __LINE__);
        close_gpio(RELAY_PIN);
        close_i2c();
        return;
    }
}

void mpr121_electrode_release(int fd, mpr121_electrode_t *electrode) {
    log_error("Electrode 0 released", LOG_LEVEL, __FILE__, __LINE__);
    if (gpio_set_value(RELAY_PIN, 0) < 0) {
        log_error("Failed to set GPIO pin value", LOG_LEVEL, __FILE__, __LINE__);
        close_gpio(RELAY_PIN);
        close_i2c();
        return;
    }
}

void mpr121_electrode_state(int fd, mpr121_electrode_t *electrode) {
    log_error("Electrode 0 state changed", LOG_LEVEL, __FILE__, __LINE__);
}

int mpr121_init(int i2c_fd) {
    if (mpr121_set_electrode_mode(0, MPR121_ELECTRODE_MODE_NORMAL) < 0) {
        return -1;
    }
    if (mpr121_set_electrode_threshold(0, 50) < 0) {
        return -1;
    }
    if (mpr121_set_electrode_bounce(0, DEBOUNCE) < 0) {
        return -1;
    }
    if (mpr121_set_electrode_callback(0, mpr121_electrode_touch, 0) < 0) {
        return -1;
    }
    if (mpr121_set_electrode_callback(0, mpr121_electrode_release, 0) < 0) {
        return -1;
    }
    if (mpr121_set_electrode_callback(0, mpr121_electrode_state, 0) < 0) {
        return -1;
    }
    return 0;
}

int mpr121_poll(int i2c_fd, struct i2c_smbus_ioctl_args *args) {
    if (i2c_smbus_read_byte_data(i2c_fd, 0x00, args->data) < 0) {
        return -1;
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/ioctl.h>
#include <linux/i2c.h>
#include <linux/i2c-dev.h>
#include <linux/joystick.h>
#include <linux/joystick.h>
#include <wiringPi.h>
#include <wiringPiDev.h>
#include <wiringPiGpio.h>
#include <wiringPiBcm2835.h>
#include <time.h>
#include <string.h>

#define GPIO17 17
#define GPIO18 18
#define GPIO23 23
#define LOG_FILE "flame_log.txt"
#define LOG_LINE "Flame Detected at %s\n"

volatile int flameDetected = 0;
volatile int flameActive = 0;
volatile int flameCount = 0;
volatile int flameLogFile = 0;
volatile int flameBuzzer = 0;
volatile int flameLed = 0;

void handleSignal(int signum) {
    if (flameLogFile) {
        close(flameLogFile);
    }
    if (flameBuzzer) {
        digitalWrite(GPIO18, 0);
    }
    if (flameLed) {
        digitalWrite(GPIO23, 0);
    }
    wiringPiGpioUnexport(GPIO17);
    wiringPiGpioUnexport(GPIO18);
    wiringPiGpioUnexport(GPIO23);
    exit(0);
}

void initGPIO() {
    wiringPiGpioExport(GPIO17);
    wiringPiGpioExport(GPIO18);
    wiringPiGpioExport(GPIO23);
    wiringPiGpioUnexport(GPIO17);
    wiringPiGpioUnexport(GPIO18);
    wiringPiGpioUnexport(GPIO23);
    wiringPiGpioSetMode(GPIO17, PI_INPUT);
    wiringPiGpioSetMode(GPIO18, PI_OUTPUT);
    wiringPiGpioSetMode(GPIO23, PI_OUTPUT);
    wiringPiGpioSetPullUpMode(GPIO17, PI_NO_PUD);
    wiringPiGpioSetPullUpMode(GPIO18, PI_NO_PUD);
    wiringPiGpioSetPullUpMode(GPIO23, PI_NO_PUD);
    wiringPiGpioSetBit(GPIO18, 0);
    wiringPiGpioSetBit(GPIO23, 0);
}

void initLog() {
    flameLogFile = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (flameLogFile < 0) {
        perror("Failed to open log file");
        exit(1);
    }
}

void logFlame() {
    if (flameDetected) {
        char timestamp[20];
        struct tm *timeinfo;
        time_t rawtime;
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
        write(flameLogFile, LOG_LINE, strlen(LOG_LINE));
        flameLogFile = fflush(flameLogFile);
    }
}

void checkFlame() {
    int value = digitalRead(GPIO17);
    if (value == 0) {
        flameCount++;
        if (flameCount >= 3) {
            flameDetected = 1;
            logFlame();
            flameBuzzer = 1;
            flameLed = 1;
        }
    } else {
        flameCount = 0;
        flameDetected = 0;
        flameBuzzer = 0;
        flameLed = 0;
    }
}

void buzzAndLed() {
    while (flameDetected) {
        digitalWrite(GPIO18, 1);
        digitalWrite(GPIO23, 1);
        delay(1000);
        digitalWrite(GPIO18, 0);
        digitalWrite(GPIO23, 0);
        delay(1000);
    }
}

int main() {
    signal(SIGINT, handleSignal);
    signal(SIGTERM, handleSignal);
    initGPIO();
    initLog();
    buzzAndLed();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/time.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO17 17
#define GPIO27 27
#define LOG_FILE "dispense_log.txt"
#define LOG_FORMAT "%ld,%d,%d,%d\n"

typedef struct {
    int fd;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_edge *edge;
} Dispenser;

Dispenser dispenser;

void handle_sigint(int sig) {
    if (dispenser.line) {
        gpiod_line_request_edge(dispenser.line, GPIOD_EDGE_BOTH, NULL);
        gpiod_line_request_edge(dispenser.line, GPIOD_EDGE_BOTH, NULL);
    }
    gpiod_chip_free(dispenser.chip);
    gpiod_exit();
    exit(0);
}

int init_driver() {
    int err;
    dispenser.chip = gpiod_chip_open("/dev/gpiod");
    if (!dispenser.chip) {
        fprintf(stderr, "Error opening gpiod device: %s\n", gpiod_chip_strerror(err));
        return 1;
    }

    dispenser.line = gpiod_chip_request_line(dispenser.chip, GPIO17, GPIOD_LINE_INPUT);
    if (!dispenser.line) {
        fprintf(stderr, "Error opening GPIO17 line: %s\n", gpiod_line_strerror(err));
        return 1;
    }

    dispenser.edge = gpiod_line_request_edge(dispenser.line, GPIOD_EDGE_BOTH, NULL);
    if (!dispenser.edge) {
        fprintf(stderr, "Error opening GPIO17 edge: %s\n", gpiod_edge_strerror(err));
        return 1;
    }

    dispenser.line = gpiod_chip_request_line(dispenser.chip, GPIO27, GPIOD_LINE_INPUT);
    if (!dispenser.line) {
        fprintf(stderr, "Error opening GPIO27 line: %s\n", gpiod_line_strerror(err));
        return 1;
    }

    dispenser.edge = gpiod_line_request_edge(dispenser.line, GPIOD_EDGE_BOTH, NULL);
    if (!dispenser.edge) {
        fprintf(stderr, "Error opening GPIO27 edge: %s\n", gpiod_edge_strerror(err));
        return 1;
    }

    return 0;
}

int main() {
    struct timeval start, end;
    int err;

    if ((err = init_driver()) != 0) {
        return err;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return 1;
    }

    while (1) {
        gettimeofday(&start, NULL);
        usleep(5000000); // 5 seconds

        // Activate solenoid 1 for 500ms
        gpiod_line_request_edge(dispenser.line, GPIOD_EDGE_RISING, NULL);
        usleep(500000); // 500ms
        gpiod_line_request_edge(dispenser.line, GPIOD_EDGE_FALLING, NULL);

        // Activate solenoid 2 for 500ms
        gpiod_line_request_edge(dispenser.line, GPIOD_EDGE_RISING, NULL);
        usleep(500000); // 500ms
        gpiod_line_request_edge(dispenser.line, GPIOD_EDGE_FALLING, NULL);

        // Deactivate both solenoids
        gpiod_line_request_edge(dispenser.line, GPIOD_EDGE_BOTH, NULL);
        gpiod_line_request_edge(dispenser.line, GPIOD_EDGE_BOTH, NULL);

        gettimeofday(&end, NULL);
        fprintf(log_file, LOG_FORMAT, start.tv_sec * 1000 + start.tv_usec / 1000, GPIO17, GPIO27, (end.tv_sec * 1000 + end.tv_usec / 1000) - start.tv_sec * 1000 - start.tv_usec / 1000);
        fflush(log_file);

        if (handle_sigint(0) != 0) {
            return 1;
        }
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <syslog.h>
#include <gpiod.h>

#define MOTOR_A_PIN 17
#define MOTOR_A_BACK_PIN 18
#define MOTOR_B_PIN 22
#define MOTOR_B_BACK_PIN 23
#define ENA_PIN 24
#define ENB_PIN 25

#define LOG_FILE "balance_log.txt"
#define LOG_FORMAT "%Y-%m-%d %H:%M:%S,%f,%f,%d,%d\n"

typedef struct {
    int pid;
    int fd;
    int fd_motor_a;
    int fd_motor_b;
    int fd_ena;
    int fd_enb;
    int fd_log;
    int log_fd;
    int log_mode;
} Driver;

static Driver driver;

static void handle_sigint(int sig) {
    if (driver.fd_log > 0) {
        close(driver.fd_log);
    }
    if (driver.fd_motor_a > 0) {
        close(driver.fd_motor_a);
    }
    if (driver.fd_motor_b > 0) {
        close(driver.fd_motor_b);
    }
    if (driver.fd_ena > 0) {
        close(driver.fd_ena);
    }
    if (driver.fd_enb > 0) {
        close(driver.fd_enb);
    }
    if (driver.fd_log > 0) {
        close(driver.fd_log);
    }
    exit(EXIT_SUCCESS);
}

static int init_driver() {
    int ret = 0;
    Driver *d = &driver;

    d->pid = getpid();
    d->fd = open("/dev/log", O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (d->fd < 0) {
        syslog(LOG_ERR, "Failed to open log file: %s", strerror(errno));
        return 1;
    }
    d->log_fd = d->fd;
    d->log_mode = O_WRONLY | O_CREAT | O_TRUNC;
    d->log_fd = open(LOG_FILE, d->log_mode, 0644);
    if (d->log_fd < 0) {
        syslog(LOG_ERR, "Failed to open log file: %s", strerror(errno));
        close(d->fd);
        return 1;
    }

    d->fd_motor_a = gpiod_new_line(MOTOR_A_PIN);
    if (d->fd_motor_a < 0) {
        syslog(LOG_ERR, "Failed to open GPIO line for Motor A: %s", strerror(errno));
        close(d->fd);
        close(d->log_fd);
        return 1;
    }
    d->fd_motor_a = gpiod_get_fd(d->fd_motor_a);
    if (d->fd_motor_a < 0) {
        syslog(LOG_ERR, "Failed to get GPIO fd for Motor A: %s", strerror(errno));
        close(d->fd);
        close(d->log_fd);
        return 1;
    }

    d->fd_motor_b = gpiod_new_line(MOTOR_B_PIN);
    if (d->fd_motor_b < 0) {
        syslog(LOG_ERR, "Failed to open GPIO line for Motor B: %s", strerror(errno));
        close(d->fd);
        close(d->log_fd);
        return 1;
    }
    d->fd_motor_b = gpiod_get_fd(d->fd_motor_b);
    if (d->fd_motor_b < 0) {
        syslog(LOG_ERR, "Failed to get GPIO fd for Motor B: %s", strerror(errno));
        close(d->fd);
        close(d->log_fd);
        return 1;
    }

    d->fd_ena = gpiod_new_line(ENA_PIN);
    if (d->fd_ena < 0) {
        syslog(LOG_ERR, "Failed to open GPIO line for ENA: %s", strerror(errno));
        close(d->fd);
        close(d->log_fd);
        return 1;
    }
    d->fd_ena = gpiod_get_fd(d->fd_ena);
    if (d->fd_ena < 0) {
        syslog(LOG_ERR, "Failed to get GPIO fd for ENA: %s", strerror(errno));
        close(d->fd);
        close(d->log_fd);
        return 1;
    }

    d->fd_enb = gpiod_new_line(ENB_PIN);
    if (d->fd_enb < 0) {
        syslog(LOG_ERR, "Failed to open GPIO line for ENB: %s", strerror(errno));
        close(d->fd);
        close(d->log_fd);
        return 1;
    }
    d->fd_enb = gpiod_get_fd(d->fd_enb);
    if (d->fd_enb < 0) {
        syslog(LOG_ERR, "Failed to get GPIO fd for ENB: %s", strerror(errno));
        close(d->fd);
        close(d->log_fd);
        return 1;
    }

    return 0;
}

static int set_motor_speed(int fd, int speed) {
    if (speed < -255 || speed > 255) {
        return 1;
    }
    return gpiod_set_value(fd, speed);
}

static int get_motor_speed(int fd) {
    int value;
    if (gpiod_get_value(fd, &value) < 0) {
        return 1;
    }
    return value;
}

static int get_tilt_error() {
    return (rand() % 21) - 10.0;
}

static int get_distance() {
    return (rand() % 198) + 2.0;
}

static int log_data(double tilt_error, double distance, int motor_a_speed, int motor_b_speed) {
    char buffer[256];
    struct tm *timeinfo;
    time_t rawtime;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(buffer, sizeof(buffer), LOG_FORMAT, timeinfo);
    fprintf(driver.log_fd, "%s,%f,%f,%d,%d\n", buffer, tilt_error, distance, motor_a_speed, motor_b_speed);
    fflush(driver.log_fd);
    return 0;
}

static int main() {
    Driver d;
    int ret = 0;
    int motor_a_speed = 0;
    int motor_b_speed = 0;
    double tilt_error = 0.0;
    double distance = 0.0;

    if (signal(SIGINT, handle_sigint) == SIG_ERR) {
        syslog(LOG_ERR, "Failed to set SIGINT handler: %s", strerror(errno));
        return 1;
    }

    if (init_driver() < 0) {
        return 1;
    }

    while (1) {
        tilt_error = get_tilt_error();
        distance = get_distance();

        if (distance < 20.0) {
            motor_a_speed = -128;
            motor_b_speed = -128;
        } else {
            motor_a_speed = 128;
            motor_b_speed = 128;
        }

        log_data(tilt_error, distance, motor_a_speed, motor_b_speed);

        if (set_motor_speed(driver.fd_motor_a, motor_a_speed) < 0) {
            syslog(LOG_ERR, "Failed to set Motor A speed: %s", strerror(errno));
        }
        if (set_motor_speed(driver.fd_motor_b, motor_b_speed) < 0) {
            syslog(LOG_ERR, "Failed to set Motor B speed: %s", strerror(errno));
        }

        usleep(5000000); // 50ms
    }

    return 0;
}

