#define RELAY_GPIO 18
#define RELAY_LOG_FILE "relay_log.txt"
#define RELAY_LOG_FORMAT "%Y-%m-%d %H:%M:%S %s"

typedef enum {
    RELAY_STATE_OFF,
    RELAY_STATE_ON
} relay_state_t;

static int relay_fd;
static int relay_state = RELAY_STATE_OFF;

static void handle_relay_state_change(const char *action) {
    if (strcmp(action, "ON") == 0) {
        relay_state = RELAY_STATE_ON;
        relay_fd = gpiod_request_fd(RELAY_GPIO, GPIOD_EDGE_NONE);
        gpiod_request_irq(relay_fd, RELAY_GPIO, RELAY_STATE_ON, NULL, NULL, NULL);
    } else if (strcmp(action, "OFF") == 0) {
        relay_state = RELAY_STATE_OFF;
        gpiod_request_fd(RELAY_GPIO, GPIOD_EDGE_NONE);
        gpiod_request_irq(relay_fd, RELAY_GPIO, RELAY_STATE_OFF, NULL, NULL, NULL);
    } else {
        syslog(LOG_ERR, "Invalid command: %s", action);
    }
}

static void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        if (relay_fd) {
            gpiod_release_fd(relay_fd);
            relay_fd = 0;
        }
        if (relay_state) {
            gpiod_request_fd(RELAY_GPIO, GPIOD_EDGE_NONE);
            gpiod_request_irq(relay_fd, RELAY_GPIO, RELAY_STATE_OFF, NULL, NULL, NULL);
        }
        close(relay_fd);
        close(relay_socket);
        fclose(relay_log_file);
        exit(EXIT_SUCCESS);
    }
}

int main() {
    struct sockaddr_in server_addr;
    struct sockaddr_in client_addr;
    int server_socket, client_socket;
    socklen_t client_len = sizeof(client_addr);
    char buffer[256];
    char command[256];
    time_t now;
    struct tm *timeinfo;

    server_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (server_socket < 0) {
        syslog(LOG_ERR, "Failed to create socket: %d", errno);
        return EXIT_FAILURE;
    }

    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(5000);

    if (bind(server_socket, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        syslog(LOG_ERR, "Failed to bind socket: %d", errno);
        close(server_socket);
        return EXIT_FAILURE;
    }

    if (listen(server_socket, 3) < 0) {
        syslog(LOG_ERR, "Failed to listen on socket: %d", errno);
        close(server_socket);
        return EXIT_FAILURE;
    }

    relay_fd = gpiod_request_fd(RELAY_GPIO, GPIOD_EDGE_NONE);
    gpiod_request_irq(relay_fd, RELAY_GPIO, RELAY_STATE_OFF, NULL, NULL, NULL);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        client_socket = accept(server_socket, (struct sockaddr *)&client_addr, &client_len);
        if (client_socket < 0) {
            syslog(LOG_ERR, "Failed to accept client: %d", errno);
            continue;
        }

        if (read(client_socket, buffer, 255) < 0) {
            syslog(LOG_ERR, "Failed to read command: %d", errno);
            close(client_socket);
            continue;
        }

        // Ignore leading and trailing whitespace
        strltrim(buffer, " \t\n\r");
        strltrim(buffer, " \t\n\r");

        if (strcmp(buffer, "ON") == 0) {
            handle_relay_state_change("ON");
        } else if (strcmp(buffer, "OFF") == 0) {
            handle_relay_state_change("OFF");
        } else {
            syslog(LOG_ERR, "Invalid command: %s", buffer);
        }

        // Log the event
        now = time(NULL);
        timeinfo = localtime(&now);
        snprintf(command, sizeof(command), RELAY_LOG_FORMAT, timeinfo, "ON" if (relay_state == RELAY_STATE_ON) else "OFF");
        fprintf(stderr, "%s\n", command);
        if (fputs(command, fopen(RELAY_LOG_FILE, "a+")) < 0) {
            syslog(LOG_ERR, "Failed to log to file: %d", errno);
        }

        close(client_socket);
    }

    return EXIT_SUCCESS;
}

