#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <linux/i2c-dev.h>
#include <wiringPi.h>
#include <wiringPiRelay.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDR 0x19
#define MPR121_REG_MHD 0x00
#define MPR121_REG_NHD 0x01
#define MPR121_REG_NCL 0x02
#define MPR121_REG_FDL 0x03
#define MPR121_REG_DEBOUNCE 0x0E
#define MPR121_REG_FFI 0x0F
#define MPR121_REG_SFI 0x10
#define MPR121_REG_CDT 0x11
#define MPR121_REG_RANGE 0x18
#define MPR121_REG_ELE_COUNT 0x1C
#define GPIO17 17

#define I2C_TIMEOUT 100

int i2c_fd = -1;
int mpr121_fd = -1;
int mpr121_initialized = 0;
int mpr121_present = 0;
int mpr121_range = 0;
int mpr121_electrode_count = 0;
int mpr121_debounce = 0;
int mpr121_ffi = 0;
int mpr121_sfi = 0;
int mpr121_cdt = 0;

void i2c_init() {
    if ((i2c_fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        exit(EXIT_FAILURE);
    }
}

void mpr121_init() {
    if (!mpr121_present) {
        return;
    }

    // Soft reset
    if (ioctl(mpr121_fd, I2C_RDWR, (unsigned long)mpr121_addr) < 0) {
        perror("Failed to send soft reset command");
        exit(EXIT_FAILURE);
    }

    // Set baseline filtering
    if (ioctl(mpr121_fd, I2C_RDWR, (unsigned long)mpr121_addr | (1 << MPR121_REG_MHD)) < 0) {
        perror("Failed to set MHD baseline filtering");
        exit(EXIT_FAILURE);
    }
    if (ioctl(mpr121_fd, I2C_RDWR, (unsigned long)mpr121_addr | (1 << MPR121_REG_NHD)) < 0) {
        perror("Failed to set NHD baseline filtering");
        exit(EXIT_FAILURE);
    }
    if (ioctl(mpr121_fd, I2C_RDWR, (unsigned long)mpr121_addr | (1 << MPR121_REG_NCL)) < 0) {
        perror("Failed to set NCL baseline filtering");
        exit(EXIT_FAILURE);
    }
    if (ioctl(mpr121_fd, I2C_RDWR, (unsigned long)mpr121_addr | (1 << MPR121_REG_FDL)) < 0) {
        perror("Failed to set FDL baseline filtering");
        exit(EXIT_FAILURE);
    }

    // Set debounce
    if (ioctl(mpr121_fd, I2C_RDWR, (unsigned long)mpr121_addr | (1 << MPR121_REG_DEBOUNCE)) < 0) {
        perror("Failed to set debounce");
        exit(EXIT_FAILURE);
    }

    // Set FFI, SFI, CDT
    if (ioctl(mpr121_fd, I2C_RDWR, (unsigned long)mpr121_addr | (1 << MPR121_REG_FFI)) < 0) {
        perror("Failed to set FFI");
        exit(EXIT_FAILURE);
    }
    if (ioctl(mpr121_fd, I2C_RDWR, (unsigned long)mpr121_addr | (1 << MPR121_REG_SFI)) < 0) {
        perror("Failed to set SFI");
        exit(EXIT_FAILURE);
    }
    if (ioctl(mpr121_fd, I2C_RDWR, (unsigned long)mpr121_addr | (1 << MPR121_REG_CDT)) < 0) {
        perror("Failed to set CDT");
        exit(EXIT_FAILURE);
    }

    // Set range
    if (ioctl(mpr121_fd, I2C_RDWR, (unsigned long)mpr121_addr | (1 << MPR121_REG_RANGE)) < 0) {
        perror("Failed to set range");
        exit(EXIT_FAILURE);
    }

    // Set electrode count
    if (ioctl(mpr121_fd, I2C_RDWR, (unsigned long)mpr121_addr | (1 << MPR121_REG_ELE_COUNT)) < 0) {
        perror("Failed to set electrode count");
        exit(EXIT_FAILURE);
    }

    // Enable auto-config
    if (ioctl(mpr121_fd, I2C_RDWR, (unsigned long)mpr121_addr | (1 << MPR121_REG_AUTO_CONFIG)) < 0) {
        perror("Failed to enable auto-config");
        exit(EXIT_FAILURE);
    }

    // Set range to 12
    if (mpr121_range == 0) {
        if (ioctl(mpr121_fd, I2C_RDWR, (unsigned long)mpr121_addr | (1 << MPR121_REG_RANGE)) < 0) {
            perror("Failed to set range to 12");
            exit(EXIT_FAILURE);
        }
    }

    mpr121_initialized = 1;
}

void mpr121_shutdown() {
    if (!mpr121_initialized) {
        return;
    }

    // Disable auto-config
    if (ioctl(mpr121_fd, I2C_RDWR, (unsigned long)mpr121_addr | (1 << MPR121_REG_AUTO_CONFIG)) < 0) {
        perror("Failed to disable auto-config");
        exit(EXIT_FAILURE);
    }

    // Set range to 0
    if (mpr121_range == 12) {
        if (ioctl(mpr121_fd, I2C_RDWR, (unsigned long)mpr121_addr | (1 << MPR121_REG_RANGE)) < 0) {
            perror("Failed to set range to 0");
            exit(EXIT_FAILURE);
        }
    }

    // Set electrode count to 0
    if (mpr121_electrode_count == 12) {
        if (ioctl(mpr121_fd, I2C_RDWR, (unsigned long)mpr121_addr | (1 << MPR121_REG_ELE_COUNT)) < 0) {
            perror("Failed to set electrode count to 0");
            exit(EXIT_FAILURE);
        }
    }

    // Disable FFI, SFI, CDT
    if (mpr121_ffi == 1) {
        if (ioctl(mpr121_fd, I2C_RDWR, (unsigned long)mpr121_addr | (1 << MPR121_REG_FFI)) < 0) {
            perror("Failed to disable FFI");
            exit(EXIT_FAILURE);
        }
    }
    if (mpr121_sfi == 1) {
        if (ioctl(mpr121_fd, I2C_RDWR, (unsigned long)mpr121_addr | (1 << MPR121_REG_SFI)) < 0) {
            perror("Failed to disable SFI");
            exit(EXIT_FAILURE);
        }
    }
    if (mpr121_cdt == 1) {
        if (ioctl(mpr121_fd, I2C_RDWR, (unsigned long)mpr121_addr | (1 << MPR121_REG_CDT)) < 0) {
            perror("Failed to disable CDT");
            exit(EXIT_FAILURE);
        }
    }

    // Disable debounce
    if (mpr121_debounce == 1) {
        if (ioctl(mpr121_fd, I2C_RDWR, (unsigned long)mpr121_addr | (1 << MPR121_REG_DEBOUNCE)) < 0) {
            perror("Failed to disable debounce");
            exit(EXIT_FAILURE);
        }
    }

    // Disable auto-config
    if (mpr121_auto_config == 1) {
        if (ioctl(mpr121_fd, I2C_RDWR, (unsigned long)mpr121_addr | (1 << MPR121_REG_AUTO_CONFIG)) < 0) {
            perror("Failed to disable auto-config");
            exit(EXIT_FAILURE);
        }
    }

    mpr121_initialized = 0;
}

void mpr121_touch_detected(int channel) {
    if (mpr121_initialized) {
        if (mpr121_electrode_count > 0) {
            if (mpr121_electrode_count == 1) {
                if (mpr121_channel[channel] & 0x8000) {
                    if (mpr121_channel[channel] == 0x8000) {
                        mpr121_channel[channel] = 0x0000;
                        wiringPiRelaySetRelay(GPIO17, 0);
                    } else {
                        mpr121_channel[channel] = 0x8000;
                        wiringPiRelaySetRelay(GPIO17, 1);
                    }
                } else {
                    mpr121_channel[channel] = 0x8000;
                    wiringPiRelaySetRelay(GPIO17, 1);
                }
            } else {
                mpr121_channel[channel] = 0x8000;
                wiringPiRelaySetRelay(GPIO17, 1);
            }
        }
    }
}

