#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <linux/i2c.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define HX711_ADDR 0x3C
#define HX711_DOUT_PIN 23
#define HX711_SCK_PIN 24
#define HX711_CHANNEL_A_GAIN 128
#define HX711_CHANNELS 2
#define HX711_BITS 24
#define HX711_SAMPLES 10
#define HX711_POLL_INTERVAL 500
#define HX711_LOCK_DURATION 200
#define HX711_RETRY_ATTEMPTS 3
#define HX711_THRESHOLD 1000
#define HX711_SCALE 1.0
#define HX711_DURATION 500

#define LOG_LEVEL_INFO 20
#define LOG_LEVEL_ERROR 30

static int hbridge_fd;
static int hbridge_line;
static int hbridge_line_count;
static struct gpiod_chip *hbridge_chip;
static struct gpiod_line *hbridge_line_list[HX711_CHANNELS];

static int hbridge_init() {
    hbridge_fd = open("/dev/gpiod", O_RDONLY | O_NONBLOCK);
    if (hbridge_fd < 0) {
        syslog(LOG_ERR, "Failed to open /dev/gpiod: %s", strerror(errno));
        return -1;
    }

    hbridge_chip = gpiod_chip_open(hbridge_fd);
    if (hbridge_chip == NULL) {
        syslog(LOG_ERR, "Failed to open gpiod chip: %s", strerror(errno));
        return -1;
    }

    hbridge_line_count = 0;
    for (int i = 0; i < HX711_CHANNELS; i++) {
        hbridge_line = gpiod_chip_request_line(hbridge_chip, HX711_SCK_PIN, GPIOD_LINE_TYPE_EDGE);
        if (hbridge_line == NULL) {
            syslog(LOG_ERR, "Failed to request line for GPIO%d: %s", HX711_SCK_PIN, strerror(errno));
            return -1;
        }
        hbridge_line_list[i] = hbridge_line;
        hbridge_line_count++;
    }

    hbridge_line = gpiod_chip_request_line(hbridge_chip, HX711_DOUT_PIN, GPIOD_LINE_TYPE_EDGE);
    if (hbridge_line == NULL) {
        syslog(LOG_ERR, "Failed to request line for GPIO%d: %s", HX711_DOUT_PIN, strerror(errno));
        return -1;
    }
    hbridge_line_list[HX711_CHANNELS] = hbridge_line;
    hbridge_line_count++;

    return 0;
}

static int hbridge_release() {
    for (int i = 0; i < hbridge_line_count; i++) {
        gpiod_line_free(hbridge_line_list[i]);
    }
    gpiod_chip_release(hbridge_chip);
    close(hbridge_fd);
    return 0;
}

static int hbridge_set_low(int line) {
    if (gpiod_line_set_value(hbridge_line_list[line], GPIOD_LINE_STATE_LOW) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO%d to LOW: %s", hbridge_line_list[line]->line_number, strerror(errno));
        return -1;
    }
    return 0;
}

static int hbridge_set_high(int line) {
    if (gpiod_line_set_value(hbridge_line_list[line], GPIOD_LINE_STATE_HIGH) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO%d to HIGH: %s", hbridge_line_list[line]->line_number, strerror(errno));
        return -1;
    }
    return 0;
}

static int hbridge_lock() {
    if (hbridge_set_high(hbridge_line_list[HX711_DOUT_PIN]) < 0) {
        return -1;
    }
    usleep(HX711_LOCK_DURATION * 1000);
    if (hbridge_set_low(hbridge_line_list[HX711_DOUT_PIN]) < 0) {
        return -1;
    }
    return 0;
}

static int hbridge_init_lock() {
    if (hbridge_set_low(hbridge_line_list[HX711_DOUT_PIN]) < 0) {
        return -1;
    }
    return 0;
}

static int hbridge_read_hx711(int channel, int gain, int bits, int samples) {
    int i, j;
    int data[HX711_CHANNELS][HX711_SAMPLES];
    int sum = 0;
    int count = 0;
    int error = 0;

    for (i = 0; i < samples; i++) {
        for (j = 0; j < bits; j++) {
            data[channel][i] = 0;
        }
        for (j = 0; j < bits; j++) {
            if (ioctl(hbridge_chip, I2C_RDWR, (unsigned long)HX711_ADDR, (unsigned long)&data[channel], 1) < 0) {
                syslog(LOG_ERR, "Failed to read I2C from HX711: %s", strerror(errno));
                error = 1;
                break;
            }
        }
        if (error) {
            break;
        }
        if (data[channel][0] < 0x800000) {
            syslog(LOG_ERR, "DOUT did not go LOW within 1 second, retrying...");
            count = 0;
            error = 1;
            continue;
        }
        for (j = 0; j < bits; j++) {
            data[channel][i] = (data[channel][i] >> j) & 1;
        }
        sum += data[channel][i];
        count++;
    }

    if (count < samples) {
        syslog(LOG_ERR, "Failed to read HX711 data, only %d samples available", count);
        return -1;
    }

    return sum / samples;
}

static int hbridge_calibrate() {
    int i;
    int sum = 0;
    int count = 0;
    int error = 0;

    for (i = 0; i < HX711_SAMPLES; i++) {
        sum += hbridge_read_hx711(0, HX711_CHANNEL_A_GAIN, HX711_BITS, 1);
        count++;
    }

    if (count < HX711_SAMPLES) {
        syslog(LOG_ERR, "Failed to calibrate HX711, only %d samples available", count);
        return -1;
    }

    return sum / HX711_SAMPLES;
}

static int hbridge_measure() {
    int i;
    int sum = 0;
    int count = 0;
    int error = 0;

    for (i = 0; i < HX711_SAMPLES; i++) {
        sum += hbridge_read_hx711(0, HX711_CHANNEL_A_GAIN, HX711_BITS, 1);
        count++;
    }

    if (count < HX711_SAMPLES) {
        syslog(LOG_ERR, "Failed to measure HX711, only %d samples available", count);
        return -1;
    }

    return sum / HX711_SAMPLES;
}

static int hbridge_main_loop() {
    int weight;
    int threshold = HX711_THRESHOLD;
    int scale = HX711_SCALE;
    int duration = HX711_DURATION;

    if (argc > 1) {
        threshold = atoi(argv[1]);
    }

    if (argc > 2) {
        scale = atof(argv[2]);
    }

    if (argc > 3) {
        duration = atoi(argv[3]);
    }

    hbridge_init_lock();

    while (1) {
        weight = hbridge_measure() * scale;
        if (weight > threshold) {
            hbridge_lock();
            usleep(duration * 1000);
            hbridge_set_low(hbridge_line_list[HX711_DOUT_PIN]);
        }
        usleep(HX711_POLL_INTERVAL * 1000);
    }

    return 0;
}

static void hbridge_signal_handler(int signum) {
    hbridge_release();
    syslog(LOG_INFO, "Received signal %d, shutting down...", signum);
    exit(EXIT_SUCCESS);
}

int main(int argc, char *argv[]) {
    struct sigaction sa;

    sa.sa_handler = hbridge_signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (hbridge_init() < 0) {
        syslog(LOG_ERR, "Failed to initialize HX711 driver: %s", strerror(errno));
        return EXIT_FAILURE;
    }

    if (hbridge_calibrate() < 0) {
        syslog(LOG_ERR, "Failed to calibrate HX711: %s", strerror(errno));
        return EXIT_FAILURE;
    }

    hbridge_main_loop();

    return EXIT_SUCCESS;
}

