#include <sys/stat.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/joystick.h>
#include <linux/pigpio.h>

#define SERVO1_PIN 7
#define SERVO2_PIN 8
#define SERVO3_PIN 9
#define SERVO4_PIN 10
#define SERVO5_PIN 11

#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500
#define PULSE_WIDTH_MIN 500
#define PULSE_WIDTH_MAX 2500
#define PULSE_WIDTH_MIN_2 500
#define PULSE_WIDTH_MAX_2 2500
#define PULSE_WIDTH_TARGET_1 1000
#define PULSE_WIDTH_TARGET_2 1500
#define PULSE_WIDTH_TARGET_3 2000
#define PULSE_WIDTH_TARGET_4 500
#define PULSE_WIDTH_TARGET_5 2500

int servo1_fd, servo2_fd, servo3_fd, servo4_fd, servo5_fd;
int servo1_return, servo2_return, servo3_return, servo4_return, servo5_return;

void init_servos() {
    servo1_fd = pigpio_open(0);
    if (servo1_fd < 0) {
        perror("pigpio_open servo1");
        exit(EXIT_FAILURE);
    }
    servo1_return = pigpio setwpi2servo(servo1_fd, SERVO1_PIN, 50);
    if (servo1_return < 0) {
        perror("pigpio setwpi2servo servo1");
        exit(EXIT_FAILURE);
    }

    servo2_fd = pigpio_open(0);
    if (servo2_fd < 0) {
        perror("pigpio_open servo2");
        exit(EXIT_FAILURE);
    }
    servo2_return = pigpio setwpi2servo(servo2_fd, SERVO2_PIN, 50);
    if (servo2_return < 0) {
        perror("pigpio setwpi2servo servo2");
        exit(EXIT_FAILURE);
    }

    servo3_fd = pigpio_open(0);
    if (servo3_fd < 0) {
        perror("pigpio_open servo3");
        exit(EXIT_FAILURE);
    }
    servo3_return = pigpio setwpi2servo(servo3_fd, SERVO3_PIN, 50);
    if (servo3_return < 0) {
        perror("pigpio setwpi2servo servo3");
        exit(EXIT_FAILURE);
    }

    servo4_fd = pigpio_open(0);
    if (servo4_fd < 0) {
        perror("pigpio_open servo4");
        exit(EXIT_FAILURE);
    }
    servo4_return = pigpio setwpi2servo(servo4_fd, SERVO4_PIN, 50);
    if (servo4_return < 0) {
        perror("pigpio setwpi2servo servo4");
        exit(EXIT_FAILURE);
    }

    servo5_fd = pigpio_open(0);
    if (servo5_fd < 0) {
        perror("pigpio_open servo5");
        exit(EXIT_FAILURE);
    }
    servo5_return = pigpio setwpi2servo(servo5_fd, SERVO5_PIN, 50);
    if (servo5_return < 0) {
        perror("pigpio setwpi2servo servo5");
        exit(EXIT_FAILURE);
    }
}

void set_servo_position(int fd, int pin, int pulse_width) {
    if (pulse_width < MIN_PULSE_WIDTH || pulse_width > MAX_PULSE_WIDTH) {
        fprintf(stderr, "Invalid pulse width: %d\n", pulse_width);
        exit(EXIT_FAILURE);
    }
    pigpio setwpi2servo(fd, pin, pulse_width);
}

void cleanup() {
    if (servo1_fd > 0) {
        pigpio setwpi2servo(servo1_fd, SERVO1_PIN, 0);
        pigpio_close(servo1_fd);
    }
    if (servo2_fd > 0) {
        pigpio setwpi2servo(servo2_fd, SERVO2_PIN, 0);
        pigpio_close(servo2_fd);
    }
    if (servo3_fd > 0) {
        pigpio setwpi2servo(servo3_fd, SERVO3_PIN, 0);
        pigpio_close(servo3_fd);
    }
    if (servo4_fd > 0) {
        pigpio setwpi2servo(servo4_fd, SERVO4_PIN, 0);
        pigpio_close(servo4_fd);
    }
    if (servo5_fd > 0) {
        pigpio setwpi2servo(servo5_fd, SERVO5_PIN, 0);
        pigpio_close(servo5_fd);
    }
}

int main() {
    init_servos();

    set_servo_position(servo1_fd, SERVO1_PIN, PULSE_WIDTH_TARGET_1);
    usleep(3000000); // 3 seconds

    set_servo_position(servo2_fd, SERVO2_PIN, PULSE_WIDTH_TARGET_2);
    usleep(3000000); // 3 seconds

    set_servo_position(servo3_fd, SERVO3_PIN, PULSE_WIDTH_TARGET_3);
    usleep(3000000); // 3 seconds

    set_servo_position(servo4_fd, SERVO4_PIN, PULSE_WIDTH_TARGET_4);
    usleep(3000000); // 3 seconds

    set_servo_position(servo5_fd, SERVO5_PIN, PULSE_WIDTH_TARGET_5);
    usleep(3000000); // 3 seconds

    cleanup();

    return 0;
}

