#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/time.h>
#include <sys/signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/hwmon.h>
#include <linux/delay.h>

#define BH1750_ADDR 0x23
#define I2C_BUS 1
#define GPIO_PIN 17
#define LOG_FILE "chicken_coop_log.txt"
#define DAWN_LUX 200
#define DUSK_LUX 50
#define HISTERY 100

typedef struct {
    int fd;
    int i2c_fd;
    int gpio_fd;
    struct i2c_msg i2c_msg;
    struct i2c_rdwr_ioctl_msg i2c_rdwr_msg;
    struct gpio_request request;
    struct gpio_event event;
    struct timeval last_read;
    int last_lux;
    int last_relay;
} SensorMonitor;

void init_sensor(SensorMonitor *sensor) {
    if ((sensor->fd = open("/dev/i2c-" I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }
    if (ioctl(sensor->fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        exit(EXIT_FAILURE);
    }
    sensor->i2c_msg.addr = BH1750_ADDR;
    sensor->i2c_msg.flags |= I2C_M_RD;
    sensor->i2c_msg.buf = (unsigned char *) &sensor->last_lux;
    sensor->i2c_rdwr_msg.msgs = &sensor->i2c_msg;
    sensor->i2c_rdwr_msg.len = sizeof(sensor->i2c_msg);
    sensor->request.request = I2C_RDWR;
    sensor->request.flags = I2C_GIOCSAD;
    if (ioctl(sensor->fd, I2C_GIOCSAD, &sensor->request) < 0) {
        perror("Failed to enable I2C address");
        exit(EXIT_FAILURE);
    }
    if (ioctl(sensor->fd, I2C_SMBHCTL1, 0) < 0) {
        perror("Failed to enable SMBus");
        exit(EXIT_FAILURE);
    }
    if ((sensor->gpio_fd = open("/dev/gpiod", O_RDWR)) < 0) {
        perror("Failed to open GPIO device");
        exit(EXIT_FAILURE);
    }
    if (gpio_request_new(&sensor->request, GPIO_PIN, GPIO_EDGE_FALL)) {
        perror("Failed to request GPIO event");
        exit(EXIT_FAILURE);
    }
    if (request_setup(&sensor->request, GPIO_EDGE_FALL, 0) < 0) {
        perror("Failed to set GPIO event");
        exit(EXIT_FAILURE);
    }
    if (request_enable(&sensor->request) < 0) {
        perror("Failed to enable GPIO event");
        exit(EXIT_FAILURE);
    }
}

void read_lux(SensorMonitor *sensor) {
    if (ioctl(sensor->fd, I2C_SMBHCTL1, I2C_SMBHCTL1_RD) < 0) {
        perror("Failed to read lux");
        exit(EXIT_FAILURE);
    }
    if (ioctl(sensor->fd, I2C_SMBHCTL1, I2C_SMBHCTL1_RD) < 0) {
        perror("Failed to read lux");
        exit(EXIT_FAILURE);
    }
    if (read(sensor->fd, &sensor->last_lux, 1) < 0) {
        perror("Failed to read lux");
        exit(EXIT_FAILURE);
    }
    sensor->last_read.tv_sec = sensor->last_read.tv_sec + 5;
    gettimeofday(&sensor->last_read, NULL);
}

void write_relay(SensorMonitor *sensor, int state) {
    if (ioctl(sensor->gpio_fd, GPIO_GET_VALUE, &sensor->event.value) < 0) {
        perror("Failed to read GPIO value");
        exit(EXIT_FAILURE);
    }
    if (state) {
        if (gpio_set_value(&sensor->request, GPIO_HIGH) < 0) {
            perror("Failed to set GPIO value");
            exit(EXIT_FAILURE);
        }
    } else {
        if (gpio_set_value(&sensor->request, GPIO_LOW) < 0) {
            perror("Failed to set GPIO value");
            exit(EXIT_FAILURE);
        }
    }
    sensor->last_relay = state;
}

void log_data(SensorMonitor *sensor) {
    char buffer[128];
    struct tm *timeinfo;
    time_t rawtime;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(stderr, "Logging: %s, Lux = %d, Relay = %d\n", buffer, sensor->last_lux, sensor->last_relay);
    fprintf(stderr, "Writing to log file: %s, Lux = %d, Relay = %d\n", buffer, sensor->last_lux, sensor->last_relay);
    if (fopen(LOG_FILE, "a") == NULL) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
    fprintf(stderr, "Log file opened successfully\n");
    fprintf(stderr, "Writing to log file: %s, Lux = %d, Relay = %d\n", buffer, sensor->last_lux, sensor->last_relay);
    fprintf(stderr, "Closing log file\n");
    if (fclose(fopen(LOG_FILE, "a")) < 0) {
        perror("Failed to close log file");
        exit(EXIT_FAILURE);
    }
}

void handle_signal(SensorMonitor *sensor, int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        fprintf(stderr, "Received signal %d, shutting down\n", signum);
        log_data(sensor);
        if (sensor->gpio_fd > 0) {
            if (gpio_request_free(&sensor->request) < 0) {
                perror("Failed to free GPIO request");
                exit(EXIT_FAILURE);
            }
            if (request_disable(&sensor->request) < 0) {
                perror("Failed to disable GPIO event");
                exit(EXIT_FAILURE);
            }
            if (close(sensor->gpio_fd) < 0) {
                perror("Failed to close GPIO device");
                exit(EXIT_FAILURE);
            }
        }
        if (sensor->i2c_fd > 0) {
            if (close(sensor->i2c_fd) < 0) {
                perror("Failed to close I2C device");
                exit(EXIT_FAILURE);
            }
        }
        if (sensor->fd > 0) {
            if (close(sensor->fd) < 0) {
                perror("Failed to close I2C device");
                exit(EXIT_FAILURE);
            }
        }
        fprintf(stderr, "Exiting cleanly\n");
        exit(EXIT_SUCCESS);
    }
}

int main() {
    SensorMonitor sensor;
    init_sensor(&sensor);
    while (1) {
        read_lux(&sensor);
        if (sensor.last_lux < DUSK_LUX && sensor.last_lux > sensor.last_relay) {
            write_relay(&sensor, 1);
        } else if (sensor.last_lux > DAWN_LUX && sensor.last_lux < sensor.last_relay) {
            write_relay(&sensor, 0);
        }
        log_data(&sensor);
        usleep(180000); // Wait at least 180ms after issuing the mode command
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_MS 50
#define LOG_INTERVAL_MS 10

typedef struct {
    int fd;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int state;
    int last_state;
    int last_time;
} TouchRelay;

static void sigint_handler(int sig) {
    TouchRelay *tr = (TouchRelay *)malloc(sizeof(TouchRelay));
    tr->fd = -1;
    tr->chip = NULL;
    tr->line = NULL;
    tr->state = 0;
    tr->last_state = 0;
    tr->last_time = 0;

    if (tr->line) {
        gpiod_line_close(tr->line);
    }
    if (tr->chip) {
        gpiod_chip_free(tr->chip);
    }
    free(tr);

    printf("Relay OFF. Exiting.\n");
    exit(0);
}

int main() {
    signal(SIGINT, sigint_handler);

    TouchRelay *tr = (TouchRelay *)malloc(sizeof(TouchRelay));
    tr->fd = -1;
    tr->chip = NULL;
    tr->line = NULL;
    tr->state = 0;
    tr->last_state = 0;
    tr->last_time = 0;

    tr->fd = open("/dev/gpiod", O_RDONLY | O_NONBLOCK);
    if (tr->fd == -1) {
        perror("Failed to open /dev/gpiod");
        return 1;
    }

    tr->chip = gpiod_chip_open(tr->fd);
    if (tr->chip == NULL) {
        perror("Failed to open gpiod_chip");
        goto cleanup;
    }

    tr->line = gpiod_chip_get_line(tr->chip, GPIO_LINE_4);
    if (tr->line == NULL) {
        perror("Failed to get GPIO_LINE_4");
        goto cleanup;
    }

    tr->line->direction = GPIOD_LINE_DIR_IN;
    if (gpiod_chip_request_line(tr->chip, tr->line, 0) == -1) {
        perror("Failed to request GPIO_LINE_4");
        goto cleanup;
    }

    tr->line->edge = GPIOD_EDGE_FALL;
    if (gpiod_chip_request_edge(tr->chip, tr->line, 0) == -1) {
        perror("Failed to request edge");
        goto cleanup;
    }

    tr->line->edge_timeout = DEBOUNCE_MS;
    if (gpiod_chip_request_edge_timeout(tr->chip, tr->line, 0) == -1) {
        perror("Failed to request edge timeout");
        goto cleanup;
    }

    tr->line->edge_callback = (gpiod_edge_callback_t)edge_callback;
    if (gpiod_chip_request_edge_callback(tr->chip, tr->line, 0) == -1) {
        perror("Failed to request edge callback");
        goto cleanup;
    }

    tr->line->edge_callback(tr->line, NULL);

    tr->fd = open("/dev/relay", O_RDWR);
    if (tr->fd == -1) {
        perror("Failed to open /dev/relay");
        goto cleanup;
    }

    tr->line->value = 0;
    if (gpiod_chip_request_value(tr->chip, tr->line, 0) == -1) {
        perror("Failed to request value");
        goto cleanup;
    }

    tr->line->value = 1;
    if (gpiod_chip_request_value(tr->chip, tr->line, 1) == -1) {
        perror("Failed to set value");
        goto cleanup;
    }

    while (1) {
        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);
        if (ts.tv_sec * 1000 + ts.tv_nsec / 1000 >= tr->last_time + LOG_INTERVAL_MS) {
            tr->last_time = ts.tv_sec * 1000 + ts.tv_nsec / 1000;
            printf("%ld %s\n", tr->last_time, tr->state ? "ON" : "OFF");
        }

        if (tr->line->value) {
            tr->state = 1;
        } else {
            tr->state = 0;
        }

        if (tr->state != tr->last_state) {
            tr->last_state = tr->state;
            if (tr->state) {
                if (write(tr->fd, "1", 1) != 1) {
                    perror("Failed to write to /dev/relay");
                    goto cleanup;
                }
            } else {
                if (write(tr->fd, "0", 1) != 1) {
                    perror("Failed to write to /dev/relay");
                    goto cleanup;
                }
            }
        }

        usleep(10);
    }

cleanup:
    if (tr->line) {
        gpiod_line_close(tr->line);
    }
    if (tr->chip) {
        gpiod_chip_free(tr->chip);
    }
    if (tr->fd != -1) {
        close(tr->fd);
    }
    free(tr);
    return 0;
}

gpiod_edge_callback_t edge_callback(gpiod_line_t line, void *arg) {
    if (line->value) {
        if (line->last_value == 0) {
            if (line->last_time + DEBOUNCE_MS > clock_gettime(CLOCK_MONOTONIC, &line->ts).tv_sec * 1000 + line->ts.tv_nsec / 1000) {
                line->last_time = clock_gettime(CLOCK_MONOTONIC, &line->ts).tv_sec * 1000 + line->ts.tv_nsec / 1000;
                if (line->value) {
                    if (write(line->fd, "1", 1) != 1) {
                        perror("Failed to write to /dev/relay");
                        goto cleanup;
                    }
                } else {
                    if (write(line->fd, "0", 1) != 1) {
                        perror("Failed to write to /dev/relay");
                        goto cleanup;
                    }
                }
            }
        }
    }
    return 0;
}

