#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <string.h>
#include <poll.h>
#include <gpiod.h>

#define GPIO4 4
#define GPIO17 17
#define RELAY_ON 1
#define RELAY_OFF 0
#define TOUCH_SENSOR 0
#define RELAY_PIN 1
#define POLL_INTERVAL 50000000  // 50ms
#define TOUCH_TIMEOUT 10000000  // 10 seconds

volatile int exit_flag = 0;

int main() {
    int fd;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_edge *edge;
    struct gpiod_event *event;
    struct pollfd pollfd;
    int state = RELAY_OFF;
    int touch_state = 0;
    int timeout = TOUCH_TIMEOUT;
    int relay_state = RELAY_OFF;

    fd = open("/dev/gpiod", O_RDONLY);
    if (fd < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    chip = gpiod_chip_open(fd);
    if (!chip) {
        perror("gpiod_chip_open");
        close(fd);
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip, GPIO4);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        close(fd);
        exit(EXIT_FAILURE);
    }

    edge = gpiod_line_request_edge(line, GPIOD_EDGE_BOTH);
    if (!edge) {
        perror("gpiod_line_request_edge");
        gpiod_chip_close(chip);
        gpiod_line_unref(line);
        close(fd);
        exit(EXIT_FAILURE);
    }

    event = gpiod_edge_request_event(edge, TOUCH_SENSOR);
    if (!event) {
        perror("gpiod_edge_request_event");
        gpiod_edge_unref(edge);
        gpiod_line_unref(line);
        gpiod_chip_close(chip);
        close(fd);
        exit(EXIT_FAILURE);
    }

    fd = open("/dev/gpiod", O_RDONLY);
    if (fd < 0) {
        perror("open");
        close(fd);
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip, GPIO17);
    if (!line) {
        perror("gpiod_chip_get_line");
        close(fd);
        exit(EXIT_FAILURE);
    }

    edge = gpiod_line_request_edge(line, GPIOD_EDGE_BOTH);
    if (!edge) {
        perror("gpiod_line_request_edge");
        gpiod_chip_close(chip);
        gpiod_line_unref(line);
        close(fd);
        exit(EXIT_FAILURE);
    }

    event = gpiod_edge_request_event(edge, RELAY_PIN);
    if (!event) {
        perror("gpiod_edge_request_event");
        gpiod_edge_unref(edge);
        gpiod_line_unref(line);
        gpiod_chip_close(chip);
        close(fd);
        exit(EXIT_FAILURE);
    }

    gpiod_chip_claim_line(chip, line);
    gpiod_chip_claim_edge(chip, edge);
    gpiod_chip_claim_event(chip, event);

    gpiod_chip_enable(chip, GPIOD_ENABLE_BOTH);

    fd = open("/dev/poll", O_RDWR);
    if (fd < 0) {
        perror("open");
        close(fd);
        exit(EXIT_FAILURE);
    }

    pollfd.fd = fd;
    pollfd.events = POLLIN | POLLERR | POLLHUP | POLLNVAL;
    pollfd.revents = 0;

    while (!exit_flag) {
        if (poll(&pollfd, 1, POLL_TIMEOUT)) {
            if (pollfd.revents & POLLIN) {
                if (gpiod_event_get_value(event)) {
                    touch_state = 1;
                    relay_state = RELAY_ON;
                } else {
                    touch_state = 0;
                    relay_state = RELAY_OFF;
                }
            } else if (pollfd.revents & (POLLERR | POLLHUP | POLLNVAL)) {
                gpiod_edge_unref(edge);
                gpiod_line_unref(line);
                gpiod_chip_close(chip);
                gpiod_chip_unref(chip);
                close(fd);
                exit(EXIT_FAILURE);
            }
        }

        if (relay_state == RELAY_ON && touch_state == 1) {
            timeout = TOUCH_TIMEOUT;
        } else if (relay_state == RELAY_ON && touch_state == 0) {
            relay_state = RELAY_OFF;
            timeout = 0;
        }

        if (timeout == 0) {
            gpiod_edge_unref(edge);
            gpiod_line_unref(line);
            gpiod_chip_close(chip);
            gpiod_chip_unref(chip);
            close(fd);
            state = RELAY_OFF;
            break;
        }

        if (relay_state == RELAY_OFF && touch_state == 1) {
            relay_state = RELAY_ON;
            timeout = 0;
        }

        if (relay_state == RELAY_ON && touch_state == 1) {
            gpiod_edge_set_edge(edge, GPIOD_EDGE_RISING);
        } else {
            gpiod_edge_set_edge(edge, GPIOD_EDGE_BOTH);
        }

        if (relay_state == RELAY_ON) {
            gpiod_line_set_value(line, RELAY_ON);
        } else {
            gpiod_line_set_value(line, RELAY_OFF);
        }

        if (relay_state == RELAY_ON) {
            gpiod_event_set_value(event, 1);
        } else {
            gpiod_event_set_value(event, 0);
        }

        if (relay_state == RELAY_ON) {
            gpiod_chip_request_polarity(chip, line, 1);
        } else {
            gpiod_chip_request_polarity(chip, line, 0);
        }

        if (relay_state == RELAY_ON) {
