#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_NUM 16
#define GPIO_NUM_RELAY 20
#define LOG_FILE "relay_events.log"
#define LOG_FORMAT "%Y-%m-%d %H:%M:%S %ld %s\n"

typedef struct {
    int fd;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
} GPIOHandler;

void handle_sigint(int signum) {
    GPIOHandler *handler = (GPIOHandler *) signal_info(signum)->si_signam;
    if (handler) {
        gpiod_line_close(handler->line);
        gpiod_chip_free(handler->chip);
        close(handler->fd);
    }
    exit(EXIT_SUCCESS);
}

GPIOHandler *init_gpio_handler(int gpio_num) {
    int fd;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_event *event;

    fd = open("/dev/gpiod", O_RDONLY);
    if (fd < 0) {
        perror("Failed to open /dev/gpiod");
        return NULL;
    }

    chip = gpiod_chip_open(fd);
    if (!chip) {
        perror("Failed to open gpiod_chip");
        close(fd);
        return NULL;
    }

    line = gpiod_chip_request_line(chip, gpio_num);
    if (!line) {
        perror("Failed to request GPIO line");
        gpiod_chip_free(chip);
        close(fd);
        return NULL;
    }

    handler->fd = fd;
    handler->chip = chip;
    handler->line = line;

    event = gpiod_line_request_event(line, GPIOD_LINE_EVENT_EDGE);
    if (!event) {
        perror("Failed to request GPIO event");
        gpiod_chip_free(chip);
        gpiod_line_free(line);
        close(fd);
        return NULL;
    }

    return handler;
}

void read_gpio(GPIOHandler *handler) {
    int value;
    gpiod_line_get_value(handler->line, &value);
    if (value == 0) {
        printf("Obstacle detected\n");
        if (handler->line->direction == GPIOD_LINE_DIR_IN) {
            gpiod_line_set_value(handler->line, 1);
        } else {
            gpiod_line_set_value(handler->line, 0);
        }
    } else {
        printf("No obstacle detected\n");
        if (handler->line->direction == GPIOD_LINE_DIR_IN) {
            gpiod_line_set_value(handler->line, 0);
        } else {
            gpiod_line_set_value(handler->line, 1);
        }
    }
}

void log_event(int state, const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[128];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(buffer, sizeof(buffer), LOG_FORMAT, timeinfo);

    if (fopen(LOG_FILE, "a") == NULL) {
        perror("Failed to open log file for appending");
        return;
    }

    fprintf(stderr, "%s: %s\n", buffer, message);
    fprintf(stderr, "%s: %d\n", buffer, state);
    fprintf(f, "%s: %d\n", buffer, state);
    fclose(f);
}

int main() {
    GPIOHandler *handler = init_gpio_handler(GPIO_NUM);
    if (!handler) {
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    int state = 0;
    while (1) {
        read_gpio(handler);
        log_event(state, "Toggle event");
        state ^= 1;
    }

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/time.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>

#define GPIO_MAJOR 4
#define GPIO_MINOR 120
#define GPIO_BASE 0x40000000
#define GPIO_OFFSET 0x20000000

#define GPIO17 17
#define GPIO18 18

#define BUZZER_ON 1
#define BUZZER_OFF 0

#define LOG_FILE "motion_log.txt"

#define LOG_FORMAT "%Y-%m-%d %H:%M:%S"

typedef struct {
    int fd;
    int gpio;
    int buzzer;
} GPIOContext;

void gpio_init(GPIOContext *ctx) {
    ctx->fd = open("/dev/gpiod", O_RDWR);
    if (ctx->fd < 0) {
        perror("Failed to open /dev/gpiod");
        exit(EXIT_FAILURE);
    }

    ctx->gpio = ioctl(ctx->fd, GPIO_GET_DEVICE, 0);
    if (ctx->gpio < 0) {
        perror("Failed to get GPIO device");
        close(ctx->fd);
        exit(EXIT_FAILURE);
    }

    ctx->gpio->direction = GPIO_DIR_OUT;
    if (ioctl(ctx->fd, GPIO_SET_DIRECTION, ctx->gpio) < 0) {
        perror("Failed to set GPIO direction");
        close(ctx->fd);
        exit(EXIT_FAILURE);
    }

    ctx->gpio->value = BUZZER_OFF;
    if (ioctl(ctx->fd, GPIO_SET_VALUE, ctx->gpio) < 0) {
        perror("Failed to set GPIO value");
        close(ctx->fd);
        exit(EXIT_FAILURE);
    }

    ctx->buzzer = ctx->gpio->gpio[GPIO18];
    if (ctx->buzzer < 0) {
        perror("Failed to get GPIO 18");
        close(ctx->fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(ctx->fd, GPIO_GET_PIN, ctx->buzzer) < 0) {
        perror("Failed to get GPIO 18 pin");
        close(ctx->fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(ctx->fd, GPIO_SET_PIN, ctx->buzzer) < 0) {
        perror("Failed to set GPIO 18 pin");
        close(ctx->fd);
        exit(EXIT_FAILURE);
    }
}

void gpio_cleanup(GPIOContext *ctx) {
    if (ctx->fd >= 0) {
        close(ctx->fd);
    }
}

void buzzer_on(GPIOContext *ctx) {
    if (ioctl(ctx->fd, GPIO_SET_PIN, ctx->buzzer) < 0) {
        perror("Failed to set GPIO 18 pin");
        gpio_cleanup(ctx);
        exit(EXIT_FAILURE);
    }
}

void buzzer_off(GPIOContext *ctx) {
    if (ioctl(ctx->fd, GPIO_CLR_PIN, ctx->buzzer) < 0) {
        perror("Failed to clear GPIO 18 pin");
        gpio_cleanup(ctx);
        exit(EXIT_FAILURE);
    }
}

void log_motion(const char *timestamp) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    fprintf(log_file, "%s\n", timestamp);
    fclose(log_file);
}

void handle_motion(GPIOContext *ctx) {
    char timestamp[128];
    struct timeval tv;
    gettimeofday(&tv, NULL);
    strftime(timestamp, sizeof(timestamp), LOG_FORMAT, localtime(&tv.tv_sec));

    log_motion(timestamp);
    buzzer_on(ctx);
    usleep(2000000); // 2 seconds
    buzzer_off(ctx);
}

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        buzzer_off(ctx);
        close(ctx->fd);
        exit(EXIT_SUCCESS);
    }
}

int main() {
    GPIOContext ctx;
    gpio_init(&ctx);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        if (ioctl(ctx.fd, GPIO_GET_PIN, ctx.buzzer) < 0) {
            perror("Failed to read GPIO 18 pin");
            gpio_cleanup(&ctx);
            exit(EXIT_FAILURE);
        }

        if (ctx.gpio->value == BUZZER_ON) {
            handle_motion(&ctx);
        }
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/time.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <syslog.h>
#include <errno.h>
#include <time.h>

#define GPIO18 18
#define VALVE_ON 1
#define VALVE_OFF 0
#define MAX_DURATION 3600
#define MIN_DURATION 1

volatile sig_atomic_t exit_flag = 0;

void handle_signal(int sig) {
    exit_flag = 1;
}

void set_gpio(int value) {
    int fd = open("/dev/gpiod", O_RDWR);
    if (fd == -1) {
        perror("Failed to open /dev/gpiod");
        exit(EXIT_FAILURE);
    }

    struct gpiod_chip *chip = NULL;
    if (ioctl(fd, GPIO_GET_CHIP, &chip) < 0) {
        perror("Failed to get chip");
        close(fd);
        exit(EXIT_FAILURE);
    }

    struct gpiod_line *line = NULL;
    if (ioctl(fd, GPIO_GET_LINE, GPIO18, &line) < 0) {
        perror("Failed to get line");
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (line->direction != GPIOD_LINE_DIR_OUT) {
        fprintf(stderr, "GPIO18 is not an output line\n");
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (line->active_low != 0) {
        fprintf(stderr, "GPIO18 is not an active-low output\n");
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (line->value != VALVE_OFF) {
        fprintf(stderr, "GPIO18 is already on\n");
        close(fd);
        exit(EXIT_FAILURE);
    }

    line->value = VALVE_ON;
    if (ioctl(fd, GPIO_SET_LINE, GPIO18, &line) < 0) {
        perror("Failed to set GPIO18");
        close(fd);
        exit(EXIT_FAILURE);
    }

    close(fd);
}

void set_gpio_off() {
    set_gpio(VALVE_OFF);
}

void wait_duration(int duration) {
    struct timespec ts;
    ts.tv_sec = duration / 1000;
    ts.tv_nsec = (duration % 1000) * 1000;

    while (1) {
        if (nanosleep(&ts, &ts) < 0) {
            if (errno == EINTR) {
                continue;
            } else {
                perror("nanosleep failed");
                exit(EXIT_FAILURE);
            }
        }
    }
}

void read_config() {
    FILE *config = fopen("watering.conf", "r");
    if (config == NULL) {
        perror("Failed to open watering.conf");
        exit(EXIT_FAILURE);
    }

    char line[256];
    while (fgets(line, sizeof(line), config)) {
        if (sscanf(line, "duration=%d", &duration) != 1) {
            fprintf(stderr, "Invalid configuration line: %s\n", line);
            break;
        }

        if (duration < MIN_DURATION || duration > MAX_DURATION) {
            fprintf(stderr, "Invalid duration: %d\n", duration);
            break;
        }

        break;
    }

    if (feof(config)) {
        fprintf(stderr, "Empty configuration file\n");
    }

    fclose(config);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    duration = 0;
    read_config();

    set_gpio_off();

    while (!exit_flag) {
        if (duration > 0) {
            printf("Valve on for %d seconds\n", duration);
            wait_duration(duration);
            duration = 0;
        }

        if (exit_flag) {
            break;
        }

        set_gpio_off();
        printf("Valve off\n");
        sleep(1);
    }

    set_gpio_off();

    return 0;
}

