#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/servod.h>
#include <linux/pigpio.h>

#define GPIO18 18
#define GPIO21 21
#define GPIO22 22
#define DEBOUNCE_MS 100
#define MIN_PULSE 500
#define MAX_PULSE 2500

int servo_fd;
int lock_button = 0;
int unlock_button = 0;

void handle_signal(int signum) {
    if (servo_fd != -1) {
        pigpio_servo_stop(servod, servo_fd);
        servo_fd = -1;
    }
    if (lock_button != 0) {
        pigpio_gpiod_close(lock_button);
        lock_button = 0;
    }
    if (unlock_button != 0) {
        pigpio_gpiod_close(unlock_button);
        unlock_button = 0;
    }
    printf("SIGINT received. Releasing resources.\n");
    exit(0);
}

int init_servo() {
    if ((servo_fd = pigpio_servo_open("/dev/gpiod")) < 0) {
        perror("pigpio_servo_open");
        return -1;
    }
    if (pigpio_servo_init(servod, servo_fd) < 0) {
        perror("pigpio_servo_init");
        return -1;
    }
    return 0;
}

int init_buttons() {
    if ((lock_button = pigpio_gpiod_open(GPIO21)) < 0) {
        perror("pigpio_gpiod_open");
        return -1;
    }
    if ((unlock_button = pigpio_gpiod_open(GPIO22)) < 0) {
        perror("pigpio_gpiod_open");
        return -1;
    }
    return 0;
}

