void handle_error(int fd, int err, const char *msg) {
    if (err < 0) {
        perror(msg);
        exit(EXIT_FAILURE);
    }
}

void init_gpio(int gpio) {
    int fd = gpio_open(GPIO_OUTPUT, gpio);
    if (fd < 0) {
        handle_error(fd, fd, "gpio_open");
    }
    gpio_set_mode(fd, gpio_MODE_OUTPUT);
    gpio setw_value(fd, gpio_HIGH);
    gpio_close(fd);
}

void init_i2c() {
    int i2c_fd = open("/dev/i2c-n", O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }
    handle_error(i2c_fd, i2c_smbus_open(i2c_fd, MOTOR1), "i2c_smbus_open");
    handle_error(i2c_fd, i2c_smbus_write_byte(i2c_fd, 0x00), "i2c_smbus_write_byte");
    handle_error(i2c_fd, i2c_smbus_write_byte(i2c_fd, 0x01), "i2c_smbus_write_byte");
    handle_error(i2c_fd, i2c_smbus_write_byte(i2c_fd, 0x00), "i2c_smbus_write_byte");
    handle_error(i2c_fd, i2c_smbus_write_byte(i2c_fd, 0x01), "i2c_smbus_write_byte");
}

void stop_motors(int i2c_fd) {
    i2c_smbus_write_byte(i2c_fd, 0x00);
    i2c_smbus_write_byte(i2c_fd, 0x00);
    i2c_smbus_write_byte(i2c_fd, 0x00);
    i2c_smbus_write_byte(i2c_fd, 0x00);
    close(i2c_fd);
}

void handle_signal(int signum) {
    stop_motors(i2c_fd);
    gpio_close(gpio_fd);
    exit(EXIT_SUCCESS);
}

int main() {
    int i2c_fd = 0;
    int gpio_fd = 0;
    struct sigaction sa;

    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

