        usleep(200000); // 200ms delay
        i2c_smbus_write_byte(i2c_fd, 0x00);
        i2c_smbus_write_byte(i2c_fd, 0x01);
        usleep(300000); // 300ms delay
        i2c_smbus_write_byte(i2c_fd, 0x00);
        i2c_smbus_write_byte(i2c_fd, 0x01);
    }

    return 0;
}

