#define GPIO17 17
#define GPIO27 27
#define SOUND_ALERTS "SOUND_ALERTS"
#define ALARM_DURATION 1000  // 1 second

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s [mode]\n", argv[0]);
        return 1;
    }

    int mode = atoi(argv[1]);
    if (mode != 1 && mode != 2) {
        fprintf(stderr, "Invalid mode. Use 1 for sound_sensor or 2 for alarm_node.\n");
        return 1;
    }

    int socket_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (socket_fd < 0) {
        perror("socket");
        return 1;
    }

    struct sockaddr_in addr;
    addr.sin_family = AF_INET;
    addr.sin_port = htons(5555);
    addr.sin_addr.s_addr = INADDR_ANY;

    if (bind(socket_fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("bind");
        return 1;
    }

    if (listen(socket_fd, 1) < 0) {
        perror("listen");
        return 1;
    }

    int client_fd;
    struct sockaddr_in client_addr;
    socklen_t client_len = sizeof(client_addr);

    if ((client_fd = accept(socket_fd, (struct sockaddr *)&client_addr, &client_len)) < 0) {
        perror("accept");
        return 1;
    }

    char buffer[256];
    ssize_t bytes_read = read(client_fd, buffer, sizeof(buffer));
    if (bytes_read < 0) {
        perror("read");
        return 1;
    }

    if (strcmp(buffer, SOUND_ALERTS) == 0) {
        // Alarm node mode
        if (gpio_is_set(GPIO27)) {
            fprintf(stderr, "GPIO27 is already set. Exiting...\n");
            return 1;
        }

        if (ioctl(gpio_fd, GPIO_GET_LINE, GPIO27) == 0) {
            fprintf(stderr, "GPIO27 is not configured as an output. Exiting...\n");
            return 1;
        }

        if (gpio_set_value(GPIO27, 1) < 0) {
            perror("gpio_set_value");
            return 1;
        }

        usleep(ALARM_DURATION);
        if (gpio_set_value(GPIO27, 0) < 0) {
            perror("gpio_set_value");
            return 1;
        }

        close(client_fd);
        return 0;
    } else {
        // Sound sensor mode
        if (gpio_is_set(GPIO17)) {
            fprintf(stderr, "GPIO17 is already set. Exiting...\n");
            return 1;
        }

        if (ioctl(gpio_fd, GPIO_GET_LINE, GPIO17) == 0) {
            fprintf(stderr, "GPIO17 is not configured as an input. Exiting...\n");
            return 1;
        }

        if (gpio_set_value(GPIO17, 1) < 0) {
            perror("gpio_set_value");
            return 1;
        }

        int poll_fd = poll(NULL, 1, 10);
        if (poll_fd < 0) {
            perror("poll");
            return 1;
        }

        if (poll_fd == 0) {
            fprintf(stderr, "No events detected. Exiting...\n");
            return 1;
        }

        if (ioctl(gpio_fd, GPIO_GET_LINE, GPIO17) == 0) {
            fprintf(stderr, "No sound detected. Exiting...\n");
            return 1;
        }

        if (gpio_set_value(GPIO17, 0) < 0) {
            perror("gpio_set_value");
            return 1;
        }

        send(socket_fd, "SOUND_ALERT", strlen("SOUND_ALERT"), 0);
        close(client_fd);
        return 0;
    }

    return 0;
}

