#define IR_RECEIVER_GPIO 17
#define IR_RECEIVER_PIN 1
#define IR_RECEIVER_MODE_INPUT 0
#define IR_RECEIVER_MODE_EDGE_FALLING 1
#define IR_RECEIVER_TIMEOUT 1000000  // 1 second
#define IR_RECEIVER_BUFFER_SIZE 1024

typedef struct {
    int fd;
    int mqtt_client;
    int mqtt_port;
    struct json_object *json;
} mqtt_context;

typedef struct {
    int start;
    int end;
    int duration;
} pulse;

typedef struct {
    int address;
    int command;
    int checksum;
} command_data;

typedef struct {
    int address;
    int command;
    int checksum;
    int valid;
} decoded_command;

typedef struct {
    int address;
    int command;
    int checksum;
    int valid;
    int inverted_valid;
} extended_command_data;

void mqtt_callback(struct json_object *json) {
    decoded_command *cmd = json_object_get_array_element(json, 0);
    extended_command_data *ext_cmd = json_object_get_array_element(json, 1);

    if (cmd && ext_cmd) {
        syslog(LOG_INFO, "Received decoded command: %d, Inverted valid: %d", cmd->command, ext_cmd->inverted_valid);
    }
}

void mqtt_init(mqtt_context *ctx) {
    ctx->mqtt_client = socket(AF_INET, SOCK_STREAM, 0);
    struct sockaddr_in addr;
    addr.sin_family = AF_INET;
    addr.sin_port = htons(ctx->mqtt_port);
    addr.sin_addr.s_addr = INADDR_ANY;
    if (bind(ctx->mqtt_client, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        syslog(LOG_ERR, "Failed to bind MQTT client: %d", errno);
        return;
    }
    if (connect(ctx->mqtt_client, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %d", errno);
        return;
    }
    if (connect(ctx->mqtt_client, "localhost", 1883) < 0) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %d", errno);
        return;
    }
    if (json_init(ctx->json) < 0) {
        syslog(LOG_ERR, "Failed to initialize JSON context: %d", errno);
        return;
    }
    json_object_set_string(ctx->json, "ir/decoded", json_object_new_array());
}

void mqtt_loop(mqtt_context *ctx) {
    while (1) {
        if (json_object_get_string(ctx->json, "ir/decoded", ctx->json) < 0) {
            syslog(LOG_ERR, "Failed to publish decoded command: %d", errno);
            return;
        }
        if (write(ctx->mqtt_client, json_object_to_json_string(ctx->json), json_object_get_string_length(ctx->json)) < 0) {
            syslog(LOG_ERR, "Failed to publish decoded command: %d", errno);
            return;
        }
        usleep(100000); // 0.1 seconds
    }
}

void mqtt_cleanup(mqtt_context *ctx) {
    if (ctx->mqtt_client > 0) {
        close(ctx->mqtt_client);
    }
    json_free(ctx->json);
}

void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        syslog(LOG_INFO, "Received signal %d, exiting", sig);
        mqtt_cleanup(&ctx);
        pi_event_clear(IR_RECEIVER_GPIO, IR_RECEIVER_MODE_EDGE_FALLING);
        pi_close();
        exit(EXIT_SUCCESS);
    }
}

int main() {
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        syslog(LOG_ERR, "Failed to register signal handler: %d", errno);
        return EXIT_FAILURE;
    }

    if (gpio_init() < 0) {
        syslog(LOG_ERR, "Failed to initialize GPIO driver: %d", errno);
        return EXIT_FAILURE;
    }

    if (gpio_set_mode(IR_RECEIVER_GPIO, IR_RECEIVER_MODE_INPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO mode: %d", errno);
        return EXIT_FAILURE;
    }

    if (gpio_set_pull_up(IR_RECEIVER_GPIO) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO pull-up: %d", errno);
        return EXIT_FAILURE;
    }

    if (gpio_event_detected(IR_RECEIVER_GPIO, IR_RECEIVER_MODE_EDGE_FALLING) < 0) {
        syslog(LOG_ERR, "Failed to enable GPIO edge detection: %d", errno);
        return EXIT_FAILURE;
    }

    mqtt_context ctx;
    ctx.mqtt_port = 1883;
    mqtt_init(&ctx);

    char buffer[IR_RECEIVER_BUFFER_SIZE];
    int buffer_index = 0;
    int start_time = 0;
    int end_time = 0;
    int duration = 0;
    int command = 0;
    int address = 0;
    int checksum = 0;
    int valid = 0;
    int inverted_valid = 0;

    while (1) {
        if (buffer_index >= IR_RECEIVER_BUFFER_SIZE) {
            syslog(LOG_ERR, "Pulse buffer overflow, exiting");
            mqtt_cleanup(&ctx);
            pi_event_clear(IR_RECEIVER_GPIO, IR_RECEIVER_MODE_EDGE_FALLING);
            pi_close();
            exit(EXIT_FAILURE);
        }

        if (gpio_event_wait(IR_RECEIVER_GPIO, IR_RECEIVER_MODE_EDGE_FALLING, IR_RECEIVER_TIMEOUT) < 0) {
            continue;
        }

        if (buffer_index > 0) {
            end_time = gpio_get_current_time();
            duration = end_time - start_time;
            if (duration < 0 || duration > 1690000) {
                syslog(LOG_ERR, "Invalid pulse duration, ignoring");
                continue;
            }
            if (duration == 560000) {
                command = 1;
            } else if (duration == 1690000) {
                command = 0;
            }
            buffer_index = 0;
            start_time = end_time;
        } else {
            start_time = gpio_get_current_time();
        }

        if (buffer_index < IR_RECEIVER_BUFFER_SIZE - 1) {
            buffer[buffer_index] = gpio_get_level(IR_RECEIVER_GPIO);
            buffer_index++;
        }
    }

    return 0;
}

