        }

        result = read(state->fd, &state->last_read, 2);
        if (result < 0) {
            if (errno == EIO) {
                fprintf(stderr, "Error: EIO (bus error)\n");
                state->last_error = EIO;
                return;
            } else {
                fprintf(stderr, "Error: %s\n", strerror(errno));
                state->last_error = errno;
                return;
            }
        }

        state->last_read_offset = offset;
        state->last_read_scale = scale;
        state->last_read_scale_offset = scale_offset;
        state->last_read_scale_offset_scale = scale_offset_scale;
        state->last_read_scale_offset_scale_2 = scale_offset_scale_2;
        state->last_read_scale_offset_scale_3 = scale_offset_scale_3;
        state->last_read_scale_offset_scale_4 = scale_offset_scale_4;
        state->last_read_scale_offset_scale_5 = scale_offset_scale_5;
        state->last_read_scale_offset_scale_6 = scale_offset_scale_6;
        state->last_read_scale_offset_scale_7 = scale_offset_scale_7;
        state->last_read_scale_offset_scale_8 = scale_offset_scale_8;
        state->last_read_scale_offset_scale_9 = scale_offset_scale_9;
        state->last_read_scale_offset_scale_10 = scale_offset_scale_10;
        state->last_read_scale_offset_scale_11 = scale_offset_scale_11;
        state->last_read_scale_offset_scale_12 = scale_offset_scale_12;

        if (result == 2) {
            int flow = (state->last_read[0] << 8) | state->last_read[1];
            int slpm = (flow >> I2C_SENSOR_SLPM_OFFSET_SCALE_2) * I2C_SENSOR_SLPM_SCALE_OFFSET_SCALE_3;
            slpm += (flow >> I2C_SENSOR_SLPM_OFFSET_SCALE_3) * I2C_SENSOR_SLPM_SCALE_OFFSET_SCALE_4;
            slpm += (flow >> I2C_SENSOR_SLPM_OFFSET_SCALE_4) * I2C_SENSOR_SLPM_SCALE_OFFSET_SCALE_5;
            slpm += (flow >> I2C_SENSOR_SLPM_OFFSET_SCALE_5) * I2C_SENSOR_SLPM_SCALE_OFFSET_SCALE_6;
            slpm += (flow >> I2C_SENSOR_SLPM_OFFSET_SCALE_6) * I2C_SENSOR_SLPM_SCALE_OFFSET_SCALE_7;
            slpm += (flow >> I2C_SENSOR_SLPM_OFFSET_SCALE_7) * I2C_SENSOR_SLPM_SCALE_OFFSET_SCALE_8;
            slpm += (flow >> I2C_SENSOR_SLPM_OFFSET_SCALE_8) * I2C_SENSOR_SLPM_SCALE_OFFSET_SCALE_9;
            slpm += (flow >> I2C_SENSOR_SLPM_OFFSET_SCALE_9) * I2C_SENSOR_SLPM_SCALE_OFFSET_SCALE_10;
            slpm += (flow >> I2C_SENSOR_SLPM_OFFSET_SCALE_10) * I2C_SENSOR_SLPM_SCALE_OFFSET_SCALE_11;
            slpm += (flow >> I2C_SENSOR_SLPM_OFFSET_SCALE_11) * I2C_SENSOR_SLPM_SCALE_OFFSET_SCALE_12;
            slpm += (flow >> I2C_SENSOR_SLPM_OFFSET_SCALE_12) * I2C_SENSOR_SLPM_SCALE;
            printf("SLPM: %d\n", slpm);
            return;
        } else {
            if (i < state->retries - 1) {
                usleep(I2C_READ_TIMEOUT * 1000);
            } else {
                fprintf(stderr, "Error: I2C read failed after %d retries\n", state->retries);
                state->last_error = EIO;
                return;
            }
        }
    }
}

void sigint_handler(int signum) {
    if (state->fd > 0) {
        close(state->fd);
    }
    fclose(log_file);
    exit(EXIT_SUCCESS);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error: sigaction failed\n");
        exit(EXIT_FAILURE);
    }

    state.retries = 3;
    state.last_error = 0;
    state.last_read = 0;
    state.last_read_offset = 0;
    state.last_read_scale = 0;
    state.last_read_scale_offset = 0;
    state.last_read_scale_offset_scale = 0;
    state.last_read_scale_offset_scale_2 = 0;
    state.last_read_scale_offset_scale_3 = 0;
    state.last_read_scale_offset_scale_4 = 0;
    state.last_read_scale_offset_scale_5 = 0;
    state.last_read_scale_offset_scale_6 = 0;
    state.last_read_scale_offset_scale_7 = 0;
    state.last_read_scale_offset_scale_8 = 0;
    state.last_read_scale_offset_scale_9 = 0;
    state.last_read_scale_offset_scale_10 = 0;
    state.last_read_scale_offset_scale_11 = 0;
    state.last_read_scale_offset_scale_12 = 0;

    state.fd = open(I2C_DEV, O_RDWR);
    if (state.fd < 0) {
        fprintf(stderr, "Error: open failed\n");
        exit(EXIT_FAILURE);
    }

    if (ioctl(state.fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Error: ioctl failed\n");
        exit(EXIT_FAILURE);
    }

    log_file = fopen("airflow_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: fopen failed\n");
        exit(EXIT_FAILURE);
    }

    while (1) {
        i2c_read(&state);
        if (state.last_error != 0) {
            break;
        }

        struct timeval tv;
        gettimeofday(&tv, NULL);
        fprintf(log_file, "%ld.%06ld SLPM: %d\n", (long)tv.tv_sec, (long)tv.tv_usec);
        fflush(log_file);
        usleep(1000000); // 1 second delay
    }

    fclose(log_file);
    exit(EXIT_SUCCESS);
}

#include <stdio.h>
#include <stdlib.h>
